/* Muse Live app modules (CAD, 360, finance, eng, …) — Wave B extract */
/* ================================================================================
   MUSE LIVE v2 MODULES
   1. Live Asset Tracking — trackers, geofence arrival alerts, fleet map
   2. Broadcast Operations Grid — work orders, transmission bookings,
      conflict/capacity engine, network visualizer  (Fabric-inspired)
   3. Muse — agent context builders (the live agent is js/muse-agent.js) + rules fallback
   ================================================================================ */

/* ---------------- venue & origin presets ---------------- */
var TRK_VENUES={
 museaitour:{label:"Meta HQ · Hacker Square, Menlo Park",lat:37.4847,lng:-122.1477},
 raybangen3:{label:"Meta HQ · Menlo Park",lat:37.4848,lng:-122.1484},
 orion:{label:"Levi's Stadium · Santa Clara",lat:37.4032,lng:-121.9697},
 museailaunch:{label:"Meta NYC · Studio M1",lat:40.7536,lng:-74.0007},
 whatsapp:{label:"Meta Miami",lat:25.7906,lng:-80.3164},
 igcreators:{label:"Herald Square · NYC",lat:40.7496,lng:-73.9876},
 charm:{label:"Milan Design Week IBC",lat:45.4781,lng:9.1240}};
/* ============================================================================
   LIVE FLEET TRACKING — Traccar-style console (self-contained, no map tiles)
   Data model mirrors Traccar (Device / Position / Geofence / Event) so it can
   be wired to a real Traccar server API later. The telemetry here is a live
   local simulation: assets move around each production's operational area
   (venue, compound, hotel, airport, lot) with heading, trails, geofence
   enter/exit events, battery and ignition state.
   ========================================================================== */
var MPD_LAT=111320;
function mpdLng(lat){return 111320*Math.cos(lat*Math.PI/180);}
function trkOffset(lat,lng,dN,dE){return {lat:lat+dN/MPD_LAT,lng:lng+dE/mpdLng(lat)};}
/* ============================================================================
   v35 — WEB-MERCATOR PROJECTION + SLIPPY-TILE BASEMAP for the fleet-telemetry
   canvas. CARTO light/dark basemap under live blips (follows html.dark). Mercator
   so tiles align with device markers, geofences and POIs. Tile miss → grid.
   Wheel: page scroll by default; ⌘/Ctrl + scroll zooms the map (cooperative).
   ============================================================================ */
var TRK_EARTH_C=40075016.686; /* equatorial circumference (m) */
function trkMercX(lng){return (lng+180)/360;}
function trkMercN(lat){lat=Math.max(-85.051,Math.min(85.051,lat));var s=Math.sin(lat*Math.PI/180);return 0.5-Math.log((1+s)/(1-s))/(4*Math.PI);}
function trkInvMercN(y){var a=(0.5-y)*4*Math.PI;var e=Math.exp(a);return Math.asin((e-1)/(e+1))*180/Math.PI;}
function trkIsDark(){try{return document.documentElement.classList.contains('dark');}catch(e){return true;}}
function trkTileUrl(z, wrapX, ty){
  /* Esri public raster tiles — no API key. CARTO basemaps.cartocdn.com now
     stamps "API KEY REQUIRED" on every tile. Esri uses {z}/{y}/{x}. */
  if(trkIsDark()){
    return 'https://server.arcgisonline.com/ArcGIS/rest/services/Canvas/World_Dark_Gray_Base/MapServer/tile/'+z+'/'+ty+'/'+wrapX;
  }
  return 'https://server.arcgisonline.com/ArcGIS/rest/services/World_Street_Map/MapServer/tile/'+z+'/'+ty+'/'+wrapX;
}
var _trkTiles={},_trkTileOrder=[],_trkTileTheme=null;
function trkClearTiles(){_trkTiles={};_trkTileOrder=[];_trkTileTheme=null;}
function trkSyncTheme(){
  var th=trkIsDark()?'dark':'light';
  if(_trkTileTheme===th)return;
  trkClearTiles();
  _trkTileTheme=th;
  try{
    document.querySelectorAll('.trk-map-shell').forEach(function(el){
      el.classList.toggle('trk-map-shell-light',th==='light');
      el.classList.toggle('trk-map-shell-dark',th==='dark');
    });
  }catch(e){}
}
function _trkTile(url){
  var t=_trkTiles[url];
  if(t)return (t.ok?t.img:null);
  if(t&&t.bad)return null;
  var img=new Image();img.crossOrigin='anonymous';
  _trkTiles[url]={img:img,ok:false};_trkTileOrder.push(url);
  img.onload=function(){var e=_trkTiles[url];if(e)e.ok=true;};
  img.onerror=function(){var e=_trkTiles[url];if(e)e.bad=true;};
  img.src=url;
  if(_trkTileOrder.length>420){var old=_trkTileOrder.shift();delete _trkTiles[old];}
  return null;
}
/* draw theme-aware raster basemap; returns #tiles drawn (rAF pops tiles in as they load). */
function _trkDrawTiles(ctx,pr){
  try{
    trkSyncTheme();
    var WP=pr.WORLDpx;if(!isFinite(WP)||WP<=0)return 0;
    var z=Math.round(Math.log(WP/256)/Math.LN2);z=Math.max(2,Math.min(19,z));
    var n=Math.pow(2,z);var ts=WP/n;if(ts<=0||!isFinite(ts))return 0;
    var leftX=pr.mcx-(pr.w/2)/WP,rightX=pr.mcx+(pr.w/2)/WP;
    var topY=pr.mcy-(pr.h/2)/WP,botY=pr.mcy+(pr.h/2)/WP;
    var tx0=Math.floor(leftX*n),tx1=Math.floor(rightX*n);
    var ty0=Math.floor(topY*n),ty1=Math.floor(botY*n);
    if((tx1-tx0+1)*(ty1-ty0+1)>140)return 0; /* safety cap — never blow up a frame */
    var drew=0;
    for(var tx=tx0;tx<=tx1;tx++){for(var ty=ty0;ty<=ty1;ty++){
      if(ty<0||ty>=n)continue;var wrapX=((tx%n)+n)%n;
      var img=_trkTile(trkTileUrl(z,wrapX,ty));
      if(!img)continue;
      var sx=pr.w/2+(tx/n-pr.mcx)*WP,sy=pr.h/2+(ty/n-pr.mcy)*WP;
      try{ctx.drawImage(img,sx,sy,ts+1,ts+1);drew++;}catch(e){}
    }}
    return drew;
  }catch(e){return 0;}
}
function trkMeters(a,b){var mLat=(a.lat-b.lat)*MPD_LAT,mLng=(a.lng-b.lng)*mpdLng((a.lat+b.lat)/2);return Math.sqrt(mLat*mLat+mLng*mLng);}
function trkBearing(a,b){var y=Math.sin((b.lng-a.lng)*Math.PI/180)*Math.cos(b.lat*Math.PI/180);
  var x=Math.cos(a.lat*Math.PI/180)*Math.sin(b.lat*Math.PI/180)-Math.sin(a.lat*Math.PI/180)*Math.cos(b.lat*Math.PI/180)*Math.cos((b.lng-a.lng)*Math.PI/180);
  return (Math.atan2(y,x)*180/Math.PI+360)%360;}
function trkCompass(b){return ['N','NE','E','SE','S','SW','W','NW'][Math.round(((b||0)%360)/45)%8];}

var TRK_CATS={
  truck:{label:'Mobile Unit',icon:'🚚',color:'#0866ff'},
  uplink:{label:'Uplink Truck',icon:'📡',color:'#0866ff'},
  van:{label:'Crew Shuttle',icon:'🚐',color:'#0866ff'},
  car:{label:'Talent Vehicle',icon:'🚗',color:'#e41e3f'},
  gen:{label:'Generator',icon:'⚡',color:'#f5832a'},
  case:{label:'Camera Case',icon:'🎥',color:'#1E7B34'},
  security:{label:'Security Patrol',icon:'🛡️',color:'#e41e3f'},
  boat:{label:'Camera Boat',icon:'⛵',color:'#0866ff'}
};

var trkDevices=[],trkPos={},trkRoutes={},trkGeos={},trkPOI={},trkEvents=[],trkView={};
var trkPaused=false,trkClock=0,trkLoopOn=false,trkSeq=1,trkEvtSeq=1,trkLastDom=0,trkModelReady=false;
var TRK_SPEED_FACTOR=5; /* accelerate motion so movement is visible in a live demo */

function trkFleetSpec(key){
  var real={
    museaitour:[['truck','NEP ND1 — Supershooter 23','compound'],['uplink','K2 Ku Uplink','compound'],['van','Crew Shuttle — IBC','loopHV'],['car','Talent Coach','airportRun'],['security','Perimeter Security','perimeter'],['gen','IBC Genset A','compound'],['case','RF Camera Case','loopVC']],
    orion:[['truck','Game Creek — Edge','compound'],['uplink','Ku Uplink 118','compound'],['van','Crew Shuttle A','loopHV'],['car','Talent SUV','airportRun'],['security','Field Security','perimeter'],['gen','Compound Genset','compound'],['case','Handheld Case','loopVC']]
  };
  if(real[key])return real[key];
  return [['truck','Mobile Unit 1','compound'],['uplink','Uplink Truck','compound'],['van','Crew Shuttle','loopHV'],['car','Talent Vehicle','airportRun'],['security','Security Patrol','perimeter'],['gen','Genset A','compound'],['case','RF Camera Case','loopVC']];
}
function trkBuildLayout(key){
  var v=(typeof TRK_VENUES!=='undefined'&&TRK_VENUES[key])?TRK_VENUES[key]:{label:((typeof productions!=='undefined'&&productions[key])?productions[key].venue:'Venue')||'Venue',lat:39.5,lng:-98.35};
  var c={lat:v.lat,lng:v.lng};
  var pois=[
    {id:'venue',name:(''+v.label).split('·')[0].trim()||'Venue',kind:'venue',pos:c},
    {id:'compound',name:'Broadcast Compound',kind:'compound',pos:trkOffset(c.lat,c.lng,-360,-300)},
    {id:'hotel',name:'Media Hotel',kind:'hotel',pos:trkOffset(c.lat,c.lng,1050,1650)},
    {id:'airport',name:'Airport / Freight',kind:'airport',pos:trkOffset(c.lat,c.lng,-2700,4200)},
    {id:'catering',name:'Catering / Staging',kind:'staging',pos:trkOffset(c.lat,c.lng,-180,560)},
    {id:'lot',name:'Truck Lot',kind:'lot',pos:trkOffset(c.lat,c.lng,-620,140)}
  ];
  trkPOI[key]=pois;
  var P={};pois.forEach(function(p){P[p.id]=p.pos;});
  trkGeos[key]=[
    {id:key+'_venue',name:pois[0].name,center:P.venue,radius:250,color:'#f0f2f5'},
    {id:key+'_comp',name:'Compound',center:P.compound,radius:210,color:'#0866ff'},
    {id:key+'_hotel',name:'Media Hotel',center:P.hotel,radius:170,color:'#0866ff'},
    {id:key+'_air',name:'Airport',center:P.airport,radius:260,color:'#0866ff'}
  ];
  // named routes
  var per=[trkOffset(c.lat,c.lng,230,230),trkOffset(c.lat,c.lng,-230,230),trkOffset(c.lat,c.lng,-230,-230),trkOffset(c.lat,c.lng,230,-230)];
  return {P:P,routes:{
    loopHV:[P.hotel,P.catering,P.venue,P.lot],
    loopVC:[P.venue,P.compound],
    airportRun:[P.airport,P.hotel,P.venue],
    perimeter:per,
    compound:[P.compound]
  }};
}
function trkAddDevice2(key,cat,name,routeKey,layout){
  var route=(layout.routes[routeKey]||[layout.P.compound]).map(function(p){return {lat:p.lat,lng:p.lng};});
  var moving=route.length>1;
  var spd={van:26,car:38,security:11,truck:22,uplink:20,case:16,gen:0,boat:14}[cat]||24;
  var dev={id:'dev'+(trkSeq++),uid:'IMEI '+Math.floor(3e14+Math.random()*6e14),name:name,cat:cat,
    model:(TRK_CATS[cat]?TRK_CATS[cat].label:cat),prod:key,status:'online',created:Date.now()};
  trkDevices.push(dev);
  var start=route[0];
  trkPos[dev.id]={lat:start.lat,lng:start.lng,speed:0,course:Math.random()*360,battery:52+Math.random()*47,
    ignition:moving,motion:moving,zone:'',fixTime:Date.now(),trail:[],spark:[],odo:0};
  trkRoutes[dev.id]={pts:route,seg:0,t:Math.random()*(moving?1:0),base:spd,dwellLeft:0,stationary:!moving};
  return dev;
}
function trkInitModel(){
  if(trkModelReady)return;trkModelReady=true;
  var keys=(typeof TRK_VENUES!=='undefined')?Object.keys(TRK_VENUES):[];
  if(typeof order!=='undefined')order.forEach(function(k){if(keys.indexOf(k)<0&&(typeof TRK_VENUES!=='undefined')&&TRK_VENUES[k])keys.push(k);});
  keys.forEach(function(key){var layout=trkBuildLayout(key);
    trkFleetSpec(key).forEach(function(s){trkAddDevice2(key,s[0],s[1],s[2],layout);});});
}
function trkZoneAt(key,p){var gz=trkGeos[key]||[];for(var i=0;i<gz.length;i++){if(trkMeters(p,gz[i].center)<=gz[i].radius)return gz[i].name;}return '';}
function trkNearestPoi(key,p){var a=trkPOI[key]||[],best=null,bd=1e12;a.forEach(function(o){var d=trkMeters(p,o.pos);if(d<bd){bd=d;best=o;}});return best?{poi:best,dist:bd}:null;}
function trkAddr(key,p){var n=trkNearestPoi(key,p);if(!n)return '—';if(n.dist<40)return 'at '+n.poi.name;
  return Math.round(n.dist)+' m '+trkCompass(trkBearing(n.poi.pos,p))+' of '+n.poi.name;}
function trkPushEvent(dev,type,zone){trkEvents.unshift({id:trkEvtSeq++,t:Date.now(),dev:dev.id,name:dev.name,cat:dev.cat,prod:dev.prod,type:type,zone:zone||''});
  if(trkEvents.length>80)trkEvents.length=80;}

function trkStep(dt){
  dt=Math.min(0.2,dt||0);
  for(var i=0;i<trkDevices.length;i++){var dev=trkDevices[i];var r=trkRoutes[dev.id],ps=trkPos[dev.id];if(!r||!ps)continue;
    if(dev.status==='offline'){ if(Math.random()<dt*0.05){dev.status='online';trkPushEvent(dev,'deviceOnline','');} continue; }
    if(Math.random()<dt*0.0016){dev.status='offline';ps.speed=0;ps.motion=false;trkPushEvent(dev,'deviceOffline','');continue;}
    ps.battery=Math.max(3,ps.battery-dt*((r.stationary)?0.003:0.02));
    if(r.stationary){ps.speed=0;ps.motion=false;ps.ignition=false;}
    else if(r.dwellLeft>0){r.dwellLeft-=dt;ps.speed=0;ps.motion=false;ps.ignition=false;}
    else{
      var a=r.pts[r.seg],b=r.pts[(r.seg+1)%r.pts.length];var segLen=Math.max(1,trkMeters(a,b));
      var mps=r.base*0.44704*TRK_SPEED_FACTOR;var frac=(mps*dt)/segLen;r.t+=frac;
      var guard=0;
      while(r.t>=1&&guard++<8){r.t-=1;r.seg=(r.seg+1)%r.pts.length;
        a=r.pts[r.seg];b=r.pts[(r.seg+1)%r.pts.length];segLen=Math.max(1,trkMeters(a,b));
        if(Math.random()<0.45){r.dwellLeft=3+Math.random()*9;break;}}
      var na=r.pts[r.seg],nb=r.pts[(r.seg+1)%r.pts.length];
      ps.lat=na.lat+(nb.lat-na.lat)*r.t;ps.lng=na.lng+(nb.lng-na.lng)*r.t;
      ps.course=trkBearing(na,nb);
      ps.speed=Math.max(0,r.base*(0.82+0.28*Math.sin(Date.now()/900+i)));
      ps.motion=r.dwellLeft<=0;ps.ignition=true;ps.odo+=mps*dt/1609.34;
      if(ps.motion){ps.trail.push({lat:ps.lat,lng:ps.lng});if(ps.trail.length>60)ps.trail.shift();}
    }
    ps.spark.push(ps.speed);if(ps.spark.length>28)ps.spark.shift();
    ps.fixTime=Date.now();
    var z=trkZoneAt(dev.prod,ps);
    if(z!==ps.zone){if(z)trkPushEvent(dev,'geofenceEnter',z);else if(ps.zone)trkPushEvent(dev,'geofenceExit',ps.zone);ps.zone=z;}
  }
}

/* ---------------- fleet helpers ---------------- */
function trkDevs(scope){return scope==='dash'?trkDevices.slice():trkDevices.filter(function(d){return d.prod===scope;});}
function trkStats(scope){var d=trkDevs(scope),online=0,moving=0,stopped=0,off=0;
  d.forEach(function(x){var ps=trkPos[x.id]||{};if(x.status==='offline'){off++;return;}online++;if(ps.motion)moving++;else stopped++;});
  return {total:d.length,online:online,moving:moving,stopped:stopped,offline:off};}
function trkAgo(t){var s=Math.max(0,Math.round((Date.now()-t)/1000));if(s<60)return s+'s ago';var m=Math.round(s/60);if(m<60)return m+'m ago';return Math.round(m/60)+'h ago';}
function trkDevById(id){for(var i=0;i<trkDevices.length;i++)if(trkDevices[i].id===id)return trkDevices[i];return null;}
function trkView2(scope){if(!trkView[scope])trkView[scope]={fit:true,follow:false,sel:null,mpp:20,clat:0,clng:0};return trkView[scope];}

/* ---------------- manual add ---------------- */
function trkAddDevice(key){if(!key)return;var cats=['truck','van','car','case','security','uplink'];
  var cat=cats[Math.floor(Math.random()*cats.length)];var layout=trkBuildLayout(key);
  var rk=({van:'loopHV',car:'airportRun',security:'perimeter',case:'loopVC'})[cat]||'compound';
  var n=trkDevs(key).filter(function(d){return d.cat===cat;}).length+1;
  var dev=trkAddDevice2(key,cat,(TRK_CATS[cat].label)+' '+n,rk,layout);
  trkPushEvent(dev,'deviceOnline','');trkView2(key).sel=dev.id;
  try{toast&&toast('Asset added — '+dev.name+' now reporting');}catch(e){}
  try{if(typeof logEvent==='function'&&productions[key]){logEvent(key,'🛰 Tracker linked — '+dev.name+' ('+dev.uid+')');saveState&&saveState();}}catch(e){}}
function trkSelect(scope,id){var vw=trkView2(scope);vw.sel=id;var ps=trkPos[id];if(ps){vw.fit=false;if(vw.mpp>40)vw.mpp=6;vw.clat=ps.lat;vw.clng=ps.lng;}}
function trkZoom(scope,dir){var vw=trkView2(scope);if(vw.fit){vw.fit=false;}vw.mpp=Math.max(1,Math.min(9000,vw.mpp*(dir<0?0.66:1.5)));}
function trkFitView(scope){var vw=trkView2(scope);vw.fit=true;vw.follow=false;}
function trkToggleFollow(scope){var vw=trkView2(scope);vw.follow=!vw.follow;if(vw.follow)vw.fit=false;try{toast&&toast('Follow '+(vw.follow?'on':'off'));}catch(e){}trkRenderScope(scope);}
function trkTogglePause(){trkPaused=!trkPaused;try{toast&&toast(trkPaused?'Telemetry paused':'Telemetry live');}catch(e){}
  document.querySelectorAll('[data-trkpause]').forEach(function(b){b.textContent=trkPaused?'▶ Resume':'⏸ Pause';});}

/* ---------------- HTML fragments ---------------- */
function trkStatDot(dev){var ps=trkPos[dev.id]||{};if(dev.status==='offline')return '#b0b3b8';return ps.motion?'#1E7B34':'#f5832a';}
function trkSummaryHTML(scope){var s=trkStats(scope);
  function chip(lbl,val,col){return '<span class="inline-flex items-center gap-1 text-[10px] font-bold mono px-2 py-1 rounded-lg border '+col+'">'+val+' <span class="font-semibold opacity-70">'+lbl+'</span></span>';}
  return chip('assets',s.total,'bg-gray-50 border-gray-200 text-gray-700')+
    chip('online',s.online,'bg-emerald-50 border-emerald-200 text-emerald-700')+
    chip('moving',s.moving,'bg-blue-50 border-blue-200 text-blue-700')+
    chip('stopped',s.stopped,'bg-amber-50 border-amber-200 text-amber-700')+
    (s.offline?chip('offline',s.offline,'bg-gray-100 border-gray-300 text-gray-500'):'');}
function trkListHTML(scope){var devs=trkDevs(scope);var vw=trkView2(scope);
  devs.sort(function(a,b){function r(d){var ps=trkPos[d.id]||{};if(d.status==='offline')return 2;return ps.motion?0:1;}return r(a)-r(b);});
  if(!devs.length)return '<div class="text-[10px] text-gray-400 p-4 text-center">No assets in this scope.</div>';
  return devs.map(function(d){var ps=trkPos[d.id]||{};var cat=TRK_CATS[d.cat]||{icon:'📍',color:'#65676b',label:d.cat};
    var sel=vw.sel===d.id;var off=d.status==='offline';
    var right=off?'<span class="text-[9px] font-bold text-gray-400 mono">OFFLINE</span>':(ps.motion?'<span class="text-[11px] font-bold mono text-blue-700">'+Math.round(ps.speed)+'<span class="text-[8px] text-gray-400"> mph</span></span>':'<span class="text-[9px] font-bold mono text-amber-600">PARKED</span>');
    var bat=Math.round(ps.battery||0);var batcol=bat<20?'#e41e3f':(bat<45?'#f5832a':'#1E7B34');
    return '<button onclick="trkSelect(\''+scope+'\',\''+d.id+'\');trkRenderScope(\''+scope+'\')" class="w-full text-left flex items-center gap-2.5 p-2 rounded-xl border transition-colors '+(sel?'border-blue-300 bg-blue-50/60':'border-gray-200 hover:bg-gray-50')+'">'+
      '<span class="relative flex-shrink-0"><span class="w-8 h-8 rounded-lg flex items-center justify-center text-[13px]" style="background:'+hexA(cat.color,0.14)+'">'+cat.icon+'</span>'+
        '<span class="absolute -right-0.5 -top-0.5 w-2.5 h-2.5 rounded-full border-2 border-white" style="background:'+trkStatDot(d)+'"></span></span>'+
      '<span class="min-w-0 flex-1"><span class="block text-[11px] font-bold text-gray-900 truncate">'+esc(d.name)+'</span>'+
        '<span class="block text-[9px] text-gray-500 mono truncate">'+esc(cat.label)+(ps.zone?' · '+esc(ps.zone):'')+'</span></span>'+
      '<span class="text-right flex-shrink-0">'+right+'<span class="flex items-center gap-1 justify-end mt-0.5"><span class="w-8 h-1 rounded-full bg-gray-200 overflow-hidden"><span class="block h-full" style="width:'+bat+'%;background:'+batcol+'"></span></span><span class="text-[8px] mono text-gray-400">'+bat+'%</span></span></span>'+
    '</button>';}).join('');}
function trkDetailHTML(scope){var vw=trkView2(scope);var d=vw.sel?trkDevById(vw.sel):null;
  if(!d)return '<div class="text-[10px] text-gray-400 text-center py-8 px-4">Select an asset to see demo telemetry, position and history (local simulation — not a live Traccar feed).</div>';
  var ps=trkPos[d.id]||{};var cat=TRK_CATS[d.cat]||{icon:'📍',color:'#65676b',label:d.cat};var off=d.status==='offline';
  function kv(l,v){return '<div class="bg-gray-50 rounded-lg p-2 border border-gray-100"><p class="text-[8px] font-bold uppercase tracking-wider text-gray-500">'+l+'</p><p class="text-[12px] font-bold mono text-gray-900 leading-tight">'+v+'</p></div>';}
  var spark=(ps.spark||[]);var mx=Math.max(1,Math.max.apply(null,spark.concat([1])));
  var sparkHTML=spark.map(function(v){return '<span style="display:inline-block;width:3px;height:'+Math.max(2,Math.round(v/mx*22))+'px;background:'+cat.color+';opacity:.75;border-radius:1px"></span>';}).join('');
  return '<div class="flex items-center gap-2 mb-3"><span class="w-9 h-9 rounded-lg flex items-center justify-center text-[15px]" style="background:'+hexA(cat.color,0.14)+'">'+cat.icon+'</span>'+
    '<div class="min-w-0"><p class="text-[13px] font-bold text-gray-900 truncate">'+esc(d.name)+'</p><p class="text-[9px] text-gray-500 mono">'+esc(cat.label)+' · '+esc(d.uid)+'</p></div>'+
    '<span class="ml-auto text-[8px] font-bold mono px-2 py-1 rounded-lg border '+(off?'bg-gray-100 border-gray-300 text-gray-500':(ps.motion?'bg-emerald-50 border-emerald-200 text-emerald-700':'bg-amber-50 border-amber-200 text-amber-700'))+'">'+(off?'OFFLINE':(ps.motion?'MOVING':'STOPPED'))+'</span></div>'+
    '<div class="grid grid-cols-3 gap-1.5 mb-2">'+kv('Speed',Math.round(ps.speed||0)+'<span class="text-[8px] text-gray-400"> mph</span>')+kv('Heading',Math.round(ps.course||0)+'°<span class="text-[8px] text-gray-400"> '+trkCompass(ps.course)+'</span>')+kv('Battery',Math.round(ps.battery||0)+'%')+'</div>'+
    '<div class="grid grid-cols-3 gap-1.5 mb-2">'+kv('Ignition',ps.ignition?'ON':'OFF')+kv('Odometer',(ps.odo||0).toFixed(1)+'<span class="text-[8px] text-gray-400"> mi</span>')+kv('Fix',trkAgo(ps.fixTime||Date.now()))+'</div>'+
    '<div class="bg-gray-50 rounded-lg p-2 border border-gray-100 mb-2"><p class="text-[8px] font-bold uppercase tracking-wider text-gray-500 mb-0.5">Location</p><p class="text-[10px] font-semibold text-gray-800">'+esc(trkAddr(d.prod,ps))+(ps.zone?' <span class="text-[8px] font-bold text-blue-700">· in '+esc(ps.zone)+'</span>':'')+'</p><p class="text-[9px] mono text-gray-400 mt-0.5">'+(ps.lat||0).toFixed(5)+', '+(ps.lng||0).toFixed(5)+'</p></div>'+
    '<div class="flex items-end gap-0.5 h-6 mb-2 px-0.5">'+(sparkHTML||'<span class="text-[9px] text-gray-300">no speed history yet</span>')+'</div>'+
    '<div class="flex gap-1.5"><button onclick="trkSelect(\''+scope+'\',\''+d.id+'\');trkRenderScope(\''+scope+'\')" class="flex-1 text-[10px] font-bold text-blue-700 border border-blue-200 bg-blue-50 rounded-lg py-1.5 hover:bg-blue-100">◎ Center</button>'+
      '<button onclick="trkToggleFollow(\''+scope+'\')" class="flex-1 text-[10px] font-bold '+(vw.follow?'text-white bg-blue-600 border border-blue-600':'text-gray-700 border border-gray-200 bg-gray-50')+' rounded-lg py-1.5">➤ Follow</button></div>';}
function trkEventsHTML(scope){var evs=trkEvents.filter(function(e){return scope==='dash'||e.prod===scope;}).slice(0,14);
  if(!evs.length)return '<div class="text-[10px] text-gray-400 text-center py-3">No events yet.</div>';
  var ic={geofenceEnter:'📍',geofenceExit:'↗',deviceOffline:'⚠',deviceOnline:'✓',overspeed:'⏱'};
  var tx={geofenceEnter:'entered',geofenceExit:'left',deviceOffline:'went offline',deviceOnline:'back online',overspeed:'overspeed'};
  return evs.map(function(e){var cat=TRK_CATS[e.cat]||{color:'#65676b'};
    return '<div class="flex items-start gap-2 py-1.5 border-b border-gray-100 last:border-0"><span class="text-[11px] leading-none mt-0.5">'+(ic[e.type]||'•')+'</span>'+
      '<div class="min-w-0 flex-1"><p class="text-[10px] text-gray-700 leading-tight"><span class="font-bold" style="color:'+cat.color+'">'+esc(e.name)+'</span> '+(tx[e.type]||e.type)+(e.zone?' <span class="font-semibold">'+esc(e.zone)+'</span>':'')+'</p>'+
      '<p class="text-[8px] mono text-gray-400">'+trkAgo(e.t)+'</p></div></div>';}).join('');}

/* ---------------- console shells ---------------- */
function trkMapControls(scope){
  return '<div class="absolute top-2 right-2 flex flex-col gap-1 z-10">'+
    '<button type="button" onclick="trkZoom(\''+scope+'\',-1)" class="w-7 h-7 rounded-lg bg-white/95 border border-gray-300 text-gray-700 text-[14px] font-bold shadow-sm hover:bg-white">+</button>'+
    '<button type="button" onclick="trkZoom(\''+scope+'\',1)" class="w-7 h-7 rounded-lg bg-white/95 border border-gray-300 text-gray-700 text-[14px] font-bold shadow-sm hover:bg-white">−</button>'+
    '<button type="button" onclick="trkFitView(\''+scope+'\')" title="Fit all" class="w-7 h-7 rounded-lg bg-white/95 border border-gray-300 text-gray-700 text-[11px] shadow-sm hover:bg-white">⤢</button></div>'+
    '<div class="absolute bottom-2 left-2 flex items-center gap-1.5 z-10 flex-wrap">'+
      '<span class="flex items-center gap-1 text-[9px] font-bold mono text-white bg-black/55 rounded-md px-2 py-1"><span class="w-1.5 h-1.5 rounded-full bg-emerald-400 animate-pulse"></span>LIVE</span>'+
      '<span class="text-[8px] font-bold mono text-gray-700 bg-white/90 border border-gray-200 rounded-md px-2 py-1 shadow-sm" title="Page scrolls over the map. Hold ⌘ or Ctrl while scrolling to zoom.">⌘/Ctrl + scroll to zoom</span>'+
    '</div>';}
function trkCanvasBox(scope,h){var shell=trkIsDark()?'trk-map-shell-dark':'trk-map-shell-light';
  return '<div class="trk-map-shell '+shell+' relative rounded-2xl overflow-hidden border" style="height:'+h+'">'+
  '<canvas class="trk-map" data-scope="'+scope+'" id="trkCanvas_'+scope+'" style="width:100%;height:100%;display:block;cursor:grab"></canvas>'+trkMapControls(scope)+'</div>';}

function trackingPaneHTML(key){var p=productions[key];trkInitModel();
  var head='<div class="bg-white rounded-2xl px-5 py-3 border border-gray-200/60 flex flex-wrap items-center justify-between gap-2" style="box-shadow:0 4px 20px rgba(0,0,0,.03)">'+
    '<div class="flex items-center gap-2 flex-wrap"><span class="w-2 h-2 rounded-full bg-amber-400"></span><h3 class="text-xs font-bold uppercase tracking-wider text-gray-600">Fleet Tracking — '+esc(p.name)+'</h3><span class="text-[8px] font-bold mono text-amber-800 bg-amber-50 border border-amber-200 rounded px-1.5 py-0.5">DEMO TELEMETRY · not live GPS</span></div>'+
    '<div class="flex items-center gap-1.5 flex-wrap"><span id="trkSum_'+key+'" class="flex items-center gap-1.5 flex-wrap">'+trkSummaryHTML(key)+'</span>'+
      '<button data-trkpause onclick="trkTogglePause()" class="text-[10px] font-bold text-gray-700 border border-gray-200 bg-gray-50 rounded-lg px-2.5 py-1 hover:bg-gray-100">'+(trkPaused?'▶ Resume':'⏸ Pause')+'</button>'+
      '<button onclick="trkAddDevice(\''+key+'\');trkRenderScope(\''+key+'\')" class="text-[10px] font-bold text-white bg-gray-900 rounded-lg px-2.5 py-1 hover:bg-gray-800">+ Add Asset</button></div></div>';
  var grid='<div class="grid grid-cols-1 lg:grid-cols-12 gap-3">'+
    '<div class="lg:col-span-3 bg-white rounded-2xl p-2.5 border border-gray-200/60 lg:max-h-[640px] lg:overflow-y-auto space-y-1.5" id="trkList_'+key+'" style="box-shadow:0 4px 20px rgba(0,0,0,.03)">'+trkListHTML(key)+'</div>'+
    '<div class="lg:col-span-6">'+trkCanvasBox(key,'min(640px,62vh)')+'</div>'+
    '<div class="lg:col-span-3 space-y-3">'+
      '<div class="bg-white rounded-2xl p-3 border border-gray-200/60" id="trkDetail_'+key+'" style="box-shadow:0 4px 20px rgba(0,0,0,.03)">'+trkDetailHTML(key)+'</div>'+
      '<div class="bg-white rounded-2xl p-3 border border-gray-200/60" style="box-shadow:0 4px 20px rgba(0,0,0,.03)"><p class="text-[9px] font-bold uppercase tracking-wider text-gray-500 mb-1">Event Feed</p><div id="trkEvt_'+key+'">'+trkEventsHTML(key)+'</div></div>'+
    '</div></div>';
  setTimeout(function(){trkEnsureLoop();},30);
  return '<div class="space-y-3">'+head+grid+'</div>';}

function trkFollowRfCase(scope){
  try{
    var list=trkDevs(scope||'dash');
    var d=null;
    for(var i=0;i<list.length;i++){if(list[i].cat==='case'&&/RF Camera/i.test(list[i].name||'')){d=list[i];break;}}
    if(!d){for(var j=0;j<list.length;j++){if(list[j].cat==='case'){d=list[j];break;}}}
    if(!d)return;
    var vw=trkView2(scope||'dash');
    vw.sel=d.id;vw.fit=false;vw.follow=true;vw.mpp=6;
    var ps=trkPos[d.id];
    if(ps){vw.clat=ps.lat;vw.clng=ps.lng;}
  }catch(e){}
}
function renderTracking(){trkInitModel();
  var cnt=document.getElementById('trkCount');if(cnt){var s=trkStats('dash');cnt.textContent=s.total+' assets · '+s.moving+' moving · '+s.online+' online';}
  var map=document.getElementById('trkMapBox');
  if(map&&!document.getElementById('trkCanvas_dash')){
    var shell=trkIsDark()?'trk-map-shell-dark':'trk-map-shell-light';
    map.innerHTML='<div class="trk-map-shell '+shell+' relative w-full h-full border-0">'+
    '<canvas class="trk-map" data-scope="dash" id="trkCanvas_dash" style="width:100%;height:100%;display:block;cursor:grab"></canvas>'+trkMapControls('dash')+'</div>';}
  var rows=document.getElementById('trkRows');
  if(rows){if(rows.id!=='trkList_dash')rows.id='trkList_dash';rows.innerHTML=trkListHTML('dash');}
  trkFollowRfCase('dash');
  trkEnsureLoop();}

function trkRenderScope(scope){ // in-place refresh of one console's panels
  var l=document.getElementById('trkList_'+scope);if(l){var st=l.scrollTop;l.innerHTML=trkListHTML(scope);l.scrollTop=st;}
  var d=document.getElementById('trkDetail_'+scope);if(d)d.innerHTML=trkDetailHTML(scope);
  var e=document.getElementById('trkEvt_'+scope);if(e)e.innerHTML=trkEventsHTML(scope);
  var s=document.getElementById('trkSum_'+scope);if(s)s.innerHTML=trkSummaryHTML(scope);
  if(scope==='dash'){var c=document.getElementById('trkCount');if(c){var st=trkStats('dash');c.textContent=st.total+' assets · '+st.moving+' moving · '+st.online+' online';}}}

function trkTabBadge(key){trkInitModel();var s=trkStats(key);if(!s.total)return '';
  return typeof museBadgeHTML==='function'?museBadgeHTML(s.total):'';}
/* legacy modal entry points → simplified add */
function openTrackerModal(key){var k=key||(document.querySelector('.view-pane.active')?document.querySelector('.view-pane.active').id.replace('view-',''):(typeof order!=='undefined'?order[0]:''));
  if(!productions[k]){k=(typeof order!=='undefined')?order[0]:'';}trkAddDevice(k);trkRenderScope('dash');
  var act=document.querySelector('.view-pane.active');if(act&&productions[act.id.replace('view-','')])trkRenderScope(act.id.replace('view-',''));}
/* ---------------- canvas rendering ---------------- */
function trkDrawAll(){var cs=document.querySelectorAll('canvas.trk-map');for(var i=0;i<cs.length;i++){var cv=cs[i];if(cv.offsetParent===null)continue;try{trkDrawCanvas(cv);}catch(e){}}}
function trkDrawCanvas(cv){var scope=cv.getAttribute('data-scope');var vw=trkView2(scope);
  var dpr=window.devicePixelRatio||1;var rect=cv.getBoundingClientRect();
  var w=Math.max(20,Math.floor(rect.width)),h=Math.max(20,Math.floor(rect.height));
  if(cv.width!==Math.floor(w*dpr)||cv.height!==Math.floor(h*dpr)){cv.width=Math.floor(w*dpr);cv.height=Math.floor(h*dpr);}
  var ctx=cv.getContext('2d');ctx.setTransform(dpr,0,0,dpr,0,0);ctx.clearRect(0,0,w,h);
  var devs=trkDevs(scope);
  var pois=[],geos=[];
  if(scope==='dash'){Object.keys(trkPOI).forEach(function(k){pois=pois.concat(trkPOI[k]);});Object.keys(trkGeos).forEach(function(k){geos=geos.concat(trkGeos[k]);});}
  else{pois=trkPOI[scope]||[];geos=trkGeos[scope]||[];}
  // view center / scale
  var pts=[];devs.forEach(function(d){var ps=trkPos[d.id];if(ps)pts.push(ps);});pois.forEach(function(p){pts.push(p.pos);});
  if(vw.follow&&vw.sel&&trkPos[vw.sel]){vw.clat=trkPos[vw.sel].lat;vw.clng=trkPos[vw.sel].lng;}
  if(vw.fit&&pts.length){var mnLa=1e9,mxLa=-1e9,mnLo=1e9,mxLo=-1e9;pts.forEach(function(p){mnLa=Math.min(mnLa,p.lat);mxLa=Math.max(mxLa,p.lat);mnLo=Math.min(mnLo,p.lng);mxLo=Math.max(mxLo,p.lng);});
    vw.clat=(mnLa+mxLa)/2;vw.clng=(mnLo+mxLo)/2;
    var spanN=Math.max(120,(mxLa-mnLa)*MPD_LAT),spanE=Math.max(120,(mxLo-mnLo)*mpdLng(vw.clat));
    vw.mpp=Math.max(spanN/(h-70),spanE/(w-70));if(!isFinite(vw.mpp)||vw.mpp<=0)vw.mpp=20;}
  else if(!pts.length){vw.clat=vw.clat||39.5;vw.clng=vw.clng||-98.35;}
  var clat=Math.max(-85,Math.min(85,vw.clat)),clng=vw.clng,mpp=vw.mpp;
  var WORLDpx=TRK_EARTH_C*Math.cos(clat*Math.PI/180)/mpp;
  var mcx=trkMercX(clng),mcy=trkMercN(clat);
  function PX(p){return {x:w/2+(trkMercX(p.lng)-mcx)*WORLDpx,y:h/2+(trkMercN(p.lat)-mcy)*WORLDpx};}
  cv.__proj={clat:clat,clng:clng,mpp:mpp,w:w,h:h,WORLDpx:WORLDpx,mcx:mcx,mcy:mcy};
  var darkMap=trkIsDark();
  // background: theme-aware basemap (falls back to a grid until tiles load)
  ctx.fillStyle=darkMap?'#18191a':'#f0f2f5';ctx.fillRect(0,0,w,h);
  var drewTiles=_trkDrawTiles(ctx,cv.__proj);
  if(!drewTiles){
    ctx.strokeStyle=darkMap?'rgba(8,102,255,0.10)':'rgba(101,103,107,0.18)';ctx.lineWidth=1;
    var gstep=Math.max(40,Math.min(120,mpp>0?(500/mpp):80));
    for(var gx=w/2%gstep;gx<w;gx+=gstep){ctx.beginPath();ctx.moveTo(gx,0);ctx.lineTo(gx,h);ctx.stroke();}
    for(var gy=h/2%gstep;gy<h;gy+=gstep){ctx.beginPath();ctx.moveTo(0,gy);ctx.lineTo(w,gy);ctx.stroke();}
  }
  var local=mpp<40;
  var ink=darkMap?'rgba(231,243,255,0.9)':'rgba(36,37,38,0.92)';
  var inkMuted=darkMap?'rgba(176,179,184,0.9)':'rgba(75,79,86,0.95)';
  var labelBg=darkMap?'rgba(24,25,26,0.82)':'rgba(255,255,255,0.92)';
  var labelFg=darkMap?'#e4e6eb':'#1c1e21';
  var scaleInk=darkMap?'rgba(231,243,255,0.6)':'rgba(62,64,66,0.75)';
  // roads between POIs (local only — skipped when the real basemap is drawn)
  if(local&&pois.length&&!drewTiles){ctx.strokeStyle=darkMap?'rgba(176,179,184,0.22)':'rgba(101,103,107,0.35)';ctx.lineWidth=6;ctx.lineCap='round';
    var byId={};pois.forEach(function(p){byId[p.id]=p;});
    [['venue','compound'],['venue','catering'],['compound','lot'],['venue','hotel'],['hotel','airport'],['venue','lot']].forEach(function(pair){var a=byId[pair[0]],b=byId[pair[1]];if(a&&b){var pa=PX(a.pos),pb=PX(b.pos);ctx.beginPath();ctx.moveTo(pa.x,pa.y);ctx.lineTo(pb.x,pb.y);ctx.stroke();}});
    ctx.strokeStyle=darkMap?'rgba(231,243,255,0.14)':'rgba(62,64,66,0.2)';ctx.lineWidth=2;
    [['venue','compound'],['venue','catering'],['compound','lot'],['venue','hotel'],['hotel','airport'],['venue','lot']].forEach(function(pair){var a=byId[pair[0]],b=byId[pair[1]];if(a&&b){var pa=PX(a.pos),pb=PX(b.pos);ctx.beginPath();ctx.moveTo(pa.x,pa.y);ctx.lineTo(pb.x,pb.y);ctx.stroke();}});}
  // geofences (local only)
  if(local){geos.forEach(function(g){var c=PX(g.center);var rp=g.radius/mpp;if(rp<3)return;
    ctx.beginPath();ctx.arc(c.x,c.y,rp,0,Math.PI*2);ctx.fillStyle=hexA(g.color,darkMap?0.08:0.12);ctx.fill();
    ctx.setLineDash([5,4]);ctx.strokeStyle=hexA(g.color,darkMap?0.55:0.7);ctx.lineWidth=1.2;ctx.stroke();ctx.setLineDash([]);
    ctx.fillStyle=hexA(g.color,darkMap?0.85:1);ctx.font='700 9px ui-monospace,SFMono-Regular,Menlo,Consolas,monospace';ctx.textAlign='center';ctx.fillText(g.name.toUpperCase(),c.x,c.y-rp-4);});}
  // POI markers (local only)
  if(local){pois.forEach(function(p){var c=PX(p.pos);ctx.fillStyle=ink;
    ctx.beginPath();ctx.moveTo(c.x,c.y-4);ctx.lineTo(c.x+4,c.y);ctx.lineTo(c.x,c.y+4);ctx.lineTo(c.x-4,c.y);ctx.closePath();ctx.fill();
    ctx.fillStyle=inkMuted;ctx.font='600 8px ui-monospace,SFMono-Regular,Menlo,Consolas,monospace';ctx.textAlign='left';ctx.fillText(p.name,c.x+7,c.y+3);});}
  // trails
  if(local){devs.forEach(function(d){var ps=trkPos[d.id];if(!ps||!ps.trail||ps.trail.length<2)return;var col=(TRK_CATS[d.cat]||{}).color||'#0866ff';
    for(var i=1;i<ps.trail.length;i++){var a=PX(ps.trail[i-1]),b=PX(ps.trail[i]);ctx.beginPath();ctx.moveTo(a.x,a.y);ctx.lineTo(b.x,b.y);
      ctx.strokeStyle=hexA(col,0.06+0.4*(i/ps.trail.length));ctx.lineWidth=2.2;ctx.stroke();}});}
  // devices
  devs.forEach(function(d){var ps=trkPos[d.id];if(!ps)return;var c=PX(ps);var cat=TRK_CATS[d.cat]||{color:'#65676b'};
    var col=d.status==='offline'?'#b0b3b8':cat.color;var sel=(vw.sel===d.id);
    if(sel){var pr=(Date.now()%1400)/1400;ctx.beginPath();ctx.arc(c.x,c.y,9+pr*10,0,Math.PI*2);ctx.strokeStyle=hexA(col,0.5*(1-pr));ctx.lineWidth=2;ctx.stroke();}
    if(ps.motion&&d.status!=='offline'){var ang=(ps.course-90)*Math.PI/180;ctx.save();ctx.translate(c.x,c.y);ctx.rotate(ang);
      ctx.beginPath();ctx.moveTo(9,0);ctx.lineTo(-4,-5);ctx.lineTo(-4,5);ctx.closePath();ctx.fillStyle=col;ctx.fill();ctx.restore();}
    ctx.beginPath();ctx.arc(c.x,c.y,sel?6:5,0,Math.PI*2);ctx.fillStyle=col;ctx.fill();ctx.lineWidth=2;ctx.strokeStyle=sel?'#ffffff':(darkMap?'rgba(24,25,26,0.9)':'rgba(255,255,255,0.95)');ctx.stroke();
    // label
    if(local||sel){var lbl=d.name.length>18?d.name.slice(0,17)+'…':d.name;var spd=ps.motion?'  '+Math.round(ps.speed)+' mph':(d.status==='offline'?'  offline':'');
      ctx.font='700 9px ui-monospace,SFMono-Regular,Menlo,Consolas,monospace';var tw=ctx.measureText(lbl+spd).width;var lx=c.x+9,ly=c.y-8;
      ctx.fillStyle=labelBg;if(ctx.roundRect){ctx.beginPath();ctx.roundRect(lx-3,ly-9,tw+9,13,3);ctx.fill();}else{ctx.fillRect(lx-3,ly-9,tw+9,13);}
      if(!darkMap){ctx.strokeStyle='rgba(28,30,33,0.12)';ctx.lineWidth=1;if(ctx.roundRect){ctx.beginPath();ctx.roundRect(lx-3,ly-9,tw+9,13,3);ctx.stroke();}else{ctx.strokeRect(lx-3,ly-9,tw+9,13);}}
      ctx.fillStyle=labelFg;ctx.textAlign='left';ctx.fillText(lbl,lx,ly);
      if(spd){ctx.fillStyle=hexA(col,1);ctx.fillText(spd,lx+ctx.measureText(lbl).width,ly);}}
  });
  // scale bar
  var target=w*0.22;var meters=target*mpp;var nice=Math.pow(10,Math.floor(Math.log(meters)/Math.LN10));var mult=meters/nice;mult=mult>=5?5:(mult>=2?2:1);var barM=nice*mult;var barPx=barM/mpp;
  ctx.strokeStyle=scaleInk;ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(12,h-14);ctx.lineTo(12+barPx,h-14);ctx.stroke();
  ctx.fillStyle=scaleInk;ctx.font='600 8px ui-monospace,SFMono-Regular,Menlo,Consolas,monospace';ctx.textAlign='left';ctx.fillText(barM>=1000?(barM/1000)+' km':Math.round(barM)+' m',12,h-18);
  // north arrow
  ctx.fillStyle=scaleInk;ctx.font='700 9px ui-monospace,SFMono-Regular,Menlo,Consolas,monospace';ctx.textAlign='center';ctx.fillText('N',w-16,h-22);
  ctx.beginPath();ctx.moveTo(w-16,h-32);ctx.lineTo(w-19,h-24);ctx.lineTo(w-13,h-24);ctx.closePath();ctx.fillStyle=scaleInk;ctx.fill();
  if(!cv.__trkWired)trkWireCanvas(cv);
}
function trkWireCanvas(cv){cv.__trkWired=true;var scope=cv.getAttribute('data-scope');var drag=null;
  cv.addEventListener('mousedown',function(e){drag={x:e.clientX,y:e.clientY,moved:0};cv.style.cursor='grabbing';});
  window.addEventListener('mouseup',function(){if(drag)cv.style.cursor='grab';drag=null;});
  cv.addEventListener('mousemove',function(e){if(!drag||!cv.__proj)return;var dx=e.clientX-drag.x,dy=e.clientY-drag.y;drag.x=e.clientX;drag.y=e.clientY;drag.moved+=Math.abs(dx)+Math.abs(dy);
    var vw=trkView2(scope);vw.fit=false;vw.follow=false;var pr=cv.__proj;
    /* Mercator pan: convert the screen delta through the world-pixel scale */
    vw.clng-=(dx/pr.WORLDpx)*360;
    vw.clat=Math.max(-85,Math.min(85,trkInvMercN(trkMercN(vw.clat)-dy/pr.WORLDpx)));});
  cv.addEventListener('click',function(e){if(drag&&drag.moved>5)return;if(!cv.__proj)return;var rect=cv.getBoundingClientRect();var mx=e.clientX-rect.left,my=e.clientY-rect.top;var pr=cv.__proj;
    var best=null,bd=22;trkDevs(scope).forEach(function(d){var ps=trkPos[d.id];if(!ps)return;var x=pr.w/2+(trkMercX(ps.lng)-pr.mcx)*pr.WORLDpx,y=pr.h/2+(trkMercN(ps.lat)-pr.mcy)*pr.WORLDpx;var dd=Math.hypot(x-mx,y-my);if(dd<bd){bd=dd;best=d;}});
    if(best){trkSelect(scope,best.id);trkRenderScope(scope);}});
  /* Cooperative scroll: plain wheel scrolls the page; ⌘/Ctrl+wheel (or trackpad pinch) zooms the map */
  cv.addEventListener('wheel',function(e){
    var zoomGesture=e.ctrlKey||e.metaKey||e.altKey;
    if(!zoomGesture)return; /* let the page scroll */
    e.preventDefault();
    var vw=trkView2(scope);vw.fit=false;vw.follow=false;
    var f=e.deltaY<0?0.85:1.18;vw.mpp=Math.max(1,Math.min(9000,vw.mpp*f));
  },{passive:false});
}
function trkEnsureLoop(){if(trkLoopOn)return;trkLoopOn=true;trkClock=Date.now();
  function trkAnyVisible(){try{var cs=document.querySelectorAll('canvas.trk-map');for(var i=0;i<cs.length;i++){if(cs[i].offsetParent!==null)return true;}}catch(e){}return false;}
  function frame(){if(!trkLoopOn)return;var now=Date.now();var dt=(now-trkClock)/1000;trkClock=now;
    var vis=trkAnyVisible();
    var phone=false;try{phone=!!(window.matchMedia&&window.matchMedia('(max-width:767px)').matches);}catch(eP){}
    if(vis){
      if(!trkPaused){try{trkStep(dt);}catch(e){}}
      try{trkDrawAll();}catch(e){}
      if(now-trkLastDom>(phone?900:650)){trkLastDom=now;try{
        var seen={};document.querySelectorAll('canvas.trk-map').forEach(function(cv){if(cv.offsetParent===null)return;var sc=cv.getAttribute('data-scope');if(seen[sc])return;seen[sc]=1;trkRenderScope(sc);});
      }catch(e){}}
    }
    var wait=vis?(phone?180:16):800;
    if(wait<=16)(window.requestAnimationFrame||function(f){setTimeout(f,60);})(frame);
    else setTimeout(function(){(window.requestAnimationFrame||function(f){setTimeout(f,60);})(frame);},wait);
  }
  (window.requestAnimationFrame||function(f){setTimeout(f,60);})(frame);}

function trackInit(){trkInitModel();try{renderTracking();}catch(e){}trkEnsureLoop();}

