/* ---------------- shared helpers ---------------- */
function prodName(k){return productions[k]?(productions[k].tab||productions[k].name):k;}
function $fmt(n){return '$'+(Math.round(n)||0).toLocaleString();}
function finToday(){return new Date().toISOString().slice(0,10);}
function invOverdue(v){return v.status!=='Paid'&&v.due&&v.due<finToday();}
function woStatusPill(s,extra){var m={'Draft':'bg-gray-100 text-gray-600 border-gray-200','Confirmed':'bg-blue-50 text-blue-700 border-blue-200','In Progress':'bg-amber-50 text-amber-700 border-amber-200','Complete':'bg-emerald-50 text-emerald-700 border-emerald-200','Invoiced':'bg-purple-50 text-purple-700 border-purple-200','Issued':'bg-blue-50 text-blue-700 border-blue-200','Acknowledged':'bg-cyan-50 text-cyan-700 border-cyan-200','Fulfilled':'bg-emerald-50 text-emerald-700 border-emerald-200','Closed':'bg-gray-100 text-gray-500 border-gray-200','Received':'bg-gray-100 text-gray-600 border-gray-200','Approved':'bg-blue-50 text-blue-700 border-blue-200','Scheduled':'bg-amber-50 text-amber-700 border-amber-200','Paid':'bg-emerald-50 text-emerald-700 border-emerald-200','Overdue':'bg-red-50 text-red-700 border-red-200','Hold':'bg-gray-100 text-gray-600 border-gray-200','Booked':'bg-blue-50 text-blue-700 border-blue-200','Line-Up':'bg-amber-50 text-amber-700 border-amber-200','Live':'bg-red-50 text-red-700 border-red-200'};
  return '<span class="text-[8px] font-bold mono border rounded px-1.5 py-0.5 '+(m[s]||m.Draft)+'">'+(extra||'')+s.toUpperCase()+'</span>';}
function fmtWin(s,e){function f(x){var d=new Date(x);return d.toLocaleDateString('en-US',{month:'short',day:'numeric'})+' '+d.toTimeString().slice(0,5);}
  return f(s)+' → '+new Date(e).toTimeString().slice(0,5);}
function fmtD(d){if(!d)return '—';var x=new Date(d+'T00:00');return isNaN(x)?d:x.toLocaleDateString('en-US',{month:'short',day:'numeric',year:'numeric'});}

/* ---------------- conflict & capacity engine ---------------- */
function txOverlap(a,b){return a.res===b.res&&new Date(a.start)<new Date(b.end)&&new Date(b.start)<new Date(a.end);}
function txConflicts(){var flags={};var notes=[];var resources={};
  txBookings.forEach(function(b){
    var start=+new Date(b.start),end=+new Date(b.end),bw=Number(b.bw);
    if(!isFinite(start)||!isFinite(end)||end<=start||!isFinite(bw)||bw<0||b.bw==null||b.bw===''){
      flags[b.id]=true;notes.push({ids:[b.id],res:b.res,text:b.id+' — invalid booking window or bandwidth'});return;
    }
    if(!resources[b.res])resources[b.res]=[];
    resources[b.res].push({booking:b,start:start,end:end,bw:bw});
  });
  Object.keys(resources).forEach(function(res){
    var rows=resources[res],cap=Number((TX_RES[res]||{}).cap),times=[];
    rows.forEach(function(r){times.push(r.start,r.end);});
    times.sort(function(a,b){return a-b;});
    for(var i=0;i<times.length-1;i++){
      if(times[i]===times[i+1])continue;
      var active=rows.filter(function(r){return r.start<=times[i]&&r.end>times[i];});
      if(!active.length)continue;
      var sum=active.reduce(function(n,r){return n+r.bw;},0);
      if(!isFinite(cap)||cap<=0||sum>cap){
        var ids=active.map(function(r){flags[r.booking.id]=true;return r.booking.id;});
        notes.push({ids:ids,res:res,text:ids.join(', ')+' — '+(!isFinite(cap)||cap<=0?'unverified capacity for '+res:'oversubscribe '+res+' — '+sum+' of '+cap+' Mbps in the overlap window')});
      }
    }
  });
  return {flags:flags,notes:notes};}

/* ---------------- per-production financial math ---------------- */
function finCommitted(key){var c=0;
  finPOs.forEach(function(po){if(po.prod===key&&po.status!=='Draft')c+=po.amount;});
  workOrders.forEach(function(w){if(w.prod===key&&w.status!=='Draft'&&!finPOs.some(function(po){return po.prod===key&&po.wo===w.id&&po.status!=='Draft';}))c+=w.cost;});
  txBookings.forEach(function(t){if(t.prod===key&&t.status!=='Hold')c+=(t.cost||0);});
  return c;}
function finInvoiced(key){var c=0;finInvoices.forEach(function(v){if(v.prod===key)c+=v.amount;});return c;}
function finPaid(key){var c=0;finInvoices.forEach(function(v){if(v.prod===key&&v.status==='Paid')c+=v.amount;});return c;}
function finOverdueList(key){return finInvoices.filter(function(v){return (key?v.prod===key:true)&&invOverdue(v);});}
function finExceptions(key){var ex=[];
  finOverdueList(key).forEach(function(v){var days=Math.round((new Date(finToday())-new Date(v.due))/864e5);
    ex.push({sev:'red',text:v.id+' '+v.vendor+' '+$fmt(v.amount)+' is OVERDUE by '+days+' day'+(days===1?'':'s')+' (due '+fmtD(v.due)+') — status '+v.status});});
  workOrders.forEach(function(w){if(w.prod!==key)return;
    if((w.status==='Complete'||w.status==='Invoiced')&&!finInvoices.some(function(v){return v.prod===key&&(v.ref===w.id||finPOs.some(function(po){return po.id===v.ref&&po.wo===w.id;}));}))
      ex.push({sev:'amber',text:w.id+' "'+w.desc+'" is '+w.status+' but no vendor invoice has been received — '+$fmt(w.cost)+' unbilled'});});
  finPOs.forEach(function(po){if(po.prod!==key)return;
    if(po.status==='Fulfilled'&&!finInvoices.some(function(v){return v.ref===po.id;}))
      ex.push({sev:'amber',text:po.id+' '+po.vendor+' is Fulfilled with no invoice on file — expect '+$fmt(po.amount)});});
  finInvoices.forEach(function(v){if(v.prod!==key)return;
    if(!v.ref)ex.push({sev:'amber',text:v.id+' '+v.vendor+' '+$fmt(v.amount)+' has no PO / WO reference — uncommitted spend'});});
  return ex;}
function finTabBadge(key){var n=finOverdueList(key).length;
  return n?(typeof museBadgeHTML==='function'?museBadgeHTML(n):''):'';}
function openProjFinance(key){
  if(!productions[key])return;
  var host=document.getElementById('view-finance');
  if(!host){projSubTab[key]='finance';switchView(key);return;}
  finWsTab[key]='gl'; /* open on general ledger inside Finance, not the project workspace */
  host.innerHTML=financeWorkspaceHTML(key);
}
/* Finance stays on the finance page; a modal shows the production's roll-up without navigating. */
function openProjFinancePopup(key){
  var p=productions[key];if(!p)return;
  var ov=document.getElementById('finProjOverlay'),bx=document.getElementById('finProjBox');
  if(!ov||!bx){openProjFinance(key);return;}
  var r=finReportTotals(key);var budget=finBudgets[key]||0;
  var over=r.variance<0;var pct=budget?Math.round(r.efc/budget*100):0;
  var pos=finPOs.filter(function(x){return x.prod===key;});
  var openPO=pos.filter(function(x){return x.status!=='Fulfilled'&&x.status!=='Closed';});
  var openPOTotal=openPO.reduce(function(s,x){return s+(x.amount||0);},0);
  var invs=finInvoices.filter(function(v){return v.prod===key;});
  var openInv=invs.filter(function(v){return v.status!=='Paid';});
  var openInvTotal=openInv.reduce(function(s,v){return s+(v.amount||0);},0);
  var overdue=finOverdueList(key);
  var recent=invs.slice().sort(function(a,b){return (b.recd||'').localeCompare(a.recd||'');}).slice(0,3);
  function kpi(l,v,sub,tone){return '<div class="rounded-xl border border-gray-200 p-3 bg-gray-50/60"><div class="text-[9px] font-bold uppercase tracking-wider text-gray-500">'+l+'</div><div class="text-lg font-bold mono '+(tone||'text-gray-900')+' mt-1">'+v+'</div>'+(sub?'<div class="text-[10px] text-gray-500 mt-0.5">'+sub+'</div>':'')+'</div>';}
  function sumLine(label,count,amount,tone){return '<div class="flex items-center justify-between py-1.5 text-[11px]"><span class="text-gray-600">'+label+'</span><span class="mono '+(tone||'text-gray-900')+'"><b>'+count+'</b> · '+$fmt(amount)+'</span></div>';}
  var recentHTML=recent.length?recent.map(function(v){
    var paid=v.status==='Paid';var late=invOverdue(v);
    return '<div class="flex items-center gap-2 py-1 text-[11px]"><span class="w-1.5 h-1.5 rounded-full flex-shrink-0" style="background:'+(paid?'#1E7B34':late?'#E41E3F':'#B26B00')+'"></span>'+
      '<span class="mono text-[10px] text-gray-500 flex-shrink-0" style="width:5.5rem">'+esc(v.id||'')+'</span>'+
      '<span class="text-gray-800 truncate flex-1">'+esc(v.vendor||'')+'</span>'+
      '<span class="mono font-semibold text-gray-900 flex-shrink-0">'+$fmt(v.amount||0)+'</span>'+
      '<span class="text-[9px] uppercase font-bold flex-shrink-0 '+(paid?'text-emerald-700':late?'text-red-600':'text-amber-700')+'" style="width:3.5rem;text-align:right">'+esc(v.status||'')+'</span></div>';
  }).join(''):'<p class="text-[10px] text-gray-400 py-2">No invoices on file yet.</p>';
  bx.innerHTML='<div class="flex items-start justify-between pb-3 border-b border-gray-200 mb-4">'+
      '<div><h3 class="text-base font-bold text-gray-900">'+esc(prodName(key))+' · Finance Overview</h3><p class="text-[10px] text-gray-500 mt-0.5">Snapshot — Open full ledger drills into the general ledger for this production.</p></div>'+
      '<button onclick="closeProjFinancePopup()" class="text-gray-400 hover:text-gray-700 text-lg leading-none">✕</button></div>'+
    '<div class="grid grid-cols-2 sm:grid-cols-4 gap-2 mb-4">'+
      kpi('Budget',$fmt(budget))+
      kpi('EFC',$fmt(r.efc),pct?pct+'% of budget':'',over?'text-red-600':'text-gray-900')+
      kpi('Actual',$fmt(r.actual),'invoiced to date')+
      kpi('Variance',(r.variance>=0?'+':'')+$fmt(r.variance),over?'over budget':'under budget',over?'text-red-600':'text-emerald-700')+
    '</div>'+
    '<div class="rounded-xl border border-gray-200 p-3 mb-3">'+
      '<div class="text-[9px] font-bold uppercase tracking-wider text-gray-500 mb-1">AP / PO snapshot</div>'+
      sumLine('Open purchase orders',openPO.length,openPOTotal)+
      sumLine('Open invoices',openInv.length,openInvTotal,openInv.length?'text-amber-700':'text-gray-900')+
      (overdue.length?sumLine('Overdue invoices',overdue.length,overdue.reduce(function(s,v){return s+(v.amount||0);},0),'text-red-600'):'')+
    '</div>'+
    '<div class="rounded-xl border border-gray-200 p-3 mb-3">'+
      '<div class="text-[9px] font-bold uppercase tracking-wider text-gray-500 mb-1">Recent invoices</div>'+recentHTML+
    '</div>'+
    '<div class="flex items-center justify-end gap-2 pt-2 border-t border-gray-100">'+
      '<button onclick="closeProjFinancePopup()" class="text-[11px] font-bold text-gray-700 border border-gray-300 rounded-lg px-3 py-1.5 hover:bg-gray-50">Close</button>'+
      '<button onclick="closeProjFinancePopup();openProjFinance(\''+key+'\')" class="text-[11px] font-bold text-white bg-gray-900 rounded-lg px-3 py-1.5 hover:bg-gray-800">Open full ledger →</button></div>';
  ov.style.display='flex';
}
function closeProjFinancePopup(){var ov=document.getElementById('finProjOverlay');if(ov)ov.style.display='none';}
/* ---------------- mutations (all log + persist + re-render) ---------------- */
function finRefresh(key){saveOps();renderOps();
  var act=document.querySelector('.view-pane.active');if(act&&act.id==='view-'+key){try{renderProjectView(key);}catch(e){}}}
function advanceWO(id){for(var i=0;i<workOrders.length;i++){var w=workOrders[i];if(w.id!==id)continue;
  w.status=WO_FLOW[(WO_FLOW.indexOf(w.status)+1)%WO_FLOW.length];
  try{logEvent(w.prod,'🛠 '+w.id+' '+w.desc+' → '+w.status);saveState();}catch(e){}
  toast(w.id+' → '+w.status);finRefresh(w.prod);return;}}
function advancePO(id){for(var i=0;i<finPOs.length;i++){var p=finPOs[i];if(p.id!==id)continue;
  p.status=PO_FLOW[(PO_FLOW.indexOf(p.status)+1)%PO_FLOW.length];
  try{logEvent(p.prod,'📄 '+p.id+' '+p.vendor+' → '+p.status);saveState();}catch(e){}
  toast(p.id+' → '+p.status);finRefresh(p.prod);return;}}
function advanceInv(id){for(var i=0;i<finInvoices.length;i++){var v=finInvoices[i];if(v.id!==id)continue;
  v.status=INV_FLOW[(INV_FLOW.indexOf(v.status)+1)%INV_FLOW.length];if(v.status==='Paid')v.paidOn=finToday();else v.paidOn='';
  try{logEvent(v.prod,'💵 '+v.id+' '+v.vendor+' '+$fmt(v.amount)+' → '+v.status+(v.paidOn?' on '+fmtD(v.paidOn):''));saveState();}catch(e){}
  toast(v.id+' → '+v.status);finRefresh(v.prod);return;}}
function payInv(id){for(var i=0;i<finInvoices.length;i++){var v=finInvoices[i];if(v.id!==id)continue;
  if(v.status==='Paid')return;v.status='Paid';v.paidOn=finToday();
  try{logEvent(v.prod,'✓ PAID — '+v.id+' '+v.vendor+' '+$fmt(v.amount)+' settled '+fmtD(v.paidOn));saveState();}catch(e){}
  toast(v.id+' marked PAID');finRefresh(v.prod);return;}}
function advanceTx(id){for(var i=0;i<txBookings.length;i++){var t=txBookings[i];if(t.id!==id)continue;
  t.status=TX_FLOW[(TX_FLOW.indexOf(t.status)+1)%TX_FLOW.length];
  try{logEvent(t.prod,'📡 '+t.id+' '+t.src+' → '+t.dst+' via '+t.res+' → '+t.status);saveState();}catch(e){}
  toast(t.id+' → '+t.status);finRefresh(t.prod);return;}}
function finAddDoc(kind,id){var name=prompt('Document filename to attach to '+id+':','');if(!name)return;
  var list=kind==='po'?finPOs:finInvoices;for(var i=0;i<list.length;i++){if(list[i].id!==id)continue;
    if(!list[i].docs)list[i].docs=[];list[i].docs.push(name);
    try{logEvent(list[i].prod,'📎 '+name+' attached to '+id);saveState();}catch(e){}
    toast('Attached '+name);finRefresh(list[i].prod);return;}}
/* ---------------- PRODUCTION FINANCE TAB ---------------- */
/* ===== v28 (Work Item 7): AP aging + workspace helpers ===== */
var finWsSort=(typeof finWsSort!=='undefined')?finWsSort:{};   /* '<key>.<pane>' -> {col,dir} */
var finWsQ=(typeof finWsQ!=='undefined')?finWsQ:{};            /* '<key>.<pane>' -> search string */
var apFilter=(typeof apFilter!=='undefined')?apFilter:{};      /* key -> all|open|approved|paid */
function finWsSortSet(key,pane,col){var id=key+'.'+pane;var s=finWsSort[id]||{};
  if(s.col===col)s.dir=(s.dir==='asc'?'desc':'asc');else s={col:col,dir:'desc'};
  finWsSort[id]=s;renderProjectView(key);}
function finWsQSet(key,pane,v){finWsQ[key+'.'+pane]=(v||'').toLowerCase();renderProjectView(key);}
function finThSort(key,pane,col,label,align){var s=finWsSort[key+'.'+pane]||{};
  var arrow=s.col===col?(s.dir==='asc'?' ▲':' ▼'):'';
  return '<th onclick="finWsSortSet(\''+key+'\',\''+pane+'\',\''+col+'\')" class="fin-th p-1.5 text-[8px] font-bold uppercase tracking-wider '+(s.col===col?'text-blue-700':'text-gray-400')+' '+(align||'text-left')+'" title="Sort by '+label+'">'+label+arrow+'</th>';}
function apStatusLabel(v){if(v.status==='Paid')return 'Paid';if(v.status==='Approved'||v.status==='Scheduled')return 'Approved';return 'Open';}
function apAgingDays(v){try{var from=new Date(v.recd||finToday());var to=v.status==='Paid'?new Date(v.paidOn||finToday()):new Date(finToday());
  return Math.max(0,Math.round((to-from)/86400000));}catch(e){return 0;}}
function apAgingBucket(d){if(d<=30)return {l:'0–30',c:'#1E7B34'};if(d<=60)return {l:'31–60',c:'#f5832a'};if(d<=90)return {l:'61–90',c:'#f5832a'};return {l:'90+',c:'#e41e3f'};}
function apSetFilter(key,f){apFilter[key]=(apFilter[key]===f)?'all':f;renderProjectView(key);}
/* sortable + filterable AP Ledger table (Work Item 7) */
function apTablePaneHTML(key){
  var all=finInvoices.filter(function(v){return v.prod===key;});
  var f=apFilter[key]||'all';var q=finWsQ[key+'.ap']||'';
  var list=all.filter(function(v){if(f!=='all'&&apStatusLabel(v).toLowerCase()!==f)return false;
    if(q){var hay=(v.id+' '+v.vendor+' '+(v.ref||'')+' '+apStatusLabel(v)).toLowerCase();if(hay.indexOf(q)<0)return false;}
    return true;});
  var s=finWsSort[key+'.ap']||{col:'aging',dir:'desc'};
  var getters={vendor:function(v){return (v.vendor||'').toLowerCase();},id:function(v){return v.id;},po:function(v){return v.ref||'';},
    amount:function(v){return v.amount||0;},status:function(v){return apStatusLabel(v);},aging:function(v){return apAgingDays(v);}};
  var g=getters[s.col]||getters.aging;
  list.sort(function(a,b){var x=g(a),y=g(b);if(x<y)return s.dir==='asc'?-1:1;if(x>y)return s.dir==='asc'?1:-1;return 0;});
  var buckets={'0–30':0,'31–60':0,'61–90':0,'90+':0};
  all.forEach(function(v){if(v.status!=='Paid')buckets[apAgingBucket(apAgingDays(v)).l]+=(v.amount||0);});
  function fchip(fk,label,n){var on=(f===fk);return '<button onclick="apSetFilter(\''+key+'\',\''+fk+'\')" class="text-[9px] font-bold px-2 py-1 rounded-lg border '+(on?'bg-gray-900 text-white border-gray-900':'bg-white text-gray-600 border-gray-200 hover:border-gray-400')+'">'+label+' <span class="opacity-60">'+n+'</span></button>';}
  var chips=fchip('open','Open',all.filter(function(v){return apStatusLabel(v)==='Open';}).length)+
    fchip('approved','Approved',all.filter(function(v){return apStatusLabel(v)==='Approved';}).length)+
    fchip('paid','Paid',all.filter(function(v){return apStatusLabel(v)==='Paid';}).length);
  var rows=list.map(function(v){var d=apAgingDays(v);var bk=apAgingBucket(d);var lab=apStatusLabel(v);
    var sc=lab==='Paid'?'bg-emerald-50 text-emerald-700 border-emerald-200':(lab==='Approved'?'bg-blue-50 text-blue-700 border-blue-200':'bg-amber-50 text-amber-700 border-amber-200');
    return '<tr class="border-t border-gray-100 hover:bg-gray-50 cursor-pointer" onclick="openFinDoc(\'inv\',\''+v.id+'\')" title="Open invoice document">'+
      '<td class="p-1.5 text-[10px] font-bold text-gray-900">'+esc(v.vendor)+'</td>'+
      '<td class="p-1.5 text-[9px] mono text-gray-600">'+v.id+'</td>'+
      '<td class="p-1.5 text-[9px] mono text-gray-500">'+(v.ref||'—')+'</td>'+
      '<td class="p-1.5 text-right text-[10px] mono font-bold text-gray-800">'+$fmt(v.amount)+'</td>'+
      '<td class="p-1.5 text-center" onclick="event.stopPropagation()"><button onclick="advanceInv(\''+v.id+'\')" title="Advance status" class="text-[8px] font-bold border rounded px-1.5 py-0.5 '+sc+'">'+lab.toUpperCase()+'</button></td>'+
      '<td class="p-1.5 text-right text-[9px] mono text-gray-600">'+d+'d</td>'+
      '<td class="p-1.5"><span class="text-[8px] font-bold mono px-1.5 py-0.5 rounded" style="background:'+bk.c+'22;color:'+bk.c+'">'+bk.l+'</span></td></tr>';
  }).join('')||'<tr><td colspan="7" class="p-4 text-center text-[10px] text-gray-400">No invoices match.</td></tr>';
  return '<div class="bg-white rounded-2xl p-4 sm:p-5 border border-gray-200/60" style="box-shadow:0 4px 20px rgba(0,0,0,.03)">'+
    '<div class="flex flex-wrap items-center justify-between gap-2 mb-2"><h3 class="text-[10px] font-bold uppercase tracking-wider text-gray-600">AP Ledger — sortable · click a row for the document</h3>'+
      '<div class="flex items-center gap-1.5 flex-wrap">'+chips+
      '<input value="'+esc(q).replace(/"/g,'&quot;')+'" onchange="finWsQSet(\''+key+'\',\'ap\',this.value)" placeholder="Search vendor, #, PO…" class="text-[10px] border border-gray-200 rounded-lg px-2 py-1" style="outline:none;width:150px"></div></div>'+
    '<div class="flex items-center gap-2 mb-2 text-[8px] mono text-gray-500 flex-wrap">Aging (unpaid): '+Object.keys(buckets).map(function(b){var col=b==='0–30'?'#1E7B34':(b==='31–60'?'#f5832a':(b==='61–90'?'#f5832a':'#e41e3f'));
      return '<span class="px-1.5 py-0.5 rounded" style="background:'+col+'18;color:'+col+'">'+b+'d · '+$fmt(buckets[b])+'</span>';}).join('')+'</div>'+
    '<div class="overflow-x-auto"><table class="w-full" style="min-width:640px"><thead><tr>'+
      finThSort(key,'ap','vendor','Vendor')+finThSort(key,'ap','id','Invoice #')+finThSort(key,'ap','po','PO')+
      finThSort(key,'ap','amount','Amount','text-right')+finThSort(key,'ap','status','Status','text-center')+
      finThSort(key,'ap','aging','Aging','text-right')+'<th class="p-1.5 text-[8px] font-bold uppercase tracking-wider text-gray-400">Bucket</th>'+
    '</tr></thead><tbody>'+rows+'</tbody></table></div></div>';}
/* inline-SVG analytics band (Work Item 7) */
function finAnalyticsHTML(key){
  var cats=finActiveCats(key).filter(function(c){return finCatBudget(key,c)||finCatEFC(key,c);});
  var maxV=1;cats.forEach(function(c){maxV=Math.max(maxV,finCatBudget(key,c),finCatEFC(key,c));});
  var bw=460,rh=13,gap=5,lh=cats.length*(rh*2+gap+4)+8;
  var bars=cats.map(function(c,i){var y=i*(rh*2+gap+4);var b=finCatBudget(key,c),e=finCatEFC(key,c);var over=e>b;
    return '<text x="0" y="'+(y+10)+'" font-size="8" fill="#65676B" font-family="-apple-system,BlinkMacSystemFont,Segoe UI,Roboto,Helvetica,Arial,sans-serif">'+esc((c||'—')+' '+finCatName(c)).slice(0,34)+'</text>'+
      '<rect x="150" y="'+(y+2)+'" width="'+Math.max(1,b/maxV*(bw-230))+'" height="'+rh+'" rx="2" fill="#b0b3b8" opacity="0.55"><title>Budget '+$fmt(b)+'</title></rect>'+
      '<rect x="150" y="'+(y+rh+4)+'" width="'+Math.max(1,e/maxV*(bw-230))+'" height="'+rh+'" rx="2" fill="'+(over?'#e41e3f':'#1E7B34')+'"><title>EFC '+$fmt(e)+'</title></rect>'+
      '<text x="'+(152+Math.max(1,e/maxV*(bw-230)))+'" y="'+(y+rh+14)+'" font-size="7.5" font-family="ui-monospace,monospace" fill="'+(over?'#e41e3f':'#1E7B34')+'">'+$fmt(e)+'</text>';
  }).join('');
  var chart1='<svg viewBox="0 0 '+bw+' '+Math.max(lh,40)+'" style="width:100%;height:auto">'+bars+'</svg>';
  var all=finInvoices.filter(function(v){return v.prod===key&&v.status!=='Paid';});
  var bkt={'0–30':0,'31–60':0,'61–90':0,'90+':0};all.forEach(function(v){bkt[apAgingBucket(apAgingDays(v)).l]+=(v.amount||0);});
  var bkeys=Object.keys(bkt);var bmax=Math.max.apply(null,bkeys.map(function(b){return bkt[b];}).concat([1]));
  var cols={'0–30':'#1E7B34','31–60':'#f5832a','61–90':'#f5832a','90+':'#e41e3f'};
  var chart2='<svg viewBox="0 0 200 120" style="width:100%;height:auto">'+bkeys.map(function(b,i){var h=Math.max(2,bkt[b]/bmax*82);
    return '<rect x="'+(14+i*47)+'" y="'+(94-h)+'" width="32" height="'+h+'" rx="3" fill="'+cols[b]+'"><title>'+b+'d — '+$fmt(bkt[b])+'</title></rect>'+
      '<text x="'+(30+i*47)+'" y="105" text-anchor="middle" font-size="7.5" fill="#65676B" font-family="-apple-system,BlinkMacSystemFont,Segoe UI,Roboto,Helvetica,Arial,sans-serif">'+b+'d</text>'+
      '<text x="'+(30+i*47)+'" y="'+(90-h)+'" text-anchor="middle" font-size="7" font-family="ui-monospace,monospace" fill="#65676B">'+(bkt[b]?Math.round(bkt[b]/1000)+'k':'')+'</text>';}).join('')+'</svg>';
  var mix=cats.map(function(c){return {c:c,v:finCatActual(key,c)};}).filter(function(x){return x.v>0;}).sort(function(a,b){return b.v-a.v;});
  var mixTot=mix.reduce(function(s,x){return s+x.v;},0)||1;
  var MIXCOLS=['#0866ff','#0866ff','#1E7B34','#f5832a','#e41e3f','#0a58ca','#f5832a','#0866ff','#31a24c'];
  var a0=-Math.PI/2,dSegs='',legend='';
  mix.slice(0,7).concat(mix.length>7?[{c:'other',v:mix.slice(7).reduce(function(s,x){return s+x.v;},0)}]:[]).forEach(function(x,i){
    var frac=x.v/mixTot;var a1=a0+frac*Math.PI*2;
    var x0=60+46*Math.cos(a0),y0=60+46*Math.sin(a0),x1=60+46*Math.cos(a1),y1=60+46*Math.sin(a1);
    var large=frac>0.5?1:0;var col=MIXCOLS[i%MIXCOLS.length];
    if(frac>0.001)dSegs+='<path d="M '+x0.toFixed(1)+' '+y0.toFixed(1)+' A 46 46 0 '+large+' 1 '+x1.toFixed(1)+' '+y1.toFixed(1)+'" stroke="'+col+'" stroke-width="16" fill="none"><title>'+esc(x.c==='other'?'Other':finCatName(x.c))+' — '+$fmt(x.v)+'</title></path>';
    legend+='<div class="flex items-center gap-1"><span class="w-2 h-2 rounded-sm flex-shrink-0" style="background:'+col+'"></span><span class="text-[8px] text-gray-500 truncate">'+esc(x.c==='other'?'Other':finCatName(x.c))+'</span><span class="text-[8px] mono text-gray-400 ml-auto">'+Math.round(frac*100)+'%</span></div>';
    a0=a1;});
  var chart3='<div class="flex items-center gap-3"><svg viewBox="0 0 120 120" style="width:104px;height:104px;flex-shrink:0">'+(dSegs||'<circle cx="60" cy="60" r="46" stroke="#e4e6eb" stroke-width="16" fill="none"/>')+'</svg><div class="min-w-0 flex-1 space-y-0.5">'+(legend||'<p class="text-[9px] text-gray-400">No invoiced spend yet.</p>')+'</div></div>';
  function panel(t,inner){return '<div class="bg-white rounded-2xl p-4 border border-gray-200/60" style="box-shadow:0 4px 20px rgba(0,0,0,.03)"><h3 class="text-[9px] font-bold uppercase tracking-wider text-gray-500 mb-2">'+t+'</h3>'+inner+'</div>';}
  return '<div class="grid grid-cols-1 lg:grid-cols-3 gap-4">'+
    panel('Budget vs EFC by account <span class="normal-case font-normal text-gray-400">— gray budget · green/red projected</span>',chart1)+
    panel('Open AP aging',chart2)+
    panel('Invoiced spend mix',chart3)+'</div>';}
/* import/export toolbar (Work Item 7) */
function finToolbarHTML(key){
  function b(fn,label,tone){return '<button onclick="'+fn+'" class="text-[9px] font-bold rounded-lg px-2 py-1.5 border '+(tone||'text-gray-600 border-gray-200 bg-white hover:bg-gray-50')+'">'+label+'</button>';}
  return '<div class="bg-white rounded-2xl px-4 py-2.5 border border-gray-200/60 flex flex-wrap items-center gap-1.5" style="box-shadow:0 4px 20px rgba(0,0,0,.03)">'+
    b('openMasterData()','🏛 WBS / Cost Centers','text-purple-700 border-purple-200 bg-purple-50 hover:bg-purple-100')+
    '<span class="text-[8px] text-gray-300 mx-0.5">·</span>'+
    '<span class="text-[8px] font-bold uppercase tracking-wider text-gray-400 mr-1">Excel</span>'+
    b('xlsxImportOpen(null,\''+key+'\')','⬆ Import .xlsx','text-white bg-gray-900 border-gray-900 hover:bg-gray-800')+
    '<span class="text-[8px] text-gray-300 mx-0.5">·</span><span class="text-[8px] font-bold uppercase tracking-wider text-gray-400">Templates</span>'+
    b('xlsxTemplate(\'finance_cost\')','Cost')+b('xlsxTemplate(\'finance_labor\')','Labor')+b('xlsxTemplate(\'finance_ap\')','AP')+
    '<span class="text-[8px] text-gray-300 mx-0.5">·</span><span class="text-[8px] font-bold uppercase tracking-wider text-gray-400">Export .xlsx</span>'+
    b('xlsxExport(\'finance_cost\',\''+key+'\')','Cost')+b('xlsxExport(\'finance_labor\',\''+key+'\')','Labor')+b('xlsxExport(\'finance_ap\',\''+key+'\')','AP')+
    b('xlsxExportFinanceAll(\''+key+'\')','Combined','text-emerald-700 border-emerald-300 bg-emerald-50 hover:bg-emerald-100')+
    '<span class="text-[8px] text-gray-300 mx-0.5">·</span><span class="text-[8px] font-bold uppercase tracking-wider text-gray-400">PDF</span>'+
    b('finWsPDF(\''+key+'\',(finView[\''+key+'\']===\'labor\'?\'labor\':(finView[\''+key+'\']===\'report\'?\'cost\':\'ap\')))','This view')+
    b('finWsPDF(\''+key+'\',\'all\')','Combined')+
    '<span class="text-[8px] mono text-gray-400 ml-auto" title="Microsoft Graph Excel client is wired but dormant">Graph Excel API: <b>dormant stub</b></span></div>';}

function financePaneHTML(key){var p=productions[key];var conf=txConflicts();
  var budget=finBudgets[key]||0,committed=finCommitted(key),invoiced=finInvoiced(key),paid=finPaid(key);
  var openAP=invoiced-paid;var od=finOverdueList(key);var odSum=od.reduce(function(s,v){return s+v.amount;},0);
  var pos=finPOs.filter(function(x){return x.prod===key;});
  var wos=workOrders.filter(function(x){return x.prod===key;});
  var txs=txBookings.filter(function(x){return x.prod===key;});
  var invs=finInvoices.filter(function(x){return x.prod===key;});
  var ex=finExceptions(key);
  function card(label,val,cls,sub){return '<div class="bg-gray-50 rounded-xl p-3 border border-gray-100"><p class="text-[8px] font-bold uppercase tracking-wider text-gray-500">'+label+'</p><p class="text-base font-bold mono '+(cls||'text-gray-900')+' leading-tight mt-0.5">'+val+'</p>'+(sub?'<p class="text-[8px] mono text-gray-400 mt-0.5">'+sub+'</p>':'')+'</div>';}
  var pPaid=budget?Math.min(100,paid/budget*100):0,pOpen=budget?Math.min(100-pPaid,openAP/budget*100):0,pCom=budget?Math.min(100-pPaid-pOpen,Math.max(0,(committed-invoiced))/budget*100):0;
  var snapshot='<div class="bg-white rounded-2xl p-5 border border-gray-200/60" style="box-shadow:0 4px 20px rgba(0,0,0,.03)">'+
    '<div class="flex flex-wrap items-center justify-between gap-2 mb-3"><div><h3 class="text-xs font-bold uppercase tracking-wider text-gray-600">Financial Backbone — '+esc(p.name)+'</h3><p class="text-[9px] text-gray-500 mt-0.5">Purchase orders, work orders, transmission spend and accounts payable — linked end to end.</p></div>'+
    '<span class="text-[9px] mono text-gray-500">FY2025–26 · USD</span></div>'+
    '<div class="grid grid-cols-2 sm:grid-cols-3 xl:grid-cols-6 gap-2 mb-3">'+
      card('Budget',$fmt(budget))+
      card('Committed',$fmt(committed),'text-blue-700',budget?Math.round(committed/budget*100)+'% of budget':'')+
      card('Invoiced',$fmt(invoiced))+
      card('Paid',$fmt(paid),'text-emerald-700')+
      card('Open AP',$fmt(openAP),openAP>0?'text-amber-600':'text-gray-900',invs.filter(function(v){return v.status!=='Paid';}).length+' open invoice(s)')+
      card('Overdue',od.length?$fmt(odSum):'$0',od.length?'text-red-600':'text-gray-900',od.length?od.length+' invoice(s) past due':'all current')+'</div>'+
    '<div class="h-2.5 rounded-full bg-gray-100 overflow-hidden flex">'+
      '<div style="width:'+pPaid+'%;background:linear-gradient(90deg,#31A24C,#31A24C)" title="Paid"></div>'+
      '<div style="width:'+pOpen+'%;background:linear-gradient(90deg,#F5832A,#F5832A)" title="Open AP"></div>'+
      '<div style="width:'+pCom+'%;background:linear-gradient(90deg,#0866FF,#0866FF)" title="Committed, not yet invoiced"></div></div>'+
    '<div class="flex items-center gap-3 mt-1.5 text-[8px] mono text-gray-500"><span class="flex items-center gap-1"><span class="w-2 h-2 rounded-sm" style="background:#1E7B34"></span>paid</span><span class="flex items-center gap-1"><span class="w-2 h-2 rounded-sm" style="background:#f5832a"></span>open AP</span><span class="flex items-center gap-1"><span class="w-2 h-2 rounded-sm" style="background:#0866ff"></span>committed unbilled</span><span class="ml-auto">budget bar</span></div></div>';
  var exHTML='<div class="bg-white rounded-2xl p-5 border border-gray-200/60" style="box-shadow:0 4px 20px rgba(0,0,0,.03)">'+
    '<h3 class="text-[10px] font-bold uppercase tracking-wider text-gray-600 mb-2">AP Exceptions — what\u2019s missing or past due</h3>'+
    (ex.length?ex.map(function(e2){var red=e2.sev==='red';
      return '<div class="flex items-start gap-2 rounded-lg px-3 py-2 mb-1 border '+(red?'bg-red-50 border-red-200':'bg-amber-50 border-amber-200')+'"><span class="text-xs leading-none mt-0.5">'+(red?'⛔':'⚠')+'</span><span class="text-[10px] font-semibold '+(red?'text-red-800':'text-amber-800')+'">'+esc(e2.text)+'</span></div>';}).join(''):
      '<div class="flex items-center gap-2 bg-emerald-50 border border-emerald-200 rounded-lg px-3 py-2"><span class="w-1.5 h-1.5 rounded-full bg-emerald-500"></span><span class="text-[10px] font-semibold text-emerald-800">Clean — every committed dollar is invoiced or on schedule, nothing past due</span></div>')+'</div>';
  function docChips(kind,o){return '<span class="flex items-center gap-1 flex-wrap">'+(o.docs||[]).map(function(d){return '<button onclick="openFinDocPDF(\''+o.id+'\',\''+(''+d).replace(/[\u0027\u0022\\]/g,"")+'\')" class="text-[8px] mono bg-gray-100 border border-gray-200 text-gray-600 rounded px-1.5 py-0.5 hover:border-blue-300 hover:text-blue-700" title="Open document">📎 '+esc(d)+'</button>';}).join('')+
    '<button onclick="event.stopPropagation();finAddDoc(\''+kind+'\',\''+o.id+'\')" class="text-[8px] mono text-blue-700 hover:underline">+ doc</button></span>';}
  var poHTML='<div class="bg-white rounded-2xl p-5 border border-gray-200/60" style="box-shadow:0 4px 20px rgba(0,0,0,.03)">'+
    '<div class="flex items-center justify-between mb-2"><h3 class="text-[10px] font-bold uppercase tracking-wider text-gray-600">Purchase Orders</h3><button onclick="finNewPO(\''+key+'\')" class="text-[9px] font-bold text-white bg-gray-900 rounded-lg px-2.5 py-1.5 hover:bg-gray-800">+ New PO</button></div>'+

    (pos.length?pos.map(function(po){var inv=finInvoices.filter(function(v){return v.ref===po.id;});
      return '<div onclick="openFinDoc(\'po\',\''+po.id+'\')" title="Open purchase order document" class="p-2.5 rounded-lg border border-gray-100 hover:bg-gray-50 mb-1 cursor-pointer">'+
      '<div class="flex items-center justify-between gap-2"><div class="flex items-center gap-1.5 min-w-0 flex-wrap"><span class="text-[9px] mono font-bold text-gray-500">'+po.id+'</span><span class="text-[10px] font-bold text-gray-900">'+esc(po.vendor)+'</span><span class="text-[10px] text-gray-600 truncate">'+esc(po.desc)+'</span></div>'+
      '<div class="flex items-center gap-2 flex-shrink-0"><span class="text-[10px] mono font-bold text-gray-800">'+$fmt(po.amount)+'</span><button onclick="event.stopPropagation();advancePO(\''+po.id+'\')" title="Advance status">'+woStatusPill(po.status)+'</button></div></div>'+
      '<div class="flex items-center justify-between gap-2 mt-1 flex-wrap"><span class="text-[8px] mono text-gray-500">'+(po.wo?'⇄ '+po.wo:'no WO link')+(inv.length?' · invoiced: '+inv.map(function(v){return v.id;}).join(', '):' · awaiting invoice')+'</span>'+docChips('po',po)+'</div></div>';}).join(''):
      '<p class="text-[10px] text-gray-400 py-3 text-center">No purchase orders yet</p>')+'</div>';
  var woHTML='<div class="bg-white rounded-2xl p-5 border border-gray-200/60" style="box-shadow:0 4px 20px rgba(0,0,0,.03)">'+
    '<div class="flex items-center justify-between mb-2"><h3 class="text-[10px] font-bold uppercase tracking-wider text-gray-600">Work Orders</h3><button onclick="finNewWO(\''+key+'\')" class="text-[9px] font-bold text-white bg-gray-900 rounded-lg px-2.5 py-1.5 hover:bg-gray-800">+ New WO</button></div>'+

    (wos.length?wos.map(function(w){var po=finPOs.filter(function(x){return x.wo===w.id;})[0];
      return '<div onclick="openFinDoc(\'wo\',\''+w.id+'\')" title="Open work order document" class="flex items-center justify-between gap-2 p-2 rounded-lg border border-gray-100 hover:bg-gray-50 mb-1 cursor-pointer">'+
      '<div class="min-w-0"><div class="flex items-center gap-1.5 flex-wrap"><span class="text-[9px] mono font-bold text-gray-500">'+w.id+'</span><span class="text-[10px] font-bold text-gray-900 truncate">'+esc(w.desc)+'</span></div>'+
      '<p class="text-[9px] text-gray-500 mono truncate">'+esc(w.res)+(po?' · ⇄ '+po.id:'')+'</p></div>'+
      '<div class="flex items-center gap-2 flex-shrink-0"><span class="text-[9px] mono font-bold text-gray-700">'+$fmt(w.cost)+'</span><button onclick="event.stopPropagation();advanceWO(\''+w.id+'\')" title="Advance status">'+woStatusPill(w.status)+'</button></div></div>';}).join(''):
      '<p class="text-[10px] text-gray-400 py-3 text-center">No work orders yet</p>')+'</div>';
  var txHTML='<div class="bg-white rounded-2xl p-5 border border-gray-200/60" style="box-shadow:0 4px 20px rgba(0,0,0,.03)">'+
    '<div class="flex items-center justify-between mb-2"><h3 class="text-[10px] font-bold uppercase tracking-wider text-gray-600">Transmission Bookings &amp; Spend</h3><span class="text-[9px] mono text-gray-500">'+$fmt(txs.reduce(function(s,t){return s+(t.cost||0);},0))+' booked</span></div>'+
    (txs.length?txs.map(function(t){var bad=conf.flags[t.id];var cap=(TX_RES[t.res]||{}).cap||0;var load=cap?Math.round(t.bw/cap*100):0;var ty=(TX_RES[t.res]||{}).type||'';
      return '<div onclick="openFinDoc(\'tx\',\''+t.id+'\')" title="Open transmission booking" class="p-2 rounded-lg border '+(bad?'border-red-200 bg-red-50/40':'border-gray-100 hover:bg-gray-50')+' mb-1 cursor-pointer">'+
      '<div class="flex items-center justify-between gap-2"><div class="flex items-center gap-1.5 min-w-0"><span class="text-[9px] mono font-bold '+(bad?'text-red-600':'text-gray-500')+'">'+t.id+(bad?' ⚠':'')+'</span><span class="text-[8px] mono text-gray-500 border border-gray-200 bg-gray-50 rounded px-1 py-0.5">'+(TX_TYPE_TAG[ty]||ty)+'</span><span class="text-[10px] font-bold text-gray-900 truncate">'+esc(t.src)+' → '+esc(t.dst)+'</span></div>'+
      '<div class="flex items-center gap-2 flex-shrink-0"><span class="text-[9px] mono font-bold text-gray-700">'+$fmt(t.cost||0)+'</span><button onclick="event.stopPropagation();advanceTx(\''+t.id+'\')" title="Advance status">'+woStatusPill(t.status)+'</button></div></div>'+
      '<div class="flex items-center justify-between gap-2 mt-1"><span class="text-[9px] text-gray-500 mono truncate">'+esc(t.res)+' · '+t.bw+' Mbps ('+load+'%)</span><span class="text-[9px] mono text-gray-500 flex-shrink-0">'+fmtWin(t.start,t.end)+'</span></div></div>';}).join(''):
      '<p class="text-[10px] text-gray-400 py-3 text-center">No transmission bookings for this production</p>')+'</div>';
  var refOpts='<option value="">— link PO / WO —</option>'+pos.map(function(po){return '<option value="'+po.id+'">'+po.id+' · '+esc(po.vendor)+'</option>';}).join('')+wos.map(function(w){return '<option value="'+w.id+'">'+w.id+' · '+esc(w.desc)+'</option>';}).join('');
  var invHTML='<div class="bg-white rounded-2xl p-5 border border-gray-200/60" style="box-shadow:0 4px 20px rgba(0,0,0,.03)">'+
    '<div class="flex items-center justify-between mb-2"><h3 class="text-[10px] font-bold uppercase tracking-wider text-gray-600">Invoices &amp; Accounts Payable</h3><button onclick="finNewInv(\''+key+'\')" class="text-[9px] font-bold text-white bg-gray-900 rounded-lg px-2.5 py-1.5 hover:bg-gray-800">+ New Invoice</button></div>'+

    (invs.length?invs.map(function(v){var late=invOverdue(v);
      return '<div onclick="openFinDoc(\'inv\',\''+v.id+'\')" title="Open invoice" class="p-2.5 rounded-lg border '+(late?'border-red-200 bg-red-50/40':'border-gray-100 hover:bg-gray-50')+' mb-1 cursor-pointer">'+
      '<div class="flex items-center justify-between gap-2"><div class="flex items-center gap-1.5 min-w-0 flex-wrap"><span class="text-[9px] mono font-bold '+(late?'text-red-600':'text-gray-500')+'">'+v.id+'</span><span class="text-[10px] font-bold text-gray-900">'+esc(v.vendor)+'</span><span class="text-[8px] mono text-gray-500">'+(v.ref?'⇄ '+v.ref:'no reference')+'</span></div>'+
      '<div class="flex items-center gap-2 flex-shrink-0"><span class="text-[10px] mono font-bold text-gray-800">'+$fmt(v.amount)+'</span>'+
        '<button onclick="event.stopPropagation();advanceInv(\''+v.id+'\')" title="Advance status">'+woStatusPill(late?'Overdue':v.status)+'</button>'+
        (v.status!=='Paid'?'<button onclick="event.stopPropagation();payInv(\''+v.id+'\')" class="text-[8px] font-bold border border-emerald-200 bg-emerald-50 text-emerald-700 rounded px-1.5 py-0.5">✓ PAY</button>':'')+'</div></div>'+
      '<div class="flex items-center justify-between gap-2 mt-1 flex-wrap"><span class="text-[8px] mono '+(late?'text-red-600 font-bold':'text-gray-500')+'">recd '+fmtD(v.recd)+' · due '+fmtD(v.due)+(v.paidOn?' · paid '+fmtD(v.paidOn):'')+'</span>'+docChips('inv',v)+'</div></div>';}).join(''):
      '<p class="text-[10px] text-gray-400 py-3 text-center">No invoices on file</p>')+'</div>';
  var _ledger=snapshot+exHTML+
    '<div class="grid grid-cols-1 xl:grid-cols-2 gap-4">'+poHTML+woHTML+'</div>'+
    '<div class="grid grid-cols-1 xl:grid-cols-2 gap-4">'+invHTML+txHTML+'</div>';
  var _fv=(typeof finView!=='undefined'&&finView[key])?finView[key]:'report';
  return '<div class="space-y-4">'+
    '<div class="relative flex items-center justify-center flex-wrap gap-2">'+finViewStrip(key)+
      '<span class="text-[9px] mono text-gray-400 sm:absolute sm:right-0 sm:top-1/2 sm:-translate-y-1/2">FY2025&ndash;26 · production cost control</span></div>'+
    finToolbarHTML(key)+
    (_fv==='report'?finAnalyticsHTML(key)+costReportPaneHTML(key):(_fv==='labor'?laborPaneHTML(key):apTablePaneHTML(key)+_ledger))+'</div>';
}

/* ---------------- DASHBOARD SUMMARY ---------------- */
function renderOps(){
  // role gate: the Operations & Finance dashboard widget is invisible without finance access (Work Item 1)
  var _ofSec=document.getElementById('dashOpsFinance');
  if(typeof permCan==='function'&&!permCan('finance')){if(_ofSec)_ofSec.style.display='none';return;}
  if(_ofSec)_ofSec.style.display='';
  var conf=txConflicts();
  var cBox=document.getElementById('opsConflicts');
  if(cBox)cBox.innerHTML=conf.notes.length?conf.notes.map(function(n){return '<div class="flex items-start gap-2 bg-red-50 border border-red-200 rounded-lg px-3 py-2 mb-1"><span class="text-red-500 text-xs leading-none mt-0.5">⚠</span><span class="text-[10px] font-semibold text-red-800">'+esc(n.text)+'</span></div>';}).join(''):
    '<div class="flex items-center gap-2 bg-emerald-50 border border-emerald-200 rounded-lg px-3 py-2"><span class="w-1.5 h-1.5 rounded-full bg-emerald-500"></span><span class="text-[10px] font-semibold text-emerald-800">No transmission conflicts — all resource windows and bandwidth allocations clear</span></div>';
  var stats=document.getElementById('finPortfolioStats');
  if(stats){var tc=0,ti=0,tp=0,tod=0,nod=0;
    order.forEach(function(k){tc+=finCommitted(k);ti+=finInvoiced(k);tp+=finPaid(k);});
    finOverdueList(null).forEach(function(v){tod+=v.amount;nod++;});
    function sc(l,v,cls,sub){return '<div class="bg-gray-50 rounded-xl p-2.5 border border-gray-100"><p class="text-[8px] font-bold uppercase tracking-wider text-gray-500">'+l+'</p><p class="text-sm font-bold mono '+(cls||'text-gray-900')+'">'+v+'</p>'+(sub?'<p class="text-[8px] mono text-gray-400">'+sub+'</p>':'')+'</div>';}
    stats.innerHTML=sc('Committed',$fmt(tc),'text-blue-700')+sc('Invoiced',$fmt(ti))+sc('Paid',$fmt(tp),'text-emerald-700')+sc('Open AP',$fmt(ti-tp),(ti-tp)>0?'text-amber-600':'text-gray-900')+sc('Overdue',nod?$fmt(tod):'$0',nod?'text-red-600':'text-gray-900',nod?nod+' invoice(s)':'all current');}
  var rows=document.getElementById('finSummaryRows');
  if(rows)rows.innerHTML=order.map(function(k){var b=finBudgets[k]||0,c=finCommitted(k),iv=finInvoiced(k),pd=finPaid(k);
    var od=finOverdueList(k);var openAP=iv-pd;
    var pct=c?Math.min(100,Math.round(pd/c*100)):0;
    var health=od.length?'<span class="text-[8px] font-bold mono bg-red-50 text-red-700 border border-red-200 rounded px-1.5 py-0.5">'+od.length+' OVERDUE</span>':
      (openAP>0?'<span class="text-[8px] font-bold mono bg-amber-50 text-amber-700 border border-amber-200 rounded px-1.5 py-0.5">'+$fmt(openAP)+' OPEN</span>':'<span class="text-[8px] font-bold mono bg-emerald-50 text-emerald-700 border border-emerald-200 rounded px-1.5 py-0.5">CURRENT</span>');
    return '<tr class="border-b border-gray-100 hover:bg-gray-50 cursor-pointer" onclick="openProjFinance(\''+k+'\')">'+
      '<td class="py-2 pr-3"><span class="flex items-center gap-2"><span class="w-2 h-2 rounded-full flex-shrink-0" style="background:'+(dotBg[productions[k].tagColor]||'#b0b3b8')+'"></span><span class="text-[10px] font-bold text-gray-900">'+esc(prodName(k))+'</span></span></td>'+
      '<td class="py-2 pr-3 text-right text-[10px] mono text-gray-600">'+$fmt(b)+'</td>'+
      '<td class="py-2 pr-3 text-right text-[10px] mono font-bold text-blue-700">'+$fmt(c)+'</td>'+
      '<td class="py-2 pr-3 text-right text-[10px] mono text-gray-700">'+$fmt(iv)+'</td>'+
      '<td class="py-2 pr-3 text-right text-[10px] mono font-bold text-emerald-700">'+$fmt(pd)+'</td>'+
      '<td class="py-2 pr-3 text-right text-[10px] mono '+(openAP>0?'font-bold text-amber-600':'text-gray-500')+'">'+$fmt(openAP)+'</td>'+
      '<td class="py-2 pr-3">'+health+'</td>'+
      '<td class="py-2 text-right"><span class="text-[9px] font-bold text-blue-700 hover:underline">Finance →</span></td></tr>';
  }).join('');
  saveOps();
}

