function engLightClone(list){return (list||[]).map(function(g){return {cat:g.cat,model:g.model,count:g.count||1,ctemp:g.ctemp||'',power:g.power||'',mount:g.mount||'',notes:g.notes||''};});}
function engLightCatOf(model){var cats=Object.keys(ENG_LIGHT_CATALOG);for(var i=0;i<cats.length;i++){if(ENG_LIGHT_CATALOG[cats[i]].indexOf(model)>-1)return cats[i];}return 'Other';}
/* migrate any pre-v28 ENG record (single LiveU/REM/TIF + string support list) to the
   multi-unit model: liveus[], rems[], tiffs[], gear[{cat,item,qty}], loc{venue,lat,lng} */
function engMigrate(e){
  if(!e.liveus)e.liveus=e.liveu?[{model:e.liveu,serial:e.liveuserial||'',path:e.path||'Bonded cellular'}]:[];
  if(!e.audioPackages||!e.audioPackages.length){
    if(e.micqty!=null||e.mictype||e.ifbqty!=null||e.ifbtype)
      e.audioPackages=[{label:'Package 1',micqty:e.micqty!=null?e.micqty:2,mictype:e.mictype||'Lavalier',ifbqty:e.ifbqty!=null?e.ifbqty:1,ifbtype:e.ifbtype||"Wireless (RTS IFB-325)"}];
    else e.audioPackages=[];
  }
  /* v34: each LiveU can carry a multi-cam license + a list of assigned camera indices */
  e.liveus.forEach(function(u){if(u.multicam===undefined)u.multicam=false;if(!u.cams)u.cams=[];});
  if(!e.rems)e.rems=e.rem?[{ref:e.rem,talent:'',personal:false,phone:''}]:[];
  if(!e.tiffs)e.tiffs=e.tif?[{ref:e.tif,person:'',personal:false,phone:''}]:[];
  if(!e.gear)e.gear=(e.support||[]).map(function(s){return {cat:engGearCat(s),item:s,qty:1};});
  /* v34: MULTIPLE CAMERAS — fold the legacy single-camera scalars into cameras[0].
     Each camera is its own package: operator, body, lens, lens type, prompter, vanity. */
  if(!e.cameras||!e.cameras.length){e.cameras=[{op:e.op!==false,opname:e.opname||'',camera:e.camera||'',lens:e.lens||'',lenstype:e.lenstype||'ENG / handheld',prompter:!!e.prompter,prompterspec:e.prompterspec||'',vanity:e.vanity!==false,vanityspec:e.vanityspec||"TVLogic LUM-310R"}];}
  /* v34: LIGHTING package (ENG field-kit fixtures) */
  if(!e.lighting)e.lighting=[];
  if(!e.lightingSetup)e.lightingSetup='';
  /* v34: per-request Site Survey photos [{src,caption,ts}] */
  if(!e.surveyPhotos)e.surveyPhotos=[];
  if(!e.loc)e.loc={venue:e.location||'',lat:null,lng:null};
  return e;}

