var USER_PROFILES={
  'Lila Hart':{name:'Lila Hart',initials:'AC',title:'VP, Technical Production · Admin',org:'Muse Live',
    email:'avery.chen@meta.com',phone:'(212) 555-0100',location:'Meta NYC · Hudson Yards, New York · Meta Miami, Miami',
    role:'Administrator',clearance:'Top Security Clearance',timezone:'America/New_York (ET)',
    bio:'Leads technical production across Muse Live tentpole events — Muse AI World Tour 2026, Orion AR Glasses Reveal, Meta Charm Launch Milano, Instagram Creator Week, Ray-Ban Meta Gen 3 Launch and WhatsApp Business Summit coverage.'},
  'Avery Nolan':{name:'Avery Nolan',initials:'LC',title:'Hard Cam Op · Field Crew',org:'Muse Live · Mediapro',
    email:'logan.cruz@meta.com',phone:'(212) 561-0113',location:'Muse AI World Tour compound · Field',
    role:'Field Crew',clearance:'Field',timezone:'America/Mexico_City (CT)',
    bio:'Hard cam operator on Muse Live tentpoles. Field crew — Muse AI World Tour 2026, Orion AR Glasses Reveal, and day-of ENG hits. Own-gear locker and travel only.'}
};
var USER_PROFILE=USER_PROFILES['Lila Hart'];
function museUserProfile(){
  var name='Lila Hart';
  var d=null;
  try{if(typeof permRoleDef==='function')d=permRoleDef();}catch(e){}
  if(d&&d.persona)name=d.persona;
  var u={};
  var base=USER_PROFILES[name]||USER_PROFILES['Lila Hart'];
  var k;
  for(k in base)if(base.hasOwnProperty(k))u[k]=base[k];
  if(d){
    u.name=d.persona||u.name;
    u.title=d.title||u.title;
    u.role=d.admin?'Administrator':(d.label||u.role);
    u.initials=(u.name||'').split(/\s+/).map(function(w){return (w[0]||'');}).join('').slice(0,2).toUpperCase();
    if(!d.admin)u.clearance=u.clearance||'Field';
  }
  try{
    if(typeof personnelInfo==='function'){
      var info=personnelInfo(u.name)||{};
      if(info.email)u.email=info.email;
      if(info.phone)u.phone=info.phone;
    }
  }catch(eP){}
  USER_PROFILE=u;
  return u;
}
function openUserProfile(){var ov=document.getElementById('userProfileOverlay');var bx=document.getElementById('userProfileBox');if(!ov||!bx)return;
  var u=museUserProfile();
  // live portfolio rollup owned by this user
  var owned=order.filter(function(k){return (productions[k].editedBy||'')===u.name;});
  var totalProds=order.length;
  var openItems=order.reduce(function(a,k){return a+countStatus(productions[k]).missing;},0);
  var assignedCrew=(typeof projAssignedCount==='function')?order.reduce(function(a,k){return a+projAssignedCount(k);},0):0;
  var booked=(typeof crewFlights!=='undefined')?Object.keys(crewFlights).length:0;
  function stat(v,l){return '<div class="rounded-xl border border-gray-200 p-2.5 text-center bg-gray-50/50"><div class="text-lg font-bold text-gray-900 leading-none">'+v+'</div><div class="text-[8px] font-bold uppercase tracking-wider text-gray-400 mt-1">'+l+'</div></div>';}
  function row(label,val,mono){return '<div class="flex items-start justify-between gap-3 py-2 border-b border-gray-50"><span class="text-[10px] font-bold uppercase tracking-wider text-gray-400 flex-shrink-0 pt-0.5">'+label+'</span><span class="text-[12px] text-gray-800 text-right '+(mono?'mono':'')+'">'+esc(val)+'</span></div>';}
  bx.innerHTML='<div class="flex items-center justify-between px-5 py-3 border-b border-gray-100 flex-shrink-0"><h3 class="text-sm font-bold text-gray-900">Profile</h3><button onclick="closeUserProfile()" class="text-gray-400 hover:text-gray-700 text-lg leading-none">✕</button></div>'+
    '<div class="overflow-y-auto flex-1">'+
      '<div class="px-5 py-4 flex items-center gap-4 border-b border-gray-100">'+
        '<div class="w-16 h-16 rounded-full bg-gradient-to-br from-purple-600 to-blue-500 text-white flex items-center justify-center text-xl font-bold border-2 border-white shadow-md flex-shrink-0">'+esc(u.initials)+'</div>'+
        '<div class="min-w-0"><h2 class="text-lg font-bold text-gray-900 leading-tight">'+esc(u.name)+'</h2><p class="text-[12px] text-gray-600">'+esc(u.title)+'</p>'+
          '<div class="flex items-center gap-1.5 mt-1"><span class="text-[8px] font-bold uppercase tracking-wider text-purple-700 bg-purple-50 border border-purple-200 rounded px-1.5 py-0.5">'+esc(u.role)+'</span><span class="text-[8px] font-bold uppercase tracking-wider text-amber-700 bg-amber-50 border border-amber-200 rounded px-1.5 py-0.5">'+esc(u.clearance)+'</span></div></div>'+
      '</div>'+
      '<div class="px-5 py-4"><p class="text-[12px] text-gray-600 leading-relaxed">'+esc(u.bio)+'</p></div>'+
      '<div class="px-5 pb-4"><p class="text-[9px] font-bold uppercase tracking-wider text-gray-400 mb-1.5">Preferences</p>'+
        '<div class="rounded-xl border border-gray-200 p-3"><div class="flex items-center justify-between gap-3 flex-wrap">'+
          '<div class="min-w-0"><p class="text-[11px] font-bold text-gray-800">Appearance</p><p class="text-[9px] text-gray-500 mt-0.5">Muse Live opens in Dark (the Meta UI Toolkit palette). Light is a saved override. Follow OS tracks your device until you pick Light or Dark again.</p></div>'+
          '<div class="flex items-center gap-1.5 flex-shrink-0">'+themeChoiceBtn('light')+themeChoiceBtn('dark')+themeChoiceBtn('system')+'</div>'+
        '</div></div></div>'+
      '<div class="px-5 pb-3"><div class="grid grid-cols-2 gap-2">'+stat(totalProds,'Productions')+stat(assignedCrew,'Crew')+stat(booked,'Flights')+stat(openItems,'Open Items')+'</div></div>'+
      '<div class="px-5 pb-4"><p class="text-[9px] font-bold uppercase tracking-wider text-gray-400 mb-1">Contact &amp; Access</p>'+
        row('Email',u.email,true)+row('Phone',u.phone,true)+row('Organization',u.org)+row('Locations',u.location)+row('Time Zone',u.timezone,true)+
      '</div>'+
    '</div>'+
    '<div class="px-5 py-3 border-t border-gray-100 flex-shrink-0 flex flex-wrap items-center gap-2">'+
      '<button onclick="closeUserProfile();openCompose(\'production\',order[0],\'email\')" class="flex-1 bg-gray-900 text-white text-[12px] font-bold rounded-lg py-2 hover:bg-gray-800">New Message</button>'+
      '<button onclick="closeUserProfile();if(window.MuseTour)MuseTour.start()" class="text-[11px] font-bold text-gray-700 border border-gray-200 rounded-lg px-3 py-2 hover:bg-gray-50">Take the tour</button>'+
      '<button onclick="museResetDemo()" class="text-[11px] font-bold text-gray-700 border border-gray-200 rounded-lg px-3 py-2 hover:bg-gray-50">Reset demo</button>'+
      '<a href="/logout" class="text-[11px] font-bold text-gray-700 border border-gray-200 rounded-lg px-3 py-2 hover:bg-gray-50">Sign out</a>'+
    '</div>'+
    '<p class="muse-disclaimer px-5 pb-3">Concept demo — not an official Meta product. Meta, Ray-Ban and Muse are trademarks of their owners.</p>';
  ov.style.display='flex';}
function closeUserProfile(){var ov=document.getElementById('userProfileOverlay');if(ov)ov.style.display='none';}

/* one MANIFEST line — identity · itinerary · hotel · LIVE TRACKING inline on the
   right (v33: the tracker is part of the row, not a separate tile). Click → boarding pass. */
function flightRow(name,role,f,key){
  if(!f)return '';
  var al=airline(f.airlineCode);var a=airport(f.dep.code),b=airport(f.arr.code);
  var nm=name.replace(/'/g,"\\'");
  var ph=(typeof flightPhase==='function')?flightPhase(f):null;
  var travOwn=(typeof permScope==='function'&&permScope('travel')==='own');
  var h=(typeof crewHotel==='function')?crewHotel(name):null;
  if(!key)key=currentTravelKey(); // legacy call sites only — pass key explicitly where known
  var track=ph?('<div class="hidden lg:flex flex-col items-end flex-shrink-0" style="width:150px;gap:3px">'+
      '<span class="text-[8px] font-bold border rounded px-1.5 py-0.5 '+ph.cls+'">'+ph.label.toUpperCase()+(ph.id==='air'?' · '+ph.pct+'%':'')+'</span>'+
      '<div class="w-full h-1 rounded-full bg-gray-100 overflow-hidden"><div class="h-full rounded-full" style="width:'+ph.pct+'%;background:'+(ph.id==='air'?'#0a58ca':(ph.pct===100?'#1E7B34':'#b0b3b8'))+'"></div></div>'+
      '<span class="flex items-center gap-1.5">'+flightTrackLinks(f)+'</span>'+
    '</div>'):'';
  var hotelChip=travOwn?'':(h?
    '<span onclick="event.stopPropagation();openHotelEdit(\''+key+'\',\''+nm+'\')" title="'+esc(h.hotel).replace(/"/g,'&quot;')+(h.conf?' · #'+esc(h.conf).replace(/"/g,'&quot;'):'')+'" class="flex-shrink-0 cursor-pointer text-[9px] font-bold text-emerald-700 bg-emerald-50 border border-emerald-200 rounded px-1 py-0.5 hover:bg-emerald-100">🏨</span>':
    '<span onclick="event.stopPropagation();openHotelEdit(\''+key+'\',\''+nm+'\')" title="Add hotel" class="flex-shrink-0 cursor-pointer text-[9px] font-bold text-gray-400 bg-gray-50 border border-gray-200 rounded px-1 py-0.5 hover:text-emerald-700 hover:bg-emerald-50">+🏨</span>');
  return '<div role="button" tabindex="0" onclick="openTicket(\''+nm+'\')" onkeydown="if(event.key===\'Enter\'||event.key===\' \'){event.preventDefault();openTicket(\''+nm+'\');}" class="w-full text-left flex items-center gap-3 p-2.5 rounded-xl border border-gray-200/70 hover:border-blue-300 hover:bg-blue-50/30 transition-all group cursor-pointer">'+
    '<div style="width:30px;height:30px;flex-shrink:0">'+al.logo+'</div>'+
    '<div class="flex-shrink-0" style="min-width:74px"><p class="text-[12px] font-bold text-gray-900 mono leading-none">'+esc(f.flightNumber)+'</p><p class="text-[8px] text-gray-500 mt-0.5 truncate" style="max-width:90px">'+esc(al.name)+'</p></div>'+
    '<div class="min-w-0 flex-shrink-0" style="width:140px"><p class="text-[11px] font-bold text-gray-800 truncate">'+esc(name)+'</p><p class="text-[8px] text-gray-500 truncate">'+esc(role||'')+'</p></div>'+
    '<div class="flex items-center gap-1.5 flex-1 min-w-0 mono">'+
      '<div class="text-right flex-shrink-0"><p class="text-[11px] font-bold text-gray-900 leading-none">'+fmtLocalTime(f.dep.localTime)+'</p><p class="text-[8px] text-gray-500 mt-0.5">'+f.dep.code+'</p></div>'+
      '<svg width="26" height="8" viewBox="0 0 26 8" class="flex-shrink-0"><line x1="1" y1="4" x2="20" y2="4" stroke="#ced0d4" stroke-width="1" stroke-dasharray="2 2"/><path d="M19 1.5 L23 4 L19 6.5" fill="none" stroke="#b0b3b8" stroke-width="1.1"/></svg>'+
      '<div class="flex-shrink-0"><p class="text-[11px] font-bold text-gray-900 leading-none">'+fmtLocalTime(f.arr.localTime)+'</p><p class="text-[8px] text-gray-500 mt-0.5">'+f.arr.code+'</p></div>'+
    '</div>'+
    '<div class="hidden xl:block flex-shrink-0 text-right" style="width:88px"><p class="text-[8px] text-gray-400 mono">'+fmtLocalDate(f.dep.localTime)+'</p><p class="text-[8px] text-gray-400">'+esc(a.city)+'→'+esc(b.city)+'</p></div>'+
    track+
    hotelChip+
    '<span onclick="event.stopPropagation();openBookFlight(\''+key+'\',\''+nm+'\')" title="Edit traveler & booking" class="flex-shrink-0 text-gray-300 hover:text-blue-600 cursor-pointer p-1"><svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M11 4H4a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2v-7"/><path d="M18.5 2.5a2.12 2.12 0 0 1 3 3L12 15l-4 1 1-4 9.5-9.5z"/></svg></span>'+
    '<svg class="flex-shrink-0 text-gray-300 group-hover:text-blue-500" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M9 18l6-6-6-6"/></svg>'+
  '</div>';
}
/* group a set of manifest members by shared flight — the "By flight" manifest mode
   (relocates the old Flight Tracker grouping INTO the manifest, per TravelPerk/Navan patterns) */
function flightGroupRows(members){
  var byFlight={},orderK=[];
  members.forEach(function(m){var f=crewFlight(m.name);if(!f)return;
    var fk=f.airlineCode+f.flightNumber+'|'+(f.dep.localTime||'');
    if(!byFlight[fk]){byFlight[fk]={f:f,people:[]};orderK.push(fk);}
    byFlight[fk].people.push(m);});
  return orderK.map(function(fk){var g=byFlight[fk],f=g.f,ph=flightPhase(f),al=airline(f.airlineCode);
    var bar='<div class="flex-1 h-1 rounded-full bg-gray-100 overflow-hidden" style="min-width:60px;max-width:150px"><div class="h-full rounded-full" style="width:'+ph.pct+'%;background:'+(ph.id==='air'?'#0a58ca':(ph.pct===100?'#1E7B34':'#b0b3b8'))+'"></div></div>';
    return '<div class="rounded-xl border border-gray-200/70 overflow-hidden">'+
      '<div class="flex flex-wrap items-center gap-2 px-2.5 py-2 bg-gray-50/60 border-b border-gray-100">'+
        '<span class="w-6 h-6 flex-shrink-0">'+al.logo+'</span>'+
        '<span class="mono text-[11px] font-bold text-gray-900">'+esc(f.flightNumber)+'</span>'+
        '<span class="mono text-[9px] text-gray-500">'+esc(f.dep.code)+' '+fmtLocalTime(f.dep.localTime)+' → '+esc(f.arr.code)+' '+fmtLocalTime(f.arr.localTime)+' · '+fmtLocalDate(f.dep.localTime)+'</span>'+
        '<span class="text-[8px] font-bold border rounded px-1.5 py-0.5 '+ph.cls+'">'+ph.label.toUpperCase()+(ph.id==='air'?' · '+ph.pct+'%':'')+'</span>'+bar+
        '<span class="text-[9px] font-bold text-gray-500 ml-auto">👤 '+g.people.length+'</span>'+flightTrackLinks(f)+'</div>'+
      '<div class="flex flex-wrap gap-1.5 px-2.5 py-2">'+g.people.map(function(m){var nm2=m.name.replace(/'/g,"\\'");
        return '<button onclick="openTicket(\''+nm2+'\')" class="text-[10px] font-semibold text-gray-800 bg-white border border-gray-200 rounded-lg px-2 py-1 hover:border-blue-300 hover:bg-blue-50/40">'+esc(m.name)+(m.pos?' <span class="text-[8px] text-gray-400 font-normal">'+esc(m.pos)+'</span>':'')+'</button>';}).join('')+'</div>'+
    '</div>';}).join('');
}
function currentTravelKey(){var act=document.querySelector('.view-pane.active');
  if(act){var k=act.id.replace('view-','');if(productions[k])return k;
    if(act.id==='view-portal'&&typeof portalProjKey!=='undefined'&&portalProjKey&&productions[portalProjKey])return portalProjKey;}
  return order[0];}
/* stage a Skyscanner-selected itinerary into the booking editor for native confirm */
var skyChosen=null;
function skyPrefillBooking(key,name,slotId,f,ctx){
  skyChosen={airlineCode:f.airlineCode,flightNumber:f.flightNumber,depCode:f.depCode,arrCode:f.arrCode,
    depTime:(ctx.depart||'')+'T'+f.depTime,arrTime:(ctx.depart||'')+'T'+f.arrTime,price:f.price};
  // make sure tccCtx reflects the route so the editor pre-fills airports/dates
  tccCtx={key:key,slotId:slotId||(tccCtx&&tccCtx.slotId)||null,name:name,origin:f.depCode,dest:f.arrCode,depart:ctx.depart||'',ret:ctx.ret||''};
  openBookFlight(key,name,tccCtx.slotId);
}
/* ---- BOARDING PASS / TICKET MODAL ---- */
function ticketHTML(name,role,f){
  var al=airline(f.airlineCode);var a=airport(f.dep.code),b=airport(f.arr.code);
  var seg=function(side,ap2,s,dotCol){
    return '<div class="flex-1 min-w-0">'+
      '<div class="flex items-center gap-1.5 mb-1"><span class="w-1.5 h-1.5 rounded-full" style="background:'+dotCol+'"></span><span class="text-[8px] font-bold uppercase tracking-wider text-gray-400">'+side+'</span></div>'+
      '<p class="text-[26px] font-bold text-gray-900 leading-none mono">'+s.code+'</p>'+
      '<p class="text-[10px] font-semibold text-gray-700 mt-1 truncate">'+esc(ap2.city)+'</p>'+
      '<p class="text-[8px] text-gray-400 truncate">'+esc(ap2.name)+'</p>'+
      '<p class="text-[18px] font-bold text-gray-900 mt-2 leading-none">'+fmtLocalTime(s.localTime)+'</p>'+
      '<p class="text-[8px] text-gray-400 mono mt-0.5">'+fmtLocalDate(s.localTime)+' · '+tzLabel(s.localTime)+' local</p>'+
    '</div>';};
  function field(l,v){return '<div><p class="text-[7px] font-bold uppercase tracking-wider text-gray-400">'+l+'</p><p class="text-[11px] font-bold text-gray-800 mono">'+esc(v||'—')+'</p></div>';}
  return '<div class="bg-white rounded-2xl shadow-2xl overflow-hidden" style="width:460px;max-width:95vw;max-height:92vh;overflow-y:auto">'+
    // colored airline header
    '<div class="px-5 py-3 flex items-center justify-between" style="background:'+al.color+'">'+
      '<div class="flex items-center gap-2.5"><div style="width:34px;height:34px;background:#ffffff;border-radius:8px;padding:2px">'+al.logo+'</div>'+
        '<div><p class="text-[13px] font-bold text-white leading-none">'+esc(al.name)+'</p><p class="text-[9px] text-white/70 mono mt-0.5">BOARDING PASS</p></div></div>'+
      '<button onclick="closeTicket()" class="text-white/80 hover:text-white text-lg leading-none w-7 h-7 flex items-center justify-center rounded-lg hover:bg-white/10">✕</button>'+
    '</div>'+
    // passenger band
    '<div class="px-5 py-3 bg-gray-50 border-b border-gray-100 flex items-center justify-between">'+
      '<div><p class="text-[7px] font-bold uppercase tracking-wider text-gray-400">Passenger</p><p class="text-[15px] font-bold text-gray-900 leading-tight">'+esc(name)+'</p><p class="text-[9px] text-gray-500">'+esc(role||'')+'</p></div>'+
      '<div class="text-right"><p class="text-[7px] font-bold uppercase tracking-wider text-gray-400">Flight</p><p class="text-[18px] font-bold text-gray-900 mono">'+esc(f.flightNumber)+'</p></div>'+
    '</div>'+
    // route
    '<div class="px-5 py-4"><div class="flex items-center gap-3">'+
      seg('From',a,f.dep,'#1E7B34')+
      '<div class="flex flex-col items-center px-1 flex-shrink-0"><svg width="30" height="30" viewBox="0 0 24 24" fill="none" stroke="#b0b3b8" stroke-width="1.5"><path d="M2 12h20M22 12l-6-5M22 12l-6 5" transform="rotate(0 12 12)"/></svg><span class="text-[8px] mono text-gray-400 mt-1">'+flightDurStr(f)+'</span><span class="text-[7px] text-gray-300 mono">nonstop</span></div>'+
      seg('To',b,f.arr,'#E41E3F')+
    '</div></div>'+
    // gate/terminal detail grid
    '<div class="px-5 pb-4"><div class="grid grid-cols-4 gap-3 bg-gray-50 rounded-xl p-3 border border-gray-100">'+
      field('Dep Terminal',f.dep.terminal)+field('Dep Gate',f.dep.gate)+field('Arr Terminal',f.arr.terminal)+field('Arr Gate',f.arr.gate)+
    '</div></div>'+
    // map — live map centred on arrival airport (SVG arc as fallback)
    '<div class="px-5 pb-4"><div class="rounded-xl border border-gray-200 overflow-hidden bg-gray-50" style="min-height:300px;height:42vh;max-height:420px">'+
      liveMapHTML({id:'flightmap_'+(name||'x').replace(/[^a-z0-9]/gi,''),lat:(airport(f.arr.code).lat||40.7),lng:(airport(f.arr.code).lng||-74),zoom:11,label:airport(f.arr.code).name+' ('+f.arr.code+')',fallbackSVG:flightMapSVG(f,420,300)})+
    '</div></div>'+
    // perforated stub: airline CS
    '<div class="border-t-2 border-dashed border-gray-200 px-5 py-3 flex items-center justify-between bg-gray-50/50">'+
      '<div><p class="text-[7px] font-bold uppercase tracking-wider text-gray-400">'+esc(al.name)+' Customer Service</p>'+
        (al.phone&&al.phone!=='—'?'<a href="tel:'+al.phone.replace(/[^0-9+]/g,'')+'" class="text-[13px] font-bold mono text-blue-700 hover:underline">'+esc(al.phone)+'</a>':'<span class="text-[12px] mono text-gray-400">—</span>')+'</div>'+
      '<button onclick="printOneTicket(\''+name.replace(/'/g,"\\'")+'\')" class="text-[10px] font-bold text-gray-700 border border-gray-300 rounded-lg px-3 py-1.5 hover:bg-white flex items-center gap-1.5"><svg width="11" height="11" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M6 9V2h12v7M6 18H4a2 2 0 0 1-2-2v-5a2 2 0 0 1 2-2h16a2 2 0 0 1 2 2v5a2 2 0 0 1-2 2h-2M6 14h12v8H6z"/></svg>Print</button>'+
      '<button onclick="unbookFlight(\''+name.replace(/'/g,"\\'")+'\')" class="text-[10px] font-bold text-red-600 border border-red-200 rounded-lg px-3 py-1.5 hover:bg-red-50">Un-book</button>'+
    '</div>'+
  '</div>';
}
function openTicket(name){
  if(typeof permScope==='function'&&permScope('travel')==='own'&&name!==permUser()){toast('🔒 Travel is limited to your own itinerary');return;}
  var f=crewFlight(name);if(!f){toast('No flight on file for '+name);return;}
  var m=crewMember(name);var role=m?m.pos:'';
  var ov=document.getElementById('ticketOverlay');var bx=document.getElementById('ticketBox');
  if(!ov||!bx)return;bx.innerHTML=ticketHTML(name,role,f);ov.style.display='flex';try{setTimeout(mountVisibleMaps,40);}catch(e){}}
function closeTicket(){var ov=document.getElementById('ticketOverlay');if(ov)ov.style.display='none';}

/* ---- PRINTABLE TRAVEL SHEET (all travelers) ---- */
function printTravel(key){var p=productions[key];loadTravelOnce();
  var allCrew=CREW_FIELD.concat(CREW_IT,CREW_PCR,CREW_EXEC);
  if(typeof permScope==='function'&&permScope('travel')==='own'){var me=permUser();allCrew=allCrew.filter(function(m){return m.name===me;});}
  var withFlights=allCrew.filter(function(m){return crewFlight(m.name);});
  if(!withFlights.length){toast('No flights to print');return;}
  var cards=withFlights.map(function(m){return printTicketCard(m.name,m.pos,crewFlight(m.name));}).join('');
  printTravelDoc(p,cards,'Crew Travel Itinerary');}
function printOneTicket(name){var m=crewMember(name);var f=crewFlight(name);if(!f)return;
  var act=document.querySelector('.view-pane.active');var key=act?act.id.replace('view-',''):order[0];var p=productions[key]||{name:'Muse Live'};
  printTravelDoc(p,printTicketCard(name,m?m.pos:'',f),'Boarding Pass — '+name);}
function printTicketCard(name,role,f){
  var al=airline(f.airlineCode);var a=airport(f.dep.code),b=airport(f.arr.code);
  return '<div class="ticket">'+
    '<div class="thd" style="background:'+al.color+'"><span class="aln">'+esc(al.name)+'</span><span class="fno">'+esc(f.flightNumber)+'</span></div>'+
    '<div class="pax"><div><div class="k">Passenger</div><div class="pn">'+esc(name)+'</div><div class="pr">'+esc(role||'')+'</div></div></div>'+
    '<div class="rte">'+
      '<div class="end"><div class="ec">'+f.dep.code+'</div><div class="ecy">'+esc(a.city)+'</div><div class="et">'+fmtLocalTime(f.dep.localTime)+'</div><div class="ed">'+fmtLocalDate(f.dep.localTime)+' · '+tzLabel(f.dep.localTime)+' local</div></div>'+
      '<div class="arr">✈</div>'+
      '<div class="end r"><div class="ec">'+f.arr.code+'</div><div class="ecy">'+esc(b.city)+'</div><div class="et">'+fmtLocalTime(f.arr.localTime)+'</div><div class="ed">'+fmtLocalDate(f.arr.localTime)+' · '+tzLabel(f.arr.localTime)+' local</div></div>'+
    '</div>'+
    '<div class="dtl"><div><span class="dk">Dep Terminal</span><span class="dv">'+esc(f.dep.terminal||'—')+'</span></div><div><span class="dk">Dep Gate</span><span class="dv">'+esc(f.dep.gate||'—')+'</span></div><div><span class="dk">Arr Terminal</span><span class="dv">'+esc(f.arr.terminal||'—')+'</span></div><div><span class="dk">Arr Gate</span><span class="dv">'+esc(f.arr.gate||'—')+'</span></div></div>'+
    '<div class="stub"><span class="sk">'+esc(al.name)+' Customer Service</span><span class="sv">'+esc(al.phone||'—')+'</span></div>'+
  '</div>';
}
function printTravelDoc(p,cardsHTML,titleStr){
  var html='<!DOCTYPE html><html><head><meta charset="utf-8"><title>'+esc(titleStr)+' — '+esc(p.name)+'</title><style>'+
    '@page{size:A4;margin:12mm}*{box-sizing:border-box;-webkit-print-color-adjust:exact;print-color-adjust:exact}'+
    'html,body{margin:0;padding:0}body{font-family:-apple-system,Segoe UI,Helvetica,Arial,sans-serif;color:#242526}'+
    '.bar{display:flex;height:5px}.bar i{flex:1}'+
    '.hd{background:#18191A;color:#ffffff;padding:14px 18px;display:flex;justify-content:space-between;align-items:flex-end}'+
    '.hd h1{font-size:18px;margin:0;letter-spacing:1px}.hd .s{font-size:11px;color:#b0b3b8;margin-top:3px}.hd .r{text-align:right;font-size:9px;color:#b0b3b8;line-height:1.5}'+
    '.wrap{padding:14px 18px;display:grid;grid-template-columns:1fr 1fr;gap:12px}'+
    '.ticket{border:1px solid #e4e6eb;border-radius:10px;overflow:hidden;page-break-inside:avoid;background:#ffffff}'+
    '.thd{padding:8px 12px;color:#ffffff;display:flex;justify-content:space-between;align-items:center}.thd .aln{font-size:11px;font-weight:700}.thd .fno{font-size:13px;font-weight:800;font-family:monospace}'+
    '.pax{padding:8px 12px;background:#f7f8fa;border-bottom:1px solid #f0f2f5}.pax .k{font-size:7px;text-transform:uppercase;letter-spacing:1px;color:#8A8D91}.pax .pn{font-size:14px;font-weight:700}.pax .pr{font-size:9px;color:#65676B}'+
    '.rte{display:flex;align-items:center;gap:8px;padding:12px}'+
    '.end{flex:1}.end.r{text-align:right}.end .ec{font-size:22px;font-weight:800;font-family:monospace;line-height:1}.end .ecy{font-size:10px;font-weight:600;color:#4B4F56;margin-top:2px}.end .et{font-size:15px;font-weight:700;margin-top:5px}.end .ed{font-size:7px;color:#8A8D91;font-family:monospace;margin-top:1px}'+
    '.arr{font-size:16px;color:#b0b3b8}'+
    '.dtl{display:grid;grid-template-columns:repeat(4,1fr);gap:6px;padding:0 12px 10px}.dtl .dk{display:block;font-size:6.5px;text-transform:uppercase;letter-spacing:.5px;color:#8A8D91}.dtl .dv{display:block;font-size:10px;font-weight:700;font-family:monospace}'+
    '.stub{border-top:1.5px dashed #e4e6eb;padding:8px 12px;display:flex;justify-content:space-between;align-items:center;background:#f7f8fa}.stub .sk{font-size:7px;text-transform:uppercase;letter-spacing:.5px;color:#8A8D91;font-weight:700}.stub .sv{font-size:12px;font-weight:700;font-family:monospace;color:#0866ff}'+
    '.foot{padding:8px 18px;display:flex;justify-content:space-between;font-size:8px;color:#8A8D91;border-top:0.5px solid #e4e6eb}'+
    '@media screen{body{background:#65676B;padding:18px}.page{background:#ffffff;max-width:820px;margin:0 auto;box-shadow:0 8px 30px rgba(0,0,0,.3)}}'+
    '@media print{body{background:#ffffff}.page{box-shadow:none;max-width:none}}'+
    '</style></head><body><div class="page">'+
    '<div class="bar"><i style="background:linear-gradient(90deg,#0064E0,#0082FB,#00C2FF)"></i></div>'+
    '<div class="hd"><div><h1>'+esc(titleStr).toUpperCase()+'</h1><div class="s">'+esc(p.name)+' · '+esc(p.customer||'')+'</div></div><div class="r">MUSE LIVE · Broadcast Operations<br>Generated '+esc(nowStamp())+'</div></div>'+
    '<div class="wrap">'+cardsHTML+'</div>'+
    '<div class="foot"><span>Meta Broadcast Telemetry · Confidential</span><span>'+esc(p.name)+' · Crew Travel</span></div>'+
    '</div></body></html>';
  var w=window.open('','_blank');if(!w){toast('Allow pop-ups to print the itinerary');return;}
  w.document.open();w.document.write(html);w.document.close();
  toast('Travel itinerary ready — choose Save as PDF');
  setTimeout(function(){try{w.focus();w.print();}catch(e){}},650);
}

function travelTabBadge(key){loadTravelOnce();
  var crew=(typeof getProjectCrew==='function')?getProjectCrew(key).filter(function(s){return (s.name||'').trim();}):CREW_FIELD.concat(CREW_IT,CREW_PCR,CREW_EXEC);
  if(typeof permScope==='function'&&permScope('travel')==='own'){var me=permUser();crew=crew.filter(function(m){return m.name===me;});}
  var n=crew.filter(function(m){return !crewFlight(m.name);}).length; // PENDING travelers
  return n?(typeof museBadgeHTML==='function'?museBadgeHTML(n):''):'';}
/* ============================================================================
   TRAVELPAYOUTS FLIGHT SEARCH — embedded widget + Muse auto-fill
   The widget runs in its own iframe, so Muse pre-fills by passing crew data
   into the widget's CONFIG VARIABLES (origin/destination/passengers) and
   re-mounting it, then surfaces the passenger record (name/passport/email) for
   the dispatcher to complete the booking. Marker is set in AI/settings.
   ============================================================================ */
var TP_MARKER='YOUR_MARKER';   // set your Travelpayouts marker in ⚙ (stored locally)
function tpMarker(){try{return localStorage.getItem('muselive_tp_marker')||TP_MARKER;}catch(e){return TP_MARKER;}}
function setTpMarker(v){try{localStorage.setItem('muselive_tp_marker',(v||'').trim());}catch(e){}}
// nearest commercial airport for each production's venue (IATA)
var PROD_AIRPORT={museaitour:'EWR',raybangen3:'JFK',orion:'SJC',museailaunch:'JFK',whatsapp:'DCA',igcreators:'JFK',charm:'MXP'};
function prodAirport(key){return PROD_AIRPORT[key]||'JFK';}
// crew home-base inference: explicit field → city-airport guess → default hub
function crewHomeBase(slot){
  if(slot&&slot.homeBase)return String(slot.homeBase).toUpperCase().slice(0,3);
  if(slot&&slot.name){var od=personnelInfo(slot.name);if(od.homeBase)return String(od.homeBase).toUpperCase().slice(0,3);}
  return 'MIA'; // Meta Miami default hub
}
function crewPassport(slot){if(slot&&slot.passport)return slot.passport;if(slot&&slot.name){var od=personnelInfo(slot.name);if(od.passport)return od.passport;}return '—';}

// current widget config (per travel pane)
var tpConfig={origin:'',destination:'',depart:'',ret:'',oneWay:false,pax:1};
function tpSnippet(){try{return localStorage.getItem('muselive_tp_snippet')||'';}catch(e){return '';}}
function setTpSnippet(v){try{localStorage.setItem('muselive_tp_snippet',(v||'').trim());}catch(e){}}
function tpRouteChips(){
  function ap(code){var a=(typeof airport==='function')?airport(code):{city:code};return code?('<span class="inline-flex items-center gap-1 text-[10px] font-bold mono bg-blue-50 text-blue-700 border border-blue-200 rounded-lg px-2 py-1">'+esc(code)+' · '+esc(a.city||code)+'</span>'):'<span class="text-[10px] text-gray-400">any</span>';}
  return '<div class="flex items-center gap-2 flex-wrap"><span class="text-[9px] font-bold uppercase tracking-wider text-gray-400">Route</span>'+ap(tpConfig.origin)+'<span class="text-gray-300">→</span>'+ap(tpConfig.destination)+(tpConfig.paxName?'<span class="text-[10px] text-gray-500">· '+esc(tpConfig.paxName)+'</span>':'')+'</div>';
}
var tccCtx={key:null,slotId:null,name:null,origin:null,dest:null,depart:null,ret:null};
/* click a pending traveler → push their profile into the widget config */
function tccPick(key,slotId){
  var slot=crewSlotById(key,slotId);if(!slot){toast('Crew member not found');return;}
  var origin=crewHomeBase(slot),dest=prodAirport(key);
  var p=productions[key];
  // broadcast dates: prefer the production window; else a week out + 3 days
  var dep,ret;
  if(p&&p.travelDepart){dep=p.travelDepart;}else{var d=new Date();d.setDate(d.getDate()+7);dep=d.toISOString().slice(0,10);}
  if(p&&p.travelReturn){ret=p.travelReturn;}else{var r=new Date(dep);r.setDate(r.getDate()+3);ret=r.toISOString().slice(0,10);}
  tccCtx={key:key,slotId:slotId,name:slot.name,origin:origin,dest:dest,depart:dep,ret:ret};
  // stage the native flight search with this person's route + run it
  skySearchCtx={key:key,origin:origin,dest:dest,depart:dep,ret:ret,pax:1,name:slot.name,slotId:slotId,results:skyGenFlights(origin,dest,dep)};
  renderTccPane(key); // refresh selection highlight + pax record + results
  toast('Muse staged '+slot.name+': '+origin+' \u2192 '+dest+' \u2014 fares loaded');
}
/* re-render only the control center inner panes (keeps things mounted) */
function renderTccPane(key){
  var host=document.getElementById('tccBody');if(!host){if(productions[key])renderProjectView(key);return;}
  host.innerHTML=tccInnerHTML(key);
  setTimeout(function(){if(document.getElementById('tpWidgetMount'))mountSkyscanner();},30);
}
/* AUTOMATED BOOKING TRIGGER: confirm the staged fare → open the editor pre-filled,
   dispatcher reviews/edits, then Confirm moves pending → booked (reliable + visible) */
/* the inner split-pane content (re-rendered on selection) */
function tccInnerHTML(key){
  var crew=(typeof getProjectCrew==='function')?getProjectCrew(key).filter(function(s){return (s.name||'').trim();}):[];
  var pendingSlots=crew.filter(function(s){return !crewFlight(s.name);});
  var bookedSlots=crew.filter(function(s){return crewFlight(s.name);});
  var dest=prodAirport(key);
  // LEFT: pending list + add-personnel (v33: booking manifests instantly — no completion checklist)
  var left='<div class="flex flex-col" style="min-height:340px">'+
    '<div class="flex items-center justify-between mb-2"><p class="text-[10px] font-bold uppercase tracking-wider text-gray-500">Travel Pending ('+pendingSlots.length+')</p>'+
      '<span class="text-[9px] font-bold"><span class="text-emerald-600">'+bookedSlots.length+' on the manifest</span></span></div>'+
    // add personnel to travel
    '<div class="mb-2">'+tccAddPersonnelPicker(key)+'</div>'+
    (pendingSlots.length?'<div class="space-y-1.5 overflow-y-auto pr-1" style="max-height:250px">'+pendingSlots.map(function(s){return pendingRow(key,s);}).join('')+'</div>'+
      '<p class="text-[9px] text-gray-400 mt-2">Click a traveler to auto-fill their route, passport &amp; broadcast dates into the search → · confirming a booking lands them straight on the manifest</p>':
      '<div class="flex flex-col items-center justify-center text-center py-4"><p class="text-2xl mb-1">✅</p><p class="text-[11px] font-semibold text-gray-700">All assigned crew are booked &amp; on the manifest</p><p class="text-[9px] text-gray-400 mt-0.5">Add personnel above to book more travel.</p></div>')+
  '</div>';
  // RIGHT: staged pax record + NATIVE search + results
  var staged=tccCtx.key===key&&tccCtx.name;
  var slot=staged&&tccCtx.slotId?crewSlotById(key,tccCtx.slotId):null;
  var pax=staged?
    '<div class="bg-blue-50/60 border border-blue-100 rounded-xl p-3 mb-3">'+
      '<div class="flex items-center gap-2 mb-2"><span class="w-5 h-5 rounded bg-blue-600 text-white flex items-center justify-center text-[9px] font-bold">\u2726</span><p class="text-[10px] font-bold uppercase tracking-wider text-blue-700">Muse auto-filled from personnel directory</p></div>'+
      '<div class="grid grid-cols-2 gap-x-4 gap-y-1.5 text-[11px]">'+
        '<div><span class="text-gray-400">Passenger</span><br><span class="font-bold text-gray-900">'+esc(tccCtx.name)+'</span></div>'+
        '<div><span class="text-gray-400">Position</span><br><span class="text-gray-700">'+esc(slot?slot.pos:'\u2014')+'</span></div>'+
        '<div><span class="text-gray-400">Passport / ID</span><br><span class="mono text-gray-700">'+esc(slot?crewPassport(slot):'\u2014')+'</span></div>'+
        '<div><span class="text-gray-400">Email</span><br><span class="mono text-gray-700">'+esc(slot?(slot.email||'\u2014'):'\u2014')+'</span></div>'+
        '<div><span class="text-gray-400">Home base (origin)</span><br><span class="mono font-bold text-blue-700">'+esc(tccCtx.origin)+'</span></div>'+
        '<div><span class="text-gray-400">Destination venue</span><br><span class="mono font-bold text-blue-700">'+esc(tccCtx.dest)+'</span></div>'+
      '</div></div>':
    '<div class="bg-gray-50 border border-gray-100 rounded-xl p-3 mb-3 text-center"><p class="text-[11px] text-gray-500">Select a pending crew member on the left and Muse pushes their <b>name, passport, home-base origin, destination &amp; broadcast dates</b> into the flight search below.</p></div>';
  var right='<div class="flex flex-col">'+
    '<div id="tpRoute" class="mb-3">'+tpRouteChips()+'</div>'+
    pax+
    '<div id="tpWidgetMount" class="rounded-xl"></div>'+
    '<p class="text-[9px] text-gray-400 mt-2 text-center">Search &amp; book natively \u2014 no redirects. On confirm the traveler aggregates straight onto the <b>Broadcast Manifest</b> above \u2014 booked &amp; ready \u2014 and a \ud83d\udccd CREW FLIGHT BOOKED entry is logged to the Operation Log.</p>'+
  '</div>';
  return '<div class="grid grid-cols-1 lg:grid-cols-2 gap-5"><div class="lg:border-r lg:border-gray-100 lg:pr-5">'+left+'</div><div>'+right+'</div></div>';
}
/* searchable picker to add ANY person to this project's travel pending */
function tccAddPersonnelPicker(key){
  return '<div class="relative">'+
    '<div class="flex items-center gap-1.5 border border-gray-200 rounded-lg px-2 py-1.5 bg-gray-50/60 focus-within:border-blue-300">'+
      '<svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="#b0b3b8" stroke-width="2" class="flex-shrink-0"><circle cx="11" cy="11" r="8"/><path d="M21 21l-4.35-4.35"/></svg>'+
      '<input id="tccPerSearch" oninput="tccPerSearchInput(\''+key+'\',this.value)" placeholder="Add personnel to travel\u2026" class="flex-1 bg-transparent text-[11px]" style="outline:none">'+
    '</div>'+
    '<div id="tccPerResults" class="absolute left-0 right-0 top-full mt-1 z-20 bg-white border border-gray-200 rounded-lg shadow-lg max-h-52 overflow-y-auto" style="display:none"></div>'+
  '</div>';
}
function tccPerSearchInput(key,q){
  var box=document.getElementById('tccPerResults');if(!box)return;
  q=(q||'').toLowerCase().trim();
  if(!q){box.style.display='none';box.innerHTML='';return;}
  var assigned={};getProjectCrew(key).forEach(function(s){if(s.name)assigned[s.name]=1;});
  var matches=personnelRoster().filter(function(o){return o.name.toLowerCase().indexOf(q)>-1||(o.pos||'').toLowerCase().indexOf(q)>-1;}).slice(0,12);
  if(!matches.length){box.innerHTML='<div class="px-3 py-2 text-[10px] text-gray-400">No personnel match. <button onclick="openPersonnelAdd()" class="text-blue-700 font-bold">+ Add new</button></div>';box.style.display='block';return;}
  box.innerHTML=matches.map(function(o){var on=assigned[o.name];var nm=o.name.replace(/'/g,"\\'");
    return '<button '+(on?'disabled':'onclick="addPersonnelToTravel(\''+key+'\',\''+nm+'\')"')+' class="w-full text-left px-3 py-2 flex items-center justify-between gap-2 '+(on?'opacity-40':'hover:bg-blue-50')+'">'+
      '<span class="min-w-0"><span class="text-[11px] font-semibold text-gray-900 block truncate">'+esc(o.name)+'</span><span class="text-[9px] text-gray-500 truncate">'+esc(o.pos||'')+(o.homeBase?' \u00b7 '+esc(o.homeBase):'')+'</span></span>'+
      (on?'<span class="text-[8px] font-bold text-gray-400">on travel</span>':'<span class="text-[9px] font-bold text-blue-600">+ add</span>')+'</button>';
  }).join('');
  box.style.display='block';
}
/* add a person to this project's crew roster so they appear in Travel Pending */
function addPersonnelToTravel(key,name){
  var c=getProjectCrew(key);
  for(var i=0;i<c.length;i++){if(c[i].name===name){toast(name+' is already on this production');return;}}
  var info=personnelInfo(name);var roster=personnelRoster();var o=null;for(var j=0;j<roster.length;j++){if(roster[j].name===name){o=roster[j];break;}}
  c.push({id:newSlotId(),pos:(o&&o.pos)||info.pos||'Crew',group:(o&&o.group)||info.group||'Field & Technical',name:name,
    email:(o&&o.email)||info.email||'',phone:(o&&o.phone)||info.phone||'',prov:'',
    passport:(o&&o.passport)||info.passport||'',homeBase:(o&&o.homeBase)||info.homeBase||''});
  stampEdit(key);
  if(typeof logEvent==='function')logEvent(key,'\u2708 '+name+' added to travel pending');
  renderAll();travelRerender(key);
  toast(name+' added to Travel Pending');
}
/* v33: remove a traveler from this project's travel (crew slot; booking released only
   if no OTHER production still crews them — crewFlights is one global record per person) */
function crewedElsewhere(name,skipKey){
  for(var i=0;i<order.length;i++){var k2=order[i];if(k2===skipKey)continue;
    var c2=getProjectCrew(k2);for(var j=0;j<c2.length;j++){if((c2[j].name||'')===name)return k2;}}
  return null;}
function removeFromTravel(key,slotId){
  var c=getProjectCrew(key);var slot=null,idx=-1;
  for(var i=0;i<c.length;i++){if(c[i].id===slotId){slot=c[i];idx=i;break;}}
  if(!slot){toast('Traveler not found');return;}
  var f=crewFlight(slot.name);
  var elsewhere=f?crewedElsewhere(slot.name,key):null;
  if(!confirm('Remove '+slot.name+' from travel on this production?'+
    (f?(elsewhere?' They stay booked ('+f.flightNumber+') on their other production'+(productions[elsewhere]?' — '+(productions[elsewhere].tab||productions[elsewhere].name):'')+'.':' Their '+f.flightNumber+' booking is released and they come off the manifest.'):'')+
    ' Their personnel record is untouched.'))return;
  if(f&&!elsewhere){delete crewFlights[slot.name];}
  c.splice(idx,1);manifestSync(key);saveTravel();
  if(tccCtx.key===key&&tccCtx.slotId===slotId)tccCtx={key:key,slotId:null,name:null,origin:null,dest:null,depart:null,ret:null};
  stampEdit(key);
  if(typeof logEvent==='function')logEvent(key,'\u2716 '+slot.name+' removed from travel'+(f?(elsewhere?' (booking kept \u2014 still crewed elsewhere)':' (booking '+f.flightNumber+' released)'):''));
  if(typeof museAudit==='function')museAudit('travel.removed',{prod:key,person:slot.name});
  renderAll();travelRerender(key);
  toast(slot.name+' removed from travel');
}
/* ============================================================================
   v33 — BROADCAST MANIFEST ≡ THE BOOKED LIST
   Workflow: add personnel to travel → book their flight (data prefilled from
   the personnel directory) → they aggregate onto the manifest INSTANTLY,
   booked & ready. No separate "✓ Manifest" step, no separate tiles: the
   searchable list in the Travel tab IS the manifest, and live flight tracking
   rides the right edge of every row. The stored roster is derived from live
   bookings on every read, so it can never drift.
   ==========================================================================*/
function manifestSync(key){loadTravelOnce();
  var crew=(typeof getProjectCrew==='function')?getProjectCrew(key).filter(function(s){return (s.name||'').trim();}):[];
  var prev=travelManifest[key]||[];var prevBy={};prev.forEach(function(e){prevBy[e.person]=e;});
  travelManifest[key]=crew.filter(function(s){return !!crewFlight(s.name);}).map(function(s){
    var f=crewFlight(s.name);var old=prevBy[s.name];
    /* attribution only from real events (booking records bookedOn/bookedBy) — never fabricated on the read path */
    return {person:s.name,pos:s.pos||(old?old.pos:''),
      completedOn:(old&&old.completedOn)||f.bookedOn||'',by:(old&&old.by)||f.bookedBy||'',
      flight:JSON.parse(JSON.stringify(f)),hotel:crewHotels[s.name]?JSON.parse(JSON.stringify(crewHotels[s.name])):null};});
  return travelManifest[key];}
function manifestList(key){return manifestSync(key);}
function manifestFor(key,name){var a=manifestList(key);for(var i=0;i<a.length;i++)if(a[i].person===name)return a[i];return null;}
/* one re-render entry point for every travel mutation — refreshes the active
   surface (project Travel tab OR the global Travel Portal) + the given project's pane */
function travelRerender(key){var act=document.querySelector('.view-pane.active');var aid=act?act.id:'';
  if(aid==='view-portal'&&typeof renderPortalView==='function'){renderPortalView();if(key&&productions[key])renderProjectView(key);return;}
  var k=aid.replace('view-','');
  if(productions[k])renderProjectView(k);
  else if(key&&productions[key])renderProjectView(key);}
/* ---- hotel booking (per person) ---- */
var hotelEditCtx={key:null,name:null};
function openHotelEdit(key,name){
  var ov=document.getElementById('hotelOverlay'),bx=document.getElementById('hotelBox');if(!ov||!bx)return;
  hotelEditCtx={key:key,name:name};
  var h=crewHotel(name)||{};
  function inp(id,label,val,ph,type){return '<div><label class="text-[8px] font-bold uppercase text-gray-400 block mb-0.5">'+label+'</label><input id="'+id+'" type="'+(type||'text')+'" value="'+esc(val||'').replace(/"/g,'&quot;')+'" placeholder="'+ph+'" class="w-full text-[12px] border border-gray-300 rounded-lg px-2.5 py-2" style="outline:none"></div>';}
  bx.innerHTML='<div class="flex items-center justify-between px-4 py-3 border-b border-gray-100"><div><h3 class="text-sm font-bold text-gray-900">Hotel — '+esc(name)+'</h3><p class="text-[10px] text-gray-500">Booked lodging rides the broadcast manifest with the flight</p></div><button onclick="closeHotelEdit()" class="text-gray-400 hover:text-gray-700 text-lg leading-none">✕</button></div>'+
    '<div class="p-4 space-y-3">'+
      inp('ho_name','Hotel',h.hotel,'InterContinental Miami')+
      '<div class="grid grid-cols-2 gap-3">'+inp('ho_conf','Confirmation #',h.conf,'IC-88213')+inp('ho_addr','Address / Area',h.addr,'495 Brickell Ave')+'</div>'+
      '<div class="grid grid-cols-2 gap-3">'+inp('ho_in','Check-in',h.checkIn,'','date')+inp('ho_out','Check-out',h.checkOut,'','date')+'</div>'+
    '</div>'+
    '<div class="px-4 py-3 border-t border-gray-100 flex items-center gap-2">'+
      '<button onclick="saveHotelEdit()" class="flex-1 bg-blue-600 text-white text-[12px] font-bold rounded-lg py-2.5 hover:bg-blue-700">Save Hotel</button>'+
      (h.hotel?'<button onclick="deleteHotelEdit()" class="text-[11px] font-bold text-red-600 border border-red-200 rounded-lg px-3 py-2 hover:bg-red-50">Remove</button>':'')+
      '<button onclick="closeHotelEdit()" class="text-[11px] font-bold text-gray-600 px-3 py-2">Cancel</button></div>';
  ov.style.display='flex';}
function closeHotelEdit(){var ov=document.getElementById('hotelOverlay');if(ov)ov.style.display='none';}
function saveHotelEdit(){
  var key=hotelEditCtx.key,name=hotelEditCtx.name;if(!name)return;
  function v(id){return ((document.getElementById(id)||{}).value||'').trim();}
  var hotel=v('ho_name');if(!hotel){toast('Hotel name is required');return;}
  crewHotels[name]={hotel:hotel,conf:v('ho_conf'),addr:v('ho_addr'),checkIn:v('ho_in'),checkOut:v('ho_out')};
  var m=manifestFor(key,name);if(m)m.hotel=JSON.parse(JSON.stringify(crewHotels[name])); // manifested entries stay current
  saveTravel();
  if(typeof logEvent==='function')logEvent(key,'🏨 '+name+' — '+hotel+(crewHotels[name].conf?' #'+crewHotels[name].conf:'')+' booked');
  closeHotelEdit();travelRerender(key);toast('🏨 Hotel saved for '+name);}
function deleteHotelEdit(){
  var key=hotelEditCtx.key,name=hotelEditCtx.name;if(!name)return;
  delete crewHotels[name];var m=manifestFor(key,name);if(m)m.hotel=null;
  saveTravel();closeHotelEdit();travelRerender(key);toast('Hotel removed for '+name);}
/* ---- flight phase tracker (computed from itinerary local times; honest — no
        position feed on a static site; deep links open live trackers) ---- */
function flightPhase(f){
  var dep=Date.parse(f.dep&&f.dep.localTime||''),arr=Date.parse(f.arr&&f.arr.localTime||''),now=Date.now();
  if(isNaN(dep)||isNaN(arr))return {id:'tbd',label:'Schedule TBD',pct:0,cls:'bg-gray-100 border-gray-200 text-gray-500'};
  if(now<dep-86400000)return {id:'sched',label:'Scheduled',pct:0,cls:'bg-gray-100 border-gray-200 text-gray-600'};
  if(now<dep-3600000)return {id:'checkin',label:'Check-in open',pct:0,cls:'bg-blue-50 border-blue-200 text-blue-700'};
  if(now<dep)return {id:'boarding',label:'Boarding',pct:2,cls:'bg-amber-50 border-amber-200 text-amber-700'};
  if(now<arr)return {id:'air',label:'En route',pct:Math.max(3,Math.min(97,Math.round((now-dep)/(arr-dep)*100))),cls:'bg-sky-50 border-sky-200 text-sky-700'};
  if(now<arr+3*3600000)return {id:'landed',label:'Landed',pct:100,cls:'bg-emerald-50 border-emerald-200 text-emerald-700'};
  return {id:'done',label:'Completed',pct:100,cls:'bg-gray-900 border-gray-900 text-white'};}
function flightTrackLinks(f){
  var code=(f.airlineCode+f.flightNumber.replace(/^[A-Z]{2}[- ]?/,'')).toLowerCase();
  return '<a href="https://www.flightradar24.com/data/flights/'+code+'" target="_blank" rel="noopener" onclick="event.stopPropagation()" class="text-[8px] font-bold text-sky-700 hover:underline">FR24 ↗</a>'+
    ' <a href="https://www.flightaware.com/live/flight/'+code.toUpperCase()+'" target="_blank" rel="noopener" onclick="event.stopPropagation()" class="text-[8px] font-bold text-sky-700 hover:underline">FlightAware ↗</a>';}
/* v33: the standalone Flight Tracker + Broadcast Manifest tiles are GONE —
   tracking is inline on every manifest row (flightRow) and the searchable
   booked list IS the manifest. printManifest keeps the printable roster. */
function printManifest(key){
  if(typeof permScope==='function'&&permScope('travel')==='own'){toast('🔒 The full manifest is admin-only — use 🎫 Passes for your own itinerary');return;}
  var p=productions[key];var man=manifestList(key);if(!man.length){toast('Manifest is empty');return;}
  var rows=man.map(function(e){var f=e.flight;
    return '<tr><td>'+esc(e.person)+'</td><td>'+esc(e.pos||'')+'</td><td>'+esc(f?f.flightNumber+' '+f.dep.code+'→'+f.arr.code:'—')+'</td><td>'+esc(f?fmtLocalDate(f.dep.localTime)+' '+fmtLocalTime(f.dep.localTime):'')+'</td><td>'+esc(e.hotel?e.hotel.hotel+(e.hotel.conf?' #'+e.hotel.conf:''):'—')+'</td><td>'+esc(e.completedOn||'')+'</td></tr>';}).join('');
  var doc='<html><head><title>Broadcast Manifest — '+esc(p.name)+'</title><style>body{font-family:Arial,sans-serif;margin:32px;color:#18191A}h1{font-size:18px;margin:0 0 2px}p{color:#65676B;font-size:11px;margin:0 0 14px}table{width:100%;border-collapse:collapse;font-size:11px}th{text-align:left;background:#18191A;color:#ffffff;padding:6px 8px;font-size:9px;text-transform:uppercase;letter-spacing:.05em}td{padding:6px 8px;border-bottom:1px solid #e4e6eb}.bar{height:5px;background:linear-gradient(90deg,#0064E0 0%,#0082FB 55%,#00C2FF 100%);margin-bottom:16px}</style></head><body>'+
    '<div class="bar"></div><h1>Broadcast Manifest — '+esc(p.name)+'</h1><p>'+man.length+' booked &amp; ready · generated '+nowStamp()+' · Muse Live</p>'+
    '<table><thead><tr><th>Traveler</th><th>Position</th><th>Flight</th><th>Departure</th><th>Hotel</th><th>Completed</th></tr></thead><tbody>'+rows+'</tbody></table></body></html>';
  var w=window.open('','_blank');if(!w){toast('Pop-up blocked');return;}
  w.document.write(doc);w.document.close();setTimeout(function(){try{w.print();}catch(e){}},450);}
