/* ============================================================================
   NATIVE FLIGHT SEARCH & BOOKING (Skyscanner Partners styling)
   Self-contained — generates realistic itineraries, books natively in-app, no
   redirects. (A true third-party native-booking widget doesn't exist: Skyscanner
   and all metasearch are redirect-based and native ticketing needs IATA/GDS/PCI
   infrastructure a static site can't have. This engine keeps everything on-site
   and records into the crew travel system, which is what dispatch needs.)
   ============================================================================ */
var SKY_BLUE='#0866ff',SKY_NAVY='#0b2a52';
var skySearchCtx={key:null,origin:'',dest:'',depart:'',ret:'',pax:1,name:null,slotId:null,results:null};
/* deterministic pseudo-random from a string seed (stable results per route/date) */
function skyHash(s){var h=2166136261;for(var i=0;i<s.length;i++){h^=s.charCodeAt(i);h=Math.imul(h,16777619);}return (h>>>0);}
function skyRand(seed){var x=Math.sin(seed)*10000;return x-Math.floor(x);}
/* generate realistic flight options for a route */
function skyGenFlights(origin,dest,depart){
  if(!origin||!dest||origin===dest)return [];
  var pool=['AA','DL','UA','WN','AS','B6','NK'];
  // pick a stable subset of carriers for this route
  var base=skyHash(origin+dest+(depart||''));
  var carriers=[];for(var i=0;i<pool.length;i++){if(skyRand(base+i*7)>0.42)carriers.push(pool[i]);}
  if(carriers.length<3)carriers=['AA','DL','UA','B6'];
  var oa=airport(origin),da=airport(dest);
  // crude distance proxy from lat/lng for duration/price
  var dist=2200;try{var dx=(da.lat-oa.lat),dy=(da.lng-oa.lng);dist=Math.max(350,Math.round(Math.sqrt(dx*dx+dy*dy)*69));}catch(e){}
  var intl=(origin==='MXP'||dest==='MXP');
  var out=[];
  carriers.forEach(function(c,idx){
    var seed=skyHash(origin+dest+c+(depart||''))+idx;
    var depH=5+Math.floor(skyRand(seed)*16); // 5am–9pm
    var depM=[0,15,30,45][Math.floor(skyRand(seed+1)*4)];
    var durMin=Math.round((dist/8.2)+30+skyRand(seed+2)*70+(intl?260:0)); // minutes
    var stops=skyRand(seed+3)>(intl?0.45:0.72)?1:0;
    if(stops)durMin+=70+Math.floor(skyRand(seed+4)*120);
    var price=Math.round((dist*0.11)+90+skyRand(seed+5)*180+(intl?540:0)+(stops?-40:60));
    var arrTotal=depH*60+depM+durMin;
    function hhmm(t){t=((t%1440)+1440)%1440;var h=Math.floor(t/60),m=t%60;return (h<10?'0':'')+h+':'+(m<10?'0':'')+m;}
    var nextDay=arrTotal>=1440;
    out.push({airlineCode:(AIRLINES[c]?c:'AA'),flightNumber:c+(100+Math.floor(skyRand(seed+6)*8899)),
      depCode:origin,arrCode:dest,depTime:hhmm(depH*60+depM),arrTime:hhmm(arrTotal),nextDay:nextDay,
      durMin:durMin,stops:stops,price:price});
  });
  // sort by price ascending (Skyscanner default "Best/Cheapest")
  out.sort(function(a,b){return a.price-b.price;});
  return out;
}
function skyFmtDur(min){var h=Math.floor(min/60),m=min%60;return h+'h '+(m<10?'0':'')+m+'m';}
/* render the native search panel into #tpWidgetMount */
function mountSkyscanner(){
  var host=document.getElementById('tpWidgetMount');if(!host)return;
  var c=skySearchCtx;
  var apList=Object.keys(AIRPORTS);
  function apOpts(sel){return '<option value="">From/To</option>'+apList.map(function(a){return '<option value="'+a+'"'+(sel===a?' selected':'')+'>'+a+' — '+esc(AIRPORTS[a].city)+'</option>';}).join('');}
  // search form
  var form='<div class="rounded-xl p-3 mb-3" style="background:'+SKY_NAVY+'">'+
    '<div class="flex items-center gap-2 mb-2.5"><svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="#ffffff" stroke-width="2"><circle cx="11" cy="11" r="8"/><path d="M21 21l-4.35-4.35"/></svg><span class="text-[12px] font-bold text-white">Flight Search</span><span class="text-[8px] font-bold uppercase tracking-wider text-white/60 ml-auto">Skyscanner Partners</span></div>'+
    '<div class="grid grid-cols-2 gap-2 mb-2">'+
      '<div><label class="text-[8px] font-bold uppercase text-white/60 block mb-0.5">From</label><select id="sky_from" class="w-full text-[11px] rounded-lg px-2 py-1.5 bg-white border-0" style="outline:none">'+apOpts(c.origin)+'</select></div>'+
      '<div><label class="text-[8px] font-bold uppercase text-white/60 block mb-0.5">To</label><select id="sky_to" class="w-full text-[11px] rounded-lg px-2 py-1.5 bg-white border-0" style="outline:none">'+apOpts(c.dest)+'</select></div>'+
      '<div><label class="text-[8px] font-bold uppercase text-white/60 block mb-0.5">Depart</label><input id="sky_depart" type="date" value="'+esc(c.depart||'')+'" class="w-full text-[11px] rounded-lg px-2 py-1.5 bg-white border-0" style="outline:none"></div>'+
      '<div><label class="text-[8px] font-bold uppercase text-white/60 block mb-0.5">Return</label><input id="sky_return" type="date" value="'+esc(c.ret||'')+'" class="w-full text-[11px] rounded-lg px-2 py-1.5 bg-white border-0" style="outline:none"></div>'+
    '</div>'+
    '<button onclick="skyDoSearch()" class="w-full text-white text-[12px] font-bold rounded-lg py-2 flex items-center justify-center gap-2" style="background:'+SKY_BLUE+'"><svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="#ffffff" stroke-width="2.5"><circle cx="11" cy="11" r="8"/><path d="M21 21l-4.35-4.35"/></svg>Search flights</button>'+
  '</div>';
  // results
  var results='';
  if(c.results===null){
    results='<div class="text-center py-6 px-3 text-[11px] text-gray-400">Enter a route and search to see live itineraries. Pick a pending crew member on the left and it auto-fills.</div>';
  }else if(!c.results.length){
    results='<div class="text-center py-6 px-3 text-[11px] text-gray-400">No itineraries for that route. Try different airports or dates.</div>';
  }else{
    results='<div class="space-y-2">'+c.results.map(function(f,i){return skyFlightCard(f,i);}).join('')+'</div>';
  }
  host.innerHTML=form+results;
  var rc=document.getElementById('tpRoute');if(rc)rc.innerHTML=tpRouteChips();
}
function skyFlightCard(f,idx){
  var al=airline(f.airlineCode);
  var stops=f.stops?('<span class="text-[9px] font-bold text-amber-600">'+f.stops+' stop</span>'):'<span class="text-[9px] font-bold text-emerald-600">Nonstop</span>';
  var best=idx===0?'<span class="text-[7px] font-bold uppercase tracking-wider text-white rounded px-1 py-0.5" style="background:'+SKY_BLUE+'">Best</span>':'';
  return '<div class="rounded-xl border border-gray-200 hover:border-blue-300 transition-all p-3 flex items-center gap-3 bg-white">'+
    '<div style="width:30px;height:30px;flex-shrink:0">'+al.logo+'</div>'+
    '<div class="flex-1 min-w-0">'+
      '<div class="flex items-center gap-2"><span class="text-[13px] font-bold text-gray-900 mono">'+f.depTime+'</span>'+
        '<div class="flex-1 flex items-center gap-1 min-w-0"><div class="h-px bg-gray-300 flex-1"></div><span class="text-[8px] text-gray-400 whitespace-nowrap">'+skyFmtDur(f.durMin)+'</span><div class="h-px bg-gray-300 flex-1"></div></div>'+
        '<span class="text-[13px] font-bold text-gray-900 mono">'+f.arrTime+(f.nextDay?'<sup class="text-[7px] text-red-500">+1</sup>':'')+'</span></div>'+
      '<div class="flex items-center gap-2 mt-0.5"><span class="text-[9px] text-gray-500 mono">'+f.depCode+' → '+f.arrCode+'</span><span class="text-[9px] text-gray-400">'+esc(al.name)+' '+esc(f.flightNumber)+'</span>'+stops+' '+best+'</div>'+
    '</div>'+
    '<div class="text-right flex-shrink-0">'+
      '<p class="text-[15px] font-bold" style="color:'+SKY_NAVY+'">$'+f.price+'</p>'+
      '<button onclick="skyBook('+idx+')" class="text-[10px] font-bold text-white rounded-lg px-3 py-1.5 mt-0.5" style="background:'+SKY_BLUE+'">Select</button>'+
    '</div>'+
  '</div>';
}
function skyDoSearch(){
  function v(id){return ((document.getElementById(id)||{}).value||'');}
  var o=v('sky_from'),d=v('sky_to'),dep=v('sky_depart'),ret=v('sky_return');
  if(!o||!d){toast('Pick both From and To airports');return;}
  if(o===d){toast('Origin and destination must differ');return;}
  skySearchCtx.origin=o;skySearchCtx.dest=d;skySearchCtx.depart=dep;skySearchCtx.ret=ret;
  skySearchCtx.results=skyGenFlights(o,d,dep);
  if(tccCtx&&tccCtx.key)tccCtx.origin=o,tccCtx.dest=d,tccCtx.depart=dep,tccCtx.ret=ret;
  mountSkyscanner();
}
/* native booking — no redirect; records the selected itinerary into crew travel */
function skyBook(idx){
  var c=skySearchCtx;if(!c.results||!c.results[idx]){toast('Select a flight');return;}
  var f=c.results[idx];
  var key=c.key||(tccCtx&&tccCtx.key)||currentTravelKey();
  var name=c.name||(tccCtx&&tccCtx.name);
  if(!name){toast('Pick a pending crew member on the left first');return;}
  // open the booking editor pre-filled with the chosen itinerary for final review/confirm
  skyPrefillBooking(key,name,c.slotId||(tccCtx&&tccCtx.slotId),f,c);
}
function travelInit(){loadTravelOnce();}

/* ================================================================================
   8. GLOBAL SEARCH — index everything, jump anywhere
      Productions, crew, equipment, vendors, ENG requests, flights, finance docs.
   ================================================================================ */

function buildSearchIndex(){
  var idx=[];
  // productions
  order.forEach(function(k){var p=productions[k];
    idx.push({type:'Production',label:p.name,sub:(p.venue||'')+' · '+(p.date||''),icon:'🎬',action:"openProject('"+k+"')",kw:(p.name+' '+(p.venue||'')+' '+(p.customer||'')+' '+(p.tag||'')).toLowerCase()});
  });
  // personnel (full directory incl. custom + PER ids/categories — v31)
  var seen={};var allCrew=(typeof personnelRoster==='function')?personnelRoster():CREW_FIELD.concat(CREW_IT,CREW_PCR,CREW_EXEC);
  allCrew.forEach(function(m){if(seen[m.name])return;seen[m.name]=1;
    idx.push({type:'Personnel',label:m.name,sub:m.pos+(m.prov?' · '+m.prov:''),icon:'👤',action:"globalOpenCrew('"+m.name.replace(/'/g,"\\'")+"')",kw:(m.name+' '+m.pos+' '+(m.email||'')+' '+(m.prov||'')+' '+(m.id||'')+' '+(m.category||'')).toLowerCase()});
  });
  // flights (role-scoped: restricted roles only index their own itinerary)
  if(typeof crewFlights!=='undefined'){Object.keys(crewFlights).filter(function(nm){return (typeof permScope!=='function'||permScope('travel')!=='own')||nm===permUser();}).forEach(function(nm){var f=crewFlights[nm];var al=airline(f.airlineCode);
    idx.push({type:'Flight',label:f.flightNumber+' · '+nm,sub:al.name+' · '+f.dep.code+'→'+f.arr.code,icon:'✈️',action:"globalOpenTicket('"+nm.replace(/'/g,"\\'")+"')",kw:(f.flightNumber+' '+nm+' '+al.name+' '+f.dep.code+' '+f.arr.code+' '+airport(f.dep.code).city+' '+airport(f.arr.code).city).toLowerCase()});
  });}
  // ENG requests
  if(typeof engRequests!=='undefined'){engRequests.forEach(function(e){var p=productions[e.prod]||{name:e.prod};
    var camAll=(e.cameras&&e.cameras.length)?e.cameras:[{camera:e.camera,opname:e.opname}];
    var camKw=camAll.map(function(c){return (c.camera||'')+' '+(c.lens||'')+' '+(c.opname||'');}).join(' ');
    var lgtKw=(e.lighting||[]).map(function(g){return g.model;}).join(' ');
    var sub=p.name+' · '+camAll.length+' cam · '+(camAll[0].camera||'camera TBD')+' · '+e.status;
    idx.push({type:'ENG Request',label:e.id+' · '+e.name,sub:sub,icon:'🎥',action:"globalOpenEng('"+e.id+"')",kw:(e.id+' '+e.name+' '+camKw+' '+lgtKw+' '+((e.liveus||[]).map(function(u){return u.model+' '+u.serial+(u.multicam?' multicam multi-cam':'');}).join(' '))+' '+((e.rems||[]).concat(e.tiffs||[]).map(function(l){return (l.talent||l.person||'');}).join(' '))+' '+p.name+' '+e.status).toLowerCase()});
  });}
  // vendors (hidden for roles without vendor access)
  if(typeof vendors!=='undefined'&&(typeof permCan!=='function'||permCan('vendors'))){vendors.forEach(function(v){
    idx.push({type:'Vendor',label:v.name,sub:(v.category||'')+(v.contact?' · '+v.contact:''),icon:'🏢',action:"globalOpenVendor('"+v.id+"')",kw:(v.name+' '+(v.category||'')+' '+(v.contact||'')+' '+(v.email||'')).toLowerCase()});
  });}
  // finance docs (PO / WO / Invoice) — hidden for roles without finance access
  var _permFin=(typeof permCan!=='function'||permCan('finance'));
  if(typeof finPOs!=='undefined'&&_permFin){finPOs.forEach(function(po){var p=productions[po.prod]||{name:po.prod};
    idx.push({type:'Purchase Order',label:po.id+' · '+po.vendor,sub:p.name+' · '+$fmt(po.amount)+' · '+po.status,icon:'📄',action:"globalOpenFin('po','"+po.id+"','"+po.prod+"')",kw:(po.id+' '+po.vendor+' '+p.name+' '+(po.desc||'')).toLowerCase()});});}
  if(typeof workOrders!=='undefined'&&_permFin){workOrders.forEach(function(w){var p=productions[w.prod]||{name:w.prod};
    idx.push({type:'Work Order',label:w.id+' · '+(w.desc||'').slice(0,40),sub:p.name+' · '+$fmt(w.cost||0)+' · '+w.status,icon:'🛠',action:"globalOpenFin('wo','"+w.id+"','"+w.prod+"')",kw:(w.id+' '+(w.desc||'')+' '+p.name).toLowerCase()});});}
  if(typeof finInvoices!=='undefined'&&_permFin){finInvoices.forEach(function(iv){var p=productions[iv.prod]||{name:iv.prod};
    idx.push({type:'Invoice',label:iv.id+' · '+iv.vendor,sub:p.name+' · '+$fmt(iv.amount)+' · '+iv.status,icon:'💵',action:"globalOpenFin('inv','"+iv.id+"','"+iv.prod+"')",kw:(iv.id+' '+iv.vendor+' '+p.name).toLowerCase()});});}
  // equipment lines across productions
  order.forEach(function(k){var p=productions[k];if(!p.tbEquip)return;
    Object.keys(p.tbEquip).forEach(function(dep){(p.tbEquip[dep]||[]).forEach(function(ln){
      var nm=ln.model||ln.item||'';if(!nm)return;
      idx.push({type:'Equipment · packlist lines',label:nm,sub:p.name+' · '+dep,icon:'📦',action:"openProjPack('"+k+"')",kw:(nm+' '+dep+' '+p.name+' '+(ln.lens||'')+' '+(ln.notes||'')).toLowerCase()});
    });});
  });
  // departments per production
  order.forEach(function(k){var p=productions[k];(p.dept||[]).forEach(function(d){
    if((p.tbFields&&p.tbFields[d[0]])||hasEquip(p,d[0])){}
  });});
  // communications (email + teams) — role-scoped: exec threads invisible to restricted roles
  if(typeof comms!=='undefined'){((typeof permComms==='function')?permComms():comms).forEach(function(m){
    idx.push({type:'Message',label:(m.subject||('Teams · '+m.from)),sub:(m.channel==='teams'?'Teams':'Outlook')+' · '+(m.dir==='out'?'to '+m.to:m.from)+' · '+commsLinkLabel(m.linkType,m.linkId),icon:(m.channel==='teams'?'💬':'✉️'),action:"globalOpenComms('"+(m.thread||m.id)+"')",kw:(m.subject+' '+m.from+' '+m.to+' '+museRichPlain(m.body)+' '+commsLinkLabel(m.linkType,m.linkId)).toLowerCase()});
  });}
  // inventory (barcode-tracked equipment) — role-scoped to own gear for restricted roles
  if(typeof inventory!=='undefined'){((typeof permInventory==='function')?permInventory():inventory).forEach(function(it){var st=(INV_STATUSES[it.status]||{}).label||it.status;
    idx.push({type:'Inventory',label:it.name,sub:it.barcode+' · '+it.category+' · '+st,icon:'📦',action:"globalOpenInv('"+it.id+"')",kw:(it.name+' '+it.barcode+' '+(it.serial||'')+' '+it.category+' '+(it.assignedTo||'')+' '+(it.location||'')).toLowerCase()});
  });}
  return idx;
}
function globalOpenInv(id){globalSearchClose();switchView('equipment');setTimeout(function(){if(typeof openInvDetail==='function')openInvDetail(id);},120);}

var _searchIdx=null;var _searchFuse=null;var _searchFuseSrc=null; /* Fuse.js fuzzy index (rebuilt when _searchIdx changes) */
var _gsAiTimer=null;var _gsAiToken=0;var _gsLastHits=[];var _gsLastQ='';
function globalSearchOpen(){
  _searchIdx=buildSearchIndex();
  var ov=document.getElementById('gsOverlay');if(!ov)return;
  ov.style.display='flex';
  var ai=document.getElementById('gsAiPanel');if(ai){ai.classList.add('hidden');ai.innerHTML='';}
  var inp=document.getElementById('gsInput');if(inp){inp.value='';setTimeout(function(){inp.focus();},60);}
  globalSearchRender('');
}
function globalSearchClose(){
  if(_gsAiTimer){clearTimeout(_gsAiTimer);_gsAiTimer=null;}
  _gsAiToken++;
  var ov=document.getElementById('gsOverlay');if(ov)ov.style.display='none';
}
function globalSearchRender(q){
  var raw=q||'';
  var corr=null;try{if(typeof museCorrectQuery==='function')corr=museCorrectQuery(raw);}catch(e){}
  var q0=(raw||'').toLowerCase().trim();
  var q=(corr&&corr.q?corr.q:q0).toLowerCase().trim();
  var box=document.getElementById('gsResults');if(!box)return;
  if(!_searchIdx)_searchIdx=buildSearchIndex();
  if(!q0){
    if(_gsAiTimer){clearTimeout(_gsAiTimer);_gsAiTimer=null;}
    var ai0=document.getElementById('gsAiPanel');if(ai0){ai0.classList.add('hidden');ai0.innerHTML='';}
    var byType={};_searchIdx.forEach(function(r){byType[r.type]=(byType[r.type]||0)+1;});
    box.innerHTML='<div class="px-4 py-6 text-center"><p class="text-[11px] text-gray-500 mb-1 font-semibold">Search everything · typo-tolerant · Ask Muse</p>'+
      '<p class="text-[10px] text-gray-400 mb-3">Misspellings are corrected automatically. Jump to records or ask a natural question.</p>'+
      '<div class="flex flex-wrap gap-1.5 justify-center">'+Object.keys(byType).map(function(t){return '<span class="text-[9px] mono bg-gray-100 border border-gray-200 text-gray-600 rounded-lg px-2 py-1">'+t+' · '+byType[t]+'</span>';}).join('')+'</div>'+
      '<p class="text-[9px] text-gray-400 mt-4">Try: <button type="button" class="text-blue-700 font-bold hover:underline" onclick="globalSearchPreset(\'Muse AI World Tour go no go\')">Muse AI World Tour go no go</button> · '+
      '<button type="button" class="text-blue-700 font-bold hover:underline" onclick="globalSearchPreset(\'superbow audio\')">superbow audio</button> · '+
      '<button type="button" class="text-blue-700 font-bold hover:underline" onclick="globalSearchPreset(\'personel directory\')">personel</button></p></div>';
    return;
  }
  /* Search both raw and spell-corrected forms; Fuse for typos; local fuzzy if Fuse absent */
  var queries=[q0];if(q&&q!==q0)queries.push(q);
  /* also token-wise corrected variants */
  var exact=[];
  queries.forEach(function(qq){
    _searchIdx.forEach(function(r){if(r.kw.indexOf(qq)>-1)exact.push(r);});
  });
  var hits;
  function _fuseHits(){
    if(typeof Fuse==='undefined')return null;
    if(!_searchFuse||_searchFuseSrc!==_searchIdx){
      try{
        _searchFuse=new Fuse(_searchIdx,{
          keys:[{name:'kw',weight:0.5},{name:'label',weight:0.35},{name:'sub',weight:0.15}],
          threshold:0.42, /* more typo-tolerant than 0.34 */
          distance:200,
          ignoreLocation:true,
          minMatchCharLength:2,
          includeScore:true
        });
        _searchFuseSrc=_searchIdx;
      }catch(e){_searchFuse=null;}
    }
    if(!_searchFuse)return null;
    var out=[];var seenF={};
    queries.forEach(function(qq){
      _searchFuse.search(qq).forEach(function(r){
        var it=r.item;var k=it.type+'|'+it.label;
        if(!seenF[k]){seenF[k]=1;out.push(it);}
      });
    });
    return out;
  }
  function _localFuzzyHits(){
    if(typeof museEditDist!=='function')return [];
    var tokens=q.split(/[^a-z0-9]+/).filter(function(t){return t.length>=3;});
    if(!tokens.length)return [];
    var scored=[];
    _searchIdx.forEach(function(r){
      var labelToks=(r.label+' '+(r.sub||'')).toLowerCase().split(/[^a-z0-9]+/).filter(function(t){return t.length>=3;});
      var score=0;
      tokens.forEach(function(t){
        var best=99;
        labelToks.forEach(function(lt){
          if(lt===t){best=0;return;}
          if(lt.indexOf(t)===0||t.indexOf(lt)===0){best=Math.min(best,1);return;}
          var d=museEditDist(t,lt);if(d<best)best=d;
        });
        if(best<=(t.length<=4?1:2))score+=3-best;
      });
      if(score>0)scored.push({r:r,s:score});
    });
    scored.sort(function(a,b){return b.s-a.s;});
    return scored.slice(0,40).map(function(x){return x.r;});
  }
  var fz=_fuseHits();
  var localF=(!fz||!fz.length)?_localFuzzyHits():[];
  if(fz&&fz.length){
    var seen={};hits=[];exact.concat(fz).forEach(function(r){var k=r.type+'|'+r.label+'|'+(r.sub||'');if(!seen[k]){seen[k]=1;hits.push(r);}});
    hits=hits.slice(0,40);
  } else {
    var seen2={};hits=[];exact.concat(localF).forEach(function(r){var k=r.type+'|'+r.label+'|'+(r.sub||'');if(!seen2[k]){seen2[k]=1;hits.push(r);}});
    hits=hits.slice(0,40);
    if(typeof MuseLazy!=='undefined'&&MuseLazy.ensureFuse&&!window.__museFuseLoading){
      window.__museFuseLoading=true;
      MuseLazy.ensureFuse().then(function(){window.__museFuseLoading=false;try{globalSearchRender(raw);}catch(eR){}}).catch(function(){window.__museFuseLoading=false;});
    }
  }
  _gsLastHits=hits||[];
  _gsLastQ=q; /* Search uses corrected query */
  var spellBar='';
  if(corr&&corr.corrections&&corr.corrections.length){
    spellBar='<div class="px-3 py-2 mx-2 mt-2 rounded-lg bg-amber-50 border border-amber-200 text-[10px] text-amber-900">'+
      '<span class="font-bold">Did you mean</span> · '+esc(typeof museCorrectHint==='function'?museCorrectHint(corr):q)+
      ' <button type="button" class="ml-1 font-bold text-blue-700 hover:underline" onclick="globalSearchPreset('+JSON.stringify(q).replace(/</g,'\\u003c')+')">Search “'+esc(q)+'”</button></div>';
  }
  if(!hits.length){
    box.innerHTML=spellBar+'<div class="px-4 py-6 text-center text-[11px] text-gray-400">No indexed matches for "<b>'+esc(raw)+'</b>"'+(q!==q0?' (also tried “'+esc(q)+'”)':'')+' — Search below may still answer.</div>';
  } else {
    var groups={};hits.forEach(function(r){(groups[r.type]=groups[r.type]||[]).push(r);});
    box.innerHTML=spellBar+Object.keys(groups).map(function(t){
      return '<div class="px-2 pt-2"><p class="text-[8px] font-bold uppercase tracking-wider text-gray-400 px-2 mb-1">'+t+' ('+groups[t].length+')</p>'+
        groups[t].map(function(r){return '<button onclick="globalSearchGo('+_searchIdx.indexOf(r)+')" class="w-full text-left flex items-center gap-3 px-2 py-2 rounded-lg hover:bg-blue-50 group">'+
          '<span class="text-base flex-shrink-0">'+r.icon+'</span>'+
          '<div class="min-w-0 flex-1"><p class="text-[12px] font-semibold text-gray-900 truncate group-hover:text-blue-700">'+esc(r.label)+'</p><p class="text-[9px] text-gray-500 truncate">'+esc(r.sub)+'</p></div>'+
          '<svg class="flex-shrink-0 text-gray-300 group-hover:text-blue-500" width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M9 18l6-6-6-6"/></svg></button>';}).join('')+'</div>';
    }).join('');
  }
  if(typeof MuseWork!=='undefined')box.insertAdjacentHTML('beforeend',MuseWork.globalResultsHTML(raw));
  /* Muse search — use spell-corrected query */
  globalSearchScheduleAI(q||raw, hits);
}
function globalSearchPreset(q){
  var inp=document.getElementById('gsInput');if(inp)inp.value=q;
  globalSearchRender(q);
  globalSearchAskNow();
}
function globalSearchAskNow(){
  var inp=document.getElementById('gsInput');
  var q=inp?inp.value:'';
  if(!q||!String(q).trim())return;
  if(_gsAiTimer){clearTimeout(_gsAiTimer);_gsAiTimer=null;}
  globalSearchRunAI(String(q).trim(), _gsLastHits||[]);
}
function globalSearchScheduleAI(q, hits){
  if(_gsAiTimer)clearTimeout(_gsAiTimer);
  q=String(q||'').trim();
  if(q.length<2){
    var ai=document.getElementById('gsAiPanel');
    if(ai){ai.classList.add('hidden');ai.innerHTML='';}
    return;
  }
  /* Show pending panel immediately for longer queries / NL style */
  var looksNL=q.length>=8||/\s/.test(q)||/\?$/.test(q)||/^(what|who|where|when|why|how|is|are|can|does|show|find|list|explain|tell)\b/i.test(q);
  var delay=looksNL?380:700;
  globalSearchAiPanel('thinking', q, null, hits);
  _gsAiTimer=setTimeout(function(){globalSearchRunAI(q, hits);}, delay);
}
function globalSearchAiPanel(mode, q, text, hits, gotoBtns){
  var ai=document.getElementById('gsAiPanel');if(!ai)return;
  ai.classList.remove('hidden');
  if(mode==='thinking'){
    ai.innerHTML='<div class="px-4 py-3 bg-gradient-to-r from-emerald-50/80 to-blue-50/50">'+
      '<div class="flex items-center gap-2 mb-1"><span class="w-1.5 h-1.5 rounded-full bg-emerald-500 animate-pulse"></span>'+
      '<p class="text-[9px] font-bold uppercase tracking-wider text-emerald-800">Muse Search</p>'+
      '</div>'+
      '<p class="text-[11px] text-gray-500">Thinking about “'+esc(q)+'”…</p></div>';
    return;
  }
  if(mode==='error'){
    ai.innerHTML='<div class="px-4 py-3 bg-amber-50/80 border-b border-amber-100">'+
      '<p class="text-[9px] font-bold uppercase tracking-wider text-amber-800 mb-1">Muse Search</p>'+
      '<p class="text-[11px] text-amber-900/90">'+esc(text||'Unavailable')+'</p>'+
      '<button type="button" onclick="testMuseAi&&testMuseAi()" class="mt-2 text-[10px] font-bold text-emerald-800 hover:underline">Test Muse</button></div>';
    return;
  }
  var btns=(gotoBtns&&gotoBtns.length)?'<div class="flex flex-wrap gap-1.5 mt-2">'+gotoBtns.map(function(b){
    return '<button type="button" onclick="globalSearchGo('+b.idx+')" class="text-[10px] font-bold text-blue-800 bg-white border border-blue-200 rounded-lg px-2 py-1 hover:bg-blue-50">'+esc(b.icon+' '+b.label)+'</button>';
  }).join('')+'</div>':'';
  var hitN=(hits&&hits.length)?hits.length:0;
  ai.innerHTML='<div class="px-4 py-3 bg-gradient-to-r from-emerald-50/90 to-slate-50">'+
    '<div class="flex items-center gap-2 mb-1.5"><span class="w-1.5 h-1.5 rounded-full bg-emerald-500"></span>'+
    '<p class="text-[9px] font-bold uppercase tracking-wider text-emerald-800">Muse Search</p>'+
    '<span class="text-[9px] text-gray-400 mono ml-auto">'+(hitN?hitN+' indexed hit'+(hitN===1?'':'s'):'no index hits')+'</span></div>'+
    '<p class="text-[12px] text-gray-800 leading-relaxed" style="white-space:pre-wrap;overflow-wrap:anywhere">'+esc(text||'')+'</p>'+btns+
    '<p class="text-[9px] text-gray-400 mt-2">Muse</p></div>';
}
function globalSearchRunAI(q, hits){
  q=String(q||'').trim();if(!q)return;
  var token=++_gsAiToken;
  hits=hits||_gsLastHits||[];
  globalSearchAiPanel('thinking', q, null, hits);

  var top=hits.slice(0,18).map(function(r,i){
    return (i+1)+'. ['+r.type+'] '+r.label+(r.sub?' — '+r.sub:'');
  }).join('\n');
  var idxStats={};
  try{(_searchIdx||[]).forEach(function(r){idxStats[r.type]=(idxStats[r.type]||0)+1;});}catch(e){}
  var hitsText=top||'(no keyword/fuzzy matches — still answer from Muse Live knowledge or general knowledge)';

  function composeLocalAnswer(){
    var parts=[];
    if(typeof museaiLooksRealWorld==='function'&&museaiLooksRealWorld(q)&&typeof museaiRealWorldTry==='function'){
      return museaiRealWorldTry(q).then(function(rw){
        if(rw)parts.push(String(rw).trim());
        if(hits&&hits.length){
          parts.push((parts.length?'\n\n':'')+'Muse Live matches:\n'+hits.slice(0,8).map(function(r,i){
            return (i+1)+'. '+r.label+(r.sub?' — '+r.sub:'');
          }).join('\n'));
        }else if(!parts.length&&typeof museaiAnswer==='function'){
          try{var ra=museaiAnswer(q);if(ra)parts.push(ra);}catch(eR){}
        }
        return parts.join('')||null;
      });
    }
    if(hits&&hits.length){
      return Promise.resolve('Muse Live matches for “'+q+'”:\n'+hits.slice(0,10).map(function(r,i){
        return (i+1)+'. ['+r.type+'] '+r.label+(r.sub?' — '+r.sub:'');
      }).join('\n'));
    }
    if(typeof museaiAnswer==='function'){
      try{var a=museaiAnswer(q);if(a)return Promise.resolve(a);}catch(eA){}
    }
    return Promise.resolve(null);
  }

  var aiPromise;
  if(typeof MuseAiMuseAi!=='undefined'&&MuseAiMuseAi.ask){
    aiPromise=MuseAiMuseAi.ask(q).catch(function(){return composeLocalAnswer();});
  }else if(typeof museaiLooksRealWorld==='function'&&museaiLooksRealWorld(q)){
    aiPromise=composeLocalAnswer();
  }else{
    aiPromise=composeLocalAnswer();
  }

  aiPromise.then(function(ans){
    if(token!==_gsAiToken)return;
    if(ans==null||!String(ans).trim()){
      globalSearchAiPanel('error', q, 'No Muse answer for that query yet. Indexed results above still work — or try a Muse Live status or weather question.', hits);
      return;
    }
    var text=String(ans).trim();
    /* Parse GOTO lines into buttons */
    var gotos=[];
    var bodyLines=[];
    text.split(/\n/).forEach(function(line){
      var m=line.match(/^\s*GOTO:\s*(.+?)\s*\|\s*(.+?)\s*$/i);
      if(m){
        var typ=m[1].trim().toLowerCase();
        var lab=m[2].trim().toLowerCase();
        var idx=-1;
        for(var i=0;i<(_searchIdx||[]).length;i++){
          var r=_searchIdx[i];
          if(String(r.label).toLowerCase()===lab||String(r.label).toLowerCase().indexOf(lab)>=0){
            if(!typ||String(r.type).toLowerCase().indexOf(typ.replace(/\s+/g,''))>=0||String(r.type).toLowerCase()===typ){
              idx=i;break;
            }
            if(idx<0)idx=i;
          }
        }
        /* also match against hits list */
        if(idx<0&&hits){
          for(var j=0;j<hits.length;j++){
            if(String(hits[j].label).toLowerCase().indexOf(lab)>=0){
              idx=_searchIdx.indexOf(hits[j]);break;
            }
          }
        }
        if(idx>=0&&_searchIdx[idx]){
          gotos.push({idx:idx,label:_searchIdx[idx].label,icon:_searchIdx[idx].icon||'→'});
        }
      }else if(!/^\s*GOTO:/i.test(line)){
        bodyLines.push(line);
      }
    });
    /* Dedup gotos */
    var seenG={};gotos=gotos.filter(function(g){if(seenG[g.idx])return false;seenG[g.idx]=1;return true;}).slice(0,4);
    /* If model forgot GOTOs but we have hits, offer top 3 */
    if(!gotos.length&&hits&&hits.length){
      hits.slice(0,3).forEach(function(h){
        var i=_searchIdx.indexOf(h);
        if(i>=0)gotos.push({idx:i,label:h.label,icon:h.icon||'→'});
      });
    }
    var body=bodyLines.join('\n').trim()||text;
    globalSearchAiPanel('answer', q, body, hits, gotos);
  }).catch(function(err){
    if(token!==_gsAiToken)return;
    var em=(err&&err.message)?String(err.message):'Model not ready';
    em=em.replace(/\bWebGPU\b/gi,'GPU');
    globalSearchAiPanel('error', q, 'Search unavailable ('+em.slice(0,100)+'). Indexed results above still work. Open Muse settings to load the free model.', hits);
  });
}
function globalSearchGo(i){if(!_searchIdx||!_searchIdx[i])return;var r=_searchIdx[i];globalSearchClose();
  try{eval(r.action);}catch(e){console.error(e);}}

/* navigation helpers used by search actions */
function globalOpenCrew(name){var m=crewMember(name);if(!m)return;
  // find a production to anchor the crew card on
  switchView(order[0]);setTimeout(function(){openCrewCard(name,order[0]);},120);}
function globalOpenTicket(name){openTicket(name);}
