/* keyboard shortcut: Cmd/Ctrl-K opens search; Esc closes */
document.addEventListener('keydown',function(e){
  if((e.metaKey||e.ctrlKey)&&(e.key==='k'||e.key==='K')){e.preventDefault();globalSearchOpen();}
  if(e.key==='Escape'){var ov=document.getElementById('gsOverlay');if(ov&&ov.style.display==='flex')globalSearchClose();var tk=document.getElementById('ticketOverlay');if(tk&&tk.style.display==='flex')closeTicket();}
});

