/* a span [a,a+aw) overlaps [b,b+bw) ? */
function spanOverlap(a,aw,b,bw){return a < b+bw && b < a+aw;}

/* ================================================================================
   ACTIVE PCR/ACR BOARD ↔ MUSE SCHEDULE
   The dashboard control-room board renders LIVE from FACILITY_ROWS, which Muse Schedule
   regenerates from its bookings. One source of truth: change a booking and the chips,
   tooltips and routing chains follow.
   ================================================================================ */
var SCHED_ROOMS={
 'Production Control (PCR)':['PCR 1','PCR 2','PCR 3','PCR 4','PCR 5','PCR 6','PCR 7','PCR 8'],
 'Audio Control (ACR)':['ACR 1','ACR 2','ACR 3','ACR 4','ACR 6','ACR 7','MIX 4'],
 'Transmission Circuits (CRK)':['CRK 1','CRK 2','CRK 3','CRK 4','CRK 5','CRK 6','CRK 7','CRK 8','CRK 9','CRK 10']};
function schedTodayCol(){return (new Date().getDay()+6)%7;} /* Mon=0 … Sun=6 — the NPC_DAYS demo week */
function roomBookings(room){var row=FACILITY_ROWS.filter(function(r){return r[0]===room;})[0];return row?row[1]:[];}
function roomToday(room){var t=schedTodayCol();return roomBookings(room).filter(function(b){return t>=b[0]&&t<b[0]+b[1];});}
function roomState(room){var tb=roomToday(room);
  if(!tb.length)return {s:'idle',all:[]};
  var onair=tb.filter(function(b){return /on air/i.test(b[5]||'');})[0];
  if(onair)return {s:'onair',b:onair,all:tb};
  var setup=tb.every(function(b){return /test|build|bench|config|setup|rehears|survey|map/i.test(b[2]);});
  return {s:setup?'setup':'active',b:tb[0],all:tb};}
function roomTip(room){var st=roomState(room);
  if(st.s==='idle')return room+' — idle today · click for this week’s schedule';
  return room+' — '+st.all.map(function(b){return b[2]+(b[5]?' · '+b[5]:'');}).join('  |  ');}
function renderRoutingBoard(){var host=document.getElementById('routingBoard');if(!host)return;
  var html=Object.keys(SCHED_ROOMS).map(function(grp){
    var rooms=SCHED_ROOMS[grp];var cols=grp.indexOf('CRK')>=0?'grid-cols-5':(rooms.length>7?'grid-cols-4 sm:grid-cols-8':'grid-cols-4 sm:grid-cols-7');
    return '<div><span class="text-[9px] text-gray-500 uppercase font-bold tracking-wider block mb-1">'+grp+'</span>'+
      '<div class="grid '+cols+' gap-1 mono text-center text-[9px]">'+rooms.map(function(rm){
        var st=roomState(rm);var short=rm.replace(' ','');
        var cls=st.s==='onair'?'bg-red-50 border-red-300 font-bold text-red-700':
                st.s==='active'?'bg-emerald-50 border-emerald-200 font-bold text-emerald-800':
                st.s==='setup'?'bg-amber-50 border-amber-200 font-bold text-amber-700':
                'bg-gray-50 border-gray-200/60 text-gray-500';
        return '<button onclick="openRoomDetail(\''+rm+'\')" title="'+esc(roomTip(rm)).replace(/"/g,'&quot;')+'" class="py-1.5 rounded border '+cls+' cursor-pointer hover:ring-1 hover:ring-blue-300 transition-shadow w-full flex items-center justify-center gap-1">'+
          (st.s==='onair'?'<span class="onair w-1.5 h-1.5 rounded-full bg-red-500"></span>':'')+short+'</button>';
      }).join('')+'</div></div>';
  }).join('');
  html+=schedChainsHTML();
  host.innerHTML=html;}
function schedChainsHTML(){var t=schedTodayCol();
  var byProd={};
  FACILITY_ROWS.forEach(function(r){r[1].forEach(function(b){if(!b[6])return;if(!(t>=b[0]&&t<b[0]+b[1]))return;
    var o=byProd[b[6]]=byProd[b[6]]||{};var rm=r[0];
    if(/^PCR/.test(rm)&&!o.pcr)o.pcr={rm:rm,b:b};
    else if((/^ACR|^MIX/.test(rm))&&!o.acr)o.acr={rm:rm,b:b};
    else if(/^CRK/.test(rm)&&!o.crk)o.crk={rm:rm,b:b};});});
  var rows=Object.keys(byProd).map(function(pk){var o=byProd[pk];var legs=[o.pcr,o.acr,o.crk].filter(Boolean);
    if(legs.length<2)return '';
    var onair=legs.some(function(l){return /on air/i.test(l.b[5]||'');});
    var tone=onair?'bg-red-50 border-red-200':'bg-emerald-50 border-emerald-200';
    var dot=onair?'<span class="onair w-1.5 h-1.5 rounded-full bg-red-500"></span>':'<span class="w-1.5 h-1.5 rounded-full bg-emerald-500"></span>';
    var name=(productions[pk]&&(productions[pk].tab||productions[pk].name))||pk;
    var win=(o.crk&&o.crk.b[5])||(o.pcr&&o.pcr.b[5])||'';
    return '<div onclick="openProject(\''+pk+'\')" title="'+esc(name+(win?' · '+win:'')).replace(/"/g,'&quot;')+'" class="flex items-center justify-between '+tone+' border rounded px-2 py-1 cursor-pointer hover:ring-1 hover:ring-blue-300"><span class="flex items-center gap-1.5">'+dot+
      legs.map(function(l,i){return (i?'<span class="text-gray-500">→</span>':'')+'<b class="'+(i===legs.length-1&&onair?'text-red-700':'text-gray-800')+'">'+l.rm.replace(' ','')+'</b>';}).join('')+
      '</span><span class="text-[8px] text-gray-600 truncate" style="max-width:110px">'+esc(name)+(win?' · '+esc(win.replace(/^ON AIR · /i,'')):'')+'</span></div>';
  }).filter(Boolean).join('');
  return '<div><span class="text-[9px] text-gray-500 uppercase font-bold tracking-wider block mb-1">Active Routing · PCR → ACR → CRK · '+esc(NPC_DAYS[t]||'')+'</span>'+
    '<div class="space-y-1 text-[9px] mono">'+(rows||'<p class="text-[9px] text-gray-400 italic py-1">No routing chains scheduled today.</p>')+'</div></div>';}
function openRoomDetail(room){var ov=document.getElementById('roomOverlay');var bx=document.getElementById('roomBox');if(!ov||!bx)return;
  var t=schedTodayCol();var st=roomState(room);var bks=roomBookings(room);
  var stChip=st.s==='onair'?'<span class="text-[9px] font-bold uppercase tracking-wider px-2 py-0.5 rounded-full bg-red-50 border border-red-200 text-red-700">● On Air now</span>':
    st.s==='active'?'<span class="text-[9px] font-bold uppercase tracking-wider px-2 py-0.5 rounded-full bg-emerald-50 border border-emerald-200 text-emerald-700">● Active today</span>':
    st.s==='setup'?'<span class="text-[9px] font-bold uppercase tracking-wider px-2 py-0.5 rounded-full bg-amber-50 border border-amber-200 text-amber-700">● Setup / prep</span>':
    '<span class="text-[9px] font-bold uppercase tracking-wider px-2 py-0.5 rounded-full bg-gray-100 border border-gray-200 text-gray-500">Idle today</span>';
  function bkRow(b){var live=t>=b[0]&&t<b[0]+b[1];
    var days=NPC_DAYS[b[0]]+(b[1]>1?' – '+(NPC_DAYS[Math.min(b[0]+b[1]-1,6)]||''):'');
    var name=b[6]&&productions[b[6]]?(productions[b[6]].tab||productions[b[6]].name):'';
    return '<div class="perm-row"'+(live?' style="border-color:#31a24c"':'')+'><div class="min-w-0">'+
      '<p class="text-[11px] font-bold text-gray-900 truncate">'+esc(b[2])+'</p>'+
      '<p class="text-[9px] text-gray-500">'+esc(days)+(b[5]?' · '+esc(b[5]):'')+(name?' · '+esc(name):'')+(live?' · <b class="text-emerald-700">today</b>':'')+'</p></div>'+
      (b[6]&&productions[b[6]]?'<button onclick="closeRoomDetail();openProject(\''+b[6]+'\')" class="text-[9px] font-bold text-blue-700 hover:underline flex-shrink-0">Open →</button>':'')+'</div>';}
  bx.innerHTML='<div class="flex items-start justify-between mb-2"><div><h3 class="text-sm font-bold text-gray-900 leading-none mono">'+esc(room)+'</h3>'+
    '<p class="text-[10px] text-gray-500 mt-1">Control-room schedule · Week of '+esc(typeof MuseSchedule!=='undefined'?MuseSchedule.weekLabel():'this week')+'</p></div>'+
    '<button onclick="closeRoomDetail()" class="text-gray-400 hover:text-gray-700 text-lg leading-none">✕</button></div>'+
    '<div class="mb-3">'+stChip+'</div>'+
    (bks.length?bks.map(bkRow).join(''):'<p class="text-[10px] text-gray-400 italic py-3">Nothing scheduled in this room this week.</p>')+
    '<div class="sim-note mt-3"><span>⇄</span><span>Live from <b>Muse Schedule</b>. Move, extend or book this room there and this board follows.</span></div>'+
    '<button onclick="closeRoomDetail();MuseSchedule.focusRes(\''+room+'\')" class="w-full text-[11px] font-bold text-white bg-blue-600 hover:bg-blue-700 rounded-full px-3 py-2 mt-2">Open '+esc(room)+' in Muse Schedule →</button>';
  ov.style.display='flex';}
function closeRoomDetail(){var ov=document.getElementById('roomOverlay');if(ov)ov.style.display='none';}

/* find facility booking(s) that collide with an NPC event (same resource row + overlapping days) */
function npcConflictsFor(ev){
  var hits=[];
  FACILITY_ROWS.forEach(function(row){if(row[0]!==ev.resource)return;
    row[1].forEach(function(b){if(spanOverlap(ev.col,ev.span,b[0],b[1]))hits.push({resource:row[0],label:b[2],col:b[0],span:b[1]});});
  });
  return hits;
}
/* all conflicts across all NPC events (for the calendar overlay — always shows) */
function npcAllConflicts(){loadNPCOnce();var out=[];
  npcEvents.forEach(function(ev){var c=npcConflictsFor(ev);if(c.length)out.push({ev:ev,conflicts:c});});
  return out;}
/* conflicts that still warrant a HOME-PAGE ALERT (dismissed / declined / crewed events drop off the banner
   but the conflict itself stays visible on the calendar until the event is deleted or marked won't-participate) */
function npcAlertConflicts(){loadNPCOnce();var out=[];
  npcEvents.forEach(function(ev){
    if(ev.dismissed||ev.participate===false||ev.crewed)return;       // off the banner, still on calendar
    var c=npcConflictsFor(ev);if(c.length)out.push({ev:ev,conflicts:c});});
  return out;}

/* render the NPC overlay lane onto the master gantt (semi-transparent vs dark facility tiles) */
function npcGanttHTML(){loadNPCOnce();
  var byRes={};npcEvents.forEach(function(ev){(byRes[ev.resource]=byRes[ev.resource]||[]).push(ev);});
  // build a row per facility resource so NPC tiles align under the same columns
  var resources=FACILITY_ROWS.map(function(r){return r[0];});
  var g='<div style="min-width:820px"><div class="grid grid-cols-8 gap-1 mb-2 text-[10px] font-bold text-gray-500 uppercase tracking-wider"><div></div>'+
    NPC_DAYS.map(function(d){return '<div class="text-center">'+d+'</div>';}).join('')+'</div>';
  resources.forEach(function(res){
    var fac=(FACILITY_ROWS.filter(function(r){return r[0]===res;})[0]||[res,[]])[1];
    var npc=byRes[res]||[];
    g+='<div class="grid grid-cols-8 gap-1 mb-1 items-center"><div class="text-[10px] font-bold mono text-gray-600">'+res+'</div>'+
      '<div class="col-span-7 relative rounded border border-gray-100" style="height:40px;background:repeating-linear-gradient(90deg,#f7f8fa,#f7f8fa calc(100%/7 - 1px),#f0f2f5 calc(100%/7 - 1px),#f0f2f5 calc(100%/7))">';
    // facility bookings — DARK, solid
    fac.forEach(function(b){var left=(b[0]/7*100),w=(b[1]/7*100);
      g+='<div onclick="toast(\''+(''+b[2]).replace(/'/g,'')+' · '+res+'\')" class="absolute rounded text-[9px] font-bold flex items-center px-2 cursor-pointer truncate text-white" style="top:2px;height:17px;left:'+left+'%;width:calc('+w+'% - 2px);background:#242526;z-index:2" title="'+txt(b[2])+'">'+txt(b[2])+'</div>';});
    // NPC events — SEMI-TRANSPARENT, overlapping below
    npc.forEach(function(ev){var left=(ev.col/7*100),w=(ev.span/7*100);var conf=npcConflictsFor(ev).length>0;
      var declined=(ev.participate===false);
      // conflict → solid LIVE-red tile (unmistakable); declined → muted gray; otherwise planned-blue
      var bg,bd,tx;
      if(declined){bg='rgba(176,179,184,0.25)';bd='rgba(101,103,107,0.5)';tx='#4B4F56';}
      else if(conf){bg='var(--live-red)';bd='var(--live-red)';tx='#ffffff';}
      else{bg='rgba(8,102,255,0.28)';bd='rgba(8,102,255,0.6)';tx='#4b4f56';}
      var tag=declined?'⊘ ':(ev.crewed?'✓ ':(conf?'⚠ ':''));
      g+='<div onclick="openNPCEvent(\''+ev.id+'\')" class="absolute rounded text-[9px] font-semibold flex items-center px-2 cursor-pointer truncate" style="bottom:2px;height:17px;left:'+left+'%;width:calc('+w+'% - 2px);background:'+bg+';color:'+tx+';border:1px '+(conf&&!declined?'solid':'dashed')+' '+bd+';z-index:'+(conf&&!declined?'2':'1')+(conf&&!declined?';box-shadow:0 1px 4px rgba(179,18,46,.45)':'')+(declined?';text-decoration:line-through':'')+'" title="'+txt(ev.title)+(declined?' — Muse Live will not participate':(conf?' — CONFLICT':''))+'">'+tag+txt(ev.title)+'</div>';});
    g+='</div></div>';
  });
  g+='</div>';
  // legend
  var legend='<div class="flex items-center gap-4 mt-3 flex-wrap">'+
    '<div class="flex items-center gap-1.5"><span class="inline-block w-4 h-3 rounded" style="background:#242526"></span><span class="text-[9px] text-gray-600">Meta Operations (booked)</span></div>'+
    '<div class="flex items-center gap-1.5"><span class="inline-block w-4 h-3 rounded" style="background:rgba(8,102,255,0.28);border:1px dashed rgba(8,102,255,0.6)"></span><span class="text-[9px] text-gray-600">National Press Club (planned)</span></div>'+
    '<div class="flex items-center gap-1.5"><span class="inline-block w-4 h-3 rounded" style="background:var(--live-red);border:1px solid var(--live-red)"></span><span class="text-[9px] text-gray-600">⚠ Direct conflict</span></div></div>';
  return g+legend;
}

/* NPC conflict surfacing — moved off the home page into the \u2630 menu (numbered badge + warning block) */
function renderNPCAlert(){
  var host=document.getElementById('npcAlertHost');if(host)host.innerHTML='';
  try{renderBurgerBadge();}catch(e){}
  try{renderMobileNav();}catch(e){}
}
function dismissNPCWarning(id){var ev=npcById(id);if(!ev)return;ev.dismissed=true;saveNPC();renderNPCAlert();
  try{var act=document.querySelector('.view-pane.active');if(act&&act.id==='view-schedule')renderSchedule();}catch(e){}
  toast('Warning dismissed — conflict still shows on the calendar');}

/* NPC event detail modal — review + one-click "crew this" (create full project) */
function openNPCEvent(id){var ev=npcById(id);if(!ev)return;
  var conf=npcConflictsFor(ev);
  var ov=document.getElementById('npcOverlay');var bx=document.getElementById('npcBox');if(!ov||!bx)return;
  var conflictBlock=conf.length?'<div class="bg-red-50 border border-red-200 rounded-xl p-3 mb-3"><p class="text-[10px] font-bold uppercase tracking-wider text-red-700 mb-1">⚠ Direct Conflict</p>'+
    '<p class="text-[11px] text-red-700/90">This event overlaps booked Muse Live operations on <b>'+esc(ev.resource)+'</b>: '+conf.map(function(x){return esc(x.label);}).join(', ')+'. Crewing it will create a parallel production you can resource independently.</p></div>':
    '<div class="bg-emerald-50 border border-emerald-200 rounded-xl p-3 mb-3"><p class="text-[11px] text-emerald-700">No facility conflict detected for this event.</p></div>';
  var already=ev.crewed?'<div class="bg-blue-50 border border-blue-200 rounded-xl p-3 mb-3"><p class="text-[11px] text-blue-700">Already crewed as a production. Opening it instead.</p></div>':'';
  bx.innerHTML='<div class="flex items-start justify-between gap-2 mb-3">'+
      '<div class="flex items-center gap-3 min-w-0"><div class="w-10 h-10 rounded-xl bg-gray-900 flex items-center justify-center flex-shrink-0"><svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="#ffffff" stroke-width="1.8"><path d="M4 22V4a2 2 0 0 1 2-2h8l6 6v14a2 2 0 0 1-2 2H6a2 2 0 0 1-2-2z"/><path d="M14 2v6h6M9 13h6M9 17h4"/></svg></div>'+
        '<div class="min-w-0"><div class="flex items-center gap-1.5"><span class="text-[9px] mono font-bold text-gray-500">'+ev.id+'</span><span class="text-[8px] font-bold uppercase px-1.5 py-0.5 rounded bg-gray-100 text-gray-600 border border-gray-200">National Press Club</span></div>'+
        '<h3 class="text-base font-bold text-gray-900 leading-tight mt-0.5">'+esc(ev.title)+'</h3>'+
        '<p class="text-[10px] text-gray-500">'+esc(ev.org)+'</p></div></div>'+
      '<button onclick="closeNPCEvent()" class="text-gray-400 hover:text-gray-700 text-lg leading-none flex-shrink-0">✕</button></div>'+
    conflictBlock+already+
    '<div class="grid grid-cols-2 gap-2 mb-3">'+
      '<div><p class="text-[8px] font-bold uppercase tracking-wider text-gray-400">When</p><p class="text-[11px] font-semibold text-gray-800">'+esc(NPC_DAYS[ev.col]||'')+(ev.span>1?'–'+esc(NPC_DAYS[ev.col+ev.span-1]||''):'')+' · '+esc(ev.time)+'</p></div>'+
      '<div><p class="text-[8px] font-bold uppercase tracking-wider text-gray-400">Resource Lane</p><p class="text-[11px] font-semibold text-gray-800">'+esc(ev.resource)+'</p></div>'+
      '<div class="col-span-2"><p class="text-[8px] font-bold uppercase tracking-wider text-gray-400">Venue</p><p class="text-[11px] font-semibold text-gray-800">'+esc(ev.venue)+'</p></div>'+
      '<div class="col-span-2"><p class="text-[8px] font-bold uppercase tracking-wider text-gray-400">Detail</p><p class="text-[11px] text-gray-700">'+esc(ev.detail)+'</p></div>'+
    '</div>'+
    (ev.participate===false?'<div class="bg-gray-100 border border-gray-200 rounded-xl p-2.5 mb-3 flex items-center justify-between"><span class="text-[11px] font-semibold text-gray-600">⊘ Marked: Muse Live will not participate</span><button onclick="npcSetParticipate(\''+ev.id+'\',true)" class="text-[10px] font-bold text-blue-700 hover:underline">Undo</button></div>':'')+
    '<div class="mb-3">'+commsPanelHTML('npc',ev.id,{shadow:false,compact:true})+'</div>'+
    '<div class="flex items-center gap-2 pt-3 border-t border-gray-100">'+
      (ev.crewed?'<button onclick="openNPCProject(\''+ev.id+'\')" class="flex-1 bg-blue-600 text-white text-xs font-bold rounded-xl py-2.5 hover:bg-blue-700">Open Production →</button>':
        '<button onclick="crewNPCEvent(\''+ev.id+'\')" class="flex-1 bg-gray-900 text-white text-xs font-bold rounded-xl py-2.5 hover:bg-gray-800">Crew this event — create production</button>')+
      (ev.participate!==false?'<button onclick="npcSetParticipate(\''+ev.id+'\',false)" class="text-[11px] font-bold text-gray-600 border border-gray-300 rounded-xl px-3 py-2.5 hover:bg-gray-50 whitespace-nowrap">Won\u2019t participate</button>':'')+
      '<button onclick="npcDeleteEvent(\''+ev.id+'\')" title="Remove from calendar entirely" class="text-[11px] font-bold text-red-600 border border-red-200 rounded-xl px-3 py-2.5 hover:bg-red-50 whitespace-nowrap">Delete</button>'+
      '<button onclick="closeNPCEvent()" class="text-xs text-gray-400 hover:text-gray-700 px-2">Close</button>'+
    '</div>';
  ov.style.display='flex';
}
function closeNPCEvent(){var ov=document.getElementById('npcOverlay');if(ov)ov.style.display='none';}

/* crew an NPC event → spin up a full production (all tabs: Overview/Finance/Transmission/Schedule/Travel/Crew/Vendors/Tracking/Workflow/PackList) */
function crewNPCEvent(id){var ev=npcById(id);if(!ev)return;
  if(ev.crewed&&ev.projectKey&&productions[ev.projectKey]){closeNPCEvent();openProject(ev.projectKey);return;}
  // build a starter schedule row for the event day
  var sched=[];
  var dayLabel=NPC_DAYS[ev.col]||'';
  sched.push([dayLabel,(ev.time||'').replace(/[^0-9:]/g,'')||'09:00','Crew Call — '+ev.title,'02:00','—',ev.venue]);
  sched.push([dayLabel,(ev.time||''),'Live Coverage — '+ev.title,'01:30','—',ev.venue]);
  var key=createProjectFromData({
    name:ev.title,
    customer:'News',
    venue:ev.venue,
    date:dayLabel,
    time:ev.time,
    desc:ev.detail,
    tagColor:'blue',
    foot:'National Press Club · '+ev.org,
    schedule:sched,
    npcSource:ev.id
  });
  ev.crewed=true;ev.projectKey=key;saveNPC();
  try{logEvent(key,'🏛 Crewed from National Press Club event '+ev.id+' — '+ev.title);saveState();}catch(e){}
  renderNPCAlert();
  closeNPCEvent();
  toast('“'+ev.title+'” crewed — production created');
  openProject(key);
}
function openNPCProject(id){var ev=npcById(id);if(ev&&ev.projectKey&&productions[ev.projectKey]){closeNPCEvent();openProject(ev.projectKey);}else{crewNPCEvent(id);}}
function npcSetParticipate(id,val){var ev=npcById(id);if(!ev)return;ev.participate=val;if(val===false)ev.dismissed=true;saveNPC();
  renderNPCAlert();try{var act=document.querySelector('.view-pane.active');if(act&&act.id==='view-schedule')renderSchedule();}catch(e){}
  openNPCEvent(id);toast(val===false?'Marked: Muse Live will not participate':'Re-enabled — Muse Live may participate');}
function npcDeleteEvent(id){var ev=npcById(id);if(!ev)return;
  if(!confirm('Remove “'+ev.title+'” from the National Press Club calendar entirely? This clears the conflict too.'))return;
  npcEvents=npcEvents.filter(function(x){return x.id!==id;});saveNPC();
  closeNPCEvent();renderNPCAlert();
  try{var act=document.querySelector('.view-pane.active');if(act&&act.id==='view-schedule')renderSchedule();}catch(e){}
  toast('Event removed from the calendar');}

function npcInit(){loadNPCOnce();renderNPCAlert();}

/* ================================================================================
   10. BROADCAST SCHEDULE — live programming grid across the five Meta Live channels:
       Facebook Live East / West, Instagram Live, WhatsApp Channels, Meta Horizon.
       Day / Week / Month / Year views, incl. the Muse AI World Tour window
       (Jun 11 – Jul 19 across Meta offices, Grand Finale at Meta HQ, Menlo Park).
   ================================================================================ */
var BCAST_CHANNELS=[
 {id:'fb_e',name:'Facebook Live',feed:'East',tz:'ET',accent:'#0866FF'},
 {id:'fb_w',name:'Facebook Live',feed:'West',tz:'PT · 3-hr delay',accent:'#0866FF'},
 {id:'ig_live',name:'Instagram Live',feed:'Global',tz:'ET',accent:'#E41E3F'},
 {id:'wa_ch',name:'WhatsApp Channels',feed:'Global',tz:'ET',accent:'#31A24C'},
 {id:'horizon',name:'Meta Horizon',feed:'Stream',tz:'ET · worldwide',accent:'#0A58CA'}
];
var bcastView='day';
var bcastDate=new Date();
/* Muse AI World Tour — phase for a given date (null outside the tour window) */
function wcPhase(d){
  if(d.getFullYear()!==2026)return null;
  var m=d.getMonth(),day=d.getDate();
  if(m===5){ // June
    if(day>=11&&day<=27)return 'Opening Keynotes';
    if(day>=28)return 'Regional Keynotes';
    return null;}
  if(m===6){ // July
    if(day<=3)return 'Regional Keynotes';
    if(day>=4&&day<=7)return 'Developer Days';
    if(day===8||day===12||day===13||day===16||day===17)return 'REST';
    if(day>=9&&day<=11)return 'Creator Showcases';
    if(day===14||day===15)return 'Semifinal Keynotes';
    if(day===18)return 'Community Day';
    if(day===19)return 'Grand Finale · Meta HQ, Menlo Park';
    return null;}
  return null;}
function wcMatchday(d){var p=wcPhase(d);return p&&p!=='REST'?p:null;}
/* program grid for one channel on one date — hours are the feed's LOCAL clock (East=ET, West=PT) */
function bcastDayGrid(chId,d){
  var dow=d.getDay(),wknd=(dow===0||dow===6);
  var phase=wcMatchday(d),wcWin=!!wcPhase(d);
  function P(s,e,t,cat,live){return {s:s,e:e,t:t,cat:cat||'gen',live:!!live};}
  var isT=(chId==='fb_e'||chId==='fb_w'),isU=(chId==='ig_live'||chId==='wa_ch');
  var isIG=(chId==='ig_live');
  if(isT){
    if(phase)return [
      P(7,9,'Muse AI Morning Brief','news',true),
      P(9,10,'Creator Spotlight','ent',true),
      P(10,11,'Muse AI World Tour: Pre-Show','sport',true),
      P(11,13,'Muse AI World Tour · '+phase+' — Keynote','match',true),
      P(13,13.5,'Developer Breakdown','sport'),
      P(13.5,15,'Hands-On: Ray-Ban Meta Gen 3','ent'),
      P(15,17.5,'Muse AI World Tour · '+phase+' — Developer Sessions','match',true),
      P(17.5,18.5,'WhatsApp Business Live','news',true),
      P(18.5,19,'Meta Newsroom','news',true),
      P(19,20,'Muse AI World Tour: Prime Pre-Show','sport',true),
      P(20,22.5,'Muse AI World Tour · '+phase+' — Prime Keynote','match',true),
      P(22.5,23,'Best of the Tour','sport'),
      P(23,24,'Meta Newsroom: Night Edition','news',true)];
    if(wcWin)return [ // tour rest day
      P(7,10,'Muse AI Morning Brief','news',true),
      P(10,12,'Tour Recap: Highlights','sport'),
      P(12,15,'Community Q&A','court'),
      P(15,16,'Instagram Creator Hour','ent',true),
      P(16,17,'Threads Trending','news',true),
      P(17,18.5,'Local Creators (partner pages)','news'),
      P(18.5,19,'Meta Newsroom','news',true),
      P(19,20,'Muse AI World Tour: Road to the Finale','sport'),
      P(20,22,'Replay: Meta Connect Keynote','movie'),
      P(22,23,'Reels of the Week','ent'),
      P(23,24,'Meta Newsroom: Night Edition','news',true)];
    if(wknd)return [
      P(7,9,'Community Programming','gen'),
      P(9,12,(dow===0&&(d.getMonth()>=7||d.getMonth()<=4))?'Horizon Worlds Live Concert':'Replay Morning',(dow===0&&(d.getMonth()>=7||d.getMonth()<=4))?'match':'movie',dow===0&&(d.getMonth()>=7||d.getMonth()<=4)),
      P(12,15,'Replay: Developer Sessions','movie'),
      P(15,17,'Community Q&A: Marathon','court'),
      P(17,18.5,'Local Creators Weekend','news'),
      P(18.5,19,'Meta Newsroom Weekend','news',true),
      P(19,22,'Replay: Prime Keynotes','movie'),
      P(22,23,dow===6?'Meta Quest Gaming Live':'Threads Trending: Special Edition',dow===6?'match':'news',dow===6),
      P(23,24,'Overnight Programming','news')];
    return [ // regular weekday
      P(7,10,'Muse AI Morning Brief','news',true),
      P(10,11,'Community Q&A','court'),
      P(11,12,'Creator Spotlight','ent'),
      P(12,13,'Community Q&A','court'),
      P(13,15,'Community Q&A: Prime Edition','court'),
      P(15,16,'Instagram Creator Hour','ent',true),
      P(16,17,'Threads Trending','news',true),
      P(17,18.5,'Local Creators (partner pages)','news'),
      P(18.5,19,'Meta Newsroom','news',true),
      P(19,20,'Made with Muse AI','ent'),
      P(20,21,'Creator Series: Behind the Reels','novela'),
      P(21,22,'Creator Series: Prime','novela'),
      P(22,23,'Reels of the Week','ent'),
      P(23,24,'Meta Newsroom: Night Edition','news',true)];
  }
  if(isU){
    if(phase)return [
      P(7,11,isIG?'Creator Series: Marathon':'Channel Updates: Marathon',isIG?'novela':'court'),
      P(11,12,'Tour Backstage (simulcast)','sport',true),
      P(12,14.5,'Muse AI World Tour — Alternate Keynote','match',true),
      P(14.5,16,isIG?'Creator Series: Marathon':'Business Messaging Clinics','novela'),
      P(16,18.5,'Muse AI World Tour — Keynote Replay','match'),
      P(18.5,20,isIG?'Reels Live':'Community Voices','sport'),
      P(20,22.5,'Muse AI World Tour — Prime Keynote (simulcast)','match',true),
      P(22.5,24,'Best of the Tour','sport')];
    return [
      P(7,12,isIG?'Creator Series: Marathon':'Channel Updates: Marathon',isIG?'novela':'court'),
      P(12,15,isIG?'Instagram Replay':'WhatsApp Replay','movie'),
      P(15,18,'Creator Series: Marathon','novela'),
      P(18,20,isIG?'Reels Live':'WhatsApp Business Live','novela'),
      P(20,22,dow===6?'Meta Quest Gaming Live':'Replay: Prime Keynotes',dow===6?'sport':'movie'),
      P(22,24,dow===5?'Late Night Live':'Overnight Programming',dow===5?'match':'gen',dow===5)];
  }
  // Meta Horizon (stream)
  if(phase)return [
    P(6,12,'Meta Newsroom Now (24/7 stream)','news',true),
    P(12,14.5,'Muse AI World Tour — Keynote (immersive)','match',true),
    P(14.5,16,'Meta Newsroom Now','news',true),
    P(16,18.5,'Muse AI World Tour — Developer Sessions (immersive)','match',true),
    P(18.5,20,'Tour Recap','sport'),
    P(20,22.5,'Muse AI World Tour — Prime Keynote (immersive)','match',true),
    P(22.5,24,'Meta Newsroom Now','news',true)];
  return [
    P(6,12,'Meta Newsroom Now (24/7 stream)','news',true),
    P(12,15,'Creator Series: On Demand','novela'),
    P(15,18,'Meta Newsroom Now','news',true),
    P(18,20,'Reality Labs: Recap','sport'),
    P(20,23,'Meta Newsroom Now: Prime','news',true),
    P(23,24,'Best of the Day','gen')];
}
/* overlap scan within each channel for the selected day — feeds the conflict bubble */
function bcastConflicts(){var out=[];
  BCAST_CHANNELS.forEach(function(ch){var g=bcastDayGrid(ch.id,bcastDate);
    for(var i=0;i<g.length;i++)for(var j=i+1;j<g.length;j++){
      if(g[i].s<g[j].e&&g[j].s<g[i].e)out.push({ch:ch,a:g[i],b:g[j]});}});
  return out;}
var BCAST_CAT_COLOR={match:'#E41E3F',sport:'#E41E3F',news:'#0866FF',novela:'#0A58CA',ent:'#8A5D00',court:'#1E7B34',movie:'#65676B',gen:'#8A8D91'};
function bcastFmtH(h){var hh=Math.floor(h),mm=Math.round((h-hh)*60);var ap=hh>=12?'PM':'AM';var h12=hh%12;if(h12===0)h12=12;return h12+(mm?':'+('0'+mm).slice(-2):'')+' '+ap;}
function bcastDateLbl(d){return d.toLocaleDateString('en-US',{weekday:'long',month:'long',day:'numeric',year:'numeric'});}
function bcastShift(n){var d=new Date(bcastDate);
  if(bcastView==='day')d.setDate(d.getDate()+n);
  else if(bcastView==='week')d.setDate(d.getDate()+7*n);
  else if(bcastView==='month')d.setMonth(d.getMonth()+n);
  else d.setFullYear(d.getFullYear()+n);
  bcastDate=d;renderSchedule();}
function bcastToday(){bcastDate=new Date();renderSchedule();}
function setBcastView(v){bcastView=v;renderSchedule();}
function bcastGoDay(y,m,day){bcastDate=new Date(y,m,day);bcastView='day';renderSchedule();}
/* ---- DAY view: vertical air grid 6 AM → midnight across all five feeds ---- */
function bcastDayHTML(){
  var H0=6,H1=24,PXH=46,tot=(H1-H0)*PXH;
  var today=new Date();var isToday=(today.toDateString()===bcastDate.toDateString());
  var nowH=today.getHours()+today.getMinutes()/60;
  var gut='<div class="relative flex-shrink-0" style="width:52px;height:'+tot+'px">';
  for(var h=H0;h<=H1;h++)gut+='<span class="absolute text-[8px] mono font-bold text-gray-400" style="top:'+((h-H0)*PXH-5)+'px;right:6px">'+bcastFmtH(h)+'</span>';
  gut+='</div>';
  var cols=BCAST_CHANNELS.map(function(ch){
    var g=bcastDayGrid(ch.id,bcastDate);
    var col='<div class="relative rounded-xl border border-gray-100 bg-gray-50/40" style="height:'+tot+'px;min-width:168px;flex:1">';
    for(var h2=H0+1;h2<H1;h2++)col+='<div class="bcast-hourline" style="top:'+((h2-H0)*PXH)+'px"></div>';
    g.forEach(function(pg){var top=(Math.max(pg.s,H0)-H0)*PXH,hgt=(Math.min(pg.e,H1)-Math.max(pg.s,H0))*PXH-3;if(hgt<=0)return;
      var c=BCAST_CAT_COLOR[pg.cat]||BCAST_CAT_COLOR.gen;
      var live=pg.live?'<span class="text-[7px] font-bold text-white rounded px-1 leading-none py-0.5 flex-shrink-0" style="background:var(--live-red)">LIVE</span>':'';
      col+='<div class="bcast-block" style="top:'+top+'px;height:'+hgt+'px;background:rgba('+parseInt(c.slice(1,3),16)+','+parseInt(c.slice(3,5),16)+','+parseInt(c.slice(5,7),16)+',.10);border-left-color:'+c+'" title="'+esc(pg.t)+' · '+bcastFmtH(pg.s)+'–'+bcastFmtH(pg.e)+'">'+
        '<div class="flex items-start justify-between gap-1"><span class="text-[9px] font-bold text-gray-800 leading-tight">'+esc(pg.t)+'</span>'+live+'</div>'+
        (hgt>30?'<span class="text-[8px] mono text-gray-500">'+bcastFmtH(pg.s)+' – '+bcastFmtH(pg.e)+'</span>':'')+'</div>';});
    if(isToday&&nowH>=H0&&nowH<=H1&&ch.tz.indexOf('PT')<0)col+='<div class="bcast-nowline" style="top:'+((nowH-H0)*PXH)+'px"></div>';
    col+='</div>';
    var hd='<div style="min-width:168px;flex:1" class="text-center pb-2"><p class="text-[11px] font-bold text-gray-900 leading-none">'+ch.name+(ch.feed!=='Stream'?' <span style="color:'+ch.accent+'">'+ch.feed+'</span>':'')+'</p><p class="text-[8px] mono text-gray-500 mt-1">'+ch.tz+'</p></div>';
    return {hd:hd,col:col};});
  var phase=wcMatchday(bcastDate);
  var banner=phase?'<div class="flex items-center gap-2 rounded-xl border border-red-200 bg-red-50 px-3 py-2 mb-3"><span class="text-[10px] font-bold text-white rounded px-1.5 py-0.5" style="background:var(--live-red)">● MUSE AI WORLD TOUR</span><span class="text-[10px] font-bold text-red-700">'+esc(phase)+' — live coverage across all five channels</span></div>':
    (wcPhase(bcastDate)?'<div class="rounded-xl border border-amber-200 bg-amber-50 px-3 py-2 mb-3 text-[10px] font-bold text-amber-700">Muse AI World Tour — rest day (studio &amp; recap programming)</div>':'');
  var legend='<div class="flex items-center gap-3 flex-wrap mt-3">'+Object.keys(BCAST_CAT_COLOR).map(function(k){var lbl={match:'Live Keynote',sport:'Launch Studio',news:'Newsroom',novela:'Creator Series',ent:'Entertainment',court:'Community Q&amp;A',movie:'Replay',gen:'Other'}[k];
    return '<span class="flex items-center gap-1.5 text-[9px] text-gray-600"><span class="inline-block w-3 h-3 rounded" style="background:'+BCAST_CAT_COLOR[k]+'"></span>'+lbl+'</span>';}).join('')+'</div>';
  return banner+'<div style="min-width:940px"><div class="flex gap-2"><div style="width:52px" class="flex-shrink-0"></div>'+cols.map(function(x){return x.hd;}).join('')+'</div>'+
    '<div class="flex gap-2">'+gut+cols.map(function(x){return x.col;}).join('')+'</div></div>'+legend;
}
/* ---- WEEK view: channels × 7 days, prime-time highlights ---- */
function bcastWeekHTML(){
  var start=new Date(bcastDate);start.setDate(start.getDate()-((start.getDay()+6)%7)); // Monday
  var days=[];for(var i=0;i<7;i++){var d=new Date(start);d.setDate(start.getDate()+i);days.push(d);}
  var head='<div class="grid gap-1 mb-2" style="grid-template-columns:150px repeat(7,1fr);min-width:980px">'+'<div></div>'+days.map(function(d){var t=(d.toDateString()===new Date().toDateString());
    return '<div class="text-center text-[9px] font-bold uppercase tracking-wider '+(t?'text-red-600':'text-gray-500')+'">'+d.toLocaleDateString('en-US',{weekday:'short'})+' '+d.getDate()+(wcMatchday(d)?' ⚽':'')+'</div>';}).join('')+'</div>';
  var rows=BCAST_CHANNELS.map(function(ch){
    var cells=days.map(function(d){var g=bcastDayGrid(ch.id,d);
      var prime=g.filter(function(pg){return pg.cat==='match'||pg.s>=18;}).slice(0,3);
      var chips=prime.map(function(pg){var c=BCAST_CAT_COLOR[pg.cat]||BCAST_CAT_COLOR.gen;
        return '<button onclick="bcastGoDay('+d.getFullYear()+','+d.getMonth()+','+d.getDate()+')" class="block w-full text-left text-[8px] font-semibold text-gray-700 rounded px-1 py-0.5 mb-0.5 truncate" style="background:rgba('+parseInt(c.slice(1,3),16)+','+parseInt(c.slice(3,5),16)+','+parseInt(c.slice(5,7),16)+',.12);border-left:2px solid '+c+'" title="'+esc(pg.t)+'">'+bcastFmtH(pg.s)+' '+esc(pg.t)+'</button>';}).join('');
      return '<div class="rounded-lg border border-gray-100 bg-gray-50/40 p-1" style="min-height:56px">'+chips+'</div>';}).join('');
    return '<div class="grid gap-1 mb-1" style="grid-template-columns:150px repeat(7,1fr);min-width:980px"><div class="text-[10px] font-bold text-gray-700 flex items-center gap-1.5"><span class="w-2 h-2 rounded-full flex-shrink-0" style="background:'+ch.accent+'"></span>'+ch.name+' '+(ch.feed!=='Stream'?ch.feed:'')+'</div>'+cells+'</div>';}).join('');
  return '<p class="text-[10px] text-gray-500 mb-3">Prime-time &amp; live-match highlights · click any show to open that day\u2019s full grid</p>'+head+rows;
}
/* ---- MONTH view: calendar with tentpole chips ---- */
function bcastMonthHTML(){
  var y=bcastDate.getFullYear(),m=bcastDate.getMonth();
  var first=new Date(y,m,1),lead=(first.getDay()+6)%7,dim=new Date(y,m+1,0).getDate();
  var head=['Mon','Tue','Wed','Thu','Fri','Sat','Sun'].map(function(x){return '<div class="text-center text-[9px] font-bold uppercase tracking-wider text-gray-500 pb-1">'+x+'</div>';}).join('');
  var cells='';for(var b=0;b<lead;b++)cells+='<div></div>';
  var today=new Date();
  for(var day=1;day<=dim;day++){var d=new Date(y,m,day);var phase=wcMatchday(d);var rest=(!phase&&wcPhase(d));
    var isT=(d.toDateString()===today.toDateString());
    var chip=phase?'<span class="block text-[7px] font-bold text-white rounded px-1 py-0.5 truncate" style="background:var(--live-red)" title="Muse AI World Tour · '+esc(phase)+'">'+esc(phase)+'</span>':
      (rest?'<span class="block text-[7px] font-bold text-amber-700 bg-amber-50 border border-amber-200 rounded px-1 py-0.5 truncate">Rest Day</span>':
      (function(){var g=bcastDayGrid('fb_e',d);var pr=g.filter(function(pg){return pg.s>=19&&pg.s<21;})[0];
        return pr?'<span class="block text-[7px] font-semibold text-gray-600 bg-gray-100 border border-gray-200 rounded px-1 py-0.5 truncate" title="'+esc(pr.t)+'">'+esc(pr.t)+'</span>':'';})());
    cells+='<button onclick="bcastGoDay('+y+','+m+','+day+')" class="text-left rounded-lg border p-1.5 hover:border-blue-300 hover:bg-blue-50/30 transition-colors '+(isT?'border-red-300 bg-red-50/40':'border-gray-100 bg-gray-50/40')+'" style="min-height:58px">'+
      '<p class="text-[10px] font-bold '+(isT?'text-red-700':'text-gray-800')+' mb-0.5">'+day+'</p>'+chip+'</button>';}
  return '<p class="text-[10px] text-gray-500 mb-3">Meta Live prime-time &amp; Muse AI World Tour tentpoles · click any day for the full five-channel grid</p>'+
    '<div class="grid grid-cols-7 gap-1" style="min-width:760px">'+head+cells+'</div>';
}
/* ---- YEAR view: tentpole calendar for the broadcast year ---- */
var BCAST_YEAR_TENTPOLES={
 0:[['Muse AI — Year Ahead Livestream','news'],['Instagram Creator Awards — nominations open','ent']],
 1:[['Orion AR Glasses — Developer Preview','match'],['Threads: Live Topics launch','news']],
 2:[['WhatsApp Business Summit — kickoff','news']],
 3:[['F8 Developer Conference','match']],
 4:[['Instagram Creator Week','ent'],['Meta Quest Gaming Showcase','match']],
 5:[['Muse AI World Tour — Opening Keynote (Jun 11 · Meta London, King\u2019s Cross)','match'],['104 tour sessions live on Facebook, Instagram & Horizon','match']],
 6:[['Muse AI World Tour — Regional Finals','match'],['THE GRAND FINALE — Jul 19 · Meta HQ, Menlo Park','match']],
 7:[['Ray-Ban Meta Gen 3 — launch livestream','ent']],
 8:[['Meta Connect 2026 — Keynote','match'],['Creator Series: new season premieres','novela']],
 9:[['Muse AI — fall feature drop','news']],
 10:[['Meta Charm wearable — pre-orders open','match'],['WhatsApp Channels: Creator Spotlight','ent']],
 11:[['Year in Review on Instagram · Happy 2027!','ent']]};
function bcastYearHTML(){
  var y=bcastDate.getFullYear();var months=['January','February','March','April','May','June','July','August','September','October','November','December'];
  var now=new Date();
  var cards=months.map(function(mn,i){
    var cur=(now.getFullYear()===y&&now.getMonth()===i);
    var tp=(y===2026?(BCAST_YEAR_TENTPOLES[i]||[]):[]);
    var items=tp.map(function(t){var c=BCAST_CAT_COLOR[t[1]]||BCAST_CAT_COLOR.gen;
      return '<p class="text-[9px] font-semibold text-gray-700 leading-snug mb-1 pl-2" style="border-left:2px solid '+c+'">'+esc(t[0])+'</p>';}).join('')||'<p class="text-[9px] text-gray-400 italic">Regular network programming</p>';
    return '<button onclick="bcastGoDay('+y+','+i+',1);bcastView=\'month\';renderSchedule()" class="text-left rounded-xl border p-3 hover:border-blue-300 transition-colors '+(cur?'border-red-300 bg-red-50/40':'border-gray-100 bg-gray-50/40')+'">'+
      '<p class="text-[10px] font-bold uppercase tracking-wider mb-1.5 '+(cur?'text-red-700':'text-gray-600')+'">'+mn+' '+y+'</p>'+items+'</button>';}).join('');
  return '<p class="text-[10px] text-gray-500 mb-3">Tentpole broadcast calendar · click a month to open its grid</p>'+
    '<div class="grid grid-cols-2 sm:grid-cols-3 lg:grid-cols-4 gap-2">'+cards+'</div>';
}
/* ---- pane: header (nav + view toggle) + active view ---- */
function bcastPaneHTML(){
  function vb(id,lbl){var on=(bcastView===id);return '<button onclick="setBcastView(\''+id+'\')" class="text-[10px] font-bold px-3 py-1.5 rounded-lg '+(on?'bg-gray-900 text-white shadow-sm':'text-gray-600 hover:bg-gray-200')+'">'+lbl+'</button>';}
  var lbl=bcastView==='day'?bcastDateLbl(bcastDate):
    (bcastView==='week'?(function(){var s=new Date(bcastDate);s.setDate(s.getDate()-((s.getDay()+6)%7));var e=new Date(s);e.setDate(s.getDate()+6);
      return 'Week of '+s.toLocaleDateString('en-US',{month:'short',day:'numeric'})+' — '+e.toLocaleDateString('en-US',{month:'short',day:'numeric',year:'numeric'});})():
    (bcastView==='month'?bcastDate.toLocaleDateString('en-US',{month:'long',year:'numeric'}):(''+bcastDate.getFullYear())));
  var body=bcastView==='day'?bcastDayHTML():(bcastView==='week'?bcastWeekHTML():(bcastView==='month'?bcastMonthHTML():bcastYearHTML()));
  return '<div class="flex flex-wrap items-center justify-between gap-2 mb-4">'+
    '<div><h3 class="text-xs font-bold uppercase tracking-wider text-gray-600">Broadcast Schedule — Network Air</h3>'+
      '<p class="text-[10px] text-gray-500 mt-0.5">Facebook Live East &amp; West · Instagram Live · WhatsApp Channels · Meta Horizon</p></div>'+
    '<div class="flex items-center gap-2 flex-wrap">'+
      '<div class="inline-flex items-center gap-1 bg-gray-100 rounded-xl p-1">'+vb('day','Day')+vb('week','Week')+vb('month','Month')+vb('year','Year')+'</div>'+
      '<div class="inline-flex items-center gap-1">'+
        '<button onclick="bcastShift(-1)" class="w-7 h-7 rounded-lg border border-gray-200 text-gray-600 hover:bg-gray-100 font-bold">\u2039</button>'+
        '<button onclick="bcastToday()" class="text-[10px] font-bold px-2.5 h-7 rounded-lg border border-gray-200 text-gray-600 hover:bg-gray-100">Today</button>'+
        '<button onclick="bcastShift(1)" class="w-7 h-7 rounded-lg border border-gray-200 text-gray-600 hover:bg-gray-100 font-bold">\u203a</button>'+
      '</div>'+
      '<span class="text-[11px] font-bold text-gray-800 mono">'+lbl+'</span></div></div>'+
    '<div class="overflow-x-auto">'+body+'</div>';
}

