function dxfXform(pt,t){return [t.a*pt[0]+t.c*pt[1]+t.e, t.b*pt[0]+t.d*pt[1]+t.f];}
function dxfEntColor(ent,model){var aci=ent.aci;
  if(!aci||aci===256){var L=model.layers[ent.layerName];aci=(L&&L.color)||7;}
  if(aci===0)aci=7;return dxfAciColor(aci);}
function dxfBulgePts(p,q,b){
  var theta=4*Math.atan(b);if(!theta)return [];
  var dx=q[0]-p[0],dy=q[1]-p[1];var chord=Math.sqrt(dx*dx+dy*dy);if(!chord)return [];
  var d=chord/(2*Math.tan(theta/2));
  var cx=(p[0]+q[0])/2 - d*(dy/chord), cy=(p[1]+q[1])/2 + d*(dx/chord);
  var a0=Math.atan2(p[1]-cy,p[0]-cx);
  var r=Math.sqrt((p[0]-cx)*(p[0]-cx)+(p[1]-cy)*(p[1]-cy));
  var n=Math.max(4,Math.ceil(Math.abs(theta)/(Math.PI/16)));var out=[];
  for(var i=1;i<n;i++){var a=a0+theta*i/n;out.push([cx+r*Math.cos(a),cy+r*Math.sin(a)]);}
  return out;}
function dxfEntPolys(ent,model,t,out,depth){try{
  var col=dxfEntColor(ent,model),i,poly;
  var mag=Math.sqrt(t.a*t.a+t.b*t.b)||1;
  if(ent.type==='LINE'){out.push({pts:[dxfXform([ent.x1||0,ent.y1||0],t),dxfXform([ent.x2||0,ent.y2||0],t)],color:col});return;}
  if(ent.type==='LWPOLYLINE'||ent.type==='POLYLINE'){
    var pts=ent.pts||[];if(pts.length<2)return;
    poly=[];
    for(i=0;i<pts.length;i++){var p=pts[i];var nxt=pts[i+1]||(ent.closed?pts[0]:null);
      poly.push([p[0],p[1]]);
      if(p[2]&&nxt){var samp=dxfBulgePts(p,nxt,p[2]);for(var s=0;s<samp.length;s++)poly.push(samp[s]);}}
    if(ent.closed)poly.push([pts[0][0],pts[0][1]]);
    out.push({pts:poly.map(function(pp){return dxfXform(pp,t);}),color:col});return;}
  if(ent.type==='CIRCLE'||ent.type==='ARC'){if(ent.r==null)return;
    var a1=(ent.type==='CIRCLE')?0:(ent.a1||0)*Math.PI/180, a2=(ent.type==='CIRCLE')?Math.PI*2:(ent.a2||0)*Math.PI/180;
    if(ent.type==='ARC'&&a2<=a1)a2+=Math.PI*2;
    var n=Math.max(8,Math.ceil((a2-a1)/(Math.PI/24)));poly=[];
    for(i=0;i<=n;i++){var a=a1+(a2-a1)*i/n;poly.push(dxfXform([(ent.cx||0)+ent.r*Math.cos(a),(ent.cy||0)+ent.r*Math.sin(a)],t));}
    out.push({pts:poly,color:col});return;}
  if(ent.type==='ELLIPSE'){if(ent.mx==null)return;
    var u1=(ent.p1||0),u2=(ent.p2!=null?ent.p2:Math.PI*2);if(u2<=u1)u2+=Math.PI*2;
    var ratio=ent.ratio||1;var minx=-(ent.my||0)*ratio,miny=(ent.mx||0)*ratio;
    var ne=Math.max(12,Math.ceil((u2-u1)/(Math.PI/24)));poly=[];
    for(i=0;i<=ne;i++){var u=u1+(u2-u1)*i/ne;
      poly.push(dxfXform([(ent.cx||0)+Math.cos(u)*(ent.mx||0)+Math.sin(u)*minx,(ent.cy||0)+Math.cos(u)*(ent.my||0)+Math.sin(u)*miny],t));}
    out.push({pts:poly,color:col});return;}
  if(ent.type==='SPLINE'){var src=(ent.fit&&ent.fit.length>1)?ent.fit:ent.ctrl;
    if(src&&src.length>1)out.push({pts:src.map(function(pp){return dxfXform(pp,t);}),color:col});return;}
  if(ent.type==='POINT'){var pp2=dxfXform([ent.x||0,ent.y||0],t);out.push({pts:[pp2,[pp2[0]+0.0001,pp2[1]]],color:col});return;}
  if(ent.type==='TEXT'||ent.type==='MTEXT'){if(!ent.text)return;
    out.push({text:String(ent.text).replace(/\\P/g,' ').replace(/\{[^}]*;/g,'').replace(/[{}]/g,'').slice(0,120),
      px:dxfXform([ent.x||0,ent.y||0],t),hUnits:(ent.h||1)*mag,color:col});return;}
  if(ent.type==='INSERT'&&depth<4){var blk=model.blocks[ent.name];if(!blk)return;
    var bents=blk.ents||blk;if(!bents.length)return;
    var rot=(ent.rot||0)*Math.PI/180,sx=(ent.sx==null?1:ent.sx),sy=(ent.sy==null?sx:ent.sy);
    var cos=Math.cos(rot),sin=Math.sin(rot);
    var loc={a:cos*sx,b:sin*sx,c:-sin*sy,d:cos*sy,e:ent.x||0,f:ent.y||0};
    /* world = insert + R·S·(p − base): fold the block base point into the translation */
    var bx=blk.bx||0,by=blk.by||0;
    loc.e-= (loc.a*bx+loc.c*by);
    loc.f-= (loc.b*bx+loc.d*by);
    var comp={a:t.a*loc.a+t.c*loc.b, b:t.b*loc.a+t.d*loc.b,
      c:t.a*loc.c+t.c*loc.d, d:t.b*loc.c+t.d*loc.d,
      e:t.a*loc.e+t.c*loc.f+t.e, f:t.b*loc.e+t.d*loc.f+t.f};
    for(i=0;i<bents.length;i++)dxfEntPolys(bents[i],model,comp,out,depth+1);return;}
}catch(e){}}
function dxfRender(model,maxDim){
  var polys=[];var t0={a:1,b:0,c:0,d:1,e:0,f:0};var i,j;
  for(i=0;i<model.entities.length;i++)dxfEntPolys(model.entities[i],model,t0,polys,0);
  var minX=Infinity,minY=Infinity,maxX=-Infinity,maxY=-Infinity;
  for(i=0;i<polys.length;i++){var P=polys[i];
    if(P.pts){for(j=0;j<P.pts.length;j++){var p=P.pts[j];
      if(isFinite(p[0])&&isFinite(p[1])){if(p[0]<minX)minX=p[0];if(p[0]>maxX)maxX=p[0];if(p[1]<minY)minY=p[1];if(p[1]>maxY)maxY=p[1];}}}
    else if(P.px&&isFinite(P.px[0])){if(P.px[0]<minX)minX=P.px[0];if(P.px[0]>maxX)maxX=P.px[0];if(P.px[1]<minY)minY=P.px[1];if(P.px[1]>maxY)maxY=P.px[1];}}
  if(!isFinite(minX)||maxX-minX<=0||maxY-minY<=0)throw new Error('no drawable geometry found');
  var w=maxX-minX,h=maxY-minY;var pad=0.03*Math.max(w,h);
  minX-=pad;minY-=pad;w+=pad*2;h+=pad*2;
  var scale=maxDim/Math.max(w,h);
  var cw=Math.max(64,Math.round(w*scale)),ch=Math.max(64,Math.round(h*scale));
  var cv=document.createElement('canvas');cv.width=cw;cv.height=ch;
  var ctx=cv.getContext('2d');
  ctx.fillStyle='#ffffff';ctx.fillRect(0,0,cw,ch);
  ctx.lineJoin='round';ctx.lineCap='round';ctx.lineWidth=Math.max(0.7,Math.min(1.6,maxDim/2400));
  function X(x){return (x-minX)*scale;}
  function Y(y){return ch-(y-minY)*scale;} /* DXF is y-up */
  for(i=0;i<polys.length;i++){var Q=polys[i];
    if(Q.pts&&Q.pts.length>1){ctx.strokeStyle=Q.color||'#1C1E21';ctx.beginPath();
      ctx.moveTo(X(Q.pts[0][0]),Y(Q.pts[0][1]));
      for(j=1;j<Q.pts.length;j++)ctx.lineTo(X(Q.pts[j][0]),Y(Q.pts[j][1]));
      ctx.stroke();}
    else if(Q.text){var fh=Math.max(5,Math.min(64,(Q.hUnits||1)*scale));
      ctx.fillStyle=Q.color||'#1C1E21';ctx.font='500 '+fh+'px Arial';ctx.textBaseline='alphabetic';
      ctx.fillText(Q.text,X(Q.px[0]),Y(Q.px[1]));}}
  return {url:cv.toDataURL('image/png'),pxPerUnit:scale,count:polys.length};}

/* stampEdit → saveState is silent on quota errors; after storing a large
   rendered sheet, verify it actually landed in localStorage and say so if not */
function cadPersistCheck(planId){try{
  var raw=localStorage.getItem('muselive_edits');
  if(!raw||raw.indexOf(planId)<0)
    toast('⚠ Sheet stored for this session, but it is too large for browser storage and may not survive a reload — consider a smaller export');
}catch(e){}}

function cadEntText(e){return (e.ov&&e.ov.text!=null)?e.ov.text:(e.text||'');}
function cadNewDoc(){return {ents:[],layers:{},src:'',units:0};}
function cadEnsureDocLayer(doc,name,aci,rgb){
  if(!name)name='0';
  if(!doc.layers[name])doc.layers[name]={name:name,aci:(aci||7),rgb:(rgb||null),off:false,locked:false};
  else{var L=doc.layers[name];
    if(aci&&!L.aci)L.aci=aci;
    if(rgb&&!L.rgb)L.rgb=rgb;}
  return doc.layers[name];}
var _cadEseq=0;
function cadEid(){return 'e'+(++_cadEseq).toString(36);}
function cadCleanText(s){
  return String(s==null?'':s)
    .replace(/\\P/g,' ').replace(/\\[A-Za-z]+[^;\\]*;/g,'').replace(/[{}]/g,'')
    .replace(/\\\\/g,'\\').replace(/\s+/g,' ').replace(/^\s+|\s+$/g,'');}
function cadMix(base,o){for(var k in o)if(o.hasOwnProperty(k))base[k]=o[k];return base;}

/* ============================================================================
   v37 CAD — seeded VECTOR drawings
   The v29 seed set shipped as baked PNGs (CAD_RENDERS), which meant the demo
   productions could never show the vector environment: no layers, no selectable
   entities, no editable text. These generators build the same four sheets as real
   entity networks on real layers, so every seeded production opens straight into
   the full CAD environment.
   ========================================================================== */
function cadSeedDoc(kind){
  var doc=cadNewDoc();doc.src='seed';_cadEseq=0;
  var L=function(n,aci){cadEnsureDocLayer(doc,n,aci);return n;};
  L('GRID',8);L('STRUCTURE',7);L('SEATING',9);L('PITCH',3);L('CAMERA',5);
  L('POWER',1);L('CABLE',2);L('TEXT',7);L('DIMS',4);
  var push=function(lay,aci,o){doc.ents.push(cadMix({id:cadEid(),lay:lay,aci:aci},o));};
  var line=function(lay,aci,x1,y1,x2,y2){push(lay,aci,{t:'LINE',pts:[[x1,y1],[x2,y2]]});};
  var poly=function(lay,aci,pts,closed){var p=pts.slice();if(closed)p.push(pts[0]);push(lay,aci,{t:'PLINE',pts:p});};
  var circ=function(lay,aci,cx,cy,r){push(lay,aci,{t:'CIRCLE',cx:cx,cy:cy,r:r});};
  var arc=function(lay,aci,cx,cy,r,a1,a2){push(lay,aci,{t:'ARC',cx:cx,cy:cy,r:r,a1:a1,a2:a2});};
  var text=function(lay,aci,x,y,s,h){push(lay,aci,{t:'TEXT',cx:x,cy:y,text:s,h:(h||3)});};
  var i,a;

  /* survey grid common to every sheet — real drafting furniture, on its own layer */
  for(i=0;i<=20;i++){line('GRID',8,i*10,0,i*10,140);}
  for(i=0;i<=14;i++){line('GRID',8,0,i*10,200,i*10);}
  text('TEXT',7,2,143,'Muse Live SPORTS — TECHNICAL SURVEY',4.5);

  if(kind==='football'){
    /* pitch + grandstands, plan view */
    poly('PITCH',3,[[40,30],[160,30],[160,110],[40,110]],true);
    line('PITCH',3,100,30,100,110);                       /* halfway */
    circ('PITCH',3,100,70,9.15);                          /* centre circle */
    poly('PITCH',3,[[40,50],[56,50],[56,90],[40,90]],true);   /* penalty area */
    poly('PITCH',3,[[160,50],[144,50],[144,90],[160,90]],true);
    poly('SEATING',9,[[20,14],[180,14],[180,126],[20,126]],true);
    poly('SEATING',9,[[30,22],[170,22],[170,118],[30,118]],true);
    for(i=0;i<8;i++)line('SEATING',9,20+i*20,14,30+i*17.5,22);
    /* camera plots */
    var cams=[[100,10,'CAM 1 · MAIN 22m'],[100,130,'CAM 4 · REVERSE'],[24,70,'CAM 2 · 18YD'],
              [176,70,'CAM 3 · 18YD'],[40,126,'CAM 5 · HANDHELD'],[160,14,'CAM 6 · RF STEADI']];
    for(i=0;i<cams.length;i++){circ('CAMERA',5,cams[i][0],cams[i][1],2.4);
      line('CAMERA',5,cams[i][0],cams[i][1],cams[i][0],70);
      text('CAMERA',5,cams[i][0]+3.5,cams[i][1]+1,cams[i][2],2.6);}
    /* power + cable */
    poly('POWER',1,[[6,60],[16,60],[16,80],[6,80]],true);
    text('POWER',1,6,82,'DISTRO A · 480V/400A',2.8);
    poly('CABLE',2,[[16,70],[30,70],[30,100],[100,100]],false);
    text('TEXT',7,40,136,'FIELD & STANDS — GENERAL PLAN  ·  1:500',3.4);
    text('DIMS',4,86,26,'105 m',2.6);
    line('DIMS',4,40,27,160,27);
  }else if(kind==='plan6'){
    /* upper concourse ring */
    circ('STRUCTURE',7,100,70,58);circ('STRUCTURE',7,100,70,46);circ('STRUCTURE',7,100,70,34);
    for(i=0;i<24;i++){a=i*Math.PI/12;
      line('STRUCTURE',7,100+34*Math.cos(a),70+34*Math.sin(a),100+58*Math.cos(a),70+58*Math.sin(a));}
    for(i=0;i<8;i++){a=i*Math.PI/4;
      poly('SEATING',9,[[100+40*Math.cos(a)-4,70+40*Math.sin(a)-4],[100+40*Math.cos(a)+4,70+40*Math.sin(a)-4],
                        [100+40*Math.cos(a)+4,70+40*Math.sin(a)+4],[100+40*Math.cos(a)-4,70+40*Math.sin(a)+4]],true);
      text('TEXT',7,100+40*Math.cos(a)-6,70+40*Math.sin(a)+6,'SEC '+(600+i*10),2.4);}
    circ('CAMERA',5,100,128,2.4);text('CAMERA',5,104,128,'CAM 7 · HIGH HOME',2.8);
    poly('POWER',1,[[150,110],[162,110],[162,122],[150,122]],true);
    text('POWER',1,150,124,'UPS RACK · L6-30',2.8);
    text('TEXT',7,40,136,'LEVEL 6 — UPPER CONCOURSE PLAN  ·  1:400',3.4);
  }else if(kind==='section1'||kind==='section2'){
    /* longitudinal / cross section through the bowl */
    line('STRUCTURE',7,10,20,190,20);                       /* ground */
    for(i=0;i<9;i++){var x=20+i*8,y=20+i*7;
      line('SEATING',9,x,y,x+8,y);line('SEATING',9,x+8,y,x+8,y+7);
      line('SEATING',9,200-x,y,192-x,y);line('SEATING',9,192-x,y,192-x,y+7);}
    poly('STRUCTURE',7,[[88,20],[112,20],[112,34],[88,34]],true);   /* pitch datum */
    if(kind==='section2'){
      /* roof truss */
      poly('STRUCTURE',7,[[16,92],[100,112],[184,92]],false);
      for(i=0;i<10;i++){var tx=16+i*18.7;
        line('STRUCTURE',7,tx,92+(i<5?i*4:(9-i)*4),tx,20+Math.min(70,i*7.6));}
      text('TEXT',7,74,118,'ROOF TRUSS — 168m CLEAR SPAN',3);
      arc('STRUCTURE',7,100,20,90,0.15,Math.PI-0.15);
    }
    circ('CAMERA',5,100,96,2.4);text('CAMERA',5,104,96,'CAM 1 · 22m PLATFORM',2.8);
    circ('CAMERA',5,30,52,2.2);text('CAMERA',5,34,52,'CAM 8 · LOW SLASH',2.6);
    line('DIMS',4,10,14,190,14);text('DIMS',4,92,8,'196 m',3);
    line('DIMS',4,6,20,6,112);text('DIMS',4,1,66,'52 m',3);
    poly('POWER',1,[[168,24],[182,24],[182,36],[168,36]],true);
    text('POWER',1,164,38,'GEN TIE-IN · 400A',2.8);
    text('TEXT',7,40,136,(kind==='section2'?'SEATING BOWL — CROSS SECTION':'LONGITUDINAL SECTION')+'  ·  1:600',3.4);
  }else if(kind==='mpk-plan'){
    /* Classroom Stage — stage block + raked seating + LED wall + camera plots */
    poly('STRUCTURE',7,[[70,22],[130,22],[130,38],[70,38]],true);
    poly('STRUCTURE',7,[[70,18],[130,18],[130,21],[70,21]],true);
    for(i=0;i<10;i++)line('SEATING',9,40,46+i*7,160,46+i*7);
    var mcams=[[100,118,'CAM 1 · HOME'],[40,70,'CAM 2 · LOW L'],[160,70,'CAM 3 · LOW R'],[100,42,'CAM 4 · STAGE']];
    for(i=0;i<mcams.length;i++){circ('CAMERA',5,mcams[i][0],mcams[i][1],2.4);
      text('CAMERA',5,mcams[i][0]+3.5,mcams[i][1]+1,mcams[i][2],2.6);}
    poly('POWER',1,[[10,100],[20,100],[20,118],[10,118]],true);
    text('POWER',1,10,120,'DISTRO A · 200A',2.6);
    text('TEXT',7,40,136,'CLASSROOM STAGE — GENERAL PLAN  ·  1:200',3.4);
  }else if(kind==='mpk-section'){
    /* raked seating in section + stage + LED wall + lighting trim */
    line('STRUCTURE',7,10,20,190,20);
    for(i=0;i<16;i++){var sx=30+i*8,sy=22+i*5;line('SEATING',9,sx,sy,sx+8,sy);line('SEATING',9,sx+8,sy,sx+8,sy+5);}
    poly('STRUCTURE',7,[[16,24],[28,24],[28,44],[16,44]],true);
    poly('STRUCTURE',7,[[14,46],[30,46],[30,86],[14,86]],true);
    line('STRUCTURE',7,10,100,190,100);
    text('TEXT',7,100,102,'LIGHTING TRIM · 10.5m',2.6);
    circ('CAMERA',5,170,70,2.4);text('CAMERA',5,174,70,'CAM 1 · 22m',2.6);
    line('DIMS',4,6,20,6,100);text('DIMS',4,1,60,'10.5m',2.6);
    text('TEXT',7,40,136,'CLASSROOM STAGE — LONGITUDINAL SECTION  ·  1:200',3.4);
  }else if(kind==='mpk-power'){
    /* A/B buses: utility, gen, ATS, distros, cable runs */
    poly('POWER',1,[[20,100],[40,100],[40,124],[20,124]],true);
    text('POWER',1,20,126,'UTILITY · 400A',2.6);
    poly('POWER',1,[[160,100],[180,100],[180,124],[160,124]],true);
    text('POWER',1,160,126,'GEN · 400A',2.6);
    poly('POWER',1,[[90,80],[110,80],[110,96],[90,96]],true);
    text('POWER',1,90,98,'ATS',2.6);
    line('CABLE',2,40,112,90,88);line('CABLE',2,160,112,110,88);
    poly('POWER',1,[[60,40],[80,40],[80,60],[60,60]],true);
    text('POWER',1,60,62,'DISTRO A · 200A',2.6);
    poly('POWER',1,[[120,40],[140,40],[140,60],[120,60]],true);
    text('POWER',1,120,62,'DISTRO B · 200A',2.6);
    line('CABLE',2,100,80,70,60);line('CABLE',2,100,80,130,60);
    text('TEXT',7,40,136,'POWER DISTRIBUTION — A/B BUSES  ·  single-line',3.4);
  }else if(kind==='mpk-lighting'){
    /* FOH + rear truss + fixture positions */
    poly('STRUCTURE',7,[[30,60],[170,60],[170,65],[30,65]],true);
    poly('STRUCTURE',7,[[30,85],[170,85],[170,90],[30,90]],true);
    for(i=0;i<10;i++){var fx=35+i*15;
      circ('CAMERA',5,fx,62.5,1.4);circ('CAMERA',5,fx,87.5,1.4);
      text('TEXT',7,fx-2,54,'S'+(i+1),2.2);}
    poly('STRUCTURE',7,[[70,22],[130,22],[130,32],[70,32]],true);
    text('TEXT',7,80,28,'STAGE',2.6);
    text('TEXT',7,40,136,'LIGHTING PLOT — PRE-RIG  ·  SkyPanel S60 + Source 4',3.4);
  }
  return doc;}

function cadStatus(t){
  var el=document.getElementById('cadvStatus');
  if(el){el.textContent=t||'';el.style.display=t?'block':'none';}}

/* ============================================================================
   DXF serialisation for the seeded venue drawings
   The seed set is generated geometry, and mlightcad opens FILES — so the seeds are
   emitted as real DXF text and go through exactly the same path as an upload.
   ========================================================================== */
function cadSeedDxfText(kind){
  var doc=cadSeedDoc(kind);
  return cadDocToDxfText(doc);}

function cadDocToDxfText(doc){
  var o=[];
  function g(code,val){o.push(String(code));o.push(String(val));}
  /* R2000 (AC1015) — the format the viewer's native DXF converter parses fully.
     The 100 subclass markers are REQUIRED: without them entities are silently
     skipped and the drawing opens empty (verified against the engine). */
  g(0,'SECTION');g(2,'HEADER');
  g(9,'$ACADVER');g(1,'AC1015');
  g(9,'$INSUNITS');g(70,1);
  g(0,'ENDSEC');
  g(0,'SECTION');g(2,'TABLES');
  g(0,'TABLE');g(2,'LTYPE');g(70,1);
  g(0,'LTYPE');g(2,'CONTINUOUS');g(70,0);g(3,'Solid line');g(72,65);g(73,0);g(40,0.0);
  g(0,'ENDTAB');
  g(0,'TABLE');g(2,'LAYER');
  var names=[],n;
  for(n in doc.layers)if(doc.layers.hasOwnProperty(n))names.push(n);
  if(names.indexOf('0')<0)names.unshift('0');
  g(70,names.length);
  for(var li=0;li<names.length;li++){
    var L=doc.layers[names[li]]||{aci:7};
    g(0,'LAYER');g(2,names[li]);g(70,0);g(62,L.aci||7);g(6,'CONTINUOUS');g(370,-1);}
  g(0,'ENDTAB');
  g(0,'ENDSEC');
  g(0,'SECTION');g(2,'BLOCKS');g(0,'ENDSEC');
  g(0,'SECTION');g(2,'ENTITIES');
  function ent(type,e,sub){
    g(0,type);g(100,'AcDbEntity');g(8,e.lay||'0');
    if(e.aci&&e.aci!==256)g(62,e.aci);
    g(100,sub);}
  for(var i=0;i<doc.ents.length;i++){
    var e=doc.ents[i];
    if(e.t==='LINE'&&e.pts&&e.pts.length>1){
      ent('LINE',e,'AcDbLine');
      g(10,e.pts[0][0]);g(20,e.pts[0][1]);g(30,0);
      g(11,e.pts[1][0]);g(21,e.pts[1][1]);g(31,0);continue;}
    if(e.t==='CIRCLE'){
      ent('CIRCLE',e,'AcDbCircle');
      g(10,e.cx);g(20,e.cy);g(30,0);g(40,e.r);continue;}
    if(e.t==='ARC'){
      ent('ARC',e,'AcDbCircle');
      g(10,e.cx);g(20,e.cy);g(30,0);g(40,e.r);
      g(100,'AcDbArc');
      g(50,(e.a1||0)*180/Math.PI);g(51,(e.a2||0)*180/Math.PI);continue;}
    if(e.t==='TEXT'){var s2=cadEntText(e);if(!s2)continue;
      ent('TEXT',e,'AcDbText');
      g(10,e.cx);g(20,e.cy);g(30,0);g(40,e.h||3);g(1,s2);
      g(100,'AcDbText');continue;}
    if((e.t==='PLINE'||e.t==='ELLIPSE')&&e.pts&&e.pts.length>1){
      ent('LWPOLYLINE',e,'AcDbPolyline');
      g(90,e.pts.length);g(70,0);g(43,0.0);
      for(var j=0;j<e.pts.length;j++){g(10,e.pts[j][0]);g(20,e.pts[j][1]);}
      continue;}
    if(e.t==='POINT'){
      ent('POINT',e,'AcDbPoint');
      g(10,e.cx);g(20,e.cy);g(30,0);continue;}
  }
  g(0,'ENDSEC');g(0,'EOF');
  return o.join('\r\n');}

function cadTextToBuffer(txt){
  if(typeof TextEncoder!=='undefined')return new TextEncoder().encode(txt).buffer;
  var b=new ArrayBuffer(txt.length),v=new Uint8Array(b);
  for(var i=0;i<txt.length;i++)v[i]=txt.charCodeAt(i)&255;
  return b;}

/* ============================================================================
   MUSE LIVE v38 — CAD ENGINE: locally built mlightcad/cad-viewer
   ----------------------------------------------------------------------------
   The CAD system IS the cad-viewer app from ./cad-viewer-main, built from
   source and deployed to ./cad/ — the complete AutoCAD-style environment:
   ribbon, layer manager, properties palette, command line, selection, draw &
   modify commands, measurement, PDF/SVG/offline-HTML export, DXF *and* native
   DWG parsing (the libredwg worker ships in ./cad/assets/). No CDN, no
   fallback engine, no canvas re-implementation.

   Muse Live embeds it in a same-origin <iframe> and drives it over postMessage:
     muse  -> viewer : {type:'open', name, buffer}   (extension picks parser)
                        {type:'new'}
     viewer -> muse  : {type:'boot'|'ready'|'opened'|'open-failed'}
   The viewer-side bridge lives in
   cad-viewer-main/packages/cad-viewer-example/src/App.vue.

   Rebuild + redeploy after changing the viewer:
     cd cad-viewer-main
     PATH="$HOME/.local/node22/bin:$PATH" pnpm exec nx run @mlightcad/cad-viewer-example:build
     rm -rf ../cad && cp -R packages/cad-viewer-example/dist ../cad

   PDF sheets and photos still open in the raster markup overlay below — they
   are scans, not geometry, and pretending otherwise would be a lie.
   ========================================================================== */
var pcad={el:null,frame:null,booted:false,pending:null,theme:'',probe:null,meta:'',req:0,bootT:0};
/* bump when ./cad is rebuilt from cad-viewer-main so clients drop the cached shell */
var PCAD_BUILD='v38.4';

function pcadThemeNow(){return (document.documentElement&&document.documentElement.classList.contains('dark'))?'dark':'light';}

function pcadBufToB64(buf){var v=new Uint8Array(buf),s='',CH=0x8000;
  for(var i=0;i<v.length;i+=CH)s+=String.fromCharCode.apply(null,v.subarray(i,Math.min(i+CH,v.length)));
  return btoa(s);}
function pcadB64ToBuf(b64){var s=atob(b64),v=new Uint8Array(s.length);
  for(var i=0;i<s.length;i++)v[i]=s.charCodeAt(i);
  return v.buffer;}

/* Absolute/relative URL to the local cad-viewer shell next to this HTML file. */
function pcadShellUrl(){
  try{return new URL('cad/index.html',location.href).href;}
  catch(e){return 'cad/index.html';}
}
/* Is the locally built viewer deployed & reachable? Prefer GET (some servers reject HEAD). */
function pcadAvailable(){
  if(pcad.probe)return pcad.probe;   /* only a POSITIVE result is memoised */
  /* file:// — browsers block module/worker CAD; still try relative open for simple hosts */
  var url=pcadShellUrl();
  var tries=[url];
  try{/* also try path-relative if opened from a nested route */
    if(location.pathname&&location.pathname.indexOf('/')>=0){
      var base=location.pathname.replace(/[^\/]+$/,'');
      tries.push(base+'cad/index.html');
      tries.push('/cad/index.html');
    }
  }catch(e){}
  function tryOne(i){
    if(i>=tries.length){pcad.probe=null;return Promise.resolve(false);}
    return fetch(tries[i],{method:'GET',cache:'no-store'})
      .then(function(r){
        if(r&&r.ok){pcad._shellUrl=tries[i];return true;}
        return tryOne(i+1);
      })
      ['catch'](function(){return tryOne(i+1);});
  }
  pcad.probe=tryOne(0).then(function(ok){if(!ok)pcad.probe=null;return ok;});
  return pcad.probe;}

function pcadEnsure(){
  if(pcad.el)return;
  var el=document.createElement('div');el.id='pcadOverlay';
  el.style.cssText='position:fixed;top:0;left:0;right:0;bottom:0;z-index:9999;display:none;flex-direction:column;background:#18191A';
  el.innerHTML=
    '<div style="display:flex;align-items:center;gap:12px;padding:9px 14px;background:#1c1e21;border-bottom:1px solid #3A3B3C;flex-wrap:wrap">'+
      '<span id="pcadTitle" style="font:800 13px -apple-system,BlinkMacSystemFont,Segoe UI,Roboto,Helvetica,Arial,sans-serif;color:#e4e6eb"></span>'+
      '<span id="pcadMeta" style="font:600 10px \'DM Mono\',monospace;color:#8a8d91"></span>'+
      '<span style="flex:1"></span>'+
      '<span title="Drawings open in the cad-viewer app built from cad-viewer-main and served from ./cad/" style="font:700 9px -apple-system,BlinkMacSystemFont,Segoe UI,Roboto,Helvetica,Arial,sans-serif;letter-spacing:.08em;color:#31a24c;border:1px solid rgba(30,123,52,.4);border-radius:20px;padding:3px 10px;background:rgba(30,123,52,.1)">&#9670; CAD-VIEWER &middot; LOCAL ENGINE</span>'+
      '<button onclick="pcadClose()" title="Close (Esc)" style="width:32px;height:32px;border:1px solid #3A3B3C;border-radius:8px;background:#242526;color:#ced0d4;font-size:15px;cursor:pointer;line-height:1">&#10005;</button>'+
    '</div>'+
    '<div style="flex:1;position:relative">'+
      '<iframe id="pcadFrame" title="CAD viewer" style="position:absolute;top:0;left:0;width:100%;height:100%;border:0;background:#18191A" allow="fullscreen"></iframe>'+
      '<div id="pcadLoad" style="display:none;position:absolute;left:50%;top:16px;transform:translateX(-50%);z-index:5;font:700 11px -apple-system,BlinkMacSystemFont,Segoe UI,Roboto,Helvetica,Arial,sans-serif;color:#e4e6eb;background:rgba(8,102,255,.94);border-radius:20px;padding:7px 16px;box-shadow:0 6px 22px rgba(0,0,0,.5)"></div>'+
    '</div>';
  document.body.appendChild(el);
  pcad.el=el;
  window.addEventListener('message',pcadOnMessage);
  document.addEventListener('keydown',function(e){
    if(e.key==='Escape'&&pcad.el&&pcad.el.style.display!=='none')pcadClose();});
}

/* (Re)load the iframe. The viewer boots once and stays alive across opens —
   later drawings are handed over by postMessage without a reload. */
function pcadLoadFrame(){
  var theme=pcadThemeNow();
  var fr=document.getElementById('pcadFrame');
  pcad.frame=fr;pcad.booted=false;pcad.theme=theme;
  /* index.html itself is unhashed, so a redeployed viewer would otherwise be
     masked by the browser cache while its hashed assets change underneath. */
  var shell=(pcad._shellUrl||pcadShellUrl());
  var sep=shell.indexOf('?')>=0?'&':'?';
  fr.src=shell+sep+'theme='+theme+'&v='+PCAD_BUILD;}

function pcadOnMessage(e){
  if(e.origin!==location.origin)return;
  var d=e.data||{};
  if(d.type==='boot'){pcad.booted=true;if(pcad.bootT){clearTimeout(pcad.bootT);pcad.bootT=0;}pcadFlush();return;}
  /* the viewer asks to be dismissed (Esc inside the frame, or its own QUIT/EXIT command) */
  if(d.type==='close'){pcadClose();return;}
  if(d.reqId&&d.reqId!==pcad.req)return;   /* a stale reply from a superseded open */
  if(d.type==='opened'){
    pcadStatusMsg('');
    var m=document.getElementById('pcadMeta');
    if(m&&d.entities!=null)m.textContent=(pcad.meta?pcad.meta+' · ':'')+d.entities+' entities · '+d.layers+' layers';
    if(d.entities===0)toast&&toast('The CAD engine opened "'+txt(d.name||'this drawing')+'" but found no entities in it');
    return;}
  if(d.type==='open-failed'){
    pcadStatusMsg('');
    toast&&toast('The CAD engine could not read "'+txt(d.name||'this file')+'"'+(d.message?(' — '+txt(d.message)):''));
    return;}}

function pcadStatusMsg(t){var s=document.getElementById('pcadLoad');if(!s)return;
  if(t){s.textContent=t;s.style.display='block';}else s.style.display='none';}

function pcadFlush(){
  if(!pcad.booted||!pcad.pending||!pcad.frame)return;
  var p=pcad.pending;pcad.pending=null;
  try{
    pcad.frame.contentWindow.postMessage({type:'open',name:p.name,buffer:p.buffer,reqId:pcad.req},location.origin,[p.buffer]);
    pcadStatusMsg('Opening '+p.name+' in the CAD engine…');
  }catch(err){pcadStatusMsg('');toast&&toast('Could not hand the drawing to the CAD engine: '+((err&&err.message)||err));}}

/* Build the {name, buffer} the viewer opens. The extension is load-bearing:
   .dwg routes to the libredwg worker, everything else to the DXF converter. */
function pcadPayload(plan,title){
  var base=String((plan&&plan.name)||title||'drawing')
    .replace(/[\/\\:*?"<>|\u0000-\u001f]+/g,' ').replace(/\s+/g,' ').replace(/^\s+|\s+$/g,'')||'drawing';
  if(plan.dxfText){
    if(!/\.dxf$/i.test(base))base+='.dxf';
    return {name:base,buffer:cadTextToBuffer(plan.dxfText)};}
  if(plan.dwgB64){
    if(!/\.dwg$/i.test(base))base+='.dwg';
    try{return {name:base,buffer:pcadB64ToBuf(plan.dwgB64)};}catch(e){return null;}}
  if(plan.vec)return {name:plan.vec+'.dxf',buffer:cadTextToBuffer(cadSeedDxfText(plan.vec))};
  return null;}

function museInjectEngine(rel, globalName, cb, failMsg){
  var urls=(typeof MuseLazy!=='undefined'&&MuseLazy.candidateUrls)
    ?MuseLazy.candidateUrls(rel)
    :[rel,'/'+rel,(location.origin||'')+'/'+rel,(location.origin||'')+'/js/'+String(rel).replace(/^js\//,'')];
  var i=0;
  function next(){
    if(typeof window[globalName]!=='undefined'&&window[globalName]&&window[globalName].open){
      cb(window[globalName]);return;}
    if(i>=urls.length){toast&&toast(failMsg||('Could not load '+rel));return;}
    var s=document.createElement('script');
    s.src=urls[i];s.async=false;s.charset='utf-8';
    s.onload=function(){
      var g=window[globalName];
      if(g&&g.open)cb(g);else{i+=1;next();}
    };
    s.onerror=function(){i+=1;next();};
    document.head.appendChild(s);
  }
  next();
}
function museCadOpen(key,plan,title){
  /* Read-only 2D/3D CAD viewer (cad-viewer-engine.js) — notes only, no geometry edit.
     Wave B: lazy-load engine on first open. */
  function _cadReady(openFn){
  if(!openFn){
    toast&&toast('CAD viewer failed to load. Pull to refresh, then try again.');
    return;}
  plan=plan||{};
  var dxf=plan.dxfText||null;
  if(!dxf&&plan.vec&&typeof cadSeedDxfText==='function'){
    try{dxf=cadSeedDxfText(plan.vec);}catch(e){dxf=null;}}
  var notes=plan.notes||(plan.cad3d&&plan.cad3d.notes)||[];
  function saveNotesPayload(payload){
    if(!plan)return;
    plan.notes=payload.notes||[];
    plan.cad3d=plan.cad3d||{v:1,readOnly:true};
    plan.cad3d.notes=plan.notes;
    plan.cad3d.readOnly=true;
    var n=plan.notes.length;
    plan.meta=(plan.meta||'').replace(/\s*·\s*\d+\s*notes?/i,'')+(n?' · '+n+' note'+(n===1?'':'s'):'');
    try{stampEdit(key);cadPersistCheck(plan.id);renderProjectView(key);}catch(e){}
  }
  function openCadWith(dxfText,extra){
    var stlBuf=null;
    if(plan.stlB64&&typeof pcadB64ToBuf==='function'){
      try{stlBuf=pcadB64ToBuf(plan.stlB64);}catch(e){stlBuf=null;}}
    var opts={
      key:key,
      planId:plan.id||null,
      title:title||plan.name||'CAD Plan',
      dxfText:dxfText||null,
      objText:plan.objText||null,
      dwgB64:plan.dwgB64||null,
      stlBuffer:stlBuf,
      img:plan.img||null,
      notes:notes,
      viewMode:(plan.objText||plan.stlB64)?'3d':'2d',
      onSaveNotes:saveNotesPayload,
      onSave:function(payload){
        if(payload&&payload.notes)saveNotesPayload(payload);
        else if(payload&&payload.cad3d&&payload.cad3d.notes)saveNotesPayload({notes:payload.cad3d.notes});
      }
    };
    openFn(opts);
    if(extra&&toast)try{toast(extra);}catch(e){}
  }
  /* DWG binary: sniff ASCII, else LibreDWG WASM → DXF, then open read-only */
  if(plan.dwgB64&&!dxf&&!plan.objText&&!plan.stlB64&&!plan.img){
    var sniffed=null;
    try{sniffed=cadDwgSniffDxf(plan.dwgB64);}catch(eD){}
    if(sniffed){openCadWith(sniffed,'DWG recovered as DXF — read-only + notes');return;}
    toast&&toast('Parsing DWG with LibreDWG…');
    museDwgB64ToDxf(plan.dwgB64).then(function(dxfText){
      if(dxfText&&dxfText.length>40){
        plan.dxfText=dxfText;
        try{stampEdit(key);}catch(e){}
        openCadWith(dxfText,'DWG loaded — view & annotate only');
      }else{
        openCadWith(null,'DWG geometry parse limited — try DXF export from AutoCAD');
      }
    });
    return;
  }
  openCadWith(dxf,'');
  } /* end _cadReady */
  var openFn=(typeof CadViewer!=='undefined'&&CadViewer.open)?CadViewer.open:
    ((typeof CAD3D!=='undefined'&&CAD3D.open)?CAD3D.open:null);
  if(openFn){_cadReady(openFn);return;}
  function _cadAfter(CV){
    var fn=(CV&&CV.open)?CV.open:((typeof CadViewer!=='undefined'&&CadViewer.open)?CadViewer.open:
      ((typeof CAD3D!=='undefined'&&CAD3D.open)?CAD3D.open:null));
    _cadReady(fn);
  }
  toast&&toast('Loading CAD engine…');
  if(typeof MuseLazy!=='undefined'&&MuseLazy.ensureCad){
    MuseLazy.ensureCad().then(_cadAfter).catch(function(){
      museInjectEngine('js/cad-viewer-engine.js','CadViewer',_cadAfter,'CAD viewer could not load. Pull to refresh.');
    });
    return;
  }
  museInjectEngine('js/cad-viewer-engine.js','CadViewer',_cadAfter,'CAD viewer could not load. Pull to refresh.');
}
/** Try to recover DXF text from a base64 DWG (works when file is ASCII DXF mislabeled or dual-format). */
function cadDwgSniffDxf(b64){
  if(!b64)return null;
  try{
    var buf=(typeof pcadB64ToBuf==='function')?pcadB64ToBuf(b64):null;
    if(!buf)return null;
    var u=new Uint8Array(buf);
    /* true binary DWG starts with AC10xx */
    if(u.length>6&&u[0]===0x41&&u[1]===0x43&&u[2]===0x31&&u[3]===0x30)return null;
    var s='';
    var n=Math.min(u.length,4*1024*1024);
    for(var i=0;i<n;i++)s+=String.fromCharCode(u[i]);
    if(/^\s*0\s*[\r\n]+\s*SECTION/i.test(s)||s.indexOf('ENTITIES')>=0){
      if(s.indexOf('EOF')<0)s+='\n0\nEOF\n';
      return s;}
  }catch(e){}
  return null;}

/* ===== LibreDWG-web (WASM) — real binary DWG → DXF in the browser ===== */
var _libreDwg=null,_libreDwgPromise=null;
function museLibreDwgBase(){
  try{
    var s=document.querySelector('script[src*="cad-viewer-engine"],script[src*="pano-engine"],script[src*="Muse_Live"]');
    if(s&&s.src){
      var u=s.src.replace(/[#?].*$/,'').replace(/[^/]+$/,'');
      /* engines live in js/ next to libredwg/ */
      if(/\/js\/?$/.test(u)) return u+'libredwg/';
      return u+'js/libredwg/';
    }
  }catch(e){}
  try{return new URL('js/libredwg/',window.location.href).href;}catch(e2){}
  return 'js/libredwg/';
}
function museLoadLibreDwg(){
  if(_libreDwg)return Promise.resolve(_libreDwg);
  if(_libreDwgPromise)return _libreDwgPromise;
  if(location.protocol==='file:'||window.__MUSE_FILE_ORIGIN){
    return Promise.reject(new Error('DWG requires http://localhost — run ./start-muse.sh (file:// blocks WASM)'));
  }
  var base=museLibreDwgBase();
  /* Dynamic ESM import — only works over http/https */
  _libreDwgPromise=import(base+'libredwg-web.esm.js').then(function(mod){
    var LibreDwg=mod.LibreDwg;
    if(!LibreDwg||!LibreDwg.create)throw new Error('LibreDwg.create missing from ESM');
    return LibreDwg.create(base.replace(/\/$/,''));
  }).then(function(lib){
    _libreDwg=lib;return lib;
  }).catch(function(err){
    _libreDwgPromise=null;
    console.warn('LibreDWG load failed',err);
    throw err;
  });
  return _libreDwgPromise;
}
/** Convert binary DWG ArrayBuffer → DXF text. Returns Promise<string|null>. */
function museDwgToDxf(arrayBuffer){
  if(location.protocol==='file:'||window.__MUSE_FILE_ORIGIN){
    try{if(typeof toast==='function')toast('⚠ Open via ./start-muse.sh — DWG cannot load from file://');}catch(e){}
    return Promise.resolve(null);
  }
  return museLoadLibreDwg().then(function(lib){
    if(!lib)return null;
    /* Path A: direct DWG→DXF bytes */
    try{
      if(typeof lib.dwg_write_dxf==='function'){
        var out=lib.dwg_write_dxf(arrayBuffer);
        if(out){
          var u=(out instanceof Uint8Array)?out:new Uint8Array(out);
          if(u.length>40){
            var s='',CH=0x8000,i;
            for(i=0;i<u.length;i+=CH)s+=String.fromCharCode.apply(null,u.subarray(i,Math.min(i+CH,u.length)));
            if(s.indexOf('EOF')<0)s+='\n0\nEOF\n';
            if(s.indexOf('ENTITIES')>=0||s.indexOf('LINE')>=0)return s;
          }
        }
      }
    }catch(e){console.warn('dwg_write_dxf',e);}
    /* Path B: read + convert database → synthetic DXF lines (most reliable) */
    try{
      var fileType=0; /* DWG */
      try{if(lib.Dwg_File_Type&&lib.Dwg_File_Type.DWG!=null)fileType=lib.Dwg_File_Type.DWG;}catch(e0){}
      var data=null;
      if(typeof lib.dwg_read_data==='function')data=lib.dwg_read_data(arrayBuffer,fileType);
      if(data==null&&typeof lib.dwg_read_data==='function')data=lib.dwg_read_data(arrayBuffer,0);
      if(data==null)return null;
      var db=null;
      if(typeof lib.convert==='function')db=lib.convert(data);
      try{if(typeof lib.dwg_free==='function')lib.dwg_free(data);}catch(e1){}
      if(!db||!db.entities||!db.entities.length)return null;
      return museDwgDatabaseToDxf(db);
    }catch(e2){console.warn('dwg convert db',e2);return null;}
  }).catch(function(err){
    console.warn('DWG convert failed',err);
    return null;
  });
}
/** Serialize LibreDWG DwgDatabase entities into a minimal DXF our CAD importer understands. */
function museDwgDatabaseToDxf(db){
  var lines=['0','SECTION','2','HEADER','0','ENDSEC','0','SECTION','2','ENTITIES'];
  var n=0;
  function addLine(x1,y1,x2,y2,layer){
    lines.push('0','LINE','8',String(layer||'0'),
      '10',String(x1),'20',String(y1),'30','0',
      '11',String(x2),'21',String(y2),'31','0');
    n++;
  }
  (db.entities||[]).forEach(function(e){
    if(!e||!e.type)return;
    var layer=(e.layer||e.layerName||'0');
    if(e.type==='LINE'&&e.startPoint&&e.endPoint){
      addLine(e.startPoint.x,e.startPoint.y,e.endPoint.x,e.endPoint.y,layer);
    }else if(e.type==='LWPOLYLINE'&&e.vertices&&e.vertices.length>1){
      var vs=e.vertices,i,a,b;
      for(i=0;i<vs.length-1;i++){
        a=vs[i];b=vs[i+1];
        addLine(a.x!=null?a.x:a[0],a.y!=null?a.y:a[1],b.x!=null?b.x:b[0],b.y!=null?b.y:b[1],layer);
      }
      if(e.closed||e.flag&1){
        a=vs[vs.length-1];b=vs[0];
        addLine(a.x!=null?a.x:a[0],a.y!=null?a.y:a[1],b.x!=null?b.x:b[0],b.y!=null?b.y:b[1],layer);
      }
    }else if(e.type==='POLYLINE'&&e.vertices&&e.vertices.length>1){
      var pv=e.vertices,j;
      for(j=0;j<pv.length-1;j++){
        addLine(pv[j].x,pv[j].y,pv[j+1].x,pv[j+1].y,layer);
      }
    }else if(e.type==='CIRCLE'&&e.center&&e.radius!=null){
      var seg=32,k,a1,a2;
      for(k=0;k<seg;k++){
        a1=k*2*Math.PI/seg;a2=(k+1)*2*Math.PI/seg;
        addLine(e.center.x+e.radius*Math.cos(a1),e.center.y+e.radius*Math.sin(a1),
                e.center.x+e.radius*Math.cos(a2),e.center.y+e.radius*Math.sin(a2),layer);
      }
    }else if(e.type==='ARC'&&e.center&&e.radius!=null){
      var sa=(e.startAngle!=null?e.startAngle:0),ea=(e.endAngle!=null?e.endAngle:Math.PI*2);
      if(ea<sa)ea+=Math.PI*2;
      var steps=Math.max(8,Math.ceil((ea-sa)/(Math.PI/16))),t;
      for(t=0;t<steps;t++){
        var t1=sa+(ea-sa)*t/steps,t2=sa+(ea-sa)*(t+1)/steps;
        addLine(e.center.x+e.radius*Math.cos(t1),e.center.y+e.radius*Math.sin(t1),
                e.center.x+e.radius*Math.cos(t2),e.center.y+e.radius*Math.sin(t2),layer);
      }
    }
  });
  lines.push('0','ENDSEC','0','EOF');
  if(!n)return null;
  return lines.join('\n');
}
function museDwgB64ToDxf(b64){
  try{
    var buf=pcadB64ToBuf(b64);
    return museDwgToDxf(buf);
  }catch(e){return Promise.resolve(null);}
}
try{window.museDwgToDxf=museDwgToDxf;window.museLoadLibreDwg=museLoadLibreDwg;}catch(e){}

function pcadClose(){
  if(pcad.bootT){clearTimeout(pcad.bootT);pcad.bootT=0;}
  pcad.req++;                     /* orphan any reply still in flight */
  pcadStatusMsg('');
  if(pcad.el)pcad.el.style.display='none';
  document.body.style.overflow='';}

/* ---- pdf.js (lazy CDN — house pattern; honest offline fallback) ---- */
var PDFJS_URL='https://cdn.jsdelivr.net/npm/pdfjs-dist@3.11.174/legacy/build/pdf.min.js';
var PDFJS_WORKER='https://cdn.jsdelivr.net/npm/pdfjs-dist@3.11.174/legacy/build/pdf.worker.min.js';
var _pdfjsPromise=null;
function loadPdfJs(){if(window.pdfjsLib)return Promise.resolve(window.pdfjsLib);
  if(_pdfjsPromise)return _pdfjsPromise;
  _pdfjsPromise=new Promise(function(res,rej){var s=document.createElement('script');s.src=PDFJS_URL;
    s.onload=function(){try{window.pdfjsLib.GlobalWorkerOptions.workerSrc=PDFJS_WORKER;res(window.pdfjsLib);}catch(e){_pdfjsPromise=null;rej(e);}};
    s.onerror=function(){_pdfjsPromise=null;rej(new Error('cdn unreachable'));};
    document.head.appendChild(s);});
  return _pdfjsPromise;}

function cadUpload(key,e){var f=e.target.files&&e.target.files[0];if(!f)return;
  var name=f.name||'plan';var base=name.replace(/\.[^.]+$/,'');
  var isImg=/^image\//.test(f.type)||/\.(png|jpe?g|webp|gif|bmp)$/i.test(name);
  var isDxf=/\.dxf$/i.test(name);
  var isPdf=(f.type==='application/pdf')||/\.pdf$/i.test(name);
  var isDwg=/\.dwg$/i.test(name);
  var isObj=/\.obj$/i.test(name);
  var isStl=/\.stl$/i.test(name);
  var isUnsupported=/\.(dwf|dwfx|x_t|x_b|stp|step|vwx)$/i.test(name);
  e.target.value='';
  if(isUnsupported){
    toast((name.split('.').pop()||'').toUpperCase()+' is not supported in-browser — export DXF, OBJ, or STL from your CAD app');
    return;}
  if(isObj||isStl){var ro=new FileReader();
    ro.onload=function(){var plans=getCadPlans(key);var id='cad'+Date.now();
      var rec={id:id,name:base,meta:(isObj?'OBJ mesh':'STL mesh')+' · read-only viewer + notes',kind:'camera',tag:'3D',img:null,notes:[],cad3d:{v:1,readOnly:true,notes:[]}};
      if(isObj)rec.objText=String(ro.result);
      else{try{rec.stlB64=pcadBufToB64(ro.result);}catch(err){toast('Could not read STL');return;}}
      plans.push(rec);stampEdit(key);cadPersistCheck(id);renderProjectView(key);
      toast((isObj?'OBJ':'STL')+' stored — opening read-only viewer');
      try{museCadOpen(key,rec,base);}catch(e3){}};
    if(isObj)ro.readAsText(f);else ro.readAsArrayBuffer(f);return;}
  if(isDxf){var rt=new FileReader();
    rt.onload=function(){cadAddDxfText(key,base,String(rt.result),'DXF');};
    rt.readAsText(f);return;}
  /* Binary DWG → store + LibreDWG → DXF for read-only view */
  if(isDwg){var rd=new FileReader();
    rd.onload=function(){
      var ab=rd.result,b64='';
      try{b64=pcadBufToB64(ab);}catch(err){toast('Could not read this DWG file');return;}
      var plans=getCadPlans(key);var id='cad'+Date.now();
      var rec={id:id,name:base,
        meta:'DWG · '+Math.round((f.size||b64.length*0.75)/1024)+' KB · read-only',
        kind:'camera',tag:'DWG',img:null,dwgB64:b64,notes:[]};
      try{var dx0=cadDwgSniffDxf(b64);if(dx0){rec.dxfText=dx0;rec.meta+=' · DXF entities recovered';rec.tag='DXF';
        plans.push(rec);stampEdit(key);cadPersistCheck(id);renderProjectView(key);
        toast('DWG/DXF stored — opening viewer');try{museCadOpen(key,rec,base);}catch(e3){}
        return;}}catch(e2){}
      plans.push(rec);stampEdit(key);cadPersistCheck(id);renderProjectView(key);
      toast('Parsing DWG with LibreDWG…');
      museDwgToDxf(ab).then(function(dxfText){
        if(dxfText&&dxfText.length>40){
          rec.dxfText=dxfText;rec.meta+=' · geometry imported';rec.tag='DWG';
          try{stampEdit(key);cadPersistCheck(id);renderProjectView(key);}catch(e){}
          toast('DWG converted — opening read-only viewer');
        }else{
          toast('DWG stored (geometry parse limited) — try a DXF export if walls are missing');
        }
        try{museCadOpen(key,rec,base);}catch(e4){}
      });
    };
    rd.readAsArrayBuffer(f);return;}
  if(isPdf){var rb=new FileReader();
    rb.onload=function(){var buf=rb.result;
      loadPdfJs().then(function(pdfjs){
        pdfjs.getDocument({data:buf}).promise.then(function(doc){
          var total=Math.min(doc.numPages,4);var done=0;
          function renderPage(n){doc.getPage(n).then(function(page){
            var vp=page.getViewport({scale:1});var sc=Math.min(4,2400/Math.max(vp.width,vp.height));
            var vp2=page.getViewport({scale:sc});
            var cv=document.createElement('canvas');cv.width=Math.round(vp2.width);cv.height=Math.round(vp2.height);
            page.render({canvasContext:cv.getContext('2d'),viewport:vp2}).promise.then(function(){
              var plans=getCadPlans(key);var pid='cad'+Date.now()+'p'+n;
              plans.push({id:pid,name:base+(total>1?' — sheet '+n:''),meta:'PDF sheet · rendered for markup',kind:'camera',tag:'PDF',img:cv.toDataURL('image/png')});
              done++;if(done===total){stampEdit(key);cadPersistCheck(pid);renderProjectView(key);
                toast('PDF rendered — '+total+' sheet'+(total>1?'s':'')+(doc.numPages>total?' (first '+total+' of '+doc.numPages+')':''));}
            }).catch(function(){done++;});
          }).catch(function(){done++;});}
          for(var n=1;n<=total;n++)renderPage(n);
        }).catch(function(){toast('Could not read this PDF file');});
      }).catch(function(){toast('PDF engine (pdf.js CDN) unreachable — connect once and re-upload to render sheets');});
    };rb.readAsArrayBuffer(f);return;}
  if(!isImg&&!isPdf){
    toast('Unsupported file — use DXF, DWG, OBJ, STL, PDF, or image');
    return;}
  var r=new FileReader();
  r.onload=function(){var plans=getCadPlans(key);
    var rec={id:'cad'+Date.now(),name:base,meta:isImg?'Image plan · read-only + notes':'Uploaded file',kind:'camera',tag:'IMG',img:isImg?r.result:null,notes:[]};
    plans.push(rec);
    stampEdit(key);cadPersistCheck(rec.id);renderProjectView(key);
    toast('Site plan added — opening viewer');
    try{if(isImg)museCadOpen(key,rec,base);}catch(e){}};
  r.readAsDataURL(f);}
function cadRemove(key,i){var plans=getCadPlans(key);if(!confirm('Remove this site plan?'))return;plans.splice(i,1);stampEdit(key);renderProjectView(key);}

/* v37: one landing point for DXF text, whoever produced it (uploaded .dxf, or a .dwg
   converted by libredwg). The DXF TEXT is what gets stored — it is the editable source,
   it is usually smaller than the PNG it replaces, and it is what the vector viewer opens.
   A small raster thumbnail is kept purely for the tile preview. */
function cadAddDxfText(key,base,text,tag){
  var model=null,out=null;
  try{model=dxfParse(text);}catch(e){model=null;}
  if(!model||!model.entities||!model.entities.length){
    toast('No drawable geometry found in this file — try exporting an ASCII DXF (R12/R2000)');return;}
  try{out=dxfRender(model,1400);}catch(e){out=null;}   /* thumbnail only; may legitimately fail */
  var plans=getCadPlans(key);var id='cad'+Date.now();
  var layerN=0;for(var ln in model.layers)if(model.layers.hasOwnProperty(ln))layerN++;
  var kb=Math.round(text.length/1024);
  var rec={id:id,name:base,
    meta:(tag||'DXF')+' · '+model.entities.length+' entities · '+(layerN||1)+' layers · '+kb+' KB · read-only + notes',
    kind:'camera',tag:(tag||'DXF'),img:(out?out.url:null),dxfText:text,notes:[]};
  plans.push(rec);
  if(out){var unitFt={1:1/12,2:1,4:0.00328084,5:0.0328084,6:3.28084}[model.insunits];
    if(unitFt)cadScaleSave(key,id,unitFt/out.pxPerUnit);}
  stampEdit(key);cadPersistCheck(id);renderProjectView(key);
  toast((tag==='DWG'?'DWG':'DXF')+' loaded — opening read-only viewer (notes only)');
  try{museCadOpen(key,rec,base);}catch(e){}}

/* survey mutations */
function surveySetAddress(key,v){var s=getSurvey(key);s.address=v;var g=surveyGuessGPS(v);if(g&&(s.lat==null||s.lng==null)){s.lat=g.lat;s.lng=g.lng;}stampEdit(key);renderProjectView(key);}
function surveySetGPS(key,axis,v){var s=getSurvey(key);var n=parseFloat(v);s[axis]=isNaN(n)?null:n;stampEdit(key);renderProjectView(key);}
/* v35: OpenMap search result → sets the survey site's address + GPS (+ moves the
   active location pin), so the multi-pin map, venue map and ShadeMap all follow */
function survGeoPick(key,r){var s=getSurvey(key);
  s.address=r.name+(r.city?', '+r.city:'');s.lat=r.lat;s.lng=r.lng;
  var L=(typeof activeLocation==='function')?activeLocation(key):null;
  if(L){L.lat=r.lat;L.lng=r.lng;if(r.city)L.city=r.city;if(!L.venue)L.venue=r.name;}
  stampEdit(key);renderProjectView(key);
  toast('📍 '+txt(r.name)+' set as survey location');
  try{museTzLookup(r.lat,r.lng,function(tz){if(!tz)return;s.tz=tz;
    var S=_shadeMaps['survshade_'+key];if(S){S.tz=tz;S.baseParts=museZonedParts(tz,museNow());_shadeLabel('survshade_'+key);}});}catch(e){}
}
/* ---- Site Gallery mutations (v29): main site photos + Surrounding Areas ---- */
function survGalArr(s,which){return which==='around'?s.imagesAround:s.images;}
function survGalAdd(key,which,e){var files=e.target.files;if(!files||!files.length)return;
  var s=getSurvey(key);var arr=survGalArr(s,which);var left=files.length,n=files.length;
  Array.prototype.forEach.call(files,function(f){var r=new FileReader();
    r.onload=function(){arr.push({src:r.result,caption:'',ts:nowStamp(),by:(productions[key].editedBy||'')});
      left--;if(!left){stampEdit(key);renderProjectView(key);toast(n>1?n+' photos added to the gallery':'Photo added to the gallery');}};
    r.readAsDataURL(f);});
  e.target.value='';}
function survGalCaption(key,which,i,val){var s=getSurvey(key);var arr=survGalArr(s,which);
  if(!arr[i]||arr[i].caption===val)return;arr[i].caption=val;
  if(!arr[i].ts)arr[i].ts=nowStamp();stampEdit(key);}
function survGalRemove(key,which,i){var s=getSurvey(key);var arr=survGalArr(s,which);
  if(!arr[i])return;if(!confirm('Remove this photo from the gallery?'))return;
  arr.splice(i,1);stampEdit(key);renderProjectView(key);}
function survGalView(key,which,i){var s=getSurvey(key);var arr=survGalArr(s,which);var im=arr[i];if(!im)return;
  var ov=document.getElementById('galLightbox');
  if(!ov){ov=document.createElement('div');ov.id='galLightbox';
    ov.style.cssText='display:none;position:fixed;inset:0;z-index:80;background:rgba(5,5,5,.93);align-items:center;justify-content:center;padding:24px;flex-direction:column;gap:10px';
    ov.onclick=function(ev){if(ev.target===ov)ov.style.display='none';};document.body.appendChild(ov);}
  ov.innerHTML='<img src="'+im.src+'" onerror="this.onerror=null;this.src=STADIUM_IMG_FALLBACK" style="max-width:92vw;max-height:76vh;border-radius:12px;box-shadow:0 20px 60px rgba(0,0,0,.6);object-fit:contain" alt="site photo">'+
    '<div style="color:#e4e6eb;font:600 12px -apple-system,BlinkMacSystemFont,Segoe UI,Roboto,Helvetica,Arial,sans-serif;max-width:80vw;text-align:center">'+esc(im.caption||'No caption yet')+
      ((im.ts||im.by)?'<div style="color:#8a8d91;font:500 10px ui-monospace,SFMono-Regular,Menlo,Consolas,monospace;margin-top:3px">'+esc(im.ts||'')+(im.by?' · '+esc(im.by):'')+'</div>':'')+'</div>'+
    '<button onclick="document.getElementById(\'galLightbox\').style.display=\'none\'" style="position:absolute;top:14px;right:18px;background:none;border:none;color:#ced0d4;font-size:22px;cursor:pointer;line-height:1">✕</button>';
  ov.style.display='flex';}

/* ---- Site Gallery pane (v29) ---- */
function survGalCard(key,which,im,i){
  return '<div class="rounded-xl overflow-hidden border border-gray-200 bg-white group relative">'+
    '<div onclick="survGalView(\''+key+'\',\''+which+'\','+i+')" class="relative cursor-pointer" style="aspect-ratio:16/10;background:#18191A">'+
      '<img src="'+im.src+'" onerror="this.onerror=null;this.src=STADIUM_IMG_FALLBACK" loading="lazy" style="width:100%;height:100%;object-fit:cover" alt="site photo">'+
      '<div class="absolute inset-0 bg-black/0 group-hover:bg-black/15 transition-colors"></div>'+
      '<button onclick="event.stopPropagation();survGalRemove(\''+key+'\',\''+which+'\','+i+')" class="absolute top-1.5 right-1.5 w-6 h-6 rounded-lg bg-black/50 text-white text-xs opacity-0 group-hover:opacity-100 transition-opacity">✕</button></div>'+
    '<div class="p-2">'+
      '<input value="'+esc(im.caption||'').replace(/"/g,'&quot;')+'" onchange="survGalCaption(\''+key+'\',\''+which+'\','+i+',this.value)" placeholder="Caption — what is this &amp; why it matters…" class="w-full text-[10px] text-gray-700 border border-transparent hover:border-gray-200 focus:border-gray-300 rounded px-1.5 py-1" style="outline:none">'+
      '<p class="text-[8px] text-gray-400 mono px-1.5 mt-0.5">'+(im.ts?esc(im.ts):'seeded reference')+(im.by?' · '+esc(im.by):'')+'</p></div></div>';}
function surveyGalleryHTML(key){var s=getSurvey(key);
  var main=(s.images||[]).map(function(im,i){return survGalCard(key,'main',im,i);}).join('');
  var around=(s.imagesAround||[]).map(function(im,i){return survGalCard(key,'around',im,i);}).join('');
  var nMain=(s.images||[]).length,nAround=(s.imagesAround||[]).length;
  return '<div class="space-y-4">'+
    '<div class="bg-white rounded-2xl p-4 sm:p-5 border border-gray-200/60" style="box-shadow:0 4px 20px rgba(0,0,0,.03)">'+
      '<div class="flex flex-wrap items-center justify-between gap-2 mb-3">'+
        '<div><h4 class="text-[10px] font-bold uppercase tracking-wider text-gray-600">Site Gallery <span class="text-gray-400 font-normal normal-case">— '+nMain+' photo'+(nMain===1?'':'s')+' · the visual record of the site</span></h4>'+
        '<p class="text-[9px] text-gray-400 mt-0.5">Camera platforms, tie-ins, demarcs, docks, rigging points — every photo carries a caption and timestamp. Click a photo to view full-size.</p></div>'+
        '<label class="text-[9px] font-bold text-white bg-gray-900 rounded-lg px-3 py-2 hover:bg-gray-800 cursor-pointer">+ Add photos<input type="file" accept="image/*" multiple onchange="survGalAdd(\''+key+'\',\'main\',event)" style="display:none"></label></div>'+
      (main?'<div class="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-3">'+main+'</div>':'<p class="text-[11px] text-gray-400 text-center py-4">No site photos yet — add the first shots from the site walk.</p>')+
    '</div>'+
    '<div class="rounded-2xl p-4 sm:p-5 border border-amber-200 bg-amber-50/30">'+
      '<div class="flex flex-wrap items-center justify-between gap-2 mb-3">'+
        '<div><h4 class="text-[10px] font-bold uppercase tracking-wider text-amber-700">Surrounding Areas <span class="text-amber-600/70 font-normal normal-case">— '+nAround+' photo'+(nAround===1?'':'s')+' · context beyond the venue</span></h4>'+
        '<p class="text-[9px] text-amber-700/70 mt-0.5">Adjacent streets, parking &amp; staging, sight-lines, neighboring structures — the logistics picture around the site, kept separate from the venue record.</p></div>'+
        '<label class="text-[9px] font-bold text-amber-800 border border-amber-300 bg-white rounded-lg px-3 py-2 hover:bg-amber-50 cursor-pointer">+ Add photos<input type="file" accept="image/*" multiple onchange="survGalAdd(\''+key+'\',\'around\',event)" style="display:none"></label></div>'+
      (around?'<div class="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-3">'+around+'</div>':'<p class="text-[11px] text-amber-700/60 text-center py-4">No surrounding-area photos yet — streets, parking, staging &amp; sight-lines live here.</p>')+
    '</div>'+
  '</div>';}

/* ---- Location & Map pane (v29 Module 2): every site pinned at once ---- */
var survMapHide=(typeof survMapHide!=='undefined')?survMapHide:{}; /* key -> {locId:1} pin visibility (UI state) */
function survMapPins(key){var p=productions[key];var act=(typeof activeLocation==='function')?activeLocation(key):null;
  var hide=survMapHide[key]||{};var pins=[];
  if(p.locations&&p.locations.length){
    p.locations.forEach(function(L){if(typeof L.lat!=='number'||typeof L.lng!=='number')return;
      pins.push({id:L.id,name:L.name,city:L.city||'',lat:L.lat,lng:L.lng,active:!!(act&&act.id===L.id),hidden:!!hide[L.id],key:key});});
  }else{var s=getSurvey(key);var v=venueFor(key);
    var la=(s.lat!=null?s.lat:(v?v.lat:null)),lo=(s.lng!=null?s.lng:(v?v.lng:null));
    if(la!=null&&lo!=null)pins.push({id:'site',name:p.venue||p.name,city:'',lat:la,lng:lo,active:true,hidden:false,key:''});}
  return pins;}
function survMapToggle(key,locId){survMapHide[key]=survMapHide[key]||{};
  if(survMapHide[key][locId])delete survMapHide[key][locId];else survMapHide[key][locId]=1;
  renderProjectView(key);}

/* ---- v37: VENUE DROPDOWN — the map follows the selection, nothing else moves --------------
   Before v37 the only way to look at a site on the map was setActiveLoc(), which also re-binds
   the production's departments, gallery, survey record and log to that site. That is a real
   state change and much too heavy for "let me see the stadium". survMapSel is pure camera
   state: session-only (never persisted, never stamped), defaulting to the active location so
   the pane opens exactly where it used to.  ------------------------------------------------- */
var survMapSel=(typeof survMapSel!=='undefined')?survMapSel:{}; /* prodKey -> locId ('' = fit all sites) */
function survMapLocs(key){var p=productions[key];return (p&&p.locations&&p.locations.length)?p.locations:[];}
function survMapFocusOf(key){
  if(key in survMapSel)return survMapSel[key];
  var locs=survMapLocs(key);if(!locs.length)return '';
  var act=(typeof activeLocation==='function')?activeLocation(key):null;
  return (act&&typeof act.lat==='number')?act.id:'';}
function survMapFocusLoc(key){var id=survMapFocusOf(key);if(!id)return null;
  var locs=survMapLocs(key);
  for(var i=0;i<locs.length;i++)if(locs[i].id===id)return locs[i];
  return null;}
/* alphabetical by venue name — the order a producer reads a venue list in */
function survMapSortedLocs(key){
  return survMapLocs(key).slice().sort(function(a,b){
    var an=(a.name||a.venue||'').toLowerCase(),bn=(b.name||b.venue||'').toLowerCase();
    return an<bn?-1:(an>bn?1:0);});}
function survMapVenueSelect(key,locs,focus){
  if(!locs||locs.length<2)return ''; /* one site = nothing to choose between */
  var act=(typeof activeLocation==='function')?activeLocation(key):null;
  var hide=survMapHide[key]||{};
  var opts='<option value=""'+(focus?'':' selected')+'>🌐 All sites — fit every pin</option>';
  survMapSortedLocs(key).forEach(function(L){
    var noPos=(typeof L.lat!=='number'||typeof L.lng!=='number');
    var tags=[];
    if(L.city)tags.push(L.city);
    if(L.role)tags.push(L.role);
    if(act&&act.id===L.id)tags.push('active');
    if(noPos)tags.push('no GPS');
    else if(hide[L.id])tags.push('pin hidden');
    opts+='<option value="'+esc(L.id)+'"'+(focus===L.id?' selected':'')+(noPos?' disabled':'')+'>'+
      (L.flag||'📍')+' '+esc(L.name)+(tags.length?'  ·  '+esc(tags.join(' · ')):'')+'</option>';});
  var focL=survMapFocusLoc(key);
  return '<div class="flex flex-wrap items-center gap-2 mt-2 mb-1">'+
    '<label for="survMapSel_'+key+'" class="text-[8px] font-bold uppercase tracking-wider text-gray-400 flex-shrink-0">Map follows</label>'+
    '<select id="survMapSel_'+key+'" onchange="survMapPick(\''+key+'\',this.value)" class="flex-1 min-w-[200px] text-[11px] font-semibold text-gray-800 border border-gray-300 rounded-lg px-2 py-1.5 bg-white" style="outline:none">'+opts+'</select>'+
    (focL?'<a href="https://www.google.com/maps/search/?api=1&query='+encodeURIComponent(focL.lat+','+focL.lng)+'" target="_blank" rel="noopener" class="text-[9px] font-bold text-blue-700 hover:underline flex-shrink-0">Google Maps →</a>':'')+
    '<span class="text-[8px] text-gray-400 flex-shrink-0">viewing only — does not change the active site</span>'+
  '</div>';}
/* dropdown / "show on map" → move the camera + the sun-shadow panel. No renderProjectView:
   tearing down and remounting the pane would kill the flyTo animation and the map instance. */
function survMapPick(key,locId){
  survMapSel[key]=locId||'';
  var mapId='mmap_'+key;
  _mmapFocusCb[mapId]=function(v){var sel=document.getElementById('survMapSel_'+key);if(sel)sel.value=v||'';
    survMapSel[key]=v||'';survMapSyncRows(key);};
  if(locId)multiFocusPin(mapId,locId);else multiFitAll(mapId);
  var sel=document.getElementById('survMapSel_'+key);if(sel&&sel.value!==(locId||''))sel.value=locId||'';
  survMapShadeFollow(key);survMapSyncRows(key);
  var L=survMapFocusLoc(key);
  if(typeof toast==='function')toast(L?('Map → '+L.name):'Map → all sites');}
/* move the ShadeMap panel without a re-render: mountShadeBox's cached branch reads the
   data-* attributes and flies the 3D view when the coordinates changed. */
function survMapShadeFollow(key){
  var el=document.getElementById('survshade_'+key);if(!el)return;
  var L=survMapFocusLoc(key);var s=getSurvey(key);
  var lat=(L&&typeof L.lat==='number')?L.lat:s.lat,lng=(L&&typeof L.lng==='number')?L.lng:s.lng;
  if(lat==null||lng==null)return;
  var tz=(L&&L.tz)||s.tz||museTzGuess(lat,lng);
  el.setAttribute('data-lat',lat);el.setAttribute('data-lng',lng);el.setAttribute('data-tz',tz);
  el.setAttribute('data-label',(L?L.name:(s.address||'Survey site')));
  el.setAttribute('data-mounted','');
  try{mountShadeBox(el);}catch(e){}}
/* repaint just the location list's focus affordances (◎ on map / show on map / row tint) */
function survMapSyncRows(key){
  var host=document.getElementById('survMapRows_'+key);if(!host)return;
  try{host.innerHTML=survMapRowsHTML(key);}catch(e){}}
function survLocNote(key,id,val){var p=productions[key];if(!p||!p.locations)return;
  for(var i=0;i<p.locations.length;i++)if(p.locations[i].id===id){p.locations[i].notes=val;break;}
  stampEdit(key);}
function survLocFormToggle(key){var f=document.getElementById('slocForm_'+key);if(f)f.style.display=(f.style.display==='none'?'block':'none');}
function survLocAdd(key){var p=productions[key];if(!p)return;
  function g(id){var el=document.getElementById(id+'_'+key);return el?el.value.trim():'';}
  var name=g('slocName');if(!name){toast('Give the location a name first');return;}
  var city=g('slocCity'),venue=g('slocVenue')||name,tz=g('slocTz')||'America/New_York',role=g('slocRole');
  var lat=parseFloat(g('slocLat')),lng=parseFloat(g('slocLng'));
  if(isNaN(lat)||isNaN(lng)){var gg=geoLookup(name+' '+venue+' '+city);if(gg){lat=gg.lat;lng=gg.lng;}}
  if(isNaN(lat)||isNaN(lng)){toast('Coordinates needed — enter lat/lng, or use a recognizable venue name');return;}
  var tzl='';var ti;for(ti=0;ti<NP_TZS.length;ti++){if(NP_TZS[ti][0]===tz){tzl=NP_TZS[ti][1].split(' ')[0];break;}}
  if(!Array.isArray(p.locations)||!p.locations.length){
    // first extra site on a single-venue production: promote the venue to location #1 and keep its survey
    var v=venueFor(key);
    p.locations=[{id:'primary',name:p.venue||p.name,venue:p.venue||'',city:'',cc:'',flag:'📍',tz:'America/New_York',tzl:'ET',lat:(v?v.lat:null),lng:(v?v.lng:null),role:'Primary site',note:''}];
    p.surveyLoc=p.surveyLoc||{};
    if(p.survey&&!p.surveyLoc.primary)p.surveyLoc.primary=p.survey;
    if(!projLoc[key])projLoc[key]='primary';
  }
  p.locations.push({id:'loc'+Date.now().toString(36),name:name,venue:venue,city:city,cc:'',flag:'📍',tz:tz,tzl:tzl,lat:lat,lng:lng,role:role||'',note:''});
  stampEdit(key);try{logEvent(key,'📍 Location added to survey: '+name);}catch(e){}
  try{if(typeof locDeptBind==='function')locDeptBind(key);}catch(e){}
  renderProjectView(key);toast('Location added — '+name);}
function surveyMapHTML(key){var p=productions[key];var s=getSurvey(key);
  var pins=survMapPins(key);var act=(typeof activeLocation==='function')?activeLocation(key):null;
  var locs=(p.locations&&p.locations.length)?p.locations:[];
  var hide=survMapHide[key]||{};
  /* v42: Overview already shows the primary venue map. Location & Map only adds a
     second multi-venue map when there is more than one site — otherwise just the
     sun & shadows map (no duplicate of the overview map). */
  var focus=survMapFocusOf(key);
  var focL=survMapFocusLoc(key);
  var multiVenue=locs.length>1;
  var mapBlock='';
  var venueSel=survMapVenueSelect(key,locs,focus);
  if(multiVenue){
    mapBlock='<div class="mt-2 rounded-xl overflow-hidden border border-gray-200 bg-gray-50" style="min-height:420px;height:48vh;max-height:560px">'+
      multiMapHTML({id:'mmap_'+key,pins:pins,height:'100%',focus:focus})+'</div>';
  }
  /* Sun & shadows map — always shown when the focused / survey site has GPS */
  var shadeBlock='';
  var shLat=(focL&&typeof focL.lat==='number')?focL.lat:(typeof s.lat==='number'?s.lat:null);
  var shLng=(focL&&typeof focL.lng==='number')?focL.lng:(typeof s.lng==='number'?s.lng:null);
  if(shLat==null||shLng==null){
    for(var _pi=0;_pi<pins.length;_pi++){
      if(typeof pins[_pi].lat==='number'&&typeof pins[_pi].lng==='number'){
        shLat=pins[_pi].lat;shLng=pins[_pi].lng;break;}}
  }
  if(shLat!=null&&shLng!=null){
    var _stz=(focL&&focL.tz)||s.tz||(act&&act.tz)||museTzGuess(shLat,shLng);
    shadeBlock='<div class="'+(multiVenue?'mt-3':'mt-2')+'">'+
      '<p class="text-[9px] font-bold uppercase tracking-wider text-gray-500 mb-1.5">Sun &amp; shadows — '+(focL?esc(focL.name):(act?esc(act.name):esc(s.address||'Survey site')))+'</p>'+
      museShadeBox({id:'survshade_'+key,lat:shLat,lng:shLng,zoom:16,tz:_stz,label:(focL?focL.name:(act?act.name:(s.address||'Survey site'))),height:'320px'})+
    '</div>';}
  else{
    shadeBlock='<div class="mt-2 rounded-xl border border-dashed border-gray-200 bg-gray-50 px-4 py-8 text-center">'+
      '<p class="text-[11px] text-gray-500">No GPS for sun &amp; shadows yet — set coordinates on the site below, or add a location with lat/lng.</p></div>';
  }
  var rows=survMapRowsHTML(key);
  var shown=pins.filter(function(pp){return !pp.hidden;}).length;
  return '<div class="bg-white rounded-2xl p-4 sm:p-5 border border-gray-200/60" style="box-shadow:0 4px 20px rgba(0,0,0,.03)">'+
    '<div class="flex flex-wrap items-center justify-between gap-2 mb-3">'+
      '<div><h4 class="text-[10px] font-bold uppercase tracking-wider text-gray-600">Location &amp; Map'+(locs.length?' <span class="text-gray-400 font-normal normal-case">— '+locs.length+' site'+(locs.length===1?'':'s')+(multiVenue?' · '+shown+' pinned':'')+'</span>':'')+'</h4>'+
      '<p class="text-[9px] text-gray-400 mt-0.5">'+(multiVenue
        ?'Multi-venue map below (pick a site to focus). Sun &amp; shadows tracks the focused venue. Overview still shows the primary pin.'
        :'Primary venue map is on Overview. Here: sun &amp; shadows for this site. Add a second location to unlock the multi-venue map.')+'</p></div>'+
      '<button onclick="survLocFormToggle(\''+key+'\')" class="text-[9px] font-bold text-blue-700 border border-blue-200 bg-blue-50 rounded-lg px-2.5 py-1.5 hover:bg-blue-100">+ Add location</button></div>'+
    survMapAddFormHTML(key)+
    (multiVenue?venueSel:'')+
    mapBlock+
    shadeBlock+
    (rows?'<div class="mt-3" id="survMapRows_'+key+'">'+rows+'</div>':'')+
    survMapSiteEditorHTML(key,s,act)+
  '</div>';}
/* location list rows — split out of surveyMapHTML so the dropdown can repaint just this strip */
function survMapRowsHTML(key){
  var p=productions[key];var locs=(p&&p.locations&&p.locations.length)?p.locations:[];
  if(!locs.length)return '';
  var act=(typeof activeLocation==='function')?activeLocation(key):null;
  var hide=survMapHide[key]||{};var focus=survMapFocusOf(key);
  return locs.map(function(L){var on=act&&act.id===L.id;var hidden=!!hide[L.id];var noPos=(typeof L.lat!=='number'||typeof L.lng!=='number');
    var shown=(focus===L.id);
    return '<div class="flex items-start gap-2 py-2 border-t border-gray-100 '+(hidden?'opacity-50':'')+(shown?' bg-amber-50/50 rounded-lg':'')+'">'+
      '<button onclick="survMapToggle(\''+key+'\',\''+L.id+'\')" title="'+(hidden?'Show pin on map':'Hide pin from map')+'" class="flex-shrink-0 mt-0.5 text-[13px] leading-none '+(hidden?'text-gray-300':'text-gray-600')+'">'+(hidden?'◌':'◉')+'</button>'+
      '<span class="w-2.5 h-2.5 rounded-full flex-shrink-0 mt-1" style="background:'+(on?'#e41e3f':'#0866ff')+'"></span>'+
      '<div class="min-w-0 flex-1">'+
        '<div class="flex items-center gap-2 flex-wrap"><p class="text-[11px] font-bold text-gray-900">'+(L.flag||'📍')+' '+esc(L.name)+'</p>'+
          '<span class="text-[9px] text-gray-500">'+esc(L.city||'')+'</span>'+
          (L.role?'<span class="text-[8px] font-bold uppercase tracking-wider text-gray-400">'+esc(L.role)+'</span>':'')+
          (noPos?'<span class="text-[8px] font-bold text-amber-600">no GPS — not on map</span>':'<span class="text-[8px] mono text-gray-400">'+L.lat.toFixed(4)+', '+L.lng.toFixed(4)+'</span>')+
          (noPos?'':(shown?'<span class="text-[8px] font-bold uppercase tracking-wider text-amber-600">◎ on map</span>'
            :'<button onclick="survMapPick(\''+key+'\',\''+L.id+'\')" class="text-[8px] font-bold text-amber-700 hover:underline">show on map</button>'))+
          (on?'<span class="text-[8px] font-bold uppercase tracking-wider text-red-600">● active</span>'
            :'<button onclick="setActiveLoc(\''+key+'\',\''+L.id+'\')" class="text-[8px] font-bold text-blue-700 hover:underline">make active →</button>')+'</div>'+
        '<div class="mt-1">'+museRichBox({id:'slocn_'+key+'_'+L.id,value:L.notes||'',toolbar:'slim',height:'54px',placeholder:'Site notes — access, compound, parking, contacts…',onchange:'function(v){survLocNote(\''+key+'\',\''+L.id+'\',v)}'})+'</div>'+
      '</div></div>';}).join('');}
function survMapAddFormHTML(key){
  var tzOpts=NP_TZS.map(function(o){return '<option value="'+o[0]+'">'+o[1]+'</option>';}).join('');
  return '<div id="slocForm_'+key+'" style="display:none" class="border border-blue-200 bg-blue-50/40 rounded-xl p-3 mt-2">'+
    '<p class="text-[9px] font-bold uppercase tracking-wider text-blue-700 mb-2">New Location</p>'+
    '<div class="grid grid-cols-2 sm:grid-cols-3 gap-1.5 mb-1.5">'+
      '<input id="slocName_'+key+'" placeholder="Site name *" class="text-[11px] border border-gray-300 rounded-lg px-2 py-1.5 col-span-2 sm:col-span-1" style="outline:none">'+
      '<input id="slocVenue_'+key+'" placeholder="Venue / address" class="text-[11px] border border-gray-300 rounded-lg px-2 py-1.5" style="outline:none">'+
      '<input id="slocCity_'+key+'" placeholder="City" class="text-[11px] border border-gray-300 rounded-lg px-2 py-1.5" style="outline:none">'+
      '<input id="slocLat_'+key+'" placeholder="Latitude" class="text-[11px] mono border border-gray-300 rounded-lg px-2 py-1.5" style="outline:none">'+
      '<input id="slocLng_'+key+'" placeholder="Longitude" class="text-[11px] mono border border-gray-300 rounded-lg px-2 py-1.5" style="outline:none">'+
      '<select id="slocTz_'+key+'" class="text-[10px] border border-gray-300 rounded-lg px-1.5 py-1.5 bg-white" style="outline:none">'+tzOpts+'</select>'+
    '</div>'+
    '<div class="flex items-center gap-2">'+
      '<input id="slocRole_'+key+'" placeholder="Role (e.g. IBC · Broadcast Hub, Semifinal venue…)" class="flex-1 text-[11px] border border-gray-300 rounded-lg px-2 py-1.5" style="outline:none">'+
      '<button onclick="survLocAdd(\''+key+'\')" class="text-[10px] font-bold text-white bg-gray-900 rounded-lg px-3 py-2 hover:bg-gray-800 flex-shrink-0">+ Add location</button></div>'+
    '<p class="text-[8px] text-gray-400 mt-1.5">Known venues auto-fill GPS from the name; otherwise enter coordinates. Each location gets its own survey, gallery, log &amp; departments.</p></div>';}
function survMapSiteEditorHTML(key,s,act){
  return '<div class="mt-3 space-y-2">'+
    '<p class="text-[9px] font-bold uppercase tracking-wider text-gray-500">'+(act?('Active site — '+esc(act.name)):'Site position')+'</p>'+
    '<div><label class="text-[8px] font-bold uppercase tracking-wider text-gray-400 block mb-0.5">Search venue / address <span class="text-gray-300 normal-case font-normal">— drops the pin, GPS &amp; shadows</span></label>'+museGeoBox('survgeo:'+key,'Search a venue or address — SoFi Stadium, Meta NYC…',true)+'</div>'+
    '<div><label class="text-[8px] font-bold uppercase tracking-wider text-gray-400 block mb-0.5">Address / Venue</label>'+
      '<input value="'+esc(s.address||'').replace(/"/g,'&quot;')+'" onchange="surveySetAddress(\''+key+'\',this.value)" placeholder="Street, city, venue" class="w-full text-[11px] border border-gray-200 rounded-lg px-2.5 py-1.5" style="outline:none"></div>'+
    '<div class="grid grid-cols-2 gap-2">'+
      '<div><label class="text-[8px] font-bold uppercase tracking-wider text-gray-400 block mb-0.5">Latitude</label><input value="'+(s.lat!=null?s.lat:'')+'" onchange="surveySetGPS(\''+key+'\',\'lat\',this.value)" placeholder="lat" class="w-full text-[11px] mono border border-gray-200 rounded-lg px-2.5 py-1.5" style="outline:none"></div>'+
      '<div><label class="text-[8px] font-bold uppercase tracking-wider text-gray-400 block mb-0.5">Longitude</label><input value="'+(s.lng!=null?s.lng:'')+'" onchange="surveySetGPS(\''+key+'\',\'lng\',this.value)" placeholder="lng" class="w-full text-[11px] mono border border-gray-200 rounded-lg px-2.5 py-1.5" style="outline:none"></div>'+
    '</div>'+
    '<div class="flex items-center justify-between pt-1"><span class="text-[10px] mono text-gray-500">GPS: '+((s.lat!=null&&s.lng!=null)?(s.lat.toFixed(4)+', '+s.lng.toFixed(4)):'Not set')+'</span>'+
      '<a href="'+gmapsLink(s)+'" target="_blank" rel="noopener" class="text-[10px] font-bold text-blue-700 hover:underline">Open in Maps →</a></div>'+
  '</div>';}
