function saveComms(){try{localStorage.setItem('muselive_comms_v1',JSON.stringify(comms));}catch(e){}}
function loadComms(){try{var r=localStorage.getItem('muselive_comms_v1');if(r){var l=JSON.parse(r);if(Array.isArray(l))comms=l;}}catch(e){}}
var _commsLoaded=false;function loadCommsOnce(){if(_commsLoaded)return;_commsLoaded=true;loadComms();}
/* ---- link-target resolution: human label for a (type,id) ---- */
function commsLinkLabel(t,id){
  if(t==='production')return (productions[id]&&productions[id].name)||id;
  if(t==='po'){var po=(typeof finPOs!=='undefined')&&finPOs.filter(function(x){return x.id===id;})[0];return po?po.id+' · '+po.vendor:id;}
  if(t==='wo'){var w=(typeof workOrders!=='undefined')&&workOrders.filter(function(x){return x.id===id;})[0];return w?w.id+' · '+(w.desc||'').slice(0,30):id;}
  if(t==='inv'){var iv=(typeof finInvoices!=='undefined')&&finInvoices.filter(function(x){return x.id===id;})[0];return iv?iv.id+' · '+iv.vendor:id;}
  if(t==='eng'){var e=(typeof engById==='function')&&engById(id);return e?e.id+' · '+e.name:id;}
  if(t==='npc'){var n=(typeof npcById==='function')&&npcById(id);return n?n.id+' · '+n.title:id;}
  if(t==='account')return 'Account · '+id;
  return id;
}
function commsLinkIcon(t){return {production:'🎬',po:'📄',wo:'🛠',inv:'💵',eng:'🎥',npc:'🏛',account:'🔑'}[t]||'🔗';}
function commsLinkGo(t,id){closeCommsMsg();
  if(t==='production'){openProject(id);return;}
  if(t==='eng'){switchView('engrequests');setTimeout(function(){if(typeof engById==='function'&&engById(id)&&!engIsLocked(engById(id)))openEngModal(id);},150);return;}
  if(t==='npc'){switchView('schedule');setTimeout(function(){if(typeof openNPCEvent==='function')openNPCEvent(id);},150);return;}
  // finance docs
  var pmap={po:'po',wo:'wo',inv:'inv'};if(pmap[t]){var rec=commsFindFin(t,id);var prod=rec?rec.prod:order[0];if(productions[prod]){projSubTab[prod]='finance';switchView(prod);setTimeout(function(){try{openFinDoc(t,id);}catch(e){}},160);}return;}
}
function commsFindFin(t,id){var arr=t==='po'?finPOs:(t==='wo'?workOrders:finInvoices);for(var i=0;i<arr.length;i++)if(arr[i].id===id)return arr[i];return null;}

/* ---- counts / badges ---- */
/* unread inbound messages flagged critical — the only Omni count that drives a badge */
function commsUnreadCritical(){try{loadCommsOnce();var vis=(typeof permComms==='function')?permComms():comms;return vis.filter(function(m){return !m.read&&m.dir==='in'&&m.priority==='critical';}).length;}catch(e){return 0;}}
function commsUnread(){loadCommsOnce();var vis=(typeof permComms==='function')?permComms():comms;return vis.filter(function(m){return !m.read&&m.dir==='in';}).length;}
function commsForRecord(t,id){loadCommsOnce();var vis=(typeof permComms==='function')?permComms():comms;return vis.filter(function(m){return m.linkType===t&&m.linkId===id;}).sort(function(a,b){return (a.ts<b.ts?-1:1);});}
function omniTabBadge(key){loadCommsOnce();var _oc=(typeof permComms==='function')?permComms():comms;var n=_oc.filter(function(m){return m.prod===key&&!m.read&&m.dir==='in';}).length;
  if(!n)return '';
  return typeof museBadgeHTML==='function'?museBadgeHTML(n):'';}
function commsNavBadge(){var n=commsUnread();var el=document.getElementById('commsNavBadge');if(el)el.innerHTML=typeof museBadgeHTML==='function'?museBadgeHTML(n):'';}

/* ---- channel chip ---- */
function commsChannelChip(ch){
  if(ch==='toc')return '<span class="inline-flex items-center gap-1 text-[8px] font-bold px-1.5 py-0.5 rounded" style="background:#fde7ea;color:#b3122e;border:1px solid #fde7ea"><span style="width:7px;height:7px;border-radius:1px;background:#b3122e;display:inline-block"></span>TOC</span>';
  return ch==='teams'?
  '<span class="inline-flex items-center gap-1 text-[8px] font-bold px-1.5 py-0.5 rounded" style="background:#e7f3ff;color:#0a58ca"><span style="width:7px;height:7px;border-radius:2px;background:#0866ff;display:inline-block"></span>Teams</span>':
  '<span class="inline-flex items-center gap-1 text-[8px] font-bold px-1.5 py-0.5 rounded" style="background:#e7f3ff;color:#0a58ca"><span style="width:7px;height:7px;border-radius:2px;background:#0a58ca;display:inline-block"></span>Outlook</span>';}
/* priority pill — drives the high-stakes operational feel */
function commsPriorityPill(pr){
  if(pr==='critical')return '<span class="inline-flex items-center gap-1 text-[7px] font-bold uppercase tracking-wider px-1.5 py-0.5 rounded" style="background:var(--live-red);color:#ffffff">● Critical</span>';
  if(pr==='high')return '<span class="inline-flex items-center gap-1 text-[7px] font-bold uppercase tracking-wider px-1.5 py-0.5 rounded" style="background:#fff0e5;color:#b24a00;border:1px solid #fbc6a4">▲ High</span>';
  return '';}
function commsChannelName(ch){return ch==='toc'?'TOC Alert':(ch==='teams'?'Teams':'Outlook');}

/* ================= UNIFIED COMMS VIEW ================= */
var commsFilter={channel:'all',q:'',linkType:'all',status:'all'};
function setCommsFilter(field,val){commsFilter[field]=(commsFilter[field]===val&&field!=='q')?'all':val;renderComms();}
function renderComms(){
  loadCommsOnce();commsNavBadge();
  var vis=(typeof permComms==='function')?permComms():comms; // role-scoped message set (Work Item 1)
  // channel filter button states (now includes TOC)
  ['all','email','teams','toc'].forEach(function(c){var b=document.getElementById('cf_'+c);if(!b)return;
    var on=(commsFilter.channel===c);
    b.className='text-[10px] font-bold px-2.5 py-1 rounded-md '+(on?'bg-white shadow-sm text-gray-900':'text-gray-500 hover:text-gray-700');});
  // status tab states (Inbox / Unread / Starred / Sent)
  ['all','unread','critical','sent'].forEach(function(c){var b=document.getElementById('cs_'+c);if(!b)return;
    var on=(commsFilter.status===c);
    b.className='text-[10px] font-bold px-2.5 py-1 rounded-md '+(on?'bg-white shadow-sm text-gray-900':'text-gray-500 hover:text-gray-700');});
  var host=document.getElementById('commsBody');if(!host)return;
  var stats=document.getElementById('commsStats');
  var total=vis.length,unread=commsUnread();
  var emailN=vis.filter(function(m){return m.channel==='email';}).length;
  var teamsN=vis.filter(function(m){return m.channel==='teams';}).length;
  var tocN=vis.filter(function(m){return m.channel==='toc';}).length;
  var critN=vis.filter(function(m){return m.priority==='critical'&&!m.read&&m.dir==='in';}).length;
  if(stats)stats.textContent=total+' messages · '+unread+' unread · '+emailN+' Outlook · '+teamsN+' Teams · '+tocN+' TOC';
  // ---- operational stat band ----
  var band=document.getElementById('commsStatBand');
  if(band){
    function tile(lbl,val,tone){return '<div class="rounded-xl border p-2.5 text-center '+tone+'"><div class="text-lg font-bold leading-none">'+val+'</div><div class="text-[8px] font-bold uppercase tracking-wider mt-1 opacity-70">'+lbl+'</div></div>';}
    var openThreads=Object.keys((function(){var t={};vis.forEach(function(m){if(!m.read&&m.dir==='in')t[m.thread||m.id]=1;});return t;})()).length;
    band.innerHTML=
      tile('Critical',critN,critN?'bg-red-50 border-red-200 text-red-700':'bg-white border-gray-200 text-gray-400')+
      tile('Unread',unread,unread?'bg-blue-50 border-blue-200 text-blue-700':'bg-white border-gray-200 text-gray-400')+
      tile('Open Threads',openThreads,'bg-white border-gray-200 text-gray-700')+
      tile('TOC Alerts',tocN,'bg-white border-gray-200 text-gray-700')+
      tile('Total',total,'bg-white border-gray-200 text-gray-700');
  }
  // ---- critical alert banner ----
  var alertHost=document.getElementById('commsAlertHost');
  if(alertHost){
    var crits=vis.filter(function(m){return m.priority==='critical'&&!m.read&&m.dir==='in';}).sort(function(a,b){return a.ts<b.ts?1:-1;});
    if(crits.length){
      alertHost.innerHTML='<div class="rounded-2xl border p-3 mb-1" style="background:#fde7ea;border-color:var(--live-red-border)"><div class="flex items-center gap-2 mb-2"><span class="attn-badge" style="width:8px;height:8px;border-radius:2px;background:var(--live-red);display:inline-block"></span><h3 class="text-[11px] font-bold uppercase tracking-wider" style="color:var(--live-red)">'+crits.length+' Critical '+(crits.length>1?'Alerts':'Alert')+' — Action Required</h3></div>'+
        crits.map(function(m){return '<button onclick="openCommsThread(\''+(m.thread||m.id)+'\')" class="w-full text-left flex items-center gap-2 bg-white border rounded-lg px-3 py-2 mb-1.5 hover:shadow-sm" style="border-color:var(--live-red-border)">'+commsChannelChip(m.channel)+'<div class="min-w-0 flex-1"><p class="text-[11px] font-bold text-gray-900 truncate">'+esc(m.subject||m.from)+'</p><p class="text-[9px] text-gray-500 truncate">'+esc(m.from)+' · '+esc(commsLinkLabel(m.linkType,m.linkId))+'</p></div><span class="text-[9px] font-bold flex-shrink-0" style="color:var(--live-red)">Review →</span></button>';}).join('')+'</div>';
    }else alertHost.innerHTML='';
  }
  // filters
  var q=(commsFilter.q||'').toLowerCase();
  var list=vis.filter(function(m){
    if(commsFilter.channel!=='all'&&m.channel!==commsFilter.channel)return false;
    if(commsFilter.linkType!=='all'&&m.linkType!==commsFilter.linkType)return false;
    if(commsFilter.status==='unread'&&!(!m.read&&m.dir==='in'))return false;
    if(commsFilter.status==='critical'&&m.priority!=='critical')return false;
    if(commsFilter.status==='sent'&&m.dir!=='out')return false;
    if(q){var hay=(m.from+' '+m.to+' '+m.subject+' '+museRichPlain(m.body)+' '+commsLinkLabel(m.linkType,m.linkId)).toLowerCase();if(hay.indexOf(q)<0)return false;}
    return true;}).sort(function(a,b){return (a.ts<b.ts?1:-1);});
  // group into threads
  var threads={};list.forEach(function(m){(threads[m.thread||m.id]=threads[m.thread||m.id]||[]).push(m);});
  // sort threads: unread-critical first, then unread, then recency
  var prRank={critical:0,high:1,normal:2};
  function threadScore(msgs){var last=msgs[msgs.length-1];var unreadCt=msgs.filter(function(m){return !m.read&&m.dir==='in';}).length;
    var topPr=Math.min.apply(null,msgs.map(function(m){return prRank[m.priority]!==undefined?prRank[m.priority]:2;}));
    return {unread:unreadCt,pr:topPr,ts:last.ts};}
  var tkeys=Object.keys(threads).sort(function(a,b){var sa=threadScore(threads[a]),sb=threadScore(threads[b]);
    if((sa.unread>0)!==(sb.unread>0))return sa.unread>0?-1:1;
    if(sa.unread>0&&sa.pr!==sb.pr)return sa.pr-sb.pr;
    return sa.ts<sb.ts?1:-1;});
  var rows=tkeys.map(function(tk){var msgs=threads[tk].sort(function(a,b){return a.ts<b.ts?-1:1;});var last=msgs[msgs.length-1];
    var unreadCt=msgs.filter(function(m){return !m.read&&m.dir==='in';}).length;
    var topPr=msgs.reduce(function(acc,m){return (prRank[m.priority]<prRank[acc])?m.priority:acc;},'normal');
    var leftBar=topPr==='critical'?'border-l-2':'';var leftCol=topPr==='critical'?'border-color:var(--live-red)':'';
    return '<button onclick="openCommsThread(\''+tk+'\')" class="w-full text-left flex items-start gap-3 p-3 rounded-xl border '+leftBar+' '+(unreadCt?'border-blue-200 bg-blue-50/30':'border-gray-100')+' hover:border-blue-300 hover:bg-blue-50/40 transition-all" style="'+leftCol+'">'+
      '<div class="flex flex-col items-center gap-1 flex-shrink-0 pt-0.5">'+commsChannelChip(last.channel)+(unreadCt?'<span class="text-[7px] font-bold text-white bg-red-500 rounded-full px-1.5">'+unreadCt+' new</span>':'')+'</div>'+
      '<div class="min-w-0 flex-1">'+
        '<div class="flex items-center justify-between gap-2"><div class="flex items-center gap-1.5 min-w-0"><p class="text-[12px] font-bold text-gray-900 truncate">'+esc(last.subject||(commsChannelName(last.channel)+' · '+last.from))+'</p>'+commsPriorityPill(topPr)+'</div><span class="text-[8px] mono text-gray-400 flex-shrink-0">'+esc(last.ts)+'</span></div>'+
        '<p class="text-[10px] text-gray-600 truncate">'+esc(last.dir==='out'?'You → '+last.to:last.from)+' · '+esc((last.body||'').slice(0,70))+'</p>'+
        '<div class="flex items-center gap-1.5 mt-1 flex-wrap"><span class="text-[8px] mono px-1.5 py-0.5 rounded bg-gray-100 border border-gray-200 text-gray-600">'+commsLinkIcon(last.linkType)+' '+esc(commsLinkLabel(last.linkType,last.linkId))+'</span>'+(msgs.length>1?'<span class="text-[8px] mono text-gray-400">'+msgs.length+' in thread</span>':'')+'</div>'+
      '</div></button>';
  }).join('')||'<div class="text-center py-10 text-[11px] text-gray-400">No messages match. <button onclick="setCommsFilter(\'channel\',\'all\');setCommsFilter(\'linkType\',\'all\');document.getElementById(\'commsSearch\').value=\'\';setCommsSearchVal(\'\')" class="text-blue-700 font-bold hover:underline">Clear filters</button></div>';
  host.innerHTML=rows;
}
function setCommsSearchVal(v){commsFilter.q=v;renderComms();}

/* thread detail modal */
function openCommsThread(tk){loadCommsOnce();
  var pool=(typeof permComms==='function')?permComms():comms;
  var msgs=pool.filter(function(m){return (m.thread||m.id)===tk;}).sort(function(a,b){return a.ts<b.ts?-1:1;});
  if(!msgs.length){if(comms.some(function(m){return (m.thread||m.id)===tk;}))toast('🔒 This thread is not visible to your role');return;}msgs.forEach(function(m){if(m.dir==='in')m.read=true;});saveComms();commsNavBadge();
  var ov=document.getElementById('commsMsgOverlay');var bx=document.getElementById('commsMsgBox');if(!ov||!bx)return;
  var head=msgs[0];
  var bubbles=msgs.map(function(m){var out=m.dir==='out';
    return '<div class="flex '+(out?'justify-end':'justify-start')+'"><div class="max-w-[80%] '+(out?'rounded-2xl rounded-br-sm':'rounded-2xl rounded-bl-sm')+' px-3 py-2 text-xs" style="'+(out?'background:#0866FF;color:#fff':'background:#F0F2F5;color:#050505')+'">'+
      '<div class="flex items-center gap-2 mb-1"><span class="text-[9px] font-bold '+(out?'text-blue-100':'text-gray-500')+'">'+esc(out?'You':m.from)+'</span>'+commsChannelChip(m.channel)+'<span class="text-[8px] mono '+(out?'text-blue-200':'text-gray-400')+'">'+esc(m.ts)+'</span></div>'+
      (m.subject&&!out?'<p class="text-xs font-bold mb-1">'+esc(m.subject)+'</p>':'')+
      museRichView(m.body,'text-xs leading-relaxed'+(out?' rt-on-dark':''))+'</div></div>';
  }).join('');
  bx.innerHTML='<div class="flex items-center justify-between px-4 py-3 border-b border-gray-200 bg-white flex-shrink-0">'+
      '<div class="min-w-0"><div class="flex items-center gap-2 flex-wrap"><h3 class="text-sm font-bold text-gray-900 truncate">'+esc(head.subject||(commsChannelName(head.channel)+' thread · '+head.from))+'</h3>'+commsPriorityPill(msgs.reduce(function(acc,m){var r={critical:0,high:1,normal:2};return (r[m.priority]<r[acc])?m.priority:acc;},'normal'))+'</div>'+
      '<button onclick="commsLinkGo(\''+head.linkType+'\',\''+head.linkId+'\')" class="text-[10px] font-bold text-blue-700 hover:underline">'+commsLinkIcon(head.linkType)+' Linked to '+esc(commsLinkLabel(head.linkType,head.linkId))+' →</button></div>'+
      '<button onclick="closeCommsMsg()" class="text-gray-400 hover:text-gray-700 text-lg leading-none flex-shrink-0 ml-2">✕</button></div>'+
    '<div class="overflow-y-auto flex-1 p-4 space-y-3">'+bubbles+'</div>'+
    (head.channel==='toc'?
      '<div class="p-3 border-t border-gray-100 flex-shrink-0"><div class="flex items-center justify-center gap-2 text-[10px] text-gray-500 bg-gray-50 rounded-xl py-2.5"><span style="width:7px;height:7px;border-radius:1px;background:var(--live-red);display:inline-block"></span>System-generated TOC alert · acknowledge in the linked record</div></div>':
      '<div class="p-3 border-t border-gray-100 flex-shrink-0 flex items-center gap-2">'+
        '<button onclick="closeCommsMsg();openCompose(\''+head.linkType+'\',\''+head.linkId+'\',\''+(head.channel)+'\',\''+esc(head.thread||head.id)+'\')" class="flex-1 bg-gray-900 text-white text-xs font-bold rounded-xl py-2.5 hover:bg-gray-800">Reply</button>'+
        (head.channel==='email'?'<a href="'+commsOutlookLink(head)+'" target="_blank" class="text-[10px] font-bold text-blue-700 border border-blue-200 rounded-xl px-3 py-2.5 hover:bg-blue-50">Open in Outlook ↗</a>':
          '<a href="'+commsTeamsLink(head)+'" target="_blank" class="text-[10px] font-bold text-indigo-700 border border-indigo-200 rounded-xl px-3 py-2.5 hover:bg-indigo-50">Open in Teams ↗</a>')+
      '</div>');
  ov.style.display='flex';
  if(document.querySelector('.view-pane.active')&&document.querySelector('.view-pane.active').id==='view-comms')renderComms();
}
function closeCommsMsg(){var ov=document.getElementById('commsMsgOverlay');if(ov)ov.style.display='none';}

/* deep links */
function commsOutlookLink(m){var to=encodeURIComponent(m.dir==='out'?m.to:(m.from.match(/<(.+?)>/)?m.from.match(/<(.+?)>/)[1]:m.from));
  var sub=encodeURIComponent((m.subject&&/^re:/i.test(m.subject)?m.subject:'RE: '+(m.subject||'')));
  return 'https://outlook.office.com/mail/deeplink/compose?to='+to+'&subject='+sub;}
function commsTeamsLink(m){return 'https://teams.microsoft.com/l/chat/0/0?users='+encodeURIComponent('') ;}

/* ================= COMPOSE ================= */
var composeCtx={linkType:'production',linkId:'',channel:'email',thread:null};
function openCompose(linkType,linkId,channel,thread){loadCommsOnce();
  composeCtx={linkType:linkType||'production',linkId:linkId||order[0],channel:channel||'email',thread:thread||null};
  var ov=document.getElementById('composeOverlay');if(!ov)return;
  // populate link selector
  buildComposeLinkOptions();
  document.getElementById('cmp_to').value=composeGuessTo(composeCtx.linkType,composeCtx.linkId);
  document.getElementById('cmp_subject').value=composeCtx.thread?('RE: '+composeThreadSubject(composeCtx.thread)):composeGuessSubject(composeCtx.linkType,composeCtx.linkId);
  museRichFill('cmp_body','','full','130px','Type your message…');
  setComposeChannel(composeCtx.channel);
  ov.style.display='flex';
  setTimeout(function(){try{var rb=_richBoxes['cmp_body'];if(rb&&rb.quill)rb.quill.focus();}catch(e){}},260);
}
function closeCompose(){var ov=document.getElementById('composeOverlay');if(ov)ov.style.display='none';}
function setComposeChannel(ch){composeCtx.channel=ch;
  ['email','teams'].forEach(function(c){var b=document.getElementById('cmpCh_'+c);if(!b)return;
    if(c===ch)b.className='flex-1 text-[10px] font-bold py-2 rounded-lg border-2 border-gray-900 bg-gray-900 text-white';
    else b.className='flex-1 text-[10px] font-bold py-2 rounded-lg border-2 border-gray-200 text-gray-600 hover:border-gray-400';});
  var sw=document.getElementById('cmpSubjectWrap');if(sw)sw.style.display=ch==='teams'?'none':'block';
  var sl=document.getElementById('cmpSendLabel');if(sl)sl.textContent=ch==='teams'?'Log & open in Teams':'Log & open in Outlook';
}
function buildComposeLinkOptions(){
  var tsel=document.getElementById('cmp_linkType');var isel=document.getElementById('cmp_linkId');if(!tsel||!isel)return;
  var types=[['production','Production'],['inv','Invoice'],['po','Purchase Order'],['wo','Work Order'],['eng','ENG Request'],['npc','NPC Event']];
  tsel.innerHTML=types.map(function(t){return '<option value="'+t[0]+'"'+(composeCtx.linkType===t[0]?' selected':'')+'>'+t[1]+'</option>';}).join('');
  buildComposeIdOptions();
}
function buildComposeIdOptions(){
  var t=document.getElementById('cmp_linkType').value;composeCtx.linkType=t;
  var isel=document.getElementById('cmp_linkId');var opts=[];
  if(t==='production')opts=order.map(function(k){return [k,productions[k].name];});
  else if(t==='po'&&typeof finPOs!=='undefined')opts=finPOs.map(function(x){return [x.id,x.id+' · '+x.vendor];});
  else if(t==='wo'&&typeof workOrders!=='undefined')opts=workOrders.map(function(x){return [x.id,x.id+' · '+(x.desc||'').slice(0,30)];});
  else if(t==='inv'&&typeof finInvoices!=='undefined')opts=finInvoices.map(function(x){return [x.id,x.id+' · '+x.vendor];});
  else if(t==='eng'&&typeof engRequests!=='undefined')opts=engRequests.map(function(x){return [x.id,x.id+' · '+x.name];});
  else if(t==='npc'&&typeof npcEvents!=='undefined')opts=npcEvents.map(function(x){return [x.id,x.id+' · '+x.title];});
  isel.innerHTML=opts.map(function(o){return '<option value="'+o[0]+'"'+(composeCtx.linkId===o[0]?' selected':'')+'>'+esc(o[1])+'</option>';}).join('');
  if(opts.length&&opts.map(function(o){return o[0];}).indexOf(composeCtx.linkId)<0)composeCtx.linkId=opts[0][0];
}
function composeGuessTo(t,id){
  if(t==='po'){var po=commsFindFin('po',id);return po&&po.vendorEmail?po.vendorEmail:'vendor@example.com';}
  if(t==='inv'){var iv=commsFindFin('inv',id);return iv&&iv.vendorEmail?iv.vendorEmail:'ap@example.com';}
  if(t==='eng'){return 'crew@meta.com';}
  if(t==='npc'){return 'events@meta.com';}
  return 'team@meta.com';}
function composeGuessSubject(t,id){var lbl=commsLinkLabel(t,id);return lbl+' — ';}
function composeThreadSubject(tk){var m=comms.filter(function(x){return (x.thread||x.id)===tk;})[0];return m?(m.subject||'').replace(/^re:\s*/i,''):'';}
function composeSend(){
  var to=(document.getElementById('cmp_to').value||'').trim();
  var subject=(document.getElementById('cmp_subject').value||'').trim();
  var body=(museRichGet('cmp_body')||'').trim();
  var t=document.getElementById('cmp_linkType').value;var id=document.getElementById('cmp_linkId').value;
  if(!body){toast('Write a message first');return;}
  var ch=composeCtx.channel;
  var nmax=9006;comms.forEach(function(m){var n=parseInt((m.id||'').replace('MSG-',''),10);if(n>nmax)nmax=n;});
  var prod=t==='production'?id:(commsFindFin(t,id)||{}).prod||'';
  var rec={id:'MSG-'+(nmax+1),channel:ch,dir:'out',from:'Rowan Blake',to:to,subject:ch==='teams'?'':subject,body:body,
    ts:nowStamp(),linkType:t,linkId:id,prod:prod,read:true,thread:composeCtx.thread||('T-'+(nmax+1))};
  comms.unshift(rec);saveComms();
  try{logEvent(prod||order[0],'✉ '+(ch==='teams'?'Teams':'Email')+' logged → '+commsLinkLabel(t,id));saveState();}catch(e){}
  // open the external client
  var url;
  if(ch==='email'){url='https://outlook.office.com/mail/deeplink/compose?to='+encodeURIComponent(to)+'&subject='+encodeURIComponent(subject)+'&body='+encodeURIComponent(body);}
  else{url='https://teams.microsoft.com/l/chat/0/0?message='+encodeURIComponent(body);}
  try{window.open(url,'_blank');}catch(e){}
  closeCompose();
  toast('Message logged & '+(ch==='teams'?'Teams':'Outlook')+' opened');
  // refresh any visible comms surfaces
  try{renderComms();}catch(e){}
  var act=document.querySelector('.view-pane.active');if(act){var k=act.id.replace('view-','');if(productions[k]){try{renderProjectView(k);}catch(e){}}}
}

/* ================= PER-RECORD COMMS PANEL (embeddable) ================= */
function commsPanelHTML(linkType,linkId,opts){opts=opts||{};
  loadCommsOnce();var msgs=commsForRecord(linkType,linkId);
  var compact=opts.compact;
  var head='<div class="flex items-center justify-between mb-2"><h4 class="text-[10px] font-bold uppercase tracking-wider text-gray-600">Omni <span class="text-gray-400 font-normal normal-case">— Outlook &amp; Teams</span></h4>'+
    '<div class="flex items-center gap-1.5"><span class="text-[9px] mono text-gray-400">'+msgs.length+' linked</span>'+
    '<button onclick="openCompose(\''+linkType+'\',\''+linkId+'\',\'email\')" class="text-[9px] font-bold text-white bg-gray-900 rounded-lg px-2.5 py-1 hover:bg-gray-800">✉ New</button></div></div>';
  if(!msgs.length){return '<div class="bg-white rounded-2xl p-4 border border-gray-200/60"'+(opts.shadow!==false?' style="box-shadow:0 4px 20px rgba(0,0,0,.03)"':'')+'>'+head+
    '<div class="text-center py-4"><p class="text-[11px] text-gray-400">No linked messages yet. Compose to start a thread tied to this record.</p></div></div>';}
  var rows=msgs.slice(-(compact?3:50)).reverse().map(function(m){var out=m.dir==='out';
    return '<button onclick="openCommsThread(\''+(m.thread||m.id)+'\')" class="w-full text-left flex items-start gap-2 p-2 rounded-lg hover:bg-gray-50 border border-transparent hover:border-gray-200'+(m.priority==='critical'&&!m.read&&!out?' bg-red-50/40':'')+'">'+
      '<div class="flex-shrink-0 pt-0.5">'+commsChannelChip(m.channel)+'</div>'+
      '<div class="min-w-0 flex-1"><div class="flex items-center justify-between gap-2"><div class="flex items-center gap-1.5 min-w-0"><p class="text-[10px] font-bold text-gray-800 truncate">'+esc(out?'You → '+m.to:m.from)+'</p>'+commsPriorityPill(m.priority)+'</div><span class="text-[8px] mono text-gray-400 flex-shrink-0">'+esc(m.ts)+'</span></div>'+
        '<p class="text-[10px] text-gray-600 truncate">'+esc(m.subject?m.subject+' — ':'')+esc(museRichExcerpt(m.body,60))+'</p></div></button>';
  }).join('');
  return '<div class="bg-white rounded-2xl p-4 border border-gray-200/60"'+(opts.shadow!==false?' style="box-shadow:0 4px 20px rgba(0,0,0,.03)"':'')+'>'+head+'<div class="space-y-1">'+rows+'</div></div>';
}

function commsInit(){loadCommsOnce();commsNavBadge();}


/* ---- embedded converted DWG drawings (base64 PNG) + CAD viewer ---- */
var CAD_RENDERS = {"section2":"assets/cad/section2.png","section1":"assets/cad/section1.png","plan6":"assets/cad/plan6.png","football":"assets/cad/football.png","mpk-plan":"assets/cad/mpk-plan.svg","mpk-section":"assets/cad/mpk-section.svg","mpk-power":"assets/cad/mpk-power.svg","mpk-lighting":"assets/cad/mpk-lighting.svg"};
/* ============================================================================
   CAD MARKUP VIEWER — full-screen, high-fidelity annotation layer over the
   rendered site plans. Real HTML5 Canvas engine: pan/zoom, freehand pen,
   highlighter, arrow, line, rectangle, ellipse, text box, sticky note, select/
   move/delete, undo/redo, per-file persistence (localStorage), PNG export.
   Annotation geometry is stored in drawing (image) coordinates so markups stay
   pinned to the plan through pan & zoom; stroke widths / fonts are screen-space
   so they stay legible at every zoom level.
   ========================================================================== */
var cadV={open:false,key:null,planId:null,title:'',img:null,
  ann:[],sel:null,tool:'select',color:'#e41e3f',width:3,
  view:{scale:1,ox:0,oy:0},drag:null,hist:[],hi:-1,dpr:1,
  canvas:null,ctx:null,raf:0,editor:null,
  layer:'general',hiddenLayers:{},scaleFt:null,layersOpen:false};

var CADV_COLORS=['#e41e3f','#f5832a','#1E7B34','#0866ff','#0866ff','#1C1E21','#ffffff'];
/* v29 (Module 4): color-coded markup layers — every annotation belongs to one */
var CADV_LAYERS=[
  ['general','General','#e41e3f'],
  ['camera','Cameras','#0866ff'],
  ['audio','Audio / Comms','#1E7B34'],
  ['rigging','Rigging','#0866ff'],
  ['hazard','Hazards','#f5832a']
];
function cadLayerDef(id){for(var i=0;i<CADV_LAYERS.length;i++)if(CADV_LAYERS[i][0]===id)return CADV_LAYERS[i];return CADV_LAYERS[0];}
var CADV_TOOLS=[
  ['select','Select / Move','M4 3l16 7-6 2-2 6z'],
  ['pan','Pan','M9 11V5a1.5 1.5 0 013 0v5m0-1.5a1.5 1.5 0 013 0V11m0-1a1.5 1.5 0 013 0v4a6 6 0 01-6 6h-1a6 6 0 01-5-3l-2.5-4a1.6 1.6 0 012.7-1.6L9 13'],
  ['pen','Freehand','M3 21l3-1 11-11-2-2L4 18zM15 6l3 3'],
  ['hi','Highlighter','M4 21h6l9-9-4-4-9 9zM13 6l4 4'],
  ['arrow','Arrow','M5 19L19 5M19 5h-7M19 5v7'],
  ['line','Line','M5 19L19 5'],
  ['rect','Rectangle','M4 5h16v14H4z'],
  ['ellipse','Ellipse','M12 5c5 0 9 3 9 7s-4 7-9 7-9-3-9-7 4-7 9-7z'],
  ['text','Text','M5 5h14M12 5v14M9 19h6'],
  ['note','Sticky Note','M5 4h14v10l-5 5H5zM14 19v-5h5'],
  ['measure','Measure distance','M2 16L16 2l6 6L8 22zM7 11l2 2M10 8l2 2M13 5l2 2'],
  ['calib','Calibrate scale (drag a known dimension)','M12 3v3M5.6 5.6l2.1 2.1M3 12h3M18 12h3M16.3 7.7l2.1-2.1M12 21a4 4 0 004-4H8a4 4 0 004 4z'],
  ['distro','Distro / Power source','M13 2L4.5 13H11l-1 9 8.5-11H12z'],
  ['crun','Cable run (click to route)','M4 18c3 0 3-9 8-9s5 9 8 9M3 18h2M19 18h2']
];

/* ---- v29 scale calibration + markup versions (both non-destructive) ---- */
function cadScaleLoad(key,planId){try{var raw=localStorage.getItem('muselive_cadscale');if(!raw)return null;
  var o=JSON.parse(raw);var v=o[cadStoreKey(key,planId)];return (typeof v==='number'&&v>0)?v:null;}catch(e){return null;}}
function cadScaleSave(key,planId,ftPerPx){try{var raw=localStorage.getItem('muselive_cadscale');var o=raw?JSON.parse(raw):{};
  o[cadStoreKey(key,planId)]=ftPerPx;localStorage.setItem('muselive_cadscale',JSON.stringify(o));}catch(e){}}
function cadFmtDist(pxLen){if(cadV.scaleFt){var ft=pxLen*cadV.scaleFt;
    return (ft>=1000?(ft/5280).toFixed(2)+' mi':ft.toFixed(1)+' ft')+'  ·  '+(ft*0.3048).toFixed(1)+' m';}
  return Math.round(pxLen)+' px — calibrate for real units';}
function cadVersionsLoad(){try{var raw=localStorage.getItem('muselive_cadversions');if(!raw)return [];
  var o=JSON.parse(raw);var a=o[cadStoreKey(cadV.key,cadV.planId)];return Array.isArray(a)?a:[];}catch(e){return [];}}
function cadVersionsStore(list){try{var raw=localStorage.getItem('muselive_cadversions');var o=raw?JSON.parse(raw):{};
  o[cadStoreKey(cadV.key,cadV.planId)]=list;localStorage.setItem('muselive_cadversions',JSON.stringify(o));}catch(e){}}
function cadSaveVersion(){if(!cadV.open)return;
  var name=prompt('Name this markup version:','Markup '+nowStamp());if(name==null)return;
  var list=cadVersionsLoad();list.push({name:name||('v'+(list.length+1)),ts:nowStamp(),ann:JSON.parse(JSON.stringify(cadV.ann))});
  if(list.length>12)list.shift();
  cadVersionsStore(list);cadSyncVersions();toast&&toast('Markup version saved — original drawing untouched');}
function cadRestoreVersion(idx){var list=cadVersionsLoad();var v=list[parseInt(idx,10)];if(!v)return;
  if(!confirm('Load markup version "'+v.name+'"? Current markups are replaced (undo works, and you can save them as a version first).'))
    {cadSyncVersions();return;}
  cadV.ann=JSON.parse(JSON.stringify(v.ann));cadV.sel=null;cadCommit();cadSyncVersions();}
function cadSyncVersions(){var sel=document.getElementById('cadvVersions');if(!sel)return;
  var list=cadVersionsLoad();
  sel.innerHTML='<option value="">Versions ('+list.length+')</option>'+list.map(function(v,i){return '<option value="'+i+'">'+esc(v.name)+' · '+esc(v.ts)+'</option>';}).join('');
  sel.value='';}

function cadIcon(d){return '<svg width="17" height="17" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="'+d+'"/></svg>';}

function openCadViewer(key,planId,title,imgSrc){
  var plan=cadPlanById(key,planId);
  /* v42: all plans open in the read-only CadViewer (2D/3D + colored note dots).
     Geometry is never edited. Images/PDF sheets use the same note dots. Wave B: lazy CAD. */
  if(plan){
    if(imgSrc&&!plan.img)plan.img=imgSrc;
    try{museCadOpen(key,plan,title||plan.name||'CAD Plan');return;}catch(e){}
  }
  if(imgSrc){
    var _openImg=function(CV){
      if(!CV||!CV.open){toast&&toast('CAD viewer failed to load');return;}
      CV.open({key:key,planId:planId,title:title||'CAD Plan',img:imgSrc,notes:[],
        onSaveNotes:function(payload){
          var p=cadPlanById(key,planId);if(!p)return;
          p.notes=payload.notes||[];p.cad3d=p.cad3d||{v:1,readOnly:true};p.cad3d.notes=p.notes;
          try{stampEdit(key);renderProjectView(key);}catch(e){}
        }});
    };
    if(typeof CadViewer!=='undefined'&&CadViewer.open){_openImg(CadViewer);return;}
    toast&&toast('Loading CAD engine…');
    if(typeof MuseLazy!=='undefined'&&MuseLazy.ensureCad){
      MuseLazy.ensureCad().then(_openImg).catch(function(){
        museInjectEngine('js/cad-viewer-engine.js','CadViewer',_openImg,'CAD viewer could not load.');
      });
      return;
    }
    museInjectEngine('js/cad-viewer-engine.js','CadViewer',_openImg,'CAD viewer could not load.');
    return;
  }
  toast&&toast('CAD viewer unavailable — pull to refresh');
}
/* raster page (PDF sheet / photo / legacy PNG render) — the v29 behaviour, unchanged */
function cadLoadRaster(imgSrc){
  var im=new Image();
  im.onload=function(){cadV.img=im;cadFit();cadSyncToolbar();cadRender();};
  im.onerror=function(){cadV.img=null;cadRender();};
  im.src=imgSrc;}
function cadPlanById(key,planId){
  var plans=getCadPlans(key);
  for(var i=0;i<plans.length;i++)if(plans[i].id===planId)return plans[i];
  return null;}
/* does this plan carry CAD geometry the read-only viewer can open? */
function cadPlanVectorSource(plan){
  if(!plan)return null;
  if(plan.dxfText)return {kind:'dxf'};
  if(plan.dwgB64)return {kind:'dwg'};
  if(plan.objText)return {kind:'obj'};
  if(plan.stlB64)return {kind:'stl'};
  if(plan.vec)return {kind:'seed'};
  if(plan.cad3d)return {kind:'cad3d'};
  if(plan.img)return {kind:'image'};
  return null;}
function closeCadViewer(){cadSave();cadV.open=false;
  var ov=document.getElementById('cadvOverlay');if(ov)ov.style.display='none';
  document.body.style.overflow='';cadKillEditor();cadStatus('');}

/* ---- persistence ---- */
function cadStoreKey(key,planId){return key+'::'+planId;}
function cadLoad(key,planId){try{var raw=localStorage.getItem('muselive_cadmarkup');if(!raw)return [];
  var o=JSON.parse(raw);var a=o[cadStoreKey(key,planId)];return Array.isArray(a)?a:[];}catch(e){return [];}}
function cadSave(){try{var raw=localStorage.getItem('muselive_cadmarkup');var o=raw?JSON.parse(raw):{};
  o[cadStoreKey(cadV.key,cadV.planId)]=cadV.ann;localStorage.setItem('muselive_cadmarkup',JSON.stringify(o));}catch(e){}}

/* ---- history (undo / redo) ---- */
function cadPushHist(){cadV.hist=cadV.hist.slice(0,cadV.hi+1);cadV.hist.push(JSON.stringify(cadV.ann));
  if(cadV.hist.length>60)cadV.hist.shift();cadV.hi=cadV.hist.length-1;cadSyncToolbar();}
function cadUndo(){if(cadV.hi>0){cadV.hi--;cadV.ann=JSON.parse(cadV.hist[cadV.hi]);cadV.sel=null;cadSave();cadRender();cadSyncToolbar();}}
function cadRedo(){if(cadV.hi<cadV.hist.length-1){cadV.hi++;cadV.ann=JSON.parse(cadV.hist[cadV.hi]);cadV.sel=null;cadSave();cadRender();cadSyncToolbar();}}

/* ---- view transform helpers ---- */
function cadW2S(x,y){return [x*cadV.view.scale+cadV.view.ox, y*cadV.view.scale+cadV.view.oy];}
function cadS2W(x,y){return [(x-cadV.view.ox)/cadV.view.scale, (y-cadV.view.oy)/cadV.view.scale];}
/* the page is either the raster image or the projected vector sheet — both live in
   the same world-pixel space, so everything layered on top is unaffected */
function cadPageSize(){
  if(cadV.img)return [cadV.img.width,cadV.img.height];
  return null;}
function cadFit(){var c=cadV.canvas;if(!c)return;
  var pg=cadPageSize();if(!pg)return;
  var cw=c.clientWidth,ch=c.clientHeight,iw=pg[0],ih=pg[1];
  if(!(iw>0&&ih>0&&cw>0&&ch>0))return;
  var s=Math.min(cw/iw,ch/ih)*0.94;cadV.view.scale=s;
  cadV.view.ox=(cw-iw*s)/2;cadV.view.oy=(ch-ih*s)/2;}
function cadZoom(f,cx,cy){var c=cadV.canvas;if(!c)return;
  if(cx==null){cx=c.clientWidth/2;cy=c.clientHeight/2;}
  var w=cadS2W(cx,cy);var ns=Math.max(0.05,Math.min(40,cadV.view.scale*f));
  cadV.view.scale=ns;cadV.view.ox=cx-w[0]*ns;cadV.view.oy=cy-w[1]*ns;cadRender();}

/* ---- overlay / toolbar construction ---- */
function cadEnsureOverlay(){if(document.getElementById('cadvOverlay'))return;
  var ov=document.createElement('div');ov.id='cadvOverlay';ov.className='cadv-overlay';
  var tools=CADV_TOOLS.map(function(t){return '<button class="cadv-tool" data-tool="'+t[0]+'" title="'+t[1]+'" onclick="cadSetTool(\''+t[0]+'\')">'+cadIcon(t[2])+'</button>';}).join('');
  var swatches=CADV_COLORS.map(function(c){return '<button class="cadv-swatch" data-color="'+c+'" style="background:'+c+'" onclick="cadSetColor(\''+c+'\')"></button>';}).join('');
  ov.innerHTML=
    '<div class="cadv-topbar">'+
      '<div class="cadv-group">'+
        '<span id="cadvTitle" class="cadv-title"></span>'+
        '<span class="cadv-meta">raster sheet · markup layer</span>'+
      '</div>'+
      '<div class="cadv-group cadv-tools">'+tools+'</div>'+
      '<div class="cadv-group">'+
        '<div class="cadv-swatches">'+swatches+'</div>'+
        '<input id="cadvWidth" type="range" min="1" max="14" value="3" class="cadv-range" oninput="cadSetWidth(this.value)" title="Stroke width">'+
      '</div>'+
      '<div class="cadv-group">'+
        '<button class="cadv-btn" onclick="cadUndo()" id="cadvUndo" title="Undo (Ctrl+Z)">'+cadIcon('M9 14L4 9l5-5M4 9h11a5 5 0 010 10h-3')+'</button>'+
        '<button class="cadv-btn" onclick="cadRedo()" id="cadvRedo" title="Redo (Ctrl+Y)">'+cadIcon('M15 14l5-5-5-5M20 9H9a5 5 0 000 10h3')+'</button>'+
        '<button class="cadv-btn" onclick="cadDeleteSel()" title="Delete selected (Del)">'+cadIcon('M5 7h14M9 7V5h6v2M6 7l1 13h10l1-13')+'</button>'+
        '<button class="cadv-btn" onclick="cadClearAll()" title="Clear all markups">Clear</button>'+
      '</div>'+
      '<div class="cadv-group">'+
        '<select id="cadvLayer" onchange="cadSetLayer(this.value)" title="Active markup layer — new markups land here" style="height:32px;background:#242526;color:#ced0d4;border:1px solid #3A3B3C;border-radius:8px;font-size:10px;font-weight:700;padding:0 6px;outline:none;cursor:pointer">'+CADV_LAYERS.map(function(L){return '<option value="'+L[0]+'">'+L[1]+'</option>';}).join('')+'</select>'+
        '<button class="cadv-btn" onclick="cadToggleLayers()" title="Show / hide layers">'+cadIcon('M12 3l9 5-9 5-9-5zM3 13l9 5 9-5')+'</button>'+
        '<select id="cadvVersions" onchange="if(this.value!==\'\')cadRestoreVersion(this.value)" title="Saved markup versions" style="height:32px;max-width:130px;background:#242526;color:#ced0d4;border:1px solid #3A3B3C;border-radius:8px;font-size:10px;font-weight:700;padding:0 6px;outline:none;cursor:pointer"><option value="">Versions (0)</option></select>'+
        '<button class="cadv-btn" onclick="cadSaveVersion()" title="Save current markups as a named version">＋ Ver</button>'+
      '</div>'+
      '<div class="cadv-group">'+
        '<button class="cadv-btn" onclick="cadZoom(1.25)" title="Zoom in">+</button>'+
        '<button class="cadv-btn" onclick="cadZoom(0.8)" title="Zoom out">&minus;</button>'+
        '<button class="cadv-btn" onclick="cadFitR()" title="Fit to screen">Fit</button>'+
        '<button class="cadv-btn" onclick="cadExport()" title="Export annotated PNG">'+cadIcon('M12 3v12m0 0l-4-4m4 4l4-4M5 21h14')+'</button>'+
        '<button class="cadv-btn cadv-close" onclick="closeCadViewer()" title="Close (Esc)">'+cadIcon('M6 6l12 12M18 6L6 18')+'</button>'+
      '</div>'+
    '</div>'+
    '<div class="cadv-stage" id="cadvStage"><canvas id="cadvCanvas"></canvas>'+
      '<div id="cadvLayersPanel" style="display:none;position:absolute;top:10px;right:12px;z-index:6;width:190px;background:rgba(28,30,33,.97);border:1px solid #3A3B3C;border-radius:12px;padding:8px;box-shadow:0 10px 30px rgba(0,0,0,.55)"></div>'+
      '<div id="cadvStatus" style="display:none;position:absolute;left:50%;top:14px;transform:translateX(-50%);z-index:7;font:700 11px -apple-system,BlinkMacSystemFont,Segoe UI,Roboto,Helvetica,Arial,sans-serif;color:#e4e6eb;background:rgba(8,102,255,.94);border-radius:20px;padding:7px 15px;box-shadow:0 6px 22px rgba(0,0,0,.5)"></div>'+
      '<div id="cadvScaleChip" style="position:absolute;left:12px;top:10px;z-index:6;font:700 10px ui-monospace,SFMono-Regular,Menlo,Consolas,monospace;color:#8a8d91;background:rgba(28,30,33,.9);border:1px solid #3A3B3C;border-radius:8px;padding:4px 9px"></div>'+
      '<div class="cadv-hint" id="cadvHint"></div></div>';
  document.body.appendChild(ov);
  cadV.canvas=document.getElementById('cadvCanvas');cadV.ctx=cadV.canvas.getContext('2d');
  cadBindEvents();
  window.addEventListener('resize',function(){if(cadV.open)cadResize();});
}
function cadFitR(){cadFit();cadRender();}
function cadResize(){var c=cadV.canvas,st=document.getElementById('cadvStage');if(!c||!st)return;
  cadV.dpr=window.devicePixelRatio||1;
  c.style.width=st.clientWidth+'px';c.style.height=st.clientHeight+'px';
  c.width=Math.round(st.clientWidth*cadV.dpr);c.height=Math.round(st.clientHeight*cadV.dpr);
  cadRender();}

/* ---- toolbar state sync ---- */
function cadSetTool(t){cadV.tool=t;cadV.sel=null;
  cadSyncToolbar();cadRender();
  var hint={select:'Click a markup to select · drag to move · drag empty space to pan',
    pan:'Drag to pan · scroll to zoom',pen:'Click & drag to draw freehand',
    hi:'Click & drag to highlight',arrow:'Drag from tail to head',line:'Drag to draw a line',
    rect:'Drag to draw a rectangle',ellipse:'Drag to draw an ellipse',
    text:'Click to place a text label',note:'Click to drop a sticky note',
    measure:(cadV.scaleFt?'Drag between two points — distance reads in real units':'Drag between two points — then use ⚖ Calibrate for real units'),
    calib:'Drag along a dimension you KNOW (a doorway, a court line), then enter its real length',
    distro:'Click to drop a power distribution pin (edit specs in the Power pane)',
    crun:'Click to add cable-run waypoints · SPACEBAR to finish (double-click also works · Esc cancels)'}[t]||'';
  var h=document.getElementById('cadvHint');if(h){h.textContent=hint;h.style.opacity='1';
    clearTimeout(cadV._ht);cadV._ht=setTimeout(function(){h.style.opacity='0';},2600);}}
function cadSetColor(c){cadV.color=c;if(cadV.sel){var a=cadFind(cadV.sel);if(a&&a.type!=='note'){a.color=c;cadCommit();}}cadSyncToolbar();}
function cadSetWidth(w){cadV.width=parseInt(w,10)||3;if(cadV.sel){var a=cadFind(cadV.sel);if(a&&'width' in a){a.width=cadV.width;cadCommit();}}}
function cadSyncToolbar(){var ov=document.getElementById('cadvOverlay');if(!ov)return;
  var tb=ov.querySelectorAll('.cadv-tool');for(var i=0;i<tb.length;i++){tb[i].classList.toggle('on',tb[i].getAttribute('data-tool')===cadV.tool);}
  var sw=ov.querySelectorAll('.cadv-swatch');for(var j=0;j<sw.length;j++){sw[j].classList.toggle('on',sw[j].getAttribute('data-color').toLowerCase()===cadV.color.toLowerCase());}
  var u=document.getElementById('cadvUndo'),r=document.getElementById('cadvRedo');
  if(u)u.disabled=(cadV.hi<=0);if(r)r.disabled=(cadV.hi>=cadV.hist.length-1);
  var wd=document.getElementById('cadvWidth');if(wd&&document.activeElement!==wd)wd.value=cadV.width;
  var ls=document.getElementById('cadvLayer');if(ls&&ls.value!==cadV.layer)ls.value=cadV.layer;
  var sc=document.getElementById('cadvScaleChip');if(sc)sc.textContent=cadV.scaleFt?('SCALE  1 px = '+(cadV.scaleFt<0.1?cadV.scaleFt.toFixed(4):cadV.scaleFt.toFixed(2))+' ft'):'NOT CALIBRATED — ⚖ tool sets real-world scale';}

/* ---- v29 layers UI ---- */
function cadSetLayer(id){cadV.layer=id;cadSyncToolbar();}
function cadToggleLayers(){cadV.layersOpen=!cadV.layersOpen;cadSyncLayers();}
function cadLayerToggleVis(id){if(cadV.hiddenLayers[id])delete cadV.hiddenLayers[id];else cadV.hiddenLayers[id]=1;
  if(cadV.sel){var a=cadFind(cadV.sel);if(a&&cadV.hiddenLayers[a.layer||'general'])cadV.sel=null;}
  cadSyncLayers();cadRender();}
function cadSyncLayers(){var p=document.getElementById('cadvLayersPanel');if(!p)return;
  p.style.display=cadV.layersOpen?'block':'none';
  if(!cadV.layersOpen)return;
  var counts={};cadV.ann.forEach(function(a){var l=a.layer||'general';counts[l]=(counts[l]||0)+1;});
  p.innerHTML='<div style="font:800 9px -apple-system,BlinkMacSystemFont,Segoe UI,Roboto,Helvetica,Arial,sans-serif;letter-spacing:.1em;text-transform:uppercase;color:#8a8d91;padding:2px 4px 6px">Markup Layers</div>'+
    CADV_LAYERS.map(function(L){var off=!!cadV.hiddenLayers[L[0]];
      return '<button onclick="cadLayerToggleVis(\''+L[0]+'\')" style="width:100%;display:flex;align-items:center;gap:7px;padding:5px 6px;border:none;background:transparent;border-radius:7px;cursor:pointer;color:#ced0d4;opacity:'+(off?'.4':'1')+'" onmouseover="this.style.background=\'#242526\'" onmouseout="this.style.background=\'transparent\'">'+
        '<span style="width:9px;height:9px;border-radius:50%;background:'+L[2]+';flex-shrink:0"></span>'+
        '<span style="font:600 11px -apple-system,BlinkMacSystemFont,Segoe UI,Roboto,Helvetica,Arial,sans-serif;flex:1;text-align:left">'+L[1]+'</span>'+
        '<span style="font:500 10px ui-monospace,SFMono-Regular,Menlo,Consolas,monospace;color:#65676b">'+(counts[L[0]]||0)+'</span>'+
        '<span style="color:#8a8d91">'+(off?'◌':'◉')+'</span></button>';}).join('');}

/* ---- annotation utilities ---- */
function cadId(){return 'a'+(Date.now().toString(36))+Math.floor(Math.random()*1e4).toString(36);}
function cadFind(id){for(var i=0;i<cadV.ann.length;i++)if(cadV.ann[i].id===id)return cadV.ann[i];return null;}
function cadCommit(){cadSave();cadPushHist();cadRender();}
function cadDeleteSel(){if(cadV.selPower&&typeof cadDeletePower==='function'){cadDeletePower();return;}if(!cadV.sel)return;cadV.ann=cadV.ann.filter(function(a){return a.id!==cadV.sel;});cadV.sel=null;cadCommit();}
function cadClearAll(){if(!cadV.ann.length)return;if(!confirm('Clear all markups on this drawing?'))return;cadV.ann=[];cadV.sel=null;cadCommit();}

/* ---- rendering ---- */
function cadRender(){if(!cadV.open)return;cancelAnimationFrame(cadV.raf);
  cadV.raf=requestAnimationFrame(cadDraw);}
function cadDraw(){var ctx=cadV.ctx,c=cadV.canvas;if(!ctx||!c)return;var dpr=cadV.dpr,vs=cadV.view.scale;
  ctx.setTransform(1,0,0,1,0,0);ctx.clearRect(0,0,c.width,c.height);
  ctx.fillStyle='#18191A';ctx.fillRect(0,0,c.width,c.height);
  ctx.setTransform(vs*dpr,0,0,vs*dpr,cadV.view.ox*dpr,cadV.view.oy*dpr);
  if(cadV.img){ctx.imageSmoothingEnabled=true;
    // white paper behind the drawing
    ctx.fillStyle='#ffffff';ctx.fillRect(0,0,cadV.img.width,cadV.img.height);
    ctx.drawImage(cadV.img,0,0);}
  for(var i=0;i<cadV.ann.length;i++){if(cadV.hiddenLayers[cadV.ann[i].layer||'general'])continue;cadDrawAnn(ctx,cadV.ann[i],vs);}
  if(cadV.drag&&cadV.drag.preview)cadDrawAnn(ctx,cadV.drag.preview,vs);
  if(cadV.sel){var a=cadFind(cadV.sel);if(a)cadDrawSelection(ctx,a,vs);}
  if(typeof cadDrawPower==='function')cadDrawPower(ctx,vs);
}
function cadStroke(ctx,a,vs){ctx.strokeStyle=a.color;ctx.lineWidth=(a.width||2)/vs;ctx.lineJoin='round';ctx.lineCap='round';}
function cadDrawAnn(ctx,a,vs){
  if(a.type==='pen'||a.type==='hi'){if(!a.pts||a.pts.length<1)return;
    ctx.save();if(a.type==='hi'){ctx.globalAlpha=0.32;ctx.lineWidth=(a.width*5)/vs;ctx.strokeStyle=a.color;}else{cadStroke(ctx,a,vs);}
    ctx.lineCap='round';ctx.lineJoin='round';ctx.beginPath();ctx.moveTo(a.pts[0][0],a.pts[0][1]);
    for(var i=1;i<a.pts.length;i++)ctx.lineTo(a.pts[i][0],a.pts[i][1]);
    if(a.pts.length===1){ctx.lineTo(a.pts[0][0]+0.01,a.pts[0][1]);}ctx.stroke();ctx.restore();return;}
  if(a.type==='line'||a.type==='arrow'){cadStroke(ctx,a,vs);ctx.beginPath();ctx.moveTo(a.x1,a.y1);ctx.lineTo(a.x2,a.y2);ctx.stroke();
    if(a.type==='arrow'){var ang=Math.atan2(a.y2-a.y1,a.x2-a.x1);var hl=(10+a.width*2)/vs;
      ctx.beginPath();ctx.moveTo(a.x2,a.y2);ctx.lineTo(a.x2-hl*Math.cos(ang-0.4),a.y2-hl*Math.sin(ang-0.4));
      ctx.moveTo(a.x2,a.y2);ctx.lineTo(a.x2-hl*Math.cos(ang+0.4),a.y2-hl*Math.sin(ang+0.4));ctx.stroke();}return;}
  if(a.type==='measure'||a.type==='calib'){var mc=a.color||'#0866ff';
    ctx.save();ctx.strokeStyle=mc;ctx.lineWidth=Math.max(1.5,(a.width||2))/vs;ctx.setLineDash(a.type==='calib'?[8/vs,5/vs]:[]);
    ctx.beginPath();ctx.moveTo(a.x1,a.y1);ctx.lineTo(a.x2,a.y2);ctx.stroke();ctx.setLineDash([]);
    var mang=Math.atan2(a.y2-a.y1,a.x2-a.x1),tick=7/vs;
    ctx.beginPath();
    ctx.moveTo(a.x1-tick*Math.sin(mang),a.y1+tick*Math.cos(mang));ctx.lineTo(a.x1+tick*Math.sin(mang),a.y1-tick*Math.cos(mang));
    ctx.moveTo(a.x2-tick*Math.sin(mang),a.y2+tick*Math.cos(mang));ctx.lineTo(a.x2+tick*Math.sin(mang),a.y2-tick*Math.cos(mang));
    ctx.stroke();
    var pxLen=Math.sqrt((a.x2-a.x1)*(a.x2-a.x1)+(a.y2-a.y1)*(a.y2-a.y1));
    var lbl=(a.type==='calib')?'calibrating…':cadFmtDist(pxLen);
    var fs=12.5/vs;ctx.font='700 '+fs+'px DM Mono,ui-monospace,monospace';
    var tw=ctx.measureText(lbl).width,pad=5/vs;
    var mx=(a.x1+a.x2)/2,my=(a.y1+a.y2)/2;
    ctx.fillStyle='rgba(24,25,26,.88)';
    ctx.fillRect(mx-tw/2-pad,my-fs-pad*2.2,tw+pad*2,fs+pad*2);
    ctx.strokeStyle=mc;ctx.lineWidth=1/vs;ctx.strokeRect(mx-tw/2-pad,my-fs-pad*2.2,tw+pad*2,fs+pad*2);
    ctx.fillStyle=mc;ctx.textBaseline='top';ctx.fillText(lbl,mx-tw/2,my-fs-pad*1.2);
    ctx.restore();return;}
  if(a.type==='rect'){cadStroke(ctx,a,vs);ctx.strokeRect(a.x,a.y,a.w,a.h);return;}
  if(a.type==='ellipse'){cadStroke(ctx,a,vs);ctx.beginPath();
    ctx.ellipse(a.x+a.w/2,a.y+a.h/2,Math.abs(a.w/2),Math.abs(a.h/2),0,0,Math.PI*2);ctx.stroke();return;}
  if(a.type==='text'){var fs=(a.size||18)/vs;ctx.font='600 '+fs+'px ui-sans-serif,system-ui,Arial';
    ctx.fillStyle=a.color;ctx.textBaseline='top';
    var lines=(a.text||'').split('\n');for(var k=0;k<lines.length;k++)ctx.fillText(lines[k],a.x,a.y+k*fs*1.25);return;}
  if(a.type==='note'){cadDrawNote(ctx,a,vs);return;}
}
function cadDrawNote(ctx,a,vs){var pad=8/vs;ctx.save();
  ctx.shadowColor='rgba(0,0,0,.25)';ctx.shadowBlur=10/vs;ctx.shadowOffsetY=3/vs;
  ctx.fillStyle=a.color||'#f7b928';ctx.fillRect(a.x,a.y,a.w,a.h);ctx.shadowColor='transparent';
  ctx.fillStyle='rgba(0,0,0,.10)';ctx.fillRect(a.x,a.y,a.w,a.h*0.16<14/vs?14/vs:a.h*0.16);
  ctx.fillStyle='#242526';var fs=13/vs;ctx.font='500 '+fs+'px ui-sans-serif,system-ui,Arial';ctx.textBaseline='top';
  var words=(a.text||'').split(/\s+/),line='',yy=a.y+pad+(14/vs),maxw=a.w-pad*2;
  for(var i=0;i<words.length;i++){var test=line?line+' '+words[i]:words[i];
    if(ctx.measureText(test).width>maxw&&line){ctx.fillText(line,a.x+pad,yy);line=words[i];yy+=fs*1.3;}else line=test;}
  if(line)ctx.fillText(line,a.x+pad,yy);ctx.restore();}
function cadDrawSelection(ctx,a,vs){var b=cadBBox(a);if(!b)return;var m=6/vs;
  ctx.save();ctx.strokeStyle='#0866ff';ctx.lineWidth=1.5/vs;ctx.setLineDash([6/vs,4/vs]);
  ctx.strokeRect(b.x-m,b.y-m,b.w+m*2,b.h+m*2);ctx.restore();}

/* ---- geometry / hit-testing ---- */
function cadBBox(a){
  if(a.type==='pen'||a.type==='hi'){if(!a.pts||!a.pts.length)return null;
    var xs=a.pts.map(function(p){return p[0];}),ys=a.pts.map(function(p){return p[1];});
    var x=Math.min.apply(null,xs),y=Math.min.apply(null,ys);return {x:x,y:y,w:Math.max.apply(null,xs)-x,h:Math.max.apply(null,ys)-y};}
  if(a.type==='line'||a.type==='arrow'||a.type==='measure'){var x=Math.min(a.x1,a.x2),y=Math.min(a.y1,a.y2);return {x:x,y:y,w:Math.abs(a.x2-a.x1),h:Math.abs(a.y2-a.y1)};}
  if(a.type==='rect'||a.type==='ellipse'||a.type==='note'){var x2=a.x+(a.w<0?a.w:0),y2=a.y+(a.h<0?a.h:0);return {x:x2,y:y2,w:Math.abs(a.w),h:Math.abs(a.h)};}
  if(a.type==='text'){var fs=(a.size||18);var lines=(a.text||' ').split('\n');var ww=0;
    for(var i=0;i<lines.length;i++)ww=Math.max(ww,lines[i].length*fs*0.55);return {x:a.x,y:a.y,w:ww,h:lines.length*fs*1.25};}
  return null;}
function cadHit(wx,wy){var tol=8/cadV.view.scale;
  for(var i=cadV.ann.length-1;i>=0;i--){var a=cadV.ann[i];if(cadV.hiddenLayers[a.layer||'general'])continue;
    var b=cadBBox(a);if(!b)continue;
    if(wx>=b.x-tol&&wx<=b.x+b.w+tol&&wy>=b.y-tol&&wy<=b.y+b.h+tol)return a;}return null;}

/* ---- event binding ---- */
function cadBindEvents(){var c=cadV.canvas;
  c.addEventListener('pointerdown',cadDown);c.addEventListener('pointermove',cadMove);
  window.addEventListener('pointerup',cadUp);
  c.addEventListener('wheel',function(e){e.preventDefault();var r=c.getBoundingClientRect();
    cadZoom(e.deltaY<0?1.12:0.89,e.clientX-r.left,e.clientY-r.top);},{passive:false});
  c.addEventListener('dblclick',cadDbl);
  document.addEventListener('keydown',function(e){if(!cadV.open)return;
    if(cadV.editor)return;
    /* v30 Module 12: SPACEBAR finishes the in-progress cable run (double-click stays as secondary) */
    if((e.key===' '||e.code==='Space')&&cadV.crunDraft){e.preventDefault();if(typeof cadCrunFinish==='function')cadCrunFinish();return;}
    /* Escape cancels an in-progress cable run before it closes the viewer */
    if(e.key==='Escape'){
      if(typeof cadCrunCancel==='function'&&cadCrunCancel())return;
      closeCadViewer();return;}
    if((e.key==='Delete'||e.key==='Backspace')&&(cadV.sel||cadV.selPower)){e.preventDefault();cadDeleteSel();}
    else if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='z'){e.preventDefault();if(e.shiftKey)cadRedo();else cadUndo();}
    else if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='y'){e.preventDefault();cadRedo();}});
}
function cadEvtW(e){var r=cadV.canvas.getBoundingClientRect();return cadS2W(e.clientX-r.left,e.clientY-r.top);}
function cadDown(e){if(!cadV.open)return;cadV.canvas.setPointerCapture&&cadV.canvas.setPointerCapture(e.pointerId);
  var w=cadEvtW(e),t=cadV.tool;
  if(typeof cadPowerDown==='function'&&cadPowerDown(e,w))return;
  if(t==='text'){cadPlaceText(w[0],w[1]);return;}
  if(t==='note'){cadPlaceNote(w[0],w[1]);return;}
  if(t==='pan'){cadV.drag={mode:'pan',sx:e.clientX,sy:e.clientY,ox:cadV.view.ox,oy:cadV.view.oy};return;}
  if(t==='select'){var hit=cadHit(w[0],w[1]);
    if(hit){cadV.sel=hit.id;if(hit.color)cadV.color=hit.color;cadSyncToolbar();
      cadV.drag={mode:'move',id:hit.id,startW:w,orig:JSON.parse(JSON.stringify(hit))};
      cadRender();return;}
    cadV.sel=null;cadV.drag={mode:'pan',sx:e.clientX,sy:e.clientY,ox:cadV.view.ox,oy:cadV.view.oy};
    cadRender();return;}
  // drawing tools
  if(t==='pen'||t==='hi'){cadV.drag={mode:'draw',preview:{id:cadId(),type:t,layer:cadV.layer,color:cadV.color,width:cadV.width,pts:[[w[0],w[1]]]}};}
  else if(t==='line'||t==='arrow'||t==='measure'||t==='calib'){cadV.drag={mode:'draw',preview:{id:cadId(),type:(t==='calib'?'calib':t),layer:cadV.layer,color:(t==='measure'?'#0866ff':(t==='calib'?'#31a24c':cadV.color)),width:cadV.width,x1:w[0],y1:w[1],x2:w[0],y2:w[1]}};}
  else if(t==='rect'||t==='ellipse'){cadV.drag={mode:'draw',preview:{id:cadId(),type:t,layer:cadV.layer,color:cadV.color,width:cadV.width,x:w[0],y:w[1],w:0,h:0}};}
  cadRender();
}
function cadMove(e){if(!cadV.drag)return;var d=cadV.drag;
  if(typeof cadPowerMove==='function'&&cadPowerMove(cadEvtW(e)))return;
  if(d.mode==='pan'){cadV.view.ox=d.ox+(e.clientX-d.sx);cadV.view.oy=d.oy+(e.clientY-d.sy);cadRender();return;}
  var w=cadEvtW(e);
  if(d.mode==='move'){var a=cadFind(d.id);if(!a)return;var dx=w[0]-d.startW[0],dy=w[1]-d.startW[1];cadShift(a,d.orig,dx,dy);cadRender();return;}
  if(d.mode==='draw'){var p=d.preview;
    if(p.type==='pen'||p.type==='hi'){p.pts.push([w[0],w[1]]);}
    else if(p.type==='line'||p.type==='arrow'||p.type==='measure'||p.type==='calib'){p.x2=w[0];p.y2=w[1];}
    else{p.w=w[0]-p.x;p.h=w[1]-p.y;}cadRender();return;}
}
function cadUp(e){if(!cadV.drag)return;if(typeof cadPowerUp==='function'&&cadPowerUp())return;var d=cadV.drag;cadV.drag=null;
  if(d.mode==='move'){cadCommit();return;}
  if(d.mode==='draw'){var p=d.preview;var ok=true;
    if(p.type==='pen'||p.type==='hi')ok=p.pts.length>1;
    else if(p.type==='line'||p.type==='arrow'||p.type==='measure'||p.type==='calib')ok=(Math.abs(p.x2-p.x1)+Math.abs(p.y2-p.y1))>2/cadV.view.scale;
    else ok=(Math.abs(p.w)+Math.abs(p.h))>3/cadV.view.scale;
    if(p.type==='calib'){ /* calibration drag: never stored — it SETS the plan's scale */
      if(ok){var pxLen=Math.sqrt((p.x2-p.x1)*(p.x2-p.x1)+(p.y2-p.y1)*(p.y2-p.y1));
        var ans=prompt('Real-world length of the line you just drew (in feet):','10');
        var ft=parseFloat(ans);
        if(!isNaN(ft)&&ft>0){cadV.scaleFt=ft/pxLen;cadScaleSave(cadV.key,cadV.planId,cadV.scaleFt);
          toast&&toast('Scale calibrated — 1 px = '+cadV.scaleFt.toFixed(3)+' ft. Measurements now read in real units.');
          cadV.tool='measure';}
        else if(ans!=null){toast&&toast('Calibration needs a number of feet — not changed');}}
      cadSyncToolbar();cadRender();return;}
    if(ok){if(p.type==='rect'||p.type==='ellipse'){if(p.w<0){p.x+=p.w;p.w=-p.w;}if(p.h<0){p.y+=p.h;p.h=-p.h;}}
      cadV.ann.push(p);cadV.sel=p.id;cadCommit();}else cadRender();return;}
}
function cadShift(a,orig,dx,dy){
  if(a.type==='pen'||a.type==='hi'){for(var i=0;i<a.pts.length;i++){a.pts[i][0]=orig.pts[i][0]+dx;a.pts[i][1]=orig.pts[i][1]+dy;}}
  else if(a.type==='line'||a.type==='arrow'||a.type==='measure'){a.x1=orig.x1+dx;a.y1=orig.y1+dy;a.x2=orig.x2+dx;a.y2=orig.y2+dy;}
  else{a.x=orig.x+dx;a.y=orig.y+dy;}}
function cadDbl(e){if(cadV.crunDraft){cadCrunFinish();return;}var w=cadEvtW(e);var hit=cadHit(w[0],w[1]);
  if(hit&&(hit.type==='text'||hit.type==='note')){cadEditText(hit);}}

/* ---- text / sticky note entry (HTML editor overlaid on the canvas) ---- */
function cadKillEditor(){if(cadV.editor){if(cadV.editor.parentNode)cadV.editor.parentNode.removeChild(cadV.editor);cadV.editor=null;}}
function cadShowEditor(sx,sy,val,wpx,onDone){cadKillEditor();
  var ta=document.createElement('textarea');ta.className='cadv-editor';ta.value=val||'';
  ta.style.left=sx+'px';ta.style.top=sy+'px';ta.style.width=(wpx||180)+'px';
  document.getElementById('cadvStage').appendChild(ta);cadV.editor=ta;setTimeout(function(){ta.focus();ta.select();},10);
  function done(commit){var v=ta.value;cadKillEditor();onDone(commit?v:null);}
  ta.addEventListener('keydown',function(ev){ev.stopPropagation();
    if(ev.key==='Enter'&&(ev.ctrlKey||ev.metaKey)){ev.preventDefault();done(true);}
    else if(ev.key==='Escape'){ev.preventDefault();done(false);}});
  ta.addEventListener('blur',function(){done(true);});}
function cadPlaceText(wx,wy){var s=cadW2S(wx,wy);
  cadShowEditor(s[0],s[1],'',200,function(v){if(v&&v.trim()){cadV.ann.push({id:cadId(),type:'text',layer:cadV.layer,color:cadV.color,x:wx,y:wy,text:v.trim(),size:18});cadV.sel=null;cadCommit();}});}
function cadPlaceNote(wx,wy){var w=170,h=120;var s=cadW2S(wx,wy);
  cadShowEditor(s[0],s[1],'',w*cadV.view.scale<150?150:w*cadV.view.scale,function(v){
    cadV.ann.push({id:cadId(),type:'note',layer:cadV.layer,x:wx,y:wy,w:w/cadV.view.scale*cadV.view.scale,h:h/cadV.view.scale*cadV.view.scale,color:'#f7b928',text:(v||'').trim()||'Note'});
    // store note size in world units so it scales with the drawing
    var n=cadV.ann[cadV.ann.length-1];n.w=170/cadV.view.scale;n.h=120/cadV.view.scale;cadV.sel=n.id;cadCommit();});}
function cadEditText(a){var b=cadBBox(a);var s=cadW2S(a.x,a.y);
  cadShowEditor(s[0],s[1],a.text||'',(b&&b.w?b.w*cadV.view.scale:200),function(v){if(v===null)return;
    if(!v.trim()&&a.type==='text'){cadV.ann=cadV.ann.filter(function(x){return x.id!==a.id;});}else a.text=v.trim();cadCommit();});}

/* ---- export annotated PNG ---- */
function cadExport(){if(!cadV.img)return;var oc=document.createElement('canvas');
  oc.width=cadV.img.width;oc.height=cadV.img.height;var x=oc.getContext('2d');
  x.fillStyle='#ffffff';x.fillRect(0,0,oc.width,oc.height);x.drawImage(cadV.img,0,0);
  var savedVS=cadV.view.scale,savedCtx=cadV.ctx;cadV.view.scale=1;cadV.ctx=x;
  x.setTransform(1,0,0,1,0,0);
  for(var i=0;i<cadV.ann.length;i++)cadDrawAnn(x,cadV.ann[i],1);
  cadV.view.scale=savedVS;cadV.ctx=savedCtx;
  try{var url=oc.toDataURL('image/png');var a=document.createElement('a');
    a.href=url;a.download=(cadV.title||'cad-markup').replace(/[^a-z0-9]+/gi,'_')+'.png';a.click();
    toast&&toast('Exported annotated PNG');}catch(e){toast&&toast('Export failed');}}


/* ===== Site Survey expansion: power/electrical/cable, 360, security ===== */
var SAMPLE_PANO='assets/survey/sample-pano.jpg';
/* ============================================================================
   SITE SURVEY — POWER, ELECTRICAL & CABLE RUNS
   Electrician-grade documentation: distribution sources, cable runs with full
   conductor specs, live load totals, NEC 80% continuous-load checks, conductor
   ampacity verification, and copper voltage-drop calculation. Runs can be drawn
   onto the CAD drawings (shared store with the CAD markup viewer).
   ========================================================================== */

// copper conductor resistance (ohms / 1000 ft, ~75C) and 75C THHN ampacity (A)
var AWG_DATA={
  '14':{r:3.14,amp:20},'12':{r:1.98,amp:25},'10':{r:1.24,amp:35},'8':{r:0.778,amp:50},
  '6':{r:0.491,amp:65},'4':{r:0.308,amp:85},'3':{r:0.245,amp:100},'2':{r:0.194,amp:115},
  '1':{r:0.154,amp:130},'1/0':{r:0.122,amp:150},'2/0':{r:0.0967,amp:175},
  '3/0':{r:0.0766,amp:200},'4/0':{r:0.0608,amp:230},'250':{r:0.0515,amp:255},
  '350':{r:0.0367,amp:310},'500':{r:0.0258,amp:380}};
var AWG_LIST=['14','12','10','8','6','4','3','2','1','1/0','2/0','3/0','4/0','250','350','500'];
// common broadcast cable types -> implied conductor AWG
var CABLE_TYPES={
  '4/0 Cam-Lok (single)':'4/0','2/0 Cam-Lok (single)':'2/0','#2 Cam-Lok (single)':'2',
  'Socapex 19-pin (#12)':'12','Bates / Stage-pin 100A (#2)':'2','California 100A (#2)':'2',
  'L21-30 (10/4)':'10','L14-30 (10/3)':'10','12/3 SOOW':'12','10/3 SOOW':'10',
  '8/3 SOOW':'8','6/4 SOOW':'6','powerCON TRUE1 (12/3)':'12','Edison 5-20 (12/3)':'12'};
var CABLE_LIST=Object.keys(CABLE_TYPES);
var CONNECTORS=['Cam-Lok E1016','Bates / Stage-pin 100A','California 100A','Socapex 19-pin','L21-30','L14-30','L5-30','powerCON TRUE1','Edison 5-20','Hubbell 100A','Posi-Lok'];
var PWR_SOURCES=['Utility tie-in','Generator','House / Venue power','Shore power','UPS / Battery'];
var PWR_VOLTS=['120','208','240','277','480'];

/* v29 (Module 5): per-source broadcast-electrical spec — informed by current
   remote-production power practice (company switches, service configuration,
   technical vs domestic power, transfer method, redundancy scheme, N-G
   bond/SDS discipline, generator fuel math) — every field additive, legacy
   distros normalize in place. */
var PWR_TIEINS=['Company switch (Cam-Lok)','Bull switch','Truck-dock power panel','Wall receptacle (twist-lock/Edison)','Pole / temp service drop','Generator output panel','Spider box pass-through'];
var PWR_SVC=['120/208V 3-ph wye','120/240V 1-ph','120/240V high-leg delta','277/480V 3-ph','230/400V (intl)','Unverified — meter on site'];
var PWR_CLASS=['Technical power','Domestic / utility power','Mixed'];
var PWR_XFER=['None','Manual changeover (MTS)','ATS open-transition','ATS closed-transition','No-break changeover panel'];
var PWR_REDUN=['None / single','Twin-pack (2N twinset)','N+1 paralleled','Second feed (shore + generator)','UPS-bridge only'];
var PWR_SDS=['Verify on site','SDS — neutral switched (bond N-G at gen)','Non-SDS — solid neutral (do NOT re-bond)'];
function pwrNormDistro(d){
  if(d.tieIn==null)d.tieIn=PWR_TIEINS[0];
  if(d.svc==null)d.svc=(d.phase===3?PWR_SVC[0]:PWR_SVC[1]);
  if(d.pclass==null)d.pclass='Technical power';
  if(d.xfer==null)d.xfer='None';
  if(d.redun==null)d.redun='None / single';
  if(d.redunDetail==null)d.redunDetail='';
  if(d.sds==null)d.sds='Verify on site';
  if(d.ground==null)d.ground='';
  if(d.elecName==null)d.elecName='';
  if(d.elecPhone==null)d.elecPhone='';
  if(!Array.isArray(d.photos))d.photos=[];
  if(d.genKw==null)d.genKw='';
  if(d.fuelGal==null)d.fuelGal='';
  if(d.burnGph==null)d.burnGph='';
  return d;}
function ensurePower(s){if(!s.power)s.power={distros:[],runs:[]};
  if(!Array.isArray(s.power.distros))s.power.distros=[];
  if(!Array.isArray(s.power.runs))s.power.runs=[];
  s.power.distros.forEach(pwrNormDistro);
  return s.power;}
function pwrId(pre){return pre+Date.now().toString(36)+Math.floor(Math.random()*1296).toString(36);}
function findDistro(pw,id){for(var i=0;i<pw.distros.length;i++)if(pw.distros[i].id===id)return pw.distros[i];return null;}

/* ---- mutations ---- */
function powerAddDistro(key){var pw=ensurePower(getSurvey(key));
  pw.distros.push({id:pwrId('d'),name:'Distro '+(pw.distros.length+1),src:'Generator',
    type:'Lug / Cam-Lok',volts:'208',phase:3,amps:400,location:'',notes:''});
  stampEdit(key);renderProjectView(key);}
function powerEditDistro(key,id,field,val){var d=findDistro(ensurePower(getSurvey(key)),id);if(!d)return;
  if(field==='amps'){d.amps=Math.max(0,parseInt(val,10)||0);}else if(field==='phase'){d.phase=parseInt(val,10)||1;}
  else if(field==='genKw'||field==='fuelGal'||field==='burnGph'){var n=parseFloat(val);d[field]=(isNaN(n)||n<0)?'':n;}
  else d[field]=val;stampEdit(key);
  if(field==='ground'||field==='elecName'||field==='elecPhone'||field==='redunDetail'){saveState&&saveState();return;}
  renderProjectView(key);}

/* ---- v29 per-source photos (panel nameplate, connector chamber, meter shots…) ---- */
function powerPhotoAdd(key,id,e){var file=e.target.files&&e.target.files[0];if(!file)return;var r=new FileReader();
  r.onload=function(){var d=findDistro(ensurePower(getSurvey(key)),id);if(!d)return;
    d.photos.push({src:r.result,caption:'',ts:nowStamp()});stampEdit(key);renderProjectView(key);toast('Photo attached to the power source');};
  r.readAsDataURL(file);e.target.value='';}
function powerPhotoCaption(key,id,i,val){var d=findDistro(ensurePower(getSurvey(key)),id);
  if(!d||!d.photos[i])return;d.photos[i].caption=val;stampEdit(key);}
function powerPhotoDel(key,id,i){var d=findDistro(ensurePower(getSurvey(key)),id);
  if(!d||!d.photos[i])return;d.photos.splice(i,1);stampEdit(key);renderProjectView(key);}

/* ---- v29 computed hazard conditions per source (cross-linked to the Survey Log) ---- */
function powerHazards(key,d,L){var hz=[];
  if(L.amps>L.cap&&L.cap>0)hz.push({lvl:'danger',t:'Over breaker capacity — '+L.amps+'A connected on a '+L.cap+'A source'});
  else if(L.amps>L.cont&&L.cap>0)hz.push({lvl:'warning',t:'Above 80% continuous rating ('+L.amps+'A on '+L.cap+'A — derate to '+Math.round(L.cont)+'A)'});
  if((d.svc||'').indexOf('high-leg')>-1)hz.push({lvl:'danger',t:'High-leg delta service — never land 120V loads on the wild leg (~208V to neutral)'});
  if((d.svc||'').indexOf('Unverified')>-1)hz.push({lvl:'caution',t:'Service unverified — meter every leg, G-N voltage and rotation before connecting electronics'});
  if(d.pclass==='Technical power'&&(d.xfer==='ATS open-transition'||d.xfer==='Manual changeover (MTS)'))
    hz.push({lvl:'warning',t:'Open-transition / manual changeover on the technical feed — the air chain drops during transfer unless UPS-bridged'});
  if(d.sds==='Verify on site')hz.push({lvl:'caution',t:'N-G bond unverified — exactly one neutral-ground bond upstream (SDS vs non-SDS) before energizing'});
  if(d.src==='Generator'){
    if(d.redun==='None / single')hz.push({lvl:'caution',t:'Single engine, no redundancy — an engine fault or hot refuel takes the feed down'});
    var kw=parseFloat(d.genKw);
    if(kw>0){var v=parseFloat(d.volts)||208;var loadKw=L.amps*v*(d.phase===3?1.732:1)/1000;
      if(loadKw>0){var pct=loadKw/kw;
        if(pct<0.3)hz.push({lvl:'caution',t:'Wet-stacking risk — running at '+Math.round(pct*100)+'% of nameplate ('+loadKw.toFixed(1)+' of '+kw+' kW); gensets want 50–80%'});
        else if(pct>0.85)hz.push({lvl:'warning',t:'No headroom — '+Math.round(pct*100)+'% of nameplate; size to measured load + spikes'});}}
    var gal=parseFloat(d.fuelGal),gph=parseFloat(d.burnGph);
    if(gal>0&&gph>0){var hrs=gal/gph;
      if(hrs<14)hz.push({lvl:'warning',t:'Runtime ≈ '+hrs.toFixed(1)+'h on the tank — schedule dark-hours wet hosing / nightly top-off'});}}
  return hz;}
function powerHazardLogged(key,id){var f=ensureFindings(key);
  for(var i=0;i<f.length;i++){if(f[i].srcRef===id&&f[i].status!=='closed')return true;}return false;}
function powerFlagHazard(key,id){var d=findDistro(ensurePower(getSurvey(key)),id);if(!d)return;
  var L=distroLoad(ensurePower(getSurvey(key)),d);var hz=powerHazards(key,d,L);
  if(!hz.length){toast('No open hazard conditions on this source');return;}
  var worst=hz.some(function(h){return h.lvl==='danger';})?'danger':(hz.some(function(h){return h.lvl==='warning';})?'warning':'caution');
  var f=ensureFindings(key);
  f.unshift({id:'F_'+key+'_'+Date.now().toString(36),severity:worst,status:'open',owner:'',srcRef:id,
    by:(productions[key].editedBy||'Power survey'),tags:['Electrical Hazard'],photos:[],
    text:'[Power — '+(d.name||'distro')+(d.location?' @ '+d.location:'')+'] '+hz.map(function(h){return h.t;}).join(' · '),ts:nowStamp()});
  stampEdit(key);renderProjectView(key);toast('Logged to Survey Log & Findings as Electrical Hazard');}
function powerDelDistro(key,id){var pw=ensurePower(getSurvey(key));
  if(!confirm('Remove this distribution source? Runs fed from it will be unlinked.'))return;
  pw.distros=pw.distros.filter(function(d){return d.id!==id;});
  pw.runs.forEach(function(r){if(r.distroId===id)r.distroId='';});
  stampEdit(key);renderProjectView(key);}
function powerAddRun(key){var pw=ensurePower(getSurvey(key));var d0=pw.distros[0];
  pw.runs.push({id:pwrId('r'),label:'Run '+(pw.runs.length+1),distroId:d0?d0.id:'',dest:'',
    cable:'4/0 Cam-Lok (single)',awg:'4/0',lengthFt:100,amps:100,
    volts:d0?d0.volts:'208',phase:d0?d0.phase:3,connector:'Cam-Lok E1016',
    color:'#e41e3f',planId:'',path:[],notes:''});
  stampEdit(key);renderProjectView(key);}
function powerEditRun(key,id,field,val){var pw=ensurePower(getSurvey(key));var r=null;
  for(var i=0;i<pw.runs.length;i++)if(pw.runs[i].id===id){r=pw.runs[i];break;}if(!r)return;
  if(field==='cable'){r.cable=val;if(CABLE_TYPES[val])r.awg=CABLE_TYPES[val];}
  else if(field==='lengthFt'){r.lengthFt=Math.max(0,parseFloat(val)||0);}
  else if(field==='amps'){r.amps=Math.max(0,parseFloat(val)||0);}
  else if(field==='phase'){r.phase=parseInt(val,10)||1;}
  else r[field]=val;
  stampEdit(key);renderProjectView(key);}
function powerDelRun(key,id){var pw=ensurePower(getSurvey(key));
  pw.runs=pw.runs.filter(function(r){return r.id!==id;});stampEdit(key);renderProjectView(key);}

/* ---- electrical calculations ---- */
function runVDrop(r){var a=AWG_DATA[r.awg];if(!a)return null;var v=parseFloat(r.volts)||120;
  var k=(r.phase===3)?1.732:2;var vd=k*(r.amps||0)*a.r*((r.lengthFt||0)/1000);
  return {volts:vd,pct:v>0?(vd/v*100):0,amp:a.amp};}
function distroLoad(pw,d){var load=0,n=0;pw.runs.forEach(function(r){if(r.distroId===d.id){load+=(parseFloat(r.amps)||0);n++;}});
  return {amps:load,count:n,cap:d.amps||0,util:d.amps>0?load/d.amps:0,cont:d.amps*0.8};}

/* ---- information pane ---- */
function powerPaneHTML(key){var s=getSurvey(key);var pw=ensurePower(s);
  var totalLoad=0;pw.runs.forEach(function(r){totalLoad+=(parseFloat(r.amps)||0);});
  // distro cards
  var distroCards=pw.distros.map(function(d){var L=distroLoad(pw,d);
    var pct=Math.min(100,Math.round(L.util*100));
    var barCol=L.amps>L.cap?'bg-red-500':(L.amps>L.cont?'bg-amber-500':'bg-emerald-500');
    var warn=L.amps>L.cap?'<span class="text-[9px] font-bold text-red-600">⚠ OVER CAPACITY ('+L.amps+'A on '+L.cap+'A)</span>'
      :(L.amps>L.cont?'<span class="text-[9px] font-bold text-amber-600">⚠ Over 80% continuous ('+L.amps+'A · derate '+Math.round(L.cont)+'A)</span>'
      :'<span class="text-[9px] font-bold text-emerald-600">✓ Within continuous rating</span>');
    /* v30 Module 11 fix: a <select>'s minimum width is its longest <option>, and long
       PWR_SDS/PWR_REDUN/PWR_TIEINS options overflowed the minmax(0,1fr) grid column and
       painted past the tile border. w-full + min-width:0 + max-width:100% pins every
       spec select inside its column; the dropdown MENU itself is browser-native and
       never clipped, so nothing is lost. */
    function sel(field,opts,cur){return '<select onchange="powerEditDistro(\''+key+'\',\''+d.id+'\',\''+field+'\',this.value)" class="w-full text-[10px] border border-gray-200 rounded px-1.5 py-1 bg-white" style="outline:none;min-width:0;max-width:100%">'+opts.map(function(o){return '<option'+(String(cur)===String(o)?' selected':'')+'>'+o+'</option>';}).join('')+'</select>';}
    return '<div class="border border-gray-200 rounded-xl p-3 bg-gradient-to-br from-white to-gray-50 overflow-hidden" style="min-width:0">'+
      '<div class="flex items-center justify-between mb-2"><input value="'+esc(d.name).replace(/"/g,'&quot;')+'" onchange="powerEditDistro(\''+key+'\',\''+d.id+'\',\'name\',this.value)" class="text-[12px] font-bold text-gray-900 bg-transparent border-b border-transparent hover:border-gray-300 focus:border-blue-400" style="outline:none;width:60%">'+
        '<button onclick="powerDelDistro(\''+key+'\',\''+d.id+'\')" class="text-gray-300 hover:text-red-500 text-xs">✕</button></div>'+
      '<div class="grid grid-cols-2 gap-1.5 mb-2" style="min-width:0">'+
        '<label class="text-[8px] font-bold uppercase tracking-wider text-gray-400" style="min-width:0">Source'+sel('src',PWR_SOURCES,d.src)+'</label>'+
        '<label class="text-[8px] font-bold uppercase tracking-wider text-gray-400" style="min-width:0">Breaker (A)<input type="number" value="'+d.amps+'" onchange="powerEditDistro(\''+key+'\',\''+d.id+'\',\'amps\',this.value)" class="w-full text-[10px] mono border border-gray-200 rounded px-1.5 py-1" style="outline:none;min-width:0"></label>'+
        '<label class="text-[8px] font-bold uppercase tracking-wider text-gray-400" style="min-width:0">Voltage'+sel('volts',PWR_VOLTS,d.volts)+'</label>'+
        '<label class="text-[8px] font-bold uppercase tracking-wider text-gray-400" style="min-width:0">Phase'+sel('phase',['1','3'],d.phase)+'</label>'+
      '</div>'+
      '<input value="'+esc(d.location||'').replace(/"/g,'&quot;')+'" onchange="powerEditDistro(\''+key+'\',\''+d.id+'\',\'location\',this.value)" placeholder="Physical location (e.g. NE tunnel, gen yard)" class="w-full text-[10px] border border-gray-200 rounded px-2 py-1 mb-2" style="outline:none">'+
      '<div class="flex items-center justify-between text-[9px] mono text-gray-500 mb-1"><span>Connected: <b class="text-gray-800">'+L.amps+'A</b> / '+L.cap+'A · '+L.count+' run'+(L.count===1?'':'s')+'</span><span>'+pct+'%</span></div>'+
      '<div class="h-2 rounded-full bg-gray-100 overflow-hidden relative"><div class="'+barCol+' h-full rounded-full" style="width:'+pct+'%"></div><div class="absolute top-0 bottom-0" style="left:80%;width:1px;background:#b0b3b8"></div></div>'+
      '<div class="mt-1.5">'+warn+'</div>'+
      /* v29 broadcast electrical spec */
      '<div class="grid grid-cols-2 gap-1.5 mt-2 pt-2 border-t border-gray-200/70" style="min-width:0">'+
        '<label class="text-[8px] font-bold uppercase tracking-wider text-gray-400" style="min-width:0">Tie-in point'+sel('tieIn',PWR_TIEINS,d.tieIn)+'</label>'+
        '<label class="text-[8px] font-bold uppercase tracking-wider text-gray-400" style="min-width:0">Service config'+sel('svc',PWR_SVC,d.svc)+'</label>'+
        '<label class="text-[8px] font-bold uppercase tracking-wider text-gray-400" style="min-width:0">Power class'+sel('pclass',PWR_CLASS,d.pclass)+'</label>'+
        '<label class="text-[8px] font-bold uppercase tracking-wider text-gray-400" style="min-width:0">Transfer'+sel('xfer',PWR_XFER,d.xfer)+'</label>'+
        '<label class="text-[8px] font-bold uppercase tracking-wider text-gray-400" style="min-width:0">Redundancy / backup'+sel('redun',PWR_REDUN,d.redun)+'</label>'+
        '<label class="text-[8px] font-bold uppercase tracking-wider text-gray-400" style="min-width:0">N-G bond / SDS'+sel('sds',PWR_SDS,d.sds)+'</label>'+
      '</div>'+
      (d.redun!=='None / single'?'<input value="'+esc(d.redunDetail||'').replace(/"/g,'&quot;')+'" onchange="powerEditDistro(\''+key+'\',\''+d.id+'\',\'redunDetail\',this.value)" placeholder="Backup detail — twinset auto-sync, second feed path, changeover operator…" class="w-full text-[10px] border border-gray-200 rounded px-2 py-1 mt-1.5" style="outline:none">':'')+
      (d.src==='Generator'?
        '<div class="grid grid-cols-3 gap-1.5 mt-1.5">'+
          '<label class="text-[8px] font-bold uppercase tracking-wider text-gray-400">Nameplate kW<input type="number" value="'+(d.genKw===''?'':d.genKw)+'" onchange="powerEditDistro(\''+key+'\',\''+d.id+'\',\'genKw\',this.value)" placeholder="kW" class="w-full text-[10px] mono border border-gray-200 rounded px-1.5 py-1" style="outline:none"></label>'+
          '<label class="text-[8px] font-bold uppercase tracking-wider text-gray-400">Tank (gal)<input type="number" value="'+(d.fuelGal===''?'':d.fuelGal)+'" onchange="powerEditDistro(\''+key+'\',\''+d.id+'\',\'fuelGal\',this.value)" placeholder="gal" class="w-full text-[10px] mono border border-gray-200 rounded px-1.5 py-1" style="outline:none"></label>'+
          '<label class="text-[8px] font-bold uppercase tracking-wider text-gray-400">Burn (gph)<input type="number" value="'+(d.burnGph===''?'':d.burnGph)+'" onchange="powerEditDistro(\''+key+'\',\''+d.id+'\',\'burnGph\',this.value)" placeholder="gph" class="w-full text-[10px] mono border border-gray-200 rounded px-1.5 py-1" style="outline:none"></label>'+
        '</div>'+
        ((parseFloat(d.fuelGal)>0&&parseFloat(d.burnGph)>0)?'<p class="text-[9px] mono text-gray-500 mt-1">⛽ Runtime ≈ <b class="text-gray-800">'+(parseFloat(d.fuelGal)/parseFloat(d.burnGph)).toFixed(1)+' h</b> on the tank at this burn rate</p>':'')
      :'')+
      '<div class="flex items-center gap-1.5 mt-1.5">'+
        '<input value="'+esc(d.elecName||'').replace(/"/g,'&quot;')+'" onchange="powerEditDistro(\''+key+'\',\''+d.id+'\',\'elecName\',this.value)" placeholder="House electrician / electrician of record" class="flex-1 text-[10px] border border-gray-200 rounded px-2 py-1" style="outline:none">'+
        '<input value="'+esc(d.elecPhone||'').replace(/"/g,'&quot;')+'" onchange="powerEditDistro(\''+key+'\',\''+d.id+'\',\'elecPhone\',this.value)" placeholder="Phone" class="text-[10px] mono border border-gray-200 rounded px-2 py-1" style="outline:none;width:96px">'+
      '</div>'+
      '<div class="mt-1.5">'+museRichBox({id:'pwrg_'+key+'_'+d.id,value:d.ground||'',toolbar:'slim',height:'66px',placeholder:'Grounding & bonding — N-G bond location (one bond only), ground rods, building-steel bond, isolated/technical ground…',onchange:'function(v){powerEditDistro(\''+key+'\',\''+d.id+'\',\'ground\',v)}'})+'</div>'+
      '<div class="flex items-center gap-1.5 mt-1.5 flex-wrap">'+
        d.photos.map(function(ph,pi){return '<span class="relative inline-block">'+
          '<img src="'+ph.src+'" onclick="survShowImg(this.src,\''+survCapArg(ph.caption||d.name)+'\')" title="'+esc(ph.caption||'').replace(/"/g,'&quot;')+'" style="height:42px;width:62px;object-fit:cover;border-radius:6px;border:1px solid #e4e6eb;cursor:pointer" alt="power source photo">'+
          '<button onclick="powerPhotoDel(\''+key+'\',\''+d.id+'\','+pi+')" class="absolute -top-1 -right-1 w-3.5 h-3.5 rounded-full bg-black/60 text-white text-[7px] leading-none">✕</button></span>';}).join('')+
        '<label class="text-[8px] font-bold text-blue-700 hover:underline cursor-pointer">📷 Add photo<input type="file" accept="image/*" onchange="powerPhotoAdd(\''+key+'\',\''+d.id+'\',event)" style="display:none"></label>'+
        '<span class="text-[7px] text-gray-400">panel nameplate · schedule · connector chamber · meter readings</span>'+
      '</div>'+
      (d.photos.length?'<div class="mt-1">'+d.photos.map(function(ph,pi){return '<input value="'+esc(ph.caption||'').replace(/"/g,'&quot;')+'" onchange="powerPhotoCaption(\''+key+'\',\''+d.id+'\','+pi+',this.value)" placeholder="Photo '+(pi+1)+' description…" class="w-full text-[9px] text-gray-600 border border-transparent hover:border-gray-200 focus:border-gray-300 rounded px-1.5 py-0.5 mb-0.5" style="outline:none">';}).join('')+'</div>':'')+
      (function(){var hz=powerHazards(key,d,L);if(!hz.length)return '';
        var chips=hz.map(function(h){var c=h.lvl==='danger'?'bg-red-50 text-red-700':(h.lvl==='warning'?'bg-amber-50 text-amber-700':'bg-yellow-50 text-yellow-700');
          return '<span class="inline-block text-[8px] font-bold px-1.5 py-0.5 rounded '+c+' mr-1 mb-1">'+esc(h.t)+'</span>';}).join('');
        var logged=powerHazardLogged(key,d.id);
        return '<div class="mt-1.5 pt-1.5 border-t border-gray-200/70">'+chips+
          (logged?'<span class="text-[8px] font-bold text-emerald-700">✓ In the Survey Log (Electrical Hazard)</span>'
            :'<button onclick="powerFlagHazard(\''+key+'\',\''+d.id+'\')" class="text-[8px] font-bold text-red-700 border border-red-200 bg-red-50 rounded px-2 py-1 hover:bg-red-100">⚠ Log as Electrical Hazard</button>')+'</div>';})()+
      '</div>';
  }).join('');
  // runs table
  var distroOpts=function(cur){return '<option value="">— pick —</option>'+pw.distros.map(function(d){return '<option value="'+d.id+'"'+(cur===d.id?' selected':'')+'>'+esc(d.name)+'</option>';}).join('');};
  var rows=pw.runs.map(function(r){var vd=runVDrop(r);
    var vdCol=!vd?'text-gray-400':(vd.pct>5?'text-red-600 font-bold':(vd.pct>3?'text-amber-600 font-semibold':'text-emerald-600'));
    var ampWarn=(vd&&r.amps>vd.amp)?' title="Conductor undersized: '+r.amps+'A load on '+r.awg+' AWG rated '+vd.amp+'A" style="box-shadow:inset 0 0 0 2px #e41e3f"':'';
    function inp(field,val,w,type){return '<input '+(type?'type="'+type+'" ':'')+'value="'+esc(String(val)).replace(/"/g,'&quot;')+'" onchange="powerEditRun(\''+key+'\',\''+r.id+'\',\''+field+'\',this.value)" class="text-[10px] mono border border-gray-200 rounded px-1.5 py-1" style="outline:none;width:'+w+'">';}
    function sel(field,opts,cur,raw){return '<select onchange="powerEditRun(\''+key+'\',\''+r.id+'\',\''+field+'\',this.value)" class="text-[10px] border border-gray-200 rounded px-1 py-1 bg-white" style="outline:none">'+(raw||'')+opts.map(function(o){return '<option'+(String(cur)===String(o)?' selected':'')+'>'+o+'</option>';}).join('')+'</select>';}
    var onCad=(r.planId&&r.path&&r.path.length>1)?'<span class="inline-flex items-center gap-0.5 text-[8px] font-bold text-blue-700" title="Mapped on '+esc(r.planId)+'">◉ mapped</span>':'<span class="text-[8px] text-gray-300">—</span>';
    return '<tr class="border-t border-gray-100 align-top">'+
      '<td class="p-1"><span class="inline-block w-2.5 h-2.5 rounded-full align-middle mr-1" style="background:'+r.color+'"></span><input value="'+esc(r.label).replace(/"/g,'&quot;')+'" onchange="powerEditRun(\''+key+'\',\''+r.id+'\',\'label\',this.value)" class="text-[10px] font-semibold border border-gray-200 rounded px-1.5 py-1" style="outline:none;width:84px"></td>'+
      '<td class="p-1"><select onchange="powerEditRun(\''+key+'\',\''+r.id+'\',\'distroId\',this.value)" class="text-[10px] border border-gray-200 rounded px-1 py-1 bg-white" style="outline:none;max-width:96px">'+distroOpts(r.distroId)+'</select></td>'+
      '<td class="p-1">'+inp('dest',r.dest||'','96px')+'</td>'+
      '<td class="p-1">'+sel('cable',CABLE_LIST,r.cable)+'</td>'+
      '<td class="p-1">'+sel('awg',AWG_LIST,r.awg)+'</td>'+
      '<td class="p-1"><input type="number" value="'+r.lengthFt+'" onchange="powerEditRun(\''+key+'\',\''+r.id+'\',\'lengthFt\',this.value)" class="text-[10px] mono border border-gray-200 rounded px-1.5 py-1" style="outline:none;width:52px"></td>'+
      '<td class="p-1"><input type="number"'+ampWarn+' value="'+r.amps+'" onchange="powerEditRun(\''+key+'\',\''+r.id+'\',\'amps\',this.value)" class="text-[10px] mono border border-gray-200 rounded px-1.5 py-1" style="outline:none;width:48px"></td>'+
      '<td class="p-1">'+sel('volts',PWR_VOLTS,r.volts)+sel('phase',['1','3'],r.phase)+'</td>'+
      '<td class="p-1">'+sel('connector',CONNECTORS,r.connector)+'</td>'+
      '<td class="p-1 text-center mono '+vdCol+'">'+(vd?vd.pct.toFixed(1)+'%':'—')+'<div class="text-[7px] text-gray-400">'+(vd?vd.volts.toFixed(1)+'V':'')+'</div></td>'+
      '<td class="p-1 text-center">'+onCad+'</td>'+
      '<td class="p-1 text-center"><button onclick="powerDelRun(\''+key+'\',\''+r.id+'\')" class="text-gray-300 hover:text-red-500">✕</button></td>'+
    '</tr>';
  }).join('');
  var th=function(t){return '<th class="p-1 text-[8px] font-bold uppercase tracking-wider text-gray-400 text-left">'+t+'</th>';};
  var runsTable=pw.runs.length?
    '<div class="overflow-x-auto"><table class="w-full" style="min-width:760px"><thead><tr>'+
      th('Run')+th('From')+th('Destination')+th('Cable')+th('AWG')+th('Len ft')+th('Amps')+th('V / φ')+th('Connector')+th('V-drop')+th('CAD')+th('')+
    '</tr></thead><tbody>'+rows+'</tbody></table></div>':
    '<p class="text-[11px] text-gray-400 text-center py-3">No cable runs documented yet — add the first run, then map its path on a CAD drawing.</p>';
  var anyVd=pw.runs.some(function(r){var v=runVDrop(r);return v&&v.pct>3;});
  return '<div class="bg-white rounded-2xl p-4 sm:p-5 border border-gray-200/60" style="box-shadow:0 4px 20px rgba(0,0,0,.03)">'+
    '<div class="flex flex-wrap items-center justify-between gap-2 mb-3">'+
      '<div><h4 class="text-[10px] font-bold uppercase tracking-wider text-gray-600">Power, Electrical &amp; Cable Runs</h4>'+
      '<p class="text-[9px] text-gray-400 mt-0.5">Tie-ins, service config, technical vs domestic power, redundancy, N-G bond discipline, fuel math &amp; copper voltage-drop — built for the site electrician.</p></div>'+
      '<div class="flex items-center gap-3 text-[10px] mono text-gray-600"><span>Total connected: <b class="text-gray-900">'+totalLoad+'A</b></span><span>'+pw.distros.length+' distro · '+pw.runs.length+' run'+(pw.runs.length===1?'':'s')+'</span></div>'+
    '</div>'+
    '<div class="flex items-center justify-between mb-2"><h5 class="text-[9px] font-bold uppercase tracking-wider text-gray-500">Distribution Sources</h5>'+
      '<button onclick="powerAddDistro(\''+key+'\')" class="text-[9px] font-bold text-blue-700 hover:underline">+ Add distro</button></div>'+
    (pw.distros.length?'<div class="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-2.5 mb-4">'+distroCards+'</div>':'<p class="text-[11px] text-gray-400 text-center py-3 mb-2">No distribution sources yet — add a generator, utility tie-in or house feed.</p>')+
    '<div class="flex items-center justify-between mb-2 pt-2 border-t border-gray-100"><h5 class="text-[9px] font-bold uppercase tracking-wider text-gray-500">Cable Runs</h5>'+
      '<button onclick="powerAddRun(\''+key+'\')" class="text-[9px] font-bold text-blue-700 hover:underline">+ Add run</button></div>'+
    runsTable+
    (anyVd?'<p class="text-[9px] text-amber-600 mt-2">⚠ Voltage drop above 3% flagged — consider larger conductor or shorter run (NEC 210.19 recommends ≤3% on branch circuits).</p>':'')+
    (function(){var eh=ensureFindings(key).filter(function(x){return x.tags&&x.tags.indexOf('Electrical Hazard')>-1&&x.status!=='closed';});
      if(!eh.length)return '';
      return '<div class="mt-3 pt-2 border-t border-gray-100 flex items-center justify-between flex-wrap gap-2">'+
        '<span class="text-[9px] font-bold text-red-700">⚡ '+eh.length+' open Electrical Hazard entr'+(eh.length===1?'y':'ies')+' in the Survey Log</span>'+
        '<button onclick="surveySetView(\''+key+'\',\'log\');setTimeout(function(){survLogSetFilter(\''+key+'\',\'tag\',\'Electrical Hazard\');},0)" class="text-[9px] font-bold text-blue-700 hover:underline">Review in Log &amp; Findings →</button></div>';})()+
  '</div>';
}

/* ============================================================================
   SITE SURVEY — SECURITY DETAILS (crew awareness)
   Access control, credentialing, restricted zones, lockup, egress, CCTV and
   on-site security contacts. Kept lightweight and skimmable for the crew.
   ========================================================================== */
var SEC_LEVELS=['Standard','Elevated','High','SEAR-rated','NSSE (National Special Security Event)'];
var SEC_FIELDS=[
  ['access','Access / Load-in Points','Gate D, NE service tunnel — badge + vehicle pass required'],
  ['badging','Credentialing / Badging','All-Access AA, working-press WP; collect at compound trailer'],
  ['escort','Escort Requirements','Non-credentialed vendors escorted by venue security; talent escort from Gate D'],
  ['restricted','Restricted Areas','Field level pre-game, locker rooms, principal holding'],
  ['lockup','Equipment Lockup / Overnight','TOC + truck compound fenced; roving guard 2200–0600'],
  ['cctv','Surveillance / CCTV','House CCTV on compound; no Muse Live coverage of secure zones'],
  ['egress','Emergency Egress / Muster','Muster A at gate D parking; secondary at media lot']
];
/* v29 (Module 7): prohibited items + mapped checkpoints */
var SEC_PROHIB_CATALOG=[
  ['cameras','No Cameras','📷'],['drones','No Drones','🚁'],['weapons','No Weapons','🔫'],
  ['liquids','No Liquids','🧴'],['laptops','No Laptops','💻'],['bags','No Large Bags','🎒'],
  ['smoking','No Smoking','🚬'],['phones','No Phones','📱'],['food','No Outside Food','🍔'],
  ['glass','No Glass','🍾'],['selfie','No Selfie Sticks','🤳'],['audio','No Recording Devices','🎙️']];
var SEC_CK_KINDS=['Main security gate','Crew entrance','Vehicle checkpoint','Credential pickup','Magnetometer bank','Media / press entrance'];
function secProhibIcon(icon,size){size=size||44;
  return '<svg width="'+size+'" height="'+size+'" viewBox="0 0 48 48" aria-hidden="true">'+
    '<text x="24" y="31" text-anchor="middle" font-size="19">'+esc(String(icon||'🚫').slice(0,4))+'</text>'+
    '<circle cx="24" cy="24" r="20" fill="none" stroke="#e41e3f" stroke-width="4.5"/>'+
    '<line x1="9.9" y1="9.9" x2="38.1" y2="38.1" stroke="#e41e3f" stroke-width="4.5" stroke-linecap="round"/></svg>';}
function ensureSecurity(s){if(!s.security)s.security={level:'Standard',contacts:[],notes:''};
  if(!Array.isArray(s.security.contacts))s.security.contacts=[];
  if(!Array.isArray(s.security.prohibited))s.security.prohibited=[];
  if(!Array.isArray(s.security.checkpoints))s.security.checkpoints=[];
  SEC_FIELDS.forEach(function(f){if(typeof s.security[f[0]]!=='string')s.security[f[0]]='';});
  return s.security;}
function secProhibToggle(key,id){var sec=ensureSecurity(getSurvey(key));
  var hit=-1;for(var i=0;i<sec.prohibited.length;i++)if(sec.prohibited[i].id===id)hit=i;
  if(hit>-1)sec.prohibited.splice(hit,1);
  else{var cat=null;for(var j=0;j<SEC_PROHIB_CATALOG.length;j++)if(SEC_PROHIB_CATALOG[j][0]===id)cat=SEC_PROHIB_CATALOG[j];
    if(cat)sec.prohibited.push({id:cat[0],label:cat[1],icon:cat[2]});}
  stampEdit(key);renderSecProhib(key);} // v30 M13: card-only re-render — the map is untouched
function secProhibCustom(key){var label=prompt('Prohibited item label (e.g. "No E-Bikes"):','');if(!label)return;
  var icon=prompt('Pick an emoji for the sign:','🚫')||'🚫';
  var sec=ensureSecurity(getSurvey(key));
  sec.prohibited.push({id:'cx'+Date.now().toString(36),label:label,icon:icon});
  stampEdit(key);renderSecProhib(key);}
function secProhibRemove(key,id){var sec=ensureSecurity(getSurvey(key));
  sec.prohibited=sec.prohibited.filter(function(x){return x.id!==id;});stampEdit(key);renderSecProhib(key);}
function secCkAdd(key){var s=getSurvey(key);var sec=ensureSecurity(s);var n=sec.checkpoints.length;
  sec.checkpoints.push({id:'ck'+Date.now().toString(36),name:'Checkpoint '+(n+1),kind:SEC_CK_KINDS[Math.min(n,SEC_CK_KINDS.length-1)],
    lat:(s.lat!=null?+((+s.lat)+0.0012*((n%4)+1)).toFixed(5):null),
    lng:(s.lng!=null?+((+s.lng)+0.0012*((n%3)-1)).toFixed(5):null),hours:'',notes:''});
  stampEdit(key);renderProjectView(key);}
function secCkEdit(key,id,field,val){var sec=ensureSecurity(getSurvey(key));
  for(var i=0;i<sec.checkpoints.length;i++){var c=sec.checkpoints[i];if(c.id!==id)continue;
    if(field==='lat'||field==='lng'){var v=parseFloat(val);c[field]=isNaN(v)?null:v;}
    else c[field]=val;break;}
  stampEdit(key);
  if(field==='hours'||field==='notes'||field==='name'){saveState&&saveState();return;}
  renderProjectView(key);}
function secCkDel(key,id){var sec=ensureSecurity(getSurvey(key));
  sec.checkpoints=sec.checkpoints.filter(function(c){return c.id!==id;});stampEdit(key);renderProjectView(key);}
function secMapPins(key){var s=getSurvey(key);var sec=ensureSecurity(s);var pins=[];
  var v=venueFor(key);var la=(s.lat!=null?s.lat:(v?v.lat:null)),lo=(s.lng!=null?s.lng:(v?v.lng:null));
  if(la!=null&&lo!=null)pins.push({id:'venue',name:(productions[key].venue||productions[key].name),city:'',lat:la,lng:lo,active:true,key:''});
  sec.checkpoints.forEach(function(c){if(typeof c.lat!=='number'||typeof c.lng!=='number')return;
    pins.push({id:c.id,name:'🛂 '+c.name,city:c.kind+(c.hours?' · '+c.hours:''),lat:c.lat,lng:c.lng,active:false,color:'#0866ff',key:''});});
  return pins;}
function secId(){return 'sc'+Date.now().toString(36)+Math.floor(Math.random()*1296).toString(36);}
function securitySet(key,field,val){var sec=ensureSecurity(getSurvey(key));sec[field]=val;stampEdit(key);
  if(field==='level')renderProjectView(key);}
function securityAddContact(key){var sec=ensureSecurity(getSurvey(key));
  sec.contacts.push({id:secId(),name:'',role:'Venue Security',phone:''});stampEdit(key);renderProjectView(key);}
function securityEditContact(key,id,field,val){var sec=ensureSecurity(getSurvey(key));
  for(var i=0;i<sec.contacts.length;i++)if(sec.contacts[i].id===id){sec.contacts[i][field]=val;break;}stampEdit(key);}
function securityDelContact(key,id){var sec=ensureSecurity(getSurvey(key));
  sec.contacts=sec.contacts.filter(function(c){return c.id!==id;});stampEdit(key);renderProjectView(key);}

/* v30 Module 13: the Prohibited Items card renders standalone (id secProhib-KEY) so
   toggling an item updates ONLY this card — the checkpoint map's DOM is never touched.
   The map re-renders only when its own data (survey lat/lng, checkpoints) changes. */
function secProhibCardHTML(key){var sec=ensureSecurity(getSurvey(key));
  var on={};sec.prohibited.forEach(function(x){on[x.id]=x;});
  var tiles=SEC_PROHIB_CATALOG.map(function(c){var act=!!on[c[0]];
    return '<button onclick="secProhibToggle(\''+key+'\',\''+c[0]+'\')" title="'+esc(c[1])+' — click to '+(act?'remove from':'add to')+' this venue" class="flex flex-col items-center gap-1 p-2 rounded-xl border transition-all '+(act?'border-red-300 bg-red-50/60 shadow-sm':'border-gray-200 bg-white opacity-40 grayscale hover:opacity-80')+'">'+
      secProhibIcon(c[2])+'<span class="text-[8px] font-bold '+(act?'text-red-700':'text-gray-500')+' text-center leading-tight">'+esc(c[1])+'</span></button>';}).join('');
  var custom=sec.prohibited.filter(function(x){return x.id.indexOf('cx')===0;}).map(function(x){
    return '<div class="relative flex flex-col items-center gap-1 p-2 rounded-xl border border-red-300 bg-red-50/60 shadow-sm">'+
      '<button onclick="secProhibRemove(\''+key+'\',\''+x.id+'\')" class="absolute -top-1.5 -right-1.5 w-4 h-4 rounded-full bg-gray-900 text-white text-[8px] leading-none">✕</button>'+
      secProhibIcon(x.icon)+'<span class="text-[8px] font-bold text-red-700 text-center leading-tight">'+esc(x.label)+'</span></div>';}).join('');
  return '<div id="secProhib-'+key+'" class="bg-white rounded-2xl p-4 sm:p-5 border border-gray-200/60" style="box-shadow:0 4px 20px rgba(0,0,0,.03)">'+
    '<div class="flex flex-wrap items-center justify-between gap-2 mb-3">'+
      '<div><h4 class="text-[10px] font-bold uppercase tracking-wider text-gray-600">Prohibited Items <span class="text-gray-400 font-normal normal-case">— '+sec.prohibited.length+' active for this venue</span></h4>'+
      '<p class="text-[9px] text-gray-400 mt-0.5">Click a sign to toggle it for this survey. Active items surface in the Tech Book so field crews know before they pack.</p></div>'+
      '<button onclick="secProhibCustom(\''+key+'\')" class="text-[9px] font-bold text-blue-700 border border-blue-200 bg-blue-50 rounded-lg px-2.5 py-1.5 hover:bg-blue-100">+ Custom item</button></div>'+
    '<div class="grid gap-2" style="grid-template-columns:repeat(auto-fill,minmax(84px,1fr))">'+tiles+custom+'</div>'+
  '</div>';}
function renderSecProhib(key){var el=document.getElementById('secProhib-'+key);
  if(!el){renderProjectView(key);return;} // card not on screen — fall back to a normal render
  el.outerHTML=secProhibCardHTML(key);}
function securityPaneHTML(key){var s=getSurvey(key);var sec=ensureSecurity(s);
  var levelCol={'Standard':'bg-gray-100 text-gray-700 border-gray-200','Elevated':'bg-amber-50 text-amber-700 border-amber-200',
    'High':'bg-orange-50 text-orange-700 border-orange-200','SEAR-rated':'bg-red-50 text-red-700 border-red-200',
    'NSSE (National Special Security Event)':'bg-red-600 text-white border-red-600'}[sec.level]||'bg-gray-100 text-gray-700 border-gray-200';
  var fields=SEC_FIELDS.map(function(f){return '<div>'+
    '<label class="text-[8px] font-bold uppercase tracking-wider text-gray-400 block mb-0.5">'+f[1]+'</label>'+
    museRichBox({id:'sec_'+key+'_'+f[0],value:sec[f[0]]||'',toolbar:'slim',height:'88px',placeholder:f[2],onchange:'function(v){securitySet(\''+key+'\',\''+f[0]+'\',v)}'})+
  '</div>';}).join('');
  var contacts=sec.contacts.map(function(c){return '<div class="flex items-center gap-1.5">'+
    '<input value="'+esc(c.name||'').replace(/"/g,'&quot;')+'" onchange="securityEditContact(\''+key+'\',\''+c.id+'\',\'name\',this.value)" placeholder="Name" class="text-[10px] border border-gray-200 rounded px-2 py-1" style="outline:none;width:34%">'+
    '<input value="'+esc(c.role||'').replace(/"/g,'&quot;')+'" onchange="securityEditContact(\''+key+'\',\''+c.id+'\',\'role\',this.value)" placeholder="Role" class="text-[10px] border border-gray-200 rounded px-2 py-1" style="outline:none;width:30%">'+
    '<input value="'+esc(c.phone||'').replace(/"/g,'&quot;')+'" onchange="securityEditContact(\''+key+'\',\''+c.id+'\',\'phone\',this.value)" placeholder="Phone" class="text-[10px] mono border border-gray-200 rounded px-2 py-1" style="outline:none;width:28%">'+
    '<button onclick="securityDelContact(\''+key+'\',\''+c.id+'\')" class="text-gray-300 hover:text-red-500 text-xs">✕</button></div>';}).join('');
  return '<div class="bg-white rounded-2xl p-4 sm:p-5 border border-gray-200/60" style="box-shadow:0 4px 20px rgba(0,0,0,.03)">'+
    '<div class="flex flex-wrap items-center justify-between gap-2 mb-3">'+
      '<div class="flex items-center gap-2"><svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="#65676B" stroke-width="2"><path d="M12 2l8 4v6c0 5-3.5 8-8 10-4.5-2-8-5-8-10V6z"/></svg>'+
        '<h4 class="text-[10px] font-bold uppercase tracking-wider text-gray-600">Security Detail</h4></div>'+
      '<div class="flex items-center gap-2"><span class="text-[8px] font-bold uppercase tracking-wider text-gray-400">Posture</span>'+
        '<select onchange="securitySet(\''+key+'\',\'level\',this.value)" class="text-[10px] font-bold rounded border px-2 py-1 '+levelCol+'" style="outline:none;cursor:pointer">'+SEC_LEVELS.map(function(l){return '<option'+(sec.level===l?' selected':'')+'>'+l+'</option>';}).join('')+'</select></div>'+
    '</div>'+
    '<div class="grid grid-cols-1 md:grid-cols-2 gap-3 mb-3">'+fields+'</div>'+
    '<div class="border-t border-gray-100 pt-3">'+
      '<div class="flex items-center justify-between mb-2"><h5 class="text-[9px] font-bold uppercase tracking-wider text-gray-500">On-site Security Contacts</h5>'+
        '<button onclick="securityAddContact(\''+key+'\')" class="text-[9px] font-bold text-blue-700 hover:underline">+ Add contact</button></div>'+
      (sec.contacts.length?'<div class="space-y-1.5">'+contacts+'</div>':'<p class="text-[10px] text-gray-400">No security contacts logged.</p>')+
    '</div>'+
    '<label class="text-[8px] font-bold uppercase tracking-wider text-gray-400 block mb-0.5 mt-3">General Security Notes</label>'+
    museRichBox({id:'secnotes_'+key,value:sec.notes||'',toolbar:'note',height:'120px',placeholder:'Curfews, sweeps, K-9, drone restrictions, comms with venue ops…',onchange:'function(v){securitySet(\''+key+'\',\'notes\',v)}'})+
  '</div>'+
  /* ---- v29 prohibited items (v30 Module 13: own card + id — re-renders alone) ---- */
  secProhibCardHTML(key)+
  /* ---- v29 checkpoints & entrances on the shared multi-pin map ---- */
  (function(){var pins=secMapPins(key);
    var rows=sec.checkpoints.map(function(c){
      return '<div class="flex items-center gap-1.5 py-1.5 border-t border-gray-100 flex-wrap">'+
        '<span class="w-2.5 h-2.5 rounded-full flex-shrink-0" style="background:#0866ff"></span>'+
        '<input value="'+esc(c.name||'').replace(/"/g,'&quot;')+'" onchange="secCkEdit(\''+key+'\',\''+c.id+'\',\'name\',this.value)" placeholder="Name" class="text-[10px] font-semibold border border-gray-200 rounded px-2 py-1" style="outline:none;width:130px">'+
        '<select onchange="secCkEdit(\''+key+'\',\''+c.id+'\',\'kind\',this.value)" class="text-[10px] border border-gray-200 rounded px-1.5 py-1 bg-white" style="outline:none">'+SEC_CK_KINDS.map(function(kk){return '<option'+(c.kind===kk?' selected':'')+'>'+kk+'</option>';}).join('')+'</select>'+
        '<input value="'+(c.lat!=null?c.lat:'')+'" onchange="secCkEdit(\''+key+'\',\''+c.id+'\',\'lat\',this.value)" placeholder="lat" class="text-[10px] mono border border-gray-200 rounded px-1.5 py-1" style="outline:none;width:76px">'+
        '<input value="'+(c.lng!=null?c.lng:'')+'" onchange="secCkEdit(\''+key+'\',\''+c.id+'\',\'lng\',this.value)" placeholder="lng" class="text-[10px] mono border border-gray-200 rounded px-1.5 py-1" style="outline:none;width:76px">'+
        '<input value="'+esc(c.hours||'').replace(/"/g,'&quot;')+'" onchange="secCkEdit(\''+key+'\',\''+c.id+'\',\'hours\',this.value)" placeholder="Hours (e.g. 05:00–23:00)" class="text-[10px] border border-gray-200 rounded px-2 py-1" style="outline:none;width:120px">'+
        '<input value="'+esc(c.notes||'').replace(/"/g,'&quot;')+'" onchange="secCkEdit(\''+key+'\',\''+c.id+'\',\'notes\',this.value)" placeholder="Notes — mags, bag check, vehicle sweep…" class="flex-1 min-w-0 text-[10px] border border-gray-200 rounded px-2 py-1" style="outline:none">'+
        '<button onclick="secCkDel(\''+key+'\',\''+c.id+'\')" class="text-gray-300 hover:text-red-500 text-xs flex-shrink-0">✕</button></div>';}).join('');
    return '<div class="bg-white rounded-2xl p-4 sm:p-5 border border-gray-200/60" style="box-shadow:0 4px 20px rgba(0,0,0,.03)">'+
      '<div class="flex flex-wrap items-center justify-between gap-2 mb-3">'+
        '<div><h4 class="text-[10px] font-bold uppercase tracking-wider text-gray-600">Security Checkpoints &amp; Entrances <span class="text-gray-400 font-normal normal-case">— '+sec.checkpoints.length+' mapped · purple pins</span></h4>'+
        '<p class="text-[9px] text-gray-400 mt-0.5">Where crews enter and get screened — pinned on the site map and pushed to the Tech Book automatically.</p></div>'+
        '<button onclick="secCkAdd(\''+key+'\')" class="text-[9px] font-bold text-white bg-gray-900 rounded-lg px-2.5 py-1.5 hover:bg-gray-800">+ Add checkpoint</button></div>'+
      '<div class="rounded-xl overflow-hidden border border-gray-200 bg-gray-50" style="min-height:300px;height:34vh;max-height:420px">'+
        multiMapHTML({id:'secmap_'+key,pins:pins,height:'100%'})+'</div>'+
      (rows?'<div class="mt-2">'+rows+'</div>':'<p class="text-[10px] text-gray-400 text-center py-3">No checkpoints mapped yet — add the main gate, credential pickup and vehicle checkpoint.</p>')+
    '</div>';})();
}

/* ============================================================================
   SITE SURVEY — 360° WALKTHROUGH
   Spin around the venue and drop georeferenced annotations for power drops,
   cable runs, hazards and camera positions — the surveyor's 360 capture with
   the broadcast plant superimposed. Bring your own equirectangular photo
   (Insta360 / Ricoh Theta / phone pano) or use the built-in sample sphere.
   Pins, routed runs, shaded zones, callouts and freehand traces all live in
   sphere coordinates (pitch/yaw), so every mark stays glued to the space.
   Layer toggles, snapshot to PNG, an inline editor, rich walkthrough notes,
   and a markup manifest folded into the Survey Report.
   ========================================================================== */
var PANO_RAD=Math.PI/180;
/* ============================================================================
   MUSE LIVE v37 — 360° WALKTHROUGH on PHOTO SPHERE VIEWER 5.14.3
   ----------------------------------------------------------------------------
   Replaces the v29-v36 Pannellum viewer and its hand-rolled SVG markup layer
   (panoProject / panoRenderMarks / requestAnimationFrame reprojection). PSV owns
   the sphere, the projection and the annotation geometry now, which is what makes
   the richer surfaces possible: real polygon/polyline markers, a virtual tour
   across positions, a thumbnail gallery, a compass, and a venue floor-plan map.

   LOADING — PSV ships NO UMD build and no window global at any version, and the
   three.js it pins (0.184) dropped its UMD at r161. The only supported path is an
   import map + a module script. Both are injected AT RUNTIME, on first open, so
   the host page stays 100% ES5 with zero module scripts at parse time. The import
   map lists EVERY package up front because the first executed module script locks
   it — a second map is ignored outside recent Chrome.

   The module script publishes window.PSV and fires 'psv:ready'; everything after
   that is ordinary ES5 calling through the bridge.
   ========================================================================== */
var PSV_V='5.14.3', PSV_THREE_V='0.184.0', PSV_CDN='https://cdn.jsdelivr.net/npm/';
var _psvState=0, _psvQueue=[];   /* 0 idle · 1 loading · 2 ready */

function psvCss(href){
  if(document.querySelector('link[data-psv="'+href+'"]'))return;
  var l=document.createElement('link');l.rel='stylesheet';l.href=href;l.setAttribute('data-psv',href);
  document.head.appendChild(l);}

function loadPSV(cb){
  /* v42: PSV CDN path retired — native PanoEng only. Keep stub so old call sites no-op cleanly. */
  if(typeof cb==='function')cb('PSV path removed — use native Broadcast 360 Planner (PanoEng)',null);
  return;
  if(_psvState===2){cb(null,window.PSV);return;}
  _psvQueue.push(cb);
  if(_psvState===1)return;
  _psvState=1;
  var P=PSV_CDN+'@photo-sphere-viewer/';
  ['core','markers-plugin','virtual-tour-plugin','gallery-plugin','compass-plugin','map-plugin','settings-plugin']
    .forEach(function(n){psvCss(P+n+'@'+PSV_V+'/index.css');});

  /* Only ONE import map may ever be injected. A second one is ignored outright in
     Safari and Firefox (and only honoured by very recent Chrome), so a retry after a
     failed load must reuse the map already in the document and re-run just the module
     bridge — otherwise "try again" could never work. */
  var alreadyMapped=!!document.getElementById('psv-importmap');
  var im=document.createElement('script');
  im.id='psv-importmap';
  im.type='importmap';
  im.textContent=JSON.stringify({imports:{
    'three':PSV_CDN+'three@'+PSV_THREE_V+'/build/three.module.js',
    '@photo-sphere-viewer/core':P+'core@'+PSV_V+'/index.module.js',
    '@photo-sphere-viewer/markers-plugin':P+'markers-plugin@'+PSV_V+'/index.module.js',
    '@photo-sphere-viewer/virtual-tour-plugin':P+'virtual-tour-plugin@'+PSV_V+'/index.module.js',
    '@photo-sphere-viewer/gallery-plugin':P+'gallery-plugin@'+PSV_V+'/index.module.js',
    '@photo-sphere-viewer/compass-plugin':P+'compass-plugin@'+PSV_V+'/index.module.js',
    '@photo-sphere-viewer/map-plugin':P+'map-plugin@'+PSV_V+'/index.module.js',
    '@photo-sphere-viewer/autorotate-plugin':P+'autorotate-plugin@'+PSV_V+'/index.module.js',
    '@photo-sphere-viewer/settings-plugin':P+'settings-plugin@'+PSV_V+'/index.module.js'
  }});
  if(!alreadyMapped)document.head.appendChild(im);

  /* One-shot: the watchdog and the real event can both fire, and settling twice
     would flip a successful load back to "unreachable" after the fact. */
  var done=false,poll=null;
  var settle=function(err){
    if(done)return;done=true;
    if(poll){clearInterval(poll);poll=null;}   /* never leave the watchdog running */
    if(!err&&!window.PSV)err='360 engine did not publish its bridge';
    _psvState=err?0:2;
    while(_psvQueue.length)_psvQueue.shift()(err,err?null:window.PSV);};
  window.addEventListener('psv:ready',function(){settle(null);},{once:true});
  window.addEventListener('psv:fail',function(e){settle((e&&e.detail)||'load failed');},{once:true});
  /* three.module.js + core + six plugins is ~1.5 MB on a cold cache. A short
     watchdog was declaring failure while the download was still in flight, so it
     is generous, and it checks for a late arrival before giving up. */
  var waited=0;
  poll=setInterval(function(){
    waited+=1500;
    if(window.PSV){settle(null);return;}
    if(waited>=60000)settle('360 engine load timeout — check the network and reopen');
  },1500);

  var m=document.createElement('script');
  m.type='module';
  m.textContent=[
    "try{",
    "  const CORE=await import('@photo-sphere-viewer/core');",
    "  const THREE=await import('three');",
    "  const {MarkersPlugin}=await import('@photo-sphere-viewer/markers-plugin');",
    "  const {VirtualTourPlugin}=await import('@photo-sphere-viewer/virtual-tour-plugin');",
    "  const {GalleryPlugin}=await import('@photo-sphere-viewer/gallery-plugin');",
    "  const {CompassPlugin}=await import('@photo-sphere-viewer/compass-plugin');",
    "  const {MapPlugin}=await import('@photo-sphere-viewer/map-plugin');",
    "  const {AutorotatePlugin}=await import('@photo-sphere-viewer/autorotate-plugin');",
    "  const {SettingsPlugin}=await import('@photo-sphere-viewer/settings-plugin');",
    "  window.PSV={THREE:THREE,Viewer:CORE.Viewer,utils:CORE.utils,events:CORE.events,",
    "    MarkersPlugin:MarkersPlugin,VirtualTourPlugin:VirtualTourPlugin,GalleryPlugin:GalleryPlugin,",
    "    CompassPlugin:CompassPlugin,MapPlugin:MapPlugin,AutorotatePlugin:AutorotatePlugin,",
    "    SettingsPlugin:SettingsPlugin};",
    "  window.dispatchEvent(new CustomEvent('psv:ready'));",
    "}catch(e){window.dispatchEvent(new CustomEvent('psv:fail',{detail:String(e)}));}"
  ].join('\n');
  document.head.appendChild(m);}

/* ---------------------------------------------------------------------------
   DATA MODEL — unchanged on disk. s.pano stays {img, hotspots[], marks[]} so
   every v29-v36 survey keeps its pins, runs, zones, callouts and freehand, and
   the Survey PDF manifest (panoManifestRows) keeps reading the same fields.
   v37 adds s.pano.nodes[] (virtual-tour positions) and s.pano.notes (rich text).
   --------------------------------------------------------------------------- */
function ensurePano(s){
  if(!s.pano)s.pano={img:null,hotspots:[],marks:[]};
  if(!s.pano.hotspots)s.pano.hotspots=[];
  if(!s.pano.marks)s.pano.marks=[];
  if(!s.pano.nodes)s.pano.nodes=[];          /* v37 virtual-tour positions */
  if(s.pano.notes==null)s.pano.notes='';     /* v37 rich walkthrough notes */
  return s.pano;}

/* PSV works in radians; the stored model is Pannellum-era degrees. Convert at the
   boundary only, so the persisted record and the PDF manifest are untouched. */
function psvDeg(v){return (v||0)*Math.PI/180;}
function psvUndeg(rad){return (rad||0)*180/Math.PI;}

/* ---- pin -> PSV marker ---- */
function psvPinMarker(h){
  var T=PANO_TYPES[h.type]||PANO_TYPES.note;
  var label=h.label||T.label;
  var m={id:'pin:'+h.id,
    position:{yaw:psvDeg(h.yaw),pitch:psvDeg(h.pitch)},
    html:'<div class="psv-pin" style="--pc:'+T.color+'"><span class="psv-pin-dot"></span>'+
      '<span class="psv-pin-lbl">'+escHtml(label)+'</span></div>',
    anchor:'bottom center',
    scale:[0.85,1.4],
    tooltip:{content:'<b>'+escHtml(T.label)+'</b>'+(h.label?' — '+escHtml(h.label):'')+
      (h.tag?'<br><span style="opacity:.75">'+escHtml(h.tag)+'</span>':'')+
      (h.detail?'<br>'+escHtml(h.detail):''),position:'top center'},
    data:{kind:'pin',id:h.id,type:h.type},
    compass:T.color};                    /* camera/power pins also draw on the compass */
  return m;}

/* ---- markup -> PSV marker (runs, zones, callouts, freehand) ---- */
function psvMarkMarker(m){
  var col=m.color||'#f5832a';
  var tip=(m.label?'<b>'+escHtml(m.label)+'</b>':'')+(m.detail?(m.label?'<br>':'')+escHtml(m.detail):'');
  if(m.kind==='zone'){
    /* a circular zone becomes a real spherical polygon — PSV keeps it glued to the
       sphere at every zoom, which the old hand-projected SVG could not */
    var pts=[],N=48,rr=psvDeg(m.radius||8),cp=psvDeg(m.pitch),cy=psvDeg(m.yaw);
    for(var i=0;i<N;i++){var a=i/N*Math.PI*2;
      var latP=Math.asin(Math.max(-1,Math.min(1,Math.sin(cp)*Math.cos(rr)+Math.cos(cp)*Math.sin(rr)*Math.cos(a))));
      var lonY=cy+Math.atan2(Math.sin(a)*Math.sin(rr)*Math.cos(cp),Math.cos(rr)-Math.sin(cp)*Math.sin(latP));
      pts.push([lonY,latP]);}
    return {id:'mark:'+m.id,polygon:pts,
      svgStyle:{fill:psvAlpha(col,0.22),stroke:col,strokeWidth:'2px'},
      tooltip:tip||'Zone',data:{kind:'mark',id:m.id,markKind:'zone'}};}
  if(m.kind==='run'||m.kind==='free'){
    var line=(m.pts||[]).map(function(p){return [psvDeg(p[1]),psvDeg(p[0])];});
    if(line.length<2)return null;
    return {id:'mark:'+m.id,polyline:line,
      svgStyle:{stroke:col,strokeWidth:(m.kind==='run'?'4px':'3px'),strokeLinecap:'round',strokeLinejoin:'round',
        strokeDasharray:(m.kind==='free'?'':'')},
      tooltip:tip||(m.kind==='run'?'Routed run':'Freehand'),
      data:{kind:'mark',id:m.id,markKind:m.kind}};}
  if(m.kind==='callout'){
    return {id:'mark:'+m.id,
      position:{yaw:psvDeg(m.yaw),pitch:psvDeg(m.pitch)},
      html:'<div class="psv-callout" style="--pc:'+col+'">'+escHtml(m.label||'Callout')+'</div>',
      anchor:'bottom left',
      tooltip:tip||'Callout',
      data:{kind:'mark',id:m.id,markKind:'callout'}};}
  return null;}

function psvAlpha(hex,a){
  var h=String(hex||'#f5832a').replace('#','');
  if(h.length===3)h=h[0]+h[0]+h[1]+h[1]+h[2]+h[2];
  var n=parseInt(h,16);
  return 'rgba('+((n>>16)&255)+','+((n>>8)&255)+','+(n&255)+','+a+')';}

function psvAllMarkers(P){
  var out=[],i,mk;
  for(i=0;i<P.hotspots.length;i++){
    if(pano.hidden&&pano.hidden[P.hotspots[i].type])continue;
    out.push(psvPinMarker(P.hotspots[i]));}
  for(i=0;i<P.marks.length;i++){
    if(pano.hidden&&pano.hidden[P.marks[i].kind])continue;
    mk=psvMarkMarker(P.marks[i]);if(mk)out.push(mk);}
  return out;}

/* ============================================================================
   v37 360° — viewer lifecycle, tools, tour, gallery, snapshot, notes
   ========================================================================== */
function openPanoViewer(key){
  /* v42: NATIVE Broadcast 360 Planner only — pure WebGL in pano-engine.js.
     Wave B: engine is lazy-loaded via MuseLazy on first open. */
  try{if(typeof ensurePano==='function')ensurePano(getSurvey(key));}catch(e){}
  function bootNative(){
    if(typeof PanoEng!=='undefined'&&PanoEng.open){
      pano.key=key;pano.open=true;
      try{var leg=document.getElementById('panoOverlay');if(leg)leg.style.display='none';}catch(e0){}
      PanoEng.open({key:key});
      return true;}
    return false;}
  if(bootNative())return;
  toast&&toast('Loading 360 planner…');
  function afterPano(eng){
    if(eng&&eng.open){bootNative();return;}
    if(!bootNative())toast&&toast('360 planner loaded but failed to start — pull to refresh');
  }
  if(typeof MuseLazy!=='undefined'&&MuseLazy.ensurePano){
    MuseLazy.ensurePano().then(afterPano).catch(function(){
      museInjectEngine('js/pano-engine.js','PanoEng',afterPano,'Could not load 360 planner. Pull to refresh.');
    });
    return;
  }
  museInjectEngine('js/pano-engine.js','PanoEng',afterPano,'Could not load 360 planner. Pull to refresh.');
}

function panoMountPSV(PSV,P){
  var host=document.getElementById('panoCanvas');
  if(!host)return;
  host.innerHTML='';
  panoDestroy();
  var nodes=panoTourNodes(P);
  var plugins=[
    PSV.MarkersPlugin.withConfig({defaultHoverScale:{amount:1.15,duration:120}, markers:[]}),
    PSV.CompassPlugin.withConfig({size:'104px',position:'top left',navigation:true,
      coneColor:'rgba(8,102,255,.35)',hotspots:[]}),
    [PSV.AutorotatePlugin,{autostartDelay:null,autorotateSpeed:'0.6rpm',autorotatePitch:'3deg'}],
    PSV.SettingsPlugin
  ];
  /* a floor plan turns the sphere into a wayfinding tool — reuse the venue's own
     CAD sheet when the survey has one, so the 360 and the drawings agree */
  var planImg=panoPlanImage();
  if(planImg)plugins.push(PSV.MapPlugin.withConfig({
    imageUrl:planImg,center:{x:1000,y:750},size:'240px',position:'bottom left',
    shape:'square',minZoom:40,maxZoom:220,
    spotStyle:{size:15,color:'#0866ff',hoverSize:21,borderSize:2,borderColor:'#ffffff'}}));
  if(nodes.length>1){
    plugins.push(PSV.GalleryPlugin.withConfig({thumbnailSize:{width:130,height:74},
      hideOnClick:false,navigationArrows:true}));
    plugins.push(PSV.VirtualTourPlugin.withConfig({
      positionMode:'manual',renderMode:'3d',nodes:nodes,
      startNodeId:(pano.node||nodes[0].id),linksOnCompass:true,preload:true}));}

  var cfg={container:host,
    caption:panoCaption(),
    navbar:['zoom','move','markers','caption','fullscreen'],
    defaultZoomLvl:42,minFov:12,maxFov:110,
    loadingTxt:'Loading the sphere…',
    mousewheelCtrlKey:false,touchmoveTwoFingers:false,
    plugins:plugins};
  if(nodes.length<=1)cfg.panorama=panoSrc(P);

  try{pano.viewer=new PSV.Viewer(cfg);}
  catch(e){panoStatus('Could not initialise the panorama: '+(e&&e.message||e));return;}
  pano.psv=PSV;
  pano.markers=pano.viewer.getPlugin(PSV.MarkersPlugin);
  pano.tour=nodes.length>1?pano.viewer.getPlugin(PSV.VirtualTourPlugin):null;

  pano.viewer.addEventListener('ready',function(){panoStatus('');panoSync();},{once:true});
  /* Do not leave "Loading…" on screen forever if the sphere is slow or the tab was
     backgrounded while it loaded — the annotations are already usable at that point. */
  setTimeout(function(){
    if(pano.viewer&&/Loading/.test((document.getElementById('panoStatus')||{}).textContent||''))panoStatus('');
  },6000);
  pano.viewer.addEventListener('panorama-error',function(e){
    panoStatus('That panorama could not be displayed'+(e&&e.error?' — '+escHtml(String(e.error)):''));});
  /* clicks place whatever tool is armed; with no tool armed a click just deselects */
  pano.viewer.addEventListener('click',function(e){panoPlaceAt(e.data);});
  pano.markers.addEventListener('select-marker',function(e){panoPickMarker(e.marker,e);});
  pano.markers.addEventListener('unselect-marker',function(){panoCloseEditor();});
  if(pano.tour)pano.tour.addEventListener('node-changed',function(e){
    pano.node=e.node&&e.node.id;panoSync();});
  panoSync();}

function panoDestroy(){
  if(pano.viewer){try{pano.viewer.destroy();}catch(e){}}
  pano.viewer=null;pano.markers=null;pano.tour=null;}

function closePanoViewer(){
  /* v41: native engine owns the overlay — always close it; legacy PSV path is dead */
  try{if(typeof PanoEng!=='undefined'&&PanoEng.close)PanoEng.close(true);}catch(e){}
  try{panoNotesFlush();}catch(e){}
  try{panoDestroy();}catch(e){}
  try{var ov=document.getElementById('panoOverlay');if(ov)ov.style.display='none';}catch(e2){}
  document.body.style.overflow='';
  pano.open=false;
  var ov=document.getElementById('panoOverlay');if(ov)ov.style.display='none';
  document.body.style.overflow='';
  pano.tool=null;pano.sel=null;pano.runDraft=null;
  if(pano.key)try{renderProjectView(pano.key);}catch(e){}}

/* push the whole annotation set at PSV in one go */
function panoSync(){
  if(!pano.markers)return;
  var P=panoData();
  try{pano.markers.setMarkers(psvAllMarkers(P));}catch(e){}
  panoCompassSync();panoRenderLayers();panoSyncToolbar();panoCountSync();}

function panoCountSync(){
  var P=panoData();var el=document.getElementById('panoCount');
  if(el)el.textContent=(P.hotspots.length+P.marks.length)+' items'+
    (P.nodes&&P.nodes.length>1?' · '+P.nodes.length+' positions':'');}

function panoCompassSync(){
  if(!pano.viewer||!pano.psv)return;
  try{
    var cp=pano.viewer.getPlugin(pano.psv.CompassPlugin);if(!cp)return;
    var P=panoData();var hs=[];
    for(var i=0;i<P.hotspots.length;i++){var h=P.hotspots[i];
      if(pano.hidden&&pano.hidden[h.type])continue;
      hs.push({yaw:psvDeg(h.yaw),color:(PANO_TYPES[h.type]||PANO_TYPES.note).color});}
    cp.setHotspots(hs);
  }catch(e){}}

function panoCaption(){
  var p=pano.key&&productions[pano.key];
  var L=(pano.key&&typeof activeLocation==='function')?activeLocation(pano.key):null;
  return escHtml((L&&L.name)||(p&&p.venue)||(p&&p.name)||'Site survey')+' — 360° walkthrough';}

/* the venue floor plan for the MapPlugin: prefer a real CAD sheet render */
function panoPlanImage(){
  try{
    var plans=getCadPlans(pano.key)||[];
    for(var i=0;i<plans.length;i++){var im=cadPlanImg(plans[i]);if(im)return im;}
  }catch(e){}
  return null;}

/* ---- virtual tour: each capture position is a node ---- */
function panoTourNodes(P){
  var out=[];
  if(!P.nodes||!P.nodes.length)return out;
  for(var i=0;i<P.nodes.length;i++){
    var n=P.nodes[i];if(!n.img)continue;
    var links=[];
    for(var j=0;j<P.nodes.length;j++){
      if(j===i||!P.nodes[j].img)continue;
      links.push({nodeId:P.nodes[j].id,position:{yaw:psvDeg(n.linkYaw!=null?n.linkYaw:(j*60)),pitch:psvDeg(-8)}});}
    out.push({id:n.id,panorama:n.img,thumbnail:n.img,name:n.name||('Position '+(i+1)),
      caption:escHtml(n.name||''),links:links,showInGallery:true,
      markers:(i===0?psvAllMarkers(P):[])});}
  return out;}

/* ---------------------------------------------------------------------------
   placing annotations — PSV hands us yaw/pitch in RADIANS; the stored model is
   in degrees, so convert at this single boundary.
   --------------------------------------------------------------------------- */
function panoPlaceAt(d){
  if(!d)return;
  var yaw=psvUndeg(d.yaw),pitch=psvUndeg(d.pitch);
  var t=pano.tool;
  if(!t){if(pano.sel){pano.sel=null;panoCloseEditor();}return;}
  var P=panoData();
  if(PIN_SET[t]){
    var h={id:panoId(),type:t,yaw:yaw,pitch:pitch,label:'',detail:'',tag:''};
    P.hotspots.push(h);stampEdit(pano.key);
    pano.tool=null;panoSync();panoOpenEditor('pin',h.id);return;}
  if(t==='run'){
    if(!pano.runDraft)pano.runDraft={id:panoId(),kind:'run',pts:[],color:PANO_TOOLS.run.color,label:'',detail:''};
    pano.runDraft.pts.push([pitch,yaw]);
    panoDraftPreview();
    panoStatus(pano.runDraft.pts.length+' point'+(pano.runDraft.pts.length===1?'':'s')+' — SPACEBAR or ⏎ finishes, Esc cancels');
    return;}
  if(t==='zone'){
    var z={id:panoId(),kind:'zone',pitch:pitch,yaw:yaw,radius:8,color:PANO_TOOLS.zone.color,label:'',detail:''};
    P.marks.push(z);stampEdit(pano.key);pano.tool=null;panoSync();panoOpenEditor('mark',z.id);return;}
  if(t==='callout'){
    var co={id:panoId(),kind:'callout',pitch:pitch,yaw:yaw,color:PANO_TOOLS.callout.color,label:'Callout',detail:''};
    P.marks.push(co);stampEdit(pano.key);pano.tool=null;panoSync();panoOpenEditor('mark',co.id);return;}
  if(t==='free'){
    /* freehand is click-to-trace on a sphere — dragging would fight PSV's own
       rotation gesture, so it uses the same waypoint model as a routed run */
    if(!pano.freeDraft)pano.freeDraft={id:panoId(),kind:'free',pts:[],color:(pano.freeColor||PANO_TOOLS.free.color),label:'',detail:''};
    pano.freeDraft.pts.push([pitch,yaw]);
    panoDraftPreview();
    panoStatus(pano.freeDraft.pts.length+' points — SPACEBAR or ⏎ finishes, Esc cancels');
    return;}}

/* live preview of the in-progress run/freehand */
function panoDraftPreview(){
  if(!pano.markers)return;
  var d=pano.runDraft||pano.freeDraft;
  try{pano.markers.removeMarker('draft');}catch(e){}
  if(!d||d.pts.length<1)return;
  if(d.pts.length===1){
    try{pano.markers.addMarker({id:'draft',
      position:{yaw:psvDeg(d.pts[0][1]),pitch:psvDeg(d.pts[0][0])},
      circle:7,svgStyle:{fill:d.color,stroke:'#ffffff','stroke-width':'2px'},
      tooltip:'Start point'});}catch(e){}
    return;}
  try{pano.markers.addMarker({id:'draft',
    polyline:d.pts.map(function(p){return [psvDeg(p[1]),psvDeg(p[0])];}),
    svgStyle:{stroke:d.color,strokeWidth:'4px',strokeLinecap:'round',strokeDasharray:'8 6'},
    tooltip:'In progress — SPACEBAR finishes'});}catch(e){}}

function panoRunFinish(){
  var d=pano.runDraft||pano.freeDraft;
  pano.runDraft=null;pano.freeDraft=null;
  try{if(pano.markers)pano.markers.removeMarker('draft');}catch(e){}
  pano.tool=null;panoStatus('');
  if(!d||d.pts.length<2){panoSync();return;}
  panoData().marks.push(d);stampEdit(pano.key);
  panoSync();panoOpenEditor('mark',d.id);}
function panoRunCancel(){
  if(!pano.runDraft&&!pano.freeDraft)return false;
  pano.runDraft=null;pano.freeDraft=null;
  try{if(pano.markers)pano.markers.removeMarker('draft');}catch(e){}
  pano.tool=null;panoStatus('');panoSyncToolbar();panoSync();return true;}

/* ---- selection ---- */
function panoPickMarker(m,ev){
  if(!m||!m.data)return;
  if(m.id==='draft')return;
  pano.sel=m.data.id;
  if(ev&&ev.doubleClick){panoDeleteSel();return;}
  panoOpenEditor(m.data.kind==='pin'?'pin':'mark',m.data.id);}

function panoFocusItem(kind,id){
  if(!pano.markers)return;
  try{pano.markers.gotoMarker((kind==='pin'?'pin:':'mark:')+id,'3rpm');}catch(e){}}

/* ---- snapshot ----
   The PSV renderer runs with preserveDrawingBuffer:false, so the back buffer is
   already gone by the time toDataURL runs on a later tick. Force a synchronous
   draw on the same tick. (The documented render-event demo does not fire when the
   scene is idle.) Also: never querySelector('canvas') here — the compass adds a
   second one. */
function panoSnapshotData(type,quality){
  if(!pano.viewer)return null;
  try{
    var r=pano.viewer.renderer;
    r.renderer.render(r.scene,r.camera);
    return r.renderer.domElement.toDataURL(type||'image/png',quality);
  }catch(e){return null;}}
function panoSnapshot(){
  var url=panoSnapshotData('image/png');
  if(!url){panoStatus('Nothing to capture yet');return;}
  var a=document.createElement('a');
  a.href=url;a.download='360-walkthrough-'+(pano.key||'view')+'-'+Date.now().toString(36)+'.png';
  document.body.appendChild(a);a.click();document.body.removeChild(a);
  panoStatus('Snapshot saved');setTimeout(function(){panoStatus('');},1800);}

/* ---- multi-position capture (virtual tour) ---- */
function panoAddNode(e){
  var f=e.target.files&&e.target.files[0];if(!f||!pano.key)return;
  e.target.value='';
  var r=new FileReader();
  r.onload=function(){
    var P=panoData();
    var name=prompt('Name this capture position:','Position '+(P.nodes.length+1));
    if(name==null)return;
    P.nodes.push({id:'n'+Date.now().toString(36),name:name||('Position '+(P.nodes.length+1)),img:r.result});
    if(!P.img)P.img=r.result;
    stampEdit(pano.key);
    toast&&toast('Position added — the walkthrough now links '+P.nodes.length+' spheres');
    openPanoViewer(pano.key);        /* rebuild: the tour plugin is configured at construction */
  };
  r.readAsDataURL(f);}

/* ---- walkthrough notes (rich text, bottom of the overlay) ---- */
function panoNotesMount(){
  var box=document.getElementById('panoNotesBox');if(!box)return;
  var P=panoData();
  box.innerHTML=museRichBox({id:'panoNotes',value:P.notes||'',toolbar:'note',height:'92px',
    placeholder:'Walkthrough notes — access, rigging points, sightlines, hazards, who walked it and when…',
    onchange:'function(v){panoNotesSet(v)}'});
  if(typeof mountRichBoxes==='function')mountRichBoxes(box);}
function panoNotesSet(v){
  if(!pano.key)return;
  var P=panoData();P.notes=v;stampEdit(pano.key);}
function panoNotesFlush(){
  if(!pano.key)return;
  try{var v=museRichGet('panoNotes');if(v!=null)panoNotesSet(v);}catch(e){}}
function panoNotesToggle(){
  var w=document.getElementById('panoNotesWrap');if(!w)return;
  var on=w.style.display==='none';
  w.style.display=on?'block':'none';
  if(on)panoNotesMount();else panoNotesFlush();
  var b=document.getElementById('panoNotesBtn');if(b)b.classList.toggle('on',on);}


/* keep the WebGL drawing buffer so snapshots (toDataURL) actually contain pixels */

/* pin marker types (native Pannellum hotspots) */
var PANO_TYPES={
  power:{label:'Power drop',color:'#f5832a'},
  cable:{label:'Cable run',color:'#e41e3f'},
  hazard:{label:'Hazard',color:'#e41e3f'},
  camera:{label:'Camera position',color:'#0866ff'},
  note:{label:'Note',color:'#1E7B34'}};
/* markup tools + shared swatch palette */
var PANO_TOOLS={
  run:{label:'Run',color:'#0866ff'},
  zone:{label:'Zone',color:'#0866ff'},
  callout:{label:'Callout',color:'#f5832a'},
  free:{label:'Draw',color:'#f7b928'}};
var PANO_SWATCHES=['#f5832a','#e41e3f','#0866ff','#0866ff','#1E7B34','#0866ff','#e41e3f','#f0f2f5'];
var PIN_SET={power:1,cable:1,hazard:1,camera:1,note:1};

var pano={open:false,key:null,viewer:null,psv:null,markers:null,tour:null,node:null,
  tool:null,sel:null,editKind:null,runDraft:null,freeDraft:null,hidden:{},
  layersOpen:false,freeColor:null};

function panoId(){return 'h'+Date.now().toString(36)+Math.floor(Math.random()*1296).toString(36);}
function panoSrc(p){return p.img||(typeof SAMPLE_PANO!=='undefined'?SAMPLE_PANO:'');}
function escHtml(s){return (''+s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');}
function panoData(){return pano.key?ensurePano(getSurvey(pano.key)):{hotspots:[],marks:[]};}
function panoStatus(t){var st=document.getElementById('panoStatus');if(st)st.textContent=t||'';}

/* ---------- open / mount ---------- */

/* ---------- coordinate helpers ---------- */
/* project a sphere point (pitch,yaw in deg) to screen pixels for the current view */
/* geodesic circle: N points at angular radius (deg) around a centre — projects to an accurate blob */

/* ---------- keyboard ----------
   SPACEBAR / Enter completes an in-progress routed run or freehand trace; Esc backs
   out one level at a time (draft -> tool -> selection -> close) rather than nuking
   the whole session on the first press. Typing inside the notes editor is exempt. */
document.addEventListener('keydown',function(e){
  if(!pano.open)return;
  var t=e.target;
  if(t&&(/INPUT|TEXTAREA|SELECT/.test(t.tagName)||t.isContentEditable))return;
  if((e.key===' '||e.code==='Space'||e.key==='Enter')&&(pano.runDraft||pano.freeDraft)){
    e.preventDefault();panoRunFinish();return;}
  if(e.key==='Escape'){
    if(panoRunCancel())return;
    if(pano.tool){pano.tool=null;panoSyncToolbar();panoStatus('');return;}
    if(pano.sel){panoCloseEditor();return;}
    closePanoViewer();return;}});

/* ---------- freehand (overlay captures the stroke) ---------- */

/* ---------- pins (native Pannellum hotspots) ---------- */

/* ---------- SVG markup render loop ---------- */

/* ---------- tools / pointer policy ---------- */
function panoSetTool(id){
  if(pano.runDraft&&id!=='run')panoRunCancel();
  pano.tool=(pano.tool===id?null:id);
  if(pano.tool!=='run'){pano.runDraft=null;pano.cursor=null;}
  pano.sel=null;panoCloseEditor();panoSyncToolbar();
  if(PIN_SET[pano.tool])panoStatus('Click the view to drop a '+PANO_TYPES[pano.tool].label.toLowerCase());
  else if(pano.tool==='run')panoStatus('Routed run: click points along the path — SPACEBAR to complete (double-click / Finish also work)');
  else if(pano.tool==='zone')panoStatus('Click the view to shade a zone, then size it in the editor');
  else if(pano.tool==='callout')panoStatus('Click the thing you want to call out');
  else if(pano.tool==='free')panoStatus('Click along the path — SPACEBAR completes it');
  else panoStatus('');}
function panoSyncToolbar(){var ov=document.getElementById('panoOverlay');if(!ov)return;
  var btns=ov.querySelectorAll('[data-pano-tool]');for(var i=0;i<btns.length;i++){btns[i].classList.toggle('on',btns[i].getAttribute('data-pano-tool')===pano.tool);}
  var P=panoData();var n=P.hotspots.length+P.marks.length;
  var cnt=document.getElementById('panoCount');if(cnt)cnt.textContent=n+' item'+(n===1?'':'s');
  var rb=document.getElementById('panoRunbar');if(rb)rb.style.display=pano.runDraft?'flex':'none';}

/* ---------- inline editor ---------- */
function panoFindMark(id){var P=panoData();for(var i=0;i<P.marks.length;i++)if(P.marks[i].id===id)return P.marks[i];return null;}
function panoFindPin(id){var P=panoData();for(var i=0;i<P.hotspots.length;i++)if(P.hotspots[i].id===id)return P.hotspots[i];return null;}
function panoSelectMark(id){pano.sel=id;pano.tool=null;panoSyncToolbar();panoOpenEditor('mark',id);panoFocusItem('mark',id);}
function panoOpenEditor(kind,id){var obj=kind==='pin'?panoFindPin(id):panoFindMark(id);if(!obj)return;
  pano.sel=id;pano.editKind=kind;var box=document.getElementById('panoEditor');if(!box)return;
  var title=kind==='pin'?((PANO_TYPES[obj.type]||{}).label||'Pin'):({run:'Routed run',zone:'Zone',callout:'Callout',free:'Freehand highlight'}[obj.kind]||'Markup');
  var swatches='';
  if(kind==='mark'){swatches='<div class="pano-ed-row"><span class="pano-ed-lbl">Colour</span><div class="pano-swatches">'+
    PANO_SWATCHES.map(function(c){return '<button class="pano-sw'+(((obj.color||'').toLowerCase()===c.toLowerCase())?' on':'')+'" style="background:'+c+'" onclick="panoEdColor(\''+c+'\')"></button>';}).join('')+'</div></div>';}
  var radius='';
  if(kind==='mark'&&obj.kind==='zone'){radius='<div class="pano-ed-row"><span class="pano-ed-lbl">Radius</span><input type="range" min="3" max="40" value="'+(obj.radius||8)+'" oninput="panoEdRadius(this.value)" class="pano-range"><span id="panoRadVal" class="pano-ed-val">'+(obj.radius||8)+'°</span></div>';}
  /* v29 (Module 6): hazard pins carry the same broadcast hazard vocabulary as the Survey Log */
  var tagRow='';
  if(kind==='pin'&&obj.type==='hazard'&&typeof SURV_TAGS!=='undefined'){
    tagRow='<div class="pano-ed-row"><span class="pano-ed-lbl">Hazard</span><select class="pano-ed-inp" style="cursor:pointer" onchange="panoEdField(\'tag\',this.value)"><option value="">— tag —</option>'+
      SURV_TAGS.map(function(t){return '<option'+(obj.tag===t?' selected':'')+'>'+t+'</option>';}).join('')+'</select></div>';}
  box.innerHTML='<div class="pano-ed-head"><span class="pano-ed-title">'+escHtml(title)+'</span><button class="pano-ed-x" onclick="panoCloseEditor()">✕</button></div>'+
    '<div class="pano-ed-row"><span class="pano-ed-lbl">Label</span><input id="panoEdLabel" class="pano-ed-inp" value="'+escHtml(obj.label||'').replace(/"/g,'&quot;')+'" placeholder="Short label" oninput="panoEdField(\'label\',this.value)"></div>'+
    tagRow+
    '<div class="pano-ed-row pano-ed-col"><span class="pano-ed-lbl">Detail</span>'+
      museRichBox({id:'panoed_'+obj.id,value:obj.detail||'',toolbar:'slim',height:'58px',placeholder:'Notes / spec',onchange:'function(v){panoEdField(\'detail\',v)}'})+'</div>'+
    swatches+radius+
    '<div class="pano-ed-foot"><button class="pano-ed-del" onclick="panoDeleteSel()">Delete</button><button class="pano-ed-done" onclick="panoCloseEditor()">Done</button></div>';
  box.style.display='block';
  if(typeof mountRichBoxes==='function')mountRichBoxes(box);}
function panoCloseEditor(){var box=document.getElementById('panoEditor');if(box)box.style.display='none';pano.sel=null;}
function panoEdField(f,v){var o=pano.editKind==='pin'?panoFindPin(pano.sel):panoFindMark(pano.sel);if(!o)return;o[f]=v;stampEdit(pano.key);
  panoSync();}
function panoEdColor(c){var o=panoFindMark(pano.sel);if(!o)return;o.color=c;stampEdit(pano.key);panoOpenEditor('mark',o.id);panoSync();}
function panoEdRadius(v){var o=panoFindMark(pano.sel);if(!o)return;o.radius=parseInt(v,10)||8;var rv=document.getElementById('panoRadVal');if(rv)rv.textContent=o.radius+'°';stampEdit(pano.key);panoSync();}
function panoDeleteSel(){var id=pano.sel;if(!id)return;var P=panoData();
  if(pano.editKind==='pin')P.hotspots=P.hotspots.filter(function(x){return x.id!==id;});
  else P.marks=P.marks.filter(function(x){return x.id!==id;});
  pano.sel=null;stampEdit(pano.key);panoCloseEditor();panoSync();}

/* ---------- layers ---------- */
function panoToggleLayers(){pano.layersOpen=!pano.layersOpen;panoRenderLayers();}
function panoLayerRows(){var P=panoData();var rows=[];
  var pc={};P.hotspots.forEach(function(h){pc[h.type]=(pc[h.type]||0)+1;});
  var mc={};P.marks.forEach(function(m){mc[m.kind]=(mc[m.kind]||0)+1;});
  Object.keys(PANO_TYPES).forEach(function(t){rows.push({key:t,color:PANO_TYPES[t].color,label:PANO_TYPES[t].label,n:pc[t]||0});});
  [['run','Runs',PANO_TOOLS.run.color],['zone','Zones',PANO_TOOLS.zone.color],['callout','Callouts',PANO_TOOLS.callout.color],['free','Freehand',PANO_TOOLS.free.color]].forEach(function(a){rows.push({key:a[0],color:a[2],label:a[1],n:mc[a[0]]||0});});
  return rows;}
function panoRenderLayers(){var box=document.getElementById('panoLayers');if(!box)return;
  box.style.display=pano.layersOpen?'block':'none';if(!pano.layersOpen)return;
  var rows=panoLayerRows().map(function(r){var hidden=!!pano.hidden[r.key];
    return '<button class="pano-layer'+(hidden?' off':'')+'" onclick="panoToggleLayer(\''+r.key+'\')">'+
      '<span class="pano-layer-dot" style="background:'+r.color+'"></span>'+
      '<span class="pano-layer-name">'+escHtml(r.label)+'</span>'+
      '<span class="pano-layer-n">'+r.n+'</span>'+
      '<span class="pano-eye">'+(hidden?panoEyeOff():panoEyeOn())+'</span></button>';}).join('');
  box.innerHTML='<div class="pano-layers-head">Layers</div>'+rows;}
function panoToggleLayer(k){pano.hidden[k]=!pano.hidden[k];panoSync();}
function panoEyeOn(){return '<svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M1 12s4-7 11-7 11 7 11 7-4 7-11 7-11-7-11-7z"/><circle cx="12" cy="12" r="3"/></svg>';}
function panoEyeOff(){return '<svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M17.94 17.94A10.07 10.07 0 0112 20c-7 0-11-8-11-8a18.45 18.45 0 015.06-5.94M9.9 4.24A9.12 9.12 0 0112 4c7 0 11 8 11 8a18.5 18.5 0 01-2.16 3.19m-6.72-1.07a3 3 0 11-4.24-4.24"/><line x1="1" y1="1" x2="23" y2="23"/></svg>';}

/* ---------- snapshot (compose WebGL canvas + SVG overlay -> PNG) ---------- */

/* ---------- overlay chrome ---------- */
function panoToolIcon(t){var I={
  run:'<svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M4 20 L10 8 L15 16 L20 5"/></svg>',
  zone:'<svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><circle cx="12" cy="12" r="8"/></svg>',
  callout:'<svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M4 4h16v11H9l-4 4v-4H4z"/></svg>',
  free:'<svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M3 21c3-1 5-4 7-8 1-2 3-3 4-1s0 4 2 4 3-3 4-5"/></svg>',
  layers:'<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M12 3 2 9l10 6 10-6-10-6z"/><path d="M2 15l10 6 10-6"/></svg>',
  camera:'<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M23 19a2 2 0 0 1-2 2H3a2 2 0 0 1-2-2V8a2 2 0 0 1 2-2h4l2-3h6l2 3h4a2 2 0 0 1 2 2z"/><circle cx="12" cy="13" r="4"/></svg>'};
  return I[t]||'';}
function panoBuildOverlay(){if(document.getElementById('panoOverlay'))return;
  var ov=document.createElement('div');ov.id='panoOverlay';ov.className='pano-overlay';
  var pinBtns=Object.keys(PANO_TYPES).map(function(t){var T=PANO_TYPES[t];
    return '<button class="pano-tbtn" data-pano-tool="'+t+'" onclick="panoSetTool(\''+t+'\')" title="Drop a '+T.label+'"><span class="pano-dot" style="background:'+T.color+'"></span>'+T.label+'</button>';}).join('');
  var drawBtns=Object.keys(PANO_TOOLS).map(function(t){var T=PANO_TOOLS[t];
    return '<button class="pano-tbtn" data-pano-tool="'+t+'" onclick="panoSetTool(\''+t+'\')" title="'+T.label+'">'+panoToolIcon(t)+T.label+'</button>';}).join('');
  ov.innerHTML=
    '<div class="pano-topbar">'+
      '<div class="cadv-group"><span class="cadv-title">360° Walkthrough</span><span class="cadv-meta" id="panoCount">0 items</span></div>'+
      '<div class="cadv-group pano-tools" title="Pins">'+pinBtns+'</div>'+
      '<div class="cadv-group pano-tools pano-tools-draw" title="Markup">'+drawBtns+'</div>'+
      '<div class="cadv-group">'+
        '<button class="cadv-btn" onclick="panoToggleLayers()" title="Layers">'+panoToolIcon('layers')+'</button>'+
        '<button class="cadv-btn" id="panoNotesBtn" onclick="panoNotesToggle()" title="Walkthrough notes">Notes</button>'+
        '<button class="cadv-btn" onclick="panoSnapshot()" title="Snapshot (PNG)">'+panoToolIcon('camera')+'</button>'+
        '<label class="cadv-btn" style="cursor:pointer" title="Replace the current sphere">Upload<input type="file" accept="image/*" onchange="panoUpload(event)" style="display:none"></label>'+
        '<label class="cadv-btn" style="cursor:pointer" title="Add another capture position — two or more turns this into a walkthrough tour with a gallery">+ Position<input type="file" accept="image/*" onchange="panoAddNode(event)" style="display:none"></label>'+
        '<span id="panoStatus" class="pano-status"></span>'+
        '<button class="cadv-btn cadv-close" onclick="closePanoViewer()" title="Close">✕</button>'+
      '</div>'+
    '</div>'+
    '<div class="pano-stage" id="panoStage">'+
      '<div class="pano-canvas" id="panoCanvas"></div>'+
      '<div class="pano-runbar" id="panoRunbar" style="display:none"><span>Routed run in progress</span><button class="pano-runbtn ok" onclick="panoRunFinish()">Finish</button><button class="pano-runbtn" onclick="panoRunCancel()">Cancel</button></div>'+
      '<div class="pano-layers" id="panoLayers" style="display:none"></div>'+
      '<div class="pano-editor" id="panoEditor" style="display:none"></div>'+
    '</div>'+
    '<div class="pano-notes-wrap" id="panoNotesWrap" style="display:none"><div id="panoNotesBox"></div></div>'+
    '<div class="pano-hint">Drag to look around · scroll to zoom · pick a tool, then click on the sphere · click any pin or run to edit · Notes writes up the walk</div>';
  document.body.appendChild(ov);}

/* ---------- uploads ---------- */
function panoUpload(e){var f=e.target.files&&e.target.files[0];if(!f||!pano.key)return;var r=new FileReader();
  r.onload=function(){var P=panoData();P.img=r.result;stampEdit(pano.key);
    if(!P.nodes.length)P.nodes.push({id:'n'+Date.now().toString(36),name:'Position 1',img:r.result});
    else P.nodes[0].img=r.result;
    openPanoViewer(pano.key);toast&&toast('360° panorama loaded');};
  r.readAsDataURL(f);}
function panoUploadFromPane(key,e){var f=e.target.files&&e.target.files[0];if(!f)return;
  /* Open planner then hand the File to the engine (auto-downscales 32k panoramas for WebGL) */
  openPanoViewer(key);
  setTimeout(function(){
    try{
      if(typeof PanoEng!=='undefined'&&typeof PanoEng.loadFile==='function'){
        PanoEng.loadFile(f);
        toast&&toast('Loading 360° — huge files auto-downscale for GPU…');
        return;
      }
    }catch(err){}
    toast&&toast('Open 360 planner and use 📂 Load 360° (prefer JPEG ≤8k wide)');
  },120);}

/* ---------- survey pane card ---------- */
function panoPaneHTML(key){var s=getSurvey(key);var p=ensurePano(s);
  var byType={};p.hotspots.forEach(function(h){var t=h.type||h.kind||'note';byType[t]=(byType[t]||0)+1;});
  var chips=Object.keys(PANO_TYPES).map(function(t){var T=PANO_TYPES[t];var n=byType[t]||0;
    return '<span class="inline-flex items-center gap-1 text-[9px] font-semibold text-gray-600"><span class="w-2 h-2 rounded-full" style="background:'+T.color+'"></span>'+T.label+' <b class="mono">'+n+'</b></span>';}).join('');
  /* also count broadcast planner types not in the legacy pin set */
  var extra=['fiber','rf','ifb','truck','talent','exit','equipment','mic','shape','text','power','cable','camera','hazard'];
  extra.forEach(function(t){if(byType[t]&&!PANO_TYPES[t]){
    chips+='<span class="inline-flex items-center gap-1 text-[9px] font-semibold text-gray-600"><span class="w-2 h-2 rounded-full" style="background:#0866ff"></span>'+t+' <b class="mono">'+byType[t]+'</b></span>';}});
  var hasOwn=!!p.img;var nMark=p.hotspots.length+(p.marks?p.marks.length:0);
  var thumb=panoSrc(p);
  var preview='<div onclick="openPanoViewer(\''+key+'\')" class="relative rounded-xl overflow-hidden border border-gray-200 cursor-pointer group" style="aspect-ratio:2/1;background:linear-gradient(135deg,#18191A 0%,#1c1e21 50%,#242526 100%)">'+
      (thumb?'<img src="'+thumb+'" style="width:100%;height:100%;object-fit:cover;opacity:.9" alt="360 panorama">':
        '<div class="absolute inset-0 flex flex-col items-center justify-center gap-2 text-gray-400">'+
          '<svg width="36" height="36" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5"><circle cx="12" cy="12" r="9"/><ellipse cx="12" cy="12" rx="9" ry="3.5"/><path d="M12 3v18"/></svg>'+
          '<span class="text-[11px] font-semibold">Native Broadcast 360 Planner</span>'+
          '<span class="text-[9px] text-gray-500">Equirect JPEG/PNG/WebP · 2:1 · auto-downscales huge files</span></div>')+
      '<div class="absolute inset-0 flex items-center justify-center bg-black/10 group-hover:bg-black/30 transition-colors">'+
        '<span class="bg-gray-900/90 text-white text-[11px] font-bold px-3 py-2 rounded-lg flex items-center gap-1.5 border border-white/10">'+
          '<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><circle cx="12" cy="12" r="9"/><ellipse cx="12" cy="12" rx="9" ry="3.5"/><path d="M12 3v18"/></svg>'+
          'Open Broadcast 360 Planner</span></div>'+
      '<span class="absolute top-1.5 left-1.5 bg-emerald-600 text-white text-[7px] font-bold px-1.5 py-0.5 rounded mono">NATIVE · IN-APP</span>'+
      (hasOwn?'':'<span class="absolute top-1.5 right-1.5 bg-amber-500 text-white text-[7px] font-bold px-1.5 py-0.5 rounded mono">'+(thumb?'SAMPLE':'NO IMAGE')+'</span>')+
      (nMark?'<span class="absolute bottom-1.5 right-1.5 bg-black/70 text-white text-[8px] font-bold mono px-1.5 py-0.5 rounded">'+nMark+' marker'+(nMark===1?'':'s')+'</span>':'')+
    '</div>';
  return '<div class="bg-white rounded-2xl p-4 sm:p-5 border border-gray-200/60" style="box-shadow:0 4px 20px rgba(0,0,0,.03)">'+
    '<div class="flex flex-wrap items-center justify-between gap-2 mb-3">'+
      '<div><h4 class="text-[10px] font-bold uppercase tracking-wider text-gray-600">Broadcast 360 Planner <span class="text-emerald-600 font-bold normal-case">· native</span></h4>'+
      '<p class="text-[9px] text-gray-400 mt-0.5">Equirectangular 360° (2:1). Preferred: JPEG / PNG / WebP up to ~8k. Giant files (e.g. 32k×16k) auto-downscale for WebGL. Markers save with the survey.</p></div>'+
      '<div class="flex items-center gap-2">'+
        '<button type="button" onclick="openPanoViewer(\''+key+'\')" class="text-[9px] font-bold text-white bg-gray-900 rounded-lg px-2.5 py-1.5 hover:bg-gray-800">Open Planner</button>'+
        '<label class="text-[9px] font-bold text-blue-700 hover:underline cursor-pointer">+ Upload 360°<input type="file" accept="image/*" onchange="panoUploadFromPane(\''+key+'\',event)" style="display:none"></label>'+
      '</div>'+
    '</div>'+
    preview+
    '<div class="flex flex-wrap items-center gap-3 mt-2.5">'+chips+'</div>'+
  '</div>';}

/* ---------- Survey Report manifest ---------- */
function panoBearing(yaw){var y=(((+yaw||0)%360)+360)%360;var dirs=['N','NE','E','SE','S','SW','W','NW'];return y.toFixed(0)+'° '+dirs[Math.round(y/45)%8];}
function panoManifestRows(s){var p=ensurePano(s);var rows=[];
  p.hotspots.forEach(function(h){rows.push({t:((PANO_TYPES[h.type]||{}).label||h.type)+(h.tag?' · '+h.tag:''),l:h.label||'—',b:panoBearing(h.yaw),d:h.detail||''});});
  p.marks.forEach(function(m){
    if(m.kind==='zone')rows.push({t:'Zone',l:m.label||'—',b:panoBearing(m.yaw)+' · r'+(m.radius||8)+'°',d:m.detail||''});
    else if(m.kind==='callout')rows.push({t:'Callout',l:m.label||'—',b:panoBearing(m.yaw),d:m.detail||''});
    else if(m.kind==='run'||m.kind==='free'){var p0=(m.pts&&m.pts[0])?m.pts[0]:[0,0];rows.push({t:(m.kind==='run'?'Routed run':'Freehand'),l:m.label||'—',b:panoBearing(p0[1])+' · '+((m.pts||[]).length)+' pts',d:m.detail||''});}});
  return rows.map(function(r){return '<tr><td>'+esc(r.t)+'</td><td>'+esc(r.l)+'</td><td>'+esc(r.b)+'</td><td style="white-space:pre-line">'+esc(museRichPlain(r.d))+'</td></tr>';}).join('')||'<tr><td colspan="4" class="mut">No 360° annotations.</td></tr>';}

/* ============================================================================
   CAD VIEWER — POWER & CABLE OVERLAY
   Drops distribution pins and routes cable runs directly onto the drawing.
   Shares the survey power store (survey.power) with the Power & Electrical pane,
   so a run mapped here shows its specs there, and vice-versa. World-coordinate
   geometry pins markups to the plan through pan/zoom.
   ========================================================================== */
function cadPower(){if(!cadV.key)return {distros:[],runs:[]};
  return ensurePower(getSurvey(cadV.key));}
function cadPowerSave(){if(cadV.key){stampEdit(cadV.key);}cadRender();cadSyncToolbar&&cadSyncToolbar();}

/* place a new distribution pin at a world point (specs edited in the Power pane) */
function cadPlaceDistro(wx,wy){var pw=cadPower();
  var d={id:pwrId('d'),name:'Distro '+(pw.distros.length+1),src:'Generator',type:'Lug / Cam-Lok',
    volts:'208',phase:3,amps:400,location:'',notes:'',planId:cadV.planId,x:wx,y:wy};
  pw.distros.push(d);cadV.selPower={kind:'distro',id:d.id};cadPowerSave();}

/* cable run = click-to-route polyline; double-click / Enter finishes */
function cadCrunClick(wx,wy){if(!cadV.crunDraft)cadV.crunDraft={color:cadV.color,pts:[]};
  cadV.crunDraft.pts.push([wx,wy]);cadRender();}
function cadCrunFinish(){var dr=cadV.crunDraft;cadV.crunDraft=null;if(!dr||dr.pts.length<2){cadRender();return;}
  var pw=cadPower();var d0=pw.distros[0];
  var r={id:pwrId('r'),label:'Run '+(pw.runs.length+1),distroId:d0?d0.id:'',dest:'',
    cable:'4/0 Cam-Lok (single)',awg:'4/0',lengthFt:cadEstLen(dr.pts),amps:100,
    volts:d0?d0.volts:'208',phase:d0?d0.phase:3,connector:'Cam-Lok E1016',
    color:dr.color||cadV.color,planId:cadV.planId,path:dr.pts,notes:''};
  pw.runs.push(r);cadV.selPower={kind:'run',id:r.id};cadV.tool='select';cadPowerSave();
  toast&&toast('Cable run mapped — set its amperage & cable in the Power pane');}
function cadCrunCancel(){if(cadV.crunDraft){cadV.crunDraft=null;cadRender();return true;}return false;}
function cadEstLen(pts){var L=0;for(var i=1;i<pts.length;i++){var dx=pts[i][0]-pts[i-1][0],dy=pts[i][1]-pts[i-1][1];L+=Math.sqrt(dx*dx+dy*dy);}
  if(cadV.scaleFt)return Math.round(L*cadV.scaleFt); /* calibrated: real feet */
  return Math.round(L/12);} // rough px->ft heuristic; surveyor confirms in the pane

/* hit-test power items on the current plan (runs first, then distros) */
function cadPowerHit(wx,wy){var pw=cadPower();var tol=8/cadV.view.scale;
  for(var i=pw.runs.length-1;i>=0;i--){var r=pw.runs[i];if(r.planId!==cadV.planId||!r.path||r.path.length<2)continue;
    for(var k=1;k<r.path.length;k++){if(cadSegDist(wx,wy,r.path[k-1],r.path[k])<tol+(r.width||4)/cadV.view.scale)return {kind:'run',id:r.id};}}
  for(var j=pw.distros.length-1;j>=0;j--){var d=pw.distros[j];if(d.planId!==cadV.planId||d.x==null)continue;
    var sz=16/cadV.view.scale;if(wx>=d.x-sz&&wx<=d.x+sz&&wy>=d.y-sz&&wy<=d.y+sz)return {kind:'distro',id:d.id};}
  return null;}
function cadSegDist(px,py,a,b){var vx=b[0]-a[0],vy=b[1]-a[1];var wx=px-a[0],wy=py-a[1];
  var c1=vx*wx+vy*wy;if(c1<=0)return Math.hypot(px-a[0],py-a[1]);var c2=vx*vx+vy*vy;if(c2<=c1)return Math.hypot(px-b[0],py-b[1]);
  var t=c1/c2;return Math.hypot(px-(a[0]+t*vx),py-(a[1]+t*vy));}

function cadFindPower(sel){if(!sel)return null;var pw=cadPower();var list=sel.kind==='run'?pw.runs:pw.distros;
  for(var i=0;i<list.length;i++)if(list[i].id===sel.id)return list[i];return null;}
function cadDeletePower(){if(!cadV.selPower)return;var pw=cadPower();
  if(cadV.selPower.kind==='run')pw.runs=pw.runs.filter(function(r){return r.id!==cadV.selPower.id;});
  else pw.distros=pw.distros.filter(function(d){return d.id!==cadV.selPower.id;});
  cadV.selPower=null;cadPowerSave();}

/* single entry hooked at the top of cadDown — returns true if it consumed the event */
function cadPowerDown(e,w){
  if(cadV.tool==='distro'){cadPlaceDistro(w[0],w[1]);return true;}
  if(cadV.tool==='crun'){cadCrunClick(w[0],w[1]);return true;}
  if(cadV.tool==='select'){var hit=cadPowerHit(w[0],w[1]);
    if(hit){cadV.selPower=hit;cadV.sel=null;
      var it=cadFindPower(hit);if(it){if(hit.kind==='run')cadV.drag={mode:'movepow',sel:hit,startW:w,orig:JSON.parse(JSON.stringify(it.path))};
        else cadV.drag={mode:'movedistro',sel:hit,startW:w,ox:it.x,oy:it.y};}
      cadRender();return true;}
    cadV.selPower=null;}
  return false;}
function cadPowerMove(w){var d=cadV.drag;if(!d)return false;
  if(d.mode==='movedistro'){var it=cadFindPower(d.sel);if(it){it.x=d.ox+(w[0]-d.startW[0]);it.y=d.oy+(w[1]-d.startW[1]);cadRender();}return true;}
  if(d.mode==='movepow'){var r=cadFindPower(d.sel);if(r){var dx=w[0]-d.startW[0],dy=w[1]-d.startW[1];
    r.path=d.orig.map(function(p){return [p[0]+dx,p[1]+dy];});cadRender();}return true;}
  return false;}
function cadPowerUp(){var d=cadV.drag;if(d&&(d.mode==='movedistro'||d.mode==='movepow')){cadV.drag=null;cadPowerSave();return true;}return false;}

/* ---- rendering ---- */
function cadDrawPower(ctx,vs){var pw=cadPower();
  // runs on this plan
  for(var i=0;i<pw.runs.length;i++){var r=pw.runs[i];if(r.planId!==cadV.planId||!r.path||r.path.length<2)continue;
    var seld=cadV.selPower&&cadV.selPower.kind==='run'&&cadV.selPower.id===r.id;
    ctx.save();
    if(seld){ctx.strokeStyle='rgba(8,102,255,.35)';ctx.lineWidth=10/vs;ctx.lineJoin='round';ctx.lineCap='round';
      ctx.beginPath();ctx.moveTo(r.path[0][0],r.path[0][1]);for(var k=1;k<r.path.length;k++)ctx.lineTo(r.path[k][0],r.path[k][1]);ctx.stroke();}
    ctx.strokeStyle=r.color||'#e41e3f';ctx.lineWidth=4/vs;ctx.lineJoin='round';ctx.lineCap='round';
    ctx.beginPath();ctx.moveTo(r.path[0][0],r.path[0][1]);
    for(var m=1;m<r.path.length;m++)ctx.lineTo(r.path[m][0],r.path[m][1]);ctx.stroke();
    // vertices
    ctx.fillStyle='#ffffff';ctx.strokeStyle=r.color||'#e41e3f';ctx.lineWidth=2/vs;
    for(var v=0;v<r.path.length;v++){ctx.beginPath();ctx.arc(r.path[v][0],r.path[v][1],4/vs,0,6.2832);ctx.fill();ctx.stroke();}
    // label at midpoint
    var mid=r.path[Math.floor(r.path.length/2)];
    cadPowerLabel(ctx,vs,mid[0],mid[1],(r.label||'Run')+' · '+(r.amps||0)+'A',r.color||'#e41e3f');
    ctx.restore();}
  // distros on this plan
  for(var j=0;j<pw.distros.length;j++){var d=pw.distros[j];if(d.planId!==cadV.planId||d.x==null)continue;
    var sel2=cadV.selPower&&cadV.selPower.kind==='distro'&&cadV.selPower.id===d.id;
    var s=13/vs;ctx.save();
    if(sel2){ctx.strokeStyle='#0866ff';ctx.lineWidth=2/vs;ctx.setLineDash([5/vs,3/vs]);ctx.strokeRect(d.x-s-3/vs,d.y-s-3/vs,(s+3/vs)*2,(s+3/vs)*2);ctx.setLineDash([]);}
    ctx.fillStyle='#f5832a';ctx.strokeStyle='#b24a00';ctx.lineWidth=1.5/vs;
    cadRoundRect(ctx,d.x-s,d.y-s,s*2,s*2,4/vs);ctx.fill();ctx.stroke();
    // lightning glyph
    ctx.fillStyle='#b24a00';ctx.beginPath();var u=s*0.9;
    ctx.moveTo(d.x+u*0.15,d.y-u*0.7);ctx.lineTo(d.x-u*0.45,d.y+u*0.1);ctx.lineTo(d.x-u*0.02,d.y+u*0.1);
    ctx.lineTo(d.x-u*0.15,d.y+u*0.7);ctx.lineTo(d.x+u*0.45,d.y-u*0.1);ctx.lineTo(d.x+u*0.02,d.y-u*0.1);ctx.closePath();ctx.fill();
    cadPowerLabel(ctx,vs,d.x,d.y+s+10/vs,(d.name||'Distro')+' · '+(d.amps||0)+'A '+(d.volts||'')+'V'+(d.phase===3?' 3φ':' 1φ'),'#b24a00');
    ctx.restore();}
  // in-progress cable run draft
  if(cadV.crunDraft&&cadV.crunDraft.pts.length){var dr=cadV.crunDraft;ctx.save();
    ctx.strokeStyle=dr.color||'#e41e3f';ctx.lineWidth=3/vs;ctx.setLineDash([8/vs,5/vs]);ctx.lineJoin='round';ctx.lineCap='round';
    ctx.beginPath();ctx.moveTo(dr.pts[0][0],dr.pts[0][1]);for(var q=1;q<dr.pts.length;q++)ctx.lineTo(dr.pts[q][0],dr.pts[q][1]);ctx.stroke();
    ctx.setLineDash([]);ctx.fillStyle=dr.color||'#e41e3f';
    for(var z=0;z<dr.pts.length;z++){ctx.beginPath();ctx.arc(dr.pts[z][0],dr.pts[z][1],4/vs,0,6.2832);ctx.fill();}
    ctx.restore();}
}
function cadPowerLabel(ctx,vs,x,y,txt,col){var fs=11/vs;ctx.font='700 '+fs+'px ui-sans-serif,system-ui,Arial';
  var w=ctx.measureText(txt).width,pad=4/vs;ctx.textBaseline='middle';
  ctx.fillStyle='rgba(255,255,255,.92)';cadRoundRect(ctx,x-w/2-pad,y-fs/2-pad,w+pad*2,fs+pad*2,3/vs);ctx.fill();
  ctx.fillStyle=col;ctx.textAlign='center';ctx.fillText(txt,x,y);ctx.textAlign='left';}
function cadRoundRect(ctx,x,y,w,h,r){ctx.beginPath();ctx.moveTo(x+r,y);ctx.arcTo(x+w,y,x+w,y+h,r);
  ctx.arcTo(x+w,y+h,x,y+h,r);ctx.arcTo(x,y+h,x,y,r);ctx.arcTo(x,y,x+w,y,r);ctx.closePath();}


/* ===== Finance: cost-report spine ===== */
/* ============================================================================
   v31 PHASE 2 — SAP-MODELED COST ARCHITECTURE
   Master data (WBS Elements per SAP PS · Cost Centers per SAP CO), a split-cost
   allocation engine (percentage or fixed-amount, validated before save), and
   data-driven per-category expense rules (SAP Concur-style policy). Every travel
   & expense line item links to ≥1 WBS element or cost center via alloc[].
   ========================================================================== */
var MD_SEED_WBS=[
  {id:'PRJ-2026-MUSEAITOUR-01',desc:'Muse AI World Tour — IBC Operations',active:true,prod:'museaitour'},
  {id:'PRJ-2026-MUSEAITOUR-02',desc:'Muse AI World Tour — Venue Production',active:true,prod:'museaitour'},
  {id:'PRJ-2026-RAYBANGEN3-01',desc:'Ray-Ban Meta Gen 3 — MPK Classroom Launch',active:true,prod:'raybangen3'},
  {id:'PRJ-2026-ORION-01',desc:'Orion Developer Preview — Host Broadcast',active:true,prod:'orion'},
  {id:'PRJ-2026-ORION-02',desc:'Orion Developer Preview — Digital & Streaming',active:true,prod:'orion'},
  {id:'PRJ-2026-MUSEAILAUNCH-01',desc:'Muse AI Launch Keynote',active:true,prod:'museailaunch'},
  {id:'PRJ-2026-WHATSAPP-01',desc:'WhatsApp Business Summit Coverage',active:true,prod:'whatsapp'},
  {id:'PRJ-2026-IGCREATORS-01',desc:'Creator Week Street Takeover Broadcast',active:true,prod:'igcreators'},
  {id:'PRJ-2026-CHARM-01',desc:'Meta Charm Launch — Milan Design Week',active:true,prod:'charm'}
];
var MD_SEED_CC=[
  {id:'CC-BROADCAST-A1',desc:'Broadcast Audio Engineering',active:true},
  {id:'CC-BROADCAST-CAM',desc:'Camera & Video Operations',active:true},
  {id:'CC-ENG-FIELD',desc:'Field Engineering & ENG',active:true},
  {id:'CC-TRAVEL-OPS',desc:'Travel & Crew Logistics',active:true},
  {id:'CC-EXEC-PROD',desc:'Executive Production',active:true},
  {id:'CC-POST-GFX',desc:'Post & Graphics',active:true}
];
var _mdStore=null;
function mdLoad(){if(_mdStore)return _mdStore;
  try{_mdStore=JSON.parse(localStorage.getItem('muselive_masterdata_v1')||'null');}catch(e){_mdStore=null;}
  if(!_mdStore||!Array.isArray(_mdStore.wbs)||!Array.isArray(_mdStore.cc)){
    _mdStore={wbs:MD_SEED_WBS.map(function(x){return {id:x.id,desc:x.desc,active:x.active,prod:x.prod||''};}),
              cc:MD_SEED_CC.map(function(x){return {id:x.id,desc:x.desc,active:x.active};})};
    mdSave();}
  return _mdStore;}
function mdSave(){try{localStorage.setItem('muselive_masterdata_v1',JSON.stringify(_mdStore));}catch(e){}}
function mdWbsElements(all){return mdLoad().wbs.filter(function(x){return all||x.active;});}
function mdCostCenters(all){return mdLoad().cc.filter(function(x){return all||x.active;});}
function mdById(id){var s=mdLoad(),i;
  for(i=0;i<s.wbs.length;i++)if(s.wbs[i].id===id)return {rec:s.wbs[i],kind:'wbs'};
  for(i=0;i<s.cc.length;i++)if(s.cc[i].id===id)return {rec:s.cc[i],kind:'cc'};
  return null;}
function wbsForProd(key){var w=mdLoad().wbs,i;
  for(i=0;i<w.length;i++)if(w[i].active&&w[i].prod===key)return w[i].id;
  return w.length?w[0].id:'';}
function mdAdd(kind,id,desc,prod){var s=mdLoad();id=String(id||'').trim().toUpperCase();
  if(!id)return 'ID is required';
  if(kind==='wbs'&&!/^PRJ-/.test(id))return 'WBS ids follow PRJ-… (e.g. PRJ-2026-ORION-01)';
  if(kind==='cc'&&!/^CC-/.test(id))return 'Cost-center ids follow CC-… (e.g. CC-BROADCAST-A1)';
  if(mdById(id))return 'An element with id '+id+' already exists';
  var rec={id:id,desc:String(desc||'').trim(),active:true};if(kind==='wbs')rec.prod=prod||'';
  s[kind].push(rec);mdSave();
  museAudit('masterdata.created',{kind:kind,id:id});museBus.emit('masterdata.updated',{kind:kind,id:id});
  return null;}
function mdUpdate(kind,id,field,val){var s=mdLoad();
  s[kind].forEach(function(x){if(x.id===id){x[field]=(field==='active')?!!val:val;}});
  mdSave();museAudit('masterdata.updated',{kind:kind,id:id,field:field});museBus.emit('masterdata.updated',{kind:kind,id:id});}
/* ---- split-cost allocation engine ----
   alloc = {mode:'pct'|'amt', splits:[{target:'PRJ-…'|'CC-…', value:Number}]}
   pct mode: values sum to 100 (±0.01). amt mode: values sum to the line total (±0.01).
   Every line item must carry ≥1 valid split — enforced by allocValidate before save. */
function allocDefault(target){return {mode:'pct',splits:[{target:target||'',value:100}]};}
function allocValidate(alloc,total){
  if(!alloc||!Array.isArray(alloc.splits)||!alloc.splits.length)return 'Every line must be allocated to at least one WBS element or cost center.';
  var sum=0,i,sp;
  for(i=0;i<alloc.splits.length;i++){sp=alloc.splits[i];
    if(!sp.target)return 'Split '+(i+1)+': pick a WBS element or cost center.';
    var md=mdById(sp.target);
    if(!md)return 'Split '+(i+1)+': "'+sp.target+'" is not in the master data.';
    if(!md.rec.active)return 'Split '+(i+1)+': '+sp.target+' is inactive — reactivate it in Cost Master Data or pick another.';
    var v=parseFloat(sp.value);
    if(isNaN(v)||v<=0)return 'Split '+(i+1)+': enter a positive '+(alloc.mode==='pct'?'percentage':'amount')+'.';
    sum+=v;}
  if(alloc.mode==='pct'&&Math.abs(sum-100)>0.01)return 'Percentages must sum to 100% — currently '+(Math.round(sum*100)/100)+'%.';
  if(alloc.mode==='amt'&&Math.abs(sum-(parseFloat(total)||0))>0.01)return 'Fixed amounts must sum to the line total ('+$fmt(total)+') — currently '+$fmt(sum)+'.';
  return null;}
function allocAmounts(alloc,total){ /* → [{target,kind,amount}] */
  if(!alloc||!Array.isArray(alloc.splits))return [];
  total=parseFloat(total)||0;
  return alloc.splits.map(function(sp){var md=mdById(sp.target);var v=parseFloat(sp.value)||0;
    var amt=alloc.mode==='pct'?total*v/100:v;
    return {target:sp.target,kind:md?md.kind:'',amount:Math.round(amt*100)/100};});}
function allocSummary(alloc){
  if(!alloc||!Array.isArray(alloc.splits)||!alloc.splits.length)return 'unallocated';
  return alloc.splits.map(function(sp){return (alloc.mode==='pct'?(Math.round(sp.value*100)/100)+'%':$fmt(sp.value))+' '+sp.target;}).join(' · ');}
/* ---- data-driven per-category expense policy (SAP Concur-style) ----
   Rules live in this config object, NOT in UI logic; edit here (or later via an
   admin surface / backend) to change what each personnel category may submit. */
var EXPENSE_RULES={
  'Employee':      {allowed:['flight','hotel','perdiem','ground','misc'],caps:{hotelNight:450,misc:200},receiptsRequired:['hotel','misc'],receiptMinAmount:25,perDiemEligible:true,perDiemMultiplier:1.0,bookingClass:'economy',note:'Standard T&E policy.'},
  'Freelancer':    {allowed:['flight','hotel','perdiem','ground'],caps:{hotelNight:350,misc:0},receiptsRequired:['hotel','ground'],receiptMinAmount:0,perDiemEligible:true,perDiemMultiplier:1.0,bookingClass:'economy',note:'Misc expenses require prior approval — not submittable.'},
  'Vendor':        {allowed:['flight','ground'],caps:{hotelNight:0,misc:0},receiptsRequired:['flight','ground'],receiptMinAmount:0,perDiemEligible:false,perDiemMultiplier:0,bookingClass:'economy',note:'Hotels & per diems bill through the vendor PO, not T&E.'},
  'Talent / On-Air':{allowed:['flight','hotel','perdiem','ground','misc'],caps:{hotelNight:900,misc:500},receiptsRequired:['misc'],receiptMinAmount:75,perDiemEligible:true,perDiemMultiplier:1.5,bookingClass:'business',note:'Contract riders may extend these caps.'}
};
function expenseRule(category){return EXPENSE_RULES[category]||EXPENSE_RULES['Employee'];}
function expenseAllowed(category,type){return expenseRule(category).allowed.indexOf(type)>-1;}
var EXPENSE_TYPES=[['flight','Flight ✈'],['hotel','Hotel 🏨'],['perdiem','Per Diem (M&IE) 🍽'],['ground','Ground 🚐'],['misc','Misc 🧾']];
function expenseTypeLabel(t){for(var i=0;i<EXPENSE_TYPES.length;i++)if(EXPENSE_TYPES[i][0]===t)return EXPENSE_TYPES[i][1];return t;}
/* ---- master data manager modal (create/edit WBS + cost centers) ---- */
function openMasterData(){
  if(typeof permCan==='function'&&!permCan('finance')){toast('🔒 Cost master data needs finance access');return;}
  var ov=document.getElementById('mdOverlay');if(!ov)return;ov.style.display='flex';renderMasterData();}
function closeMasterData(){var ov=document.getElementById('mdOverlay');if(ov)ov.style.display='none';}
function mdRowHTML(kind,x){
  var idq=x.id.replace(/'/g,"\\'");
  var prodSel='';
  if(kind==='wbs'){prodSel='<select onchange="mdUpdate(\'wbs\',\''+idq+'\',\'prod\',this.value);renderMasterData()" class="text-[9px] mono border border-gray-200 rounded px-1 py-0.5 bg-white" style="outline:none"><option value="">— any —</option>'+order.map(function(k){return '<option value="'+k+'"'+(x.prod===k?' selected':'')+'>'+esc(productions[k].name)+'</option>';}).join('')+'</select>';}
  return '<tr class="'+(x.active?'':'opacity-50')+'"><td class="py-1.5 mono text-[10px] font-bold text-gray-800 whitespace-nowrap">'+esc(x.id)+'</td>'+
    '<td class="py-1.5 pr-2 w-full"><input value="'+esc(x.desc).replace(/"/g,'&quot;')+'" onchange="mdUpdate(\''+kind+'\',\''+idq+'\',\'desc\',this.value)" class="w-full text-[10px] border border-transparent hover:border-gray-200 focus:border-blue-300 rounded px-1.5 py-1 bg-transparent" style="outline:none"></td>'+
    '<td class="py-1.5 whitespace-nowrap">'+prodSel+'</td>'+
    '<td class="py-1.5 text-right whitespace-nowrap"><button onclick="mdUpdate(\''+kind+'\',\''+idq+'\',\'active\','+(x.active?'false':'true')+');renderMasterData()" class="text-[8px] font-bold border rounded px-1.5 py-0.5 '+(x.active?'text-emerald-700 bg-emerald-50 border-emerald-200':'text-gray-500 bg-gray-100 border-gray-200')+'">'+(x.active?'ACTIVE':'inactive')+'</button></td></tr>';}
function renderMasterData(){
  var bx=document.getElementById('mdBox');if(!bx)return;
  var s=mdLoad();
  bx.innerHTML='<div class="flex items-center justify-between px-4 py-3 border-b border-gray-100 flex-shrink-0"><div><h3 class="text-sm font-bold text-gray-900">Cost Master Data</h3><p class="text-[10px] text-gray-500">WBS Elements (SAP PS) &amp; Cost Centers (SAP CO) — every travel &amp; expense line allocates to these</p></div><button onclick="closeMasterData()" class="text-gray-400 hover:text-gray-700 text-lg leading-none">✕</button></div>'+
    '<div class="p-4 space-y-4 overflow-y-auto" style="max-height:74vh">'+
      '<div><p class="text-[9px] font-bold uppercase tracking-wider text-gray-500 mb-1.5">WBS Elements <span class="text-gray-300 normal-case">· project-bound work packages</span></p>'+
        '<table class="w-full text-left"><thead><tr class="text-[8px] uppercase tracking-wider text-gray-400 border-b border-gray-100"><th class="pb-1">ID</th><th class="pb-1">Description</th><th class="pb-1">Production</th><th class="pb-1 text-right">Status</th></tr></thead><tbody class="divide-y divide-gray-50">'+
        s.wbs.map(function(x){return mdRowHTML('wbs',x);}).join('')+'</tbody></table>'+
        '<div class="flex items-center gap-1.5 mt-2"><input id="md_wbs_id" placeholder="PRJ-2026-…" class="mono text-[10px] uppercase border border-gray-300 rounded-lg px-2 py-1.5 w-48" style="outline:none"><input id="md_wbs_desc" placeholder="Description" class="text-[10px] border border-gray-300 rounded-lg px-2 py-1.5 flex-1" style="outline:none"><button onclick="mdAddFromForm(\'wbs\')" class="text-[9px] font-bold text-white bg-blue-600 rounded-lg px-2.5 py-1.5 hover:bg-blue-700">+ Add WBS</button></div></div>'+
      '<div><p class="text-[9px] font-bold uppercase tracking-wider text-gray-500 mb-1.5">Cost Centers <span class="text-gray-300 normal-case">· standing departments</span></p>'+
        '<table class="w-full text-left"><thead><tr class="text-[8px] uppercase tracking-wider text-gray-400 border-b border-gray-100"><th class="pb-1">ID</th><th class="pb-1">Description</th><th></th><th class="pb-1 text-right">Status</th></tr></thead><tbody class="divide-y divide-gray-50">'+
        s.cc.map(function(x){return mdRowHTML('cc',x);}).join('')+'</tbody></table>'+
        '<div class="flex items-center gap-1.5 mt-2"><input id="md_cc_id" placeholder="CC-…" class="mono text-[10px] uppercase border border-gray-300 rounded-lg px-2 py-1.5 w-48" style="outline:none"><input id="md_cc_desc" placeholder="Description" class="text-[10px] border border-gray-300 rounded-lg px-2 py-1.5 flex-1" style="outline:none"><button onclick="mdAddFromForm(\'cc\')" class="text-[9px] font-bold text-white bg-blue-600 rounded-lg px-2.5 py-1.5 hover:bg-blue-700">+ Add CC</button></div></div>'+
      '<p class="text-[9px] text-gray-400">Inactive elements stay on historical lines but can\'t receive new allocations. Personnel default assignments are set on each person\'s card.</p>'+
    '</div>';}
function mdAddFromForm(kind){
  var id=((document.getElementById('md_'+kind+'_id')||{}).value||'').trim();
  var desc=((document.getElementById('md_'+kind+'_desc')||{}).value||'').trim();
  var err=mdAdd(kind,id,desc,'');
  if(err){toast(err);return;}
  toast((kind==='wbs'?'WBS element ':'Cost center ')+id.toUpperCase()+' added');renderMasterData();}
/* ---- split-allocation editor (generic; used by travel & expense lines) ----
   openAllocEditor({alloc,total,label,onSave:function(alloc){}}) ---- */
var _allocCtx=null;
function openAllocEditor(ctx){
  _allocCtx=ctx||{};_allocCtx.work=JSON.parse(JSON.stringify(ctx.alloc||allocDefault('')));
  var ov=document.getElementById('allocOverlay');if(!ov)return;ov.style.display='flex';renderAllocEditor();}
function closeAllocEditor(){var ov=document.getElementById('allocOverlay');if(ov)ov.style.display='none';_allocCtx=null;}
function allocTargetOpts(cur){
  var o='<option value="">— pick target —</option><optgroup label="WBS Elements">';
  mdWbsElements().forEach(function(x){o+='<option value="'+x.id+'"'+(cur===x.id?' selected':'')+'>'+x.id+' · '+esc(x.desc)+'</option>';});
  o+='</optgroup><optgroup label="Cost Centers">';
  mdCostCenters().forEach(function(x){o+='<option value="'+x.id+'"'+(cur===x.id?' selected':'')+'>'+x.id+' · '+esc(x.desc)+'</option>';});
  return o+'</optgroup>';}
function allocEdSync(){ /* read DOM rows into _allocCtx.work */
  if(!_allocCtx)return;
  var tg=document.querySelectorAll('#allocRows .alloc-target'),vl=document.querySelectorAll('#allocRows .alloc-val'),out=[];
  for(var i=0;i<tg.length;i++)out.push({target:tg[i].value,value:parseFloat(vl[i].value)||0});
  _allocCtx.work.splits=out;}
function allocEdMode(m){allocEdSync();_allocCtx.work.mode=m;
  if(m==='pct'&&_allocCtx.work.splits.length===1)_allocCtx.work.splits[0].value=100;
  if(m==='amt'&&_allocCtx.work.splits.length===1)_allocCtx.work.splits[0].value=parseFloat(_allocCtx.total)||0;
  renderAllocEditor();}
function allocEdAdd(){allocEdSync();_allocCtx.work.splits.push({target:'',value:0});renderAllocEditor();}
function allocEdDel(i){allocEdSync();_allocCtx.work.splits.splice(i,1);renderAllocEditor();}
function allocEdCheck(){allocEdSync();renderAllocEditor(true);}
function allocEdSave(){
  allocEdSync();
  var err=allocValidate(_allocCtx.work,_allocCtx.total);
  if(err){var m=document.getElementById('allocMsg');if(m){m.textContent=err;m.className='text-[10px] font-bold text-red-600';}return;}
  var cb=_allocCtx.onSave;var val=_allocCtx.work;
  closeAllocEditor();
  if(typeof cb==='function')cb(val);}
function renderAllocEditor(keepMsg){
  var bx=document.getElementById('allocBox');if(!bx||!_allocCtx)return;
  var w=_allocCtx.work,total=parseFloat(_allocCtx.total)||0;
  var err=allocValidate(w,total);
  var amounts=err?[]:allocAmounts(w,total);
  bx.innerHTML='<div class="flex items-center justify-between px-4 py-3 border-b border-gray-100 flex-shrink-0"><div><h3 class="text-sm font-bold text-gray-900">Split-Cost Allocation</h3><p class="text-[10px] text-gray-500">'+esc(_allocCtx.label||'Line item')+' · total '+$fmt(total)+'</p></div><button onclick="closeAllocEditor()" class="text-gray-400 hover:text-gray-700 text-lg leading-none">✕</button></div>'+
    '<div class="p-4 space-y-3 overflow-y-auto" style="max-height:70vh">'+
      '<div class="flex items-center gap-1.5"><span class="text-[9px] font-bold uppercase tracking-wider text-gray-400">Split by</span>'+
        '<button onclick="allocEdMode(\'pct\')" class="text-[9px] font-bold rounded-lg px-2.5 py-1 border '+(w.mode==='pct'?'text-white bg-gray-900 border-gray-900':'text-gray-600 border-gray-200 bg-white')+'">Percentage</button>'+
        '<button onclick="allocEdMode(\'amt\')" class="text-[9px] font-bold rounded-lg px-2.5 py-1 border '+(w.mode==='amt'?'text-white bg-gray-900 border-gray-900':'text-gray-600 border-gray-200 bg-white')+'">Fixed amount</button></div>'+
      '<div id="allocRows" class="space-y-1.5">'+w.splits.map(function(sp,i){
        var amtChip=amounts[i]?'<span class="mono text-[9px] text-gray-400 whitespace-nowrap">'+$fmt(amounts[i].amount)+'</span>':'';
        return '<div class="flex items-center gap-1.5"><select class="alloc-target flex-1 text-[10px] mono border border-gray-300 rounded-lg px-1.5 py-1.5 bg-white" style="outline:none;min-width:0" onchange="allocEdCheck()">'+allocTargetOpts(sp.target)+'</select>'+
          '<div class="relative"><input class="alloc-val w-20 text-[11px] mono text-right border border-gray-300 rounded-lg px-1.5 py-1.5 '+(w.mode==='pct'?'pr-5':'')+'" style="outline:none" type="number" step="0.01" min="0" value="'+sp.value+'" onchange="allocEdCheck()">'+(w.mode==='pct'?'<span class="absolute right-1.5 top-1/2 -translate-y-1/2 text-[9px] text-gray-400">%</span>':'')+'</div>'+amtChip+
          (w.splits.length>1?'<button onclick="allocEdDel('+i+')" class="text-gray-400 hover:text-red-600 text-sm leading-none">✕</button>':'')+'</div>';}).join('')+'</div>'+
      '<button onclick="allocEdAdd()" class="text-[9px] font-bold text-blue-700 hover:underline">+ Add split target</button>'+
      '<p id="allocMsg" class="text-[10px] font-bold '+(err?'text-amber-600':'text-emerald-700')+'">'+(err?esc(err):'✓ Valid — '+esc(allocSummary(w)))+'</p>'+
    '</div>'+
    '<div class="px-4 py-3 border-t border-gray-100 flex items-center gap-2 flex-shrink-0">'+
      '<button onclick="allocEdSave()" '+(err?'disabled':'')+' class="flex-1 text-[12px] font-bold rounded-lg py-2.5 '+(err?'bg-gray-200 text-gray-400 cursor-not-allowed':'bg-blue-600 text-white hover:bg-blue-700')+'">Save Allocation</button>'+
      '<button onclick="closeAllocEditor()" class="text-[11px] font-bold text-gray-600 px-3 py-2">Cancel</button>'+
    '</div>';}

/* ============================================================================
   FINANCE — COST REPORT SPINE
   Turns the single top-line budget into a production cost report: a broadcast
   chart of accounts (topsheet categories + editable budget lines), account-coded
   commitments and actuals, and the number that actually runs a show —
   EFC (Estimated Final Cost = Actual + Open Commitments + Estimate-to-Complete)
   with variance against budget. No double-counting: once a PO/WO/Tx is invoiced
   it moves out of "committed" and into "actual".
   ========================================================================== */

// broadcast live-production chart of accounts (category code -> name + auto-code hint)
var FIN_COA=[
  {code:'10',cat:'Above-the-Line',hint:/talent|announc|host\b|producer|director|on[- ]?air|commentator|analyst/i},
  {code:'20',cat:'Production Labor & Crew',hint:/crew|labor|labour|operator|camera op|\baudio\b|\bA1\b|\bA2\b|\bEIC\b|utility|grip|stagehand|overtime|\bOT\b|technician|\bTD\b|video engineer|broadcast engineer/i},
  {code:'30',cat:'Technical Facilities',hint:/mobile unit|production truck|\btruck\b|flypack|fly pack|\bOB\b|control room|\bREMI\b|\bA-?unit|\bB-?unit|compound/i},
  {code:'40',cat:'Transmission & Connectivity',hint:/transmission|satellite|\bsat\b|fiber|fibre|uplink|encode|bonded|backhaul|signal|tie[- ]?line|connectivity|\bTx\b|teleport/i},
  {code:'50',cat:'Equipment Rental',hint:/camera|lens|rental|replay|\bEVS\b|\bRF\b|wireless|\bkit\b|gear|equipment|monitor|switcher|robotic|drone|\bjib\b|wirecam|steadicam/i},
  {code:'60',cat:'Travel & Logistics',hint:/travel|airfare|flight|hotel|lodging|per[- ]?diem|ground|shuttle|freight|shipping|logistics|cartage|baggage/i},
  {code:'70',cat:'Site, Power & Facilities',hint:/generator|genny|\bpower\b|distro|rigging|cater|\bfood\b|security|\btent\b|fencing|restroom|facilit|cabling|\bsite\b|tower|scaffold/i},
  {code:'80',cat:'Post & Graphics',hint:/graphic|\bGFX\b|design|\bedit\b|\bpost\b|finishing|colou?r|animation|motion|\bAR\b|virtual set/i},
  {code:'90',cat:'Insurance, Contingency & Fee',hint:/insurance|contingency|\bfee\b|markup|bond|legal|permit|\bmisc\b/i}
];
// seed topsheet — fractions of the top-line budget (sum = 1.00)
var FIN_SEED=[
  ['10','On-air talent & announcers',0.07],['10','Producers & director',0.05],
  ['20','Technical crew (camera/EVS/audio/EIC)',0.16],['20','Utility, grip & stage labor',0.05],['20','Overtime & penalty reserve',0.03],
  ['30','Mobile units / production trucks',0.14],['30','Flypacks, RF & comms',0.04],
  ['40','Satellite / fiber transmission',0.08],
  ['50','Cameras, lenses & specialty',0.07],['50','Replay & graphics hardware',0.03],
  ['60','Airfare & ground',0.04],['60','Hotel & per diem',0.04],
  ['70','Generators, power & distribution',0.03],['70','Rigging & structures',0.02],['70','Catering & crew services',0.02],['70','Security',0.01],
  ['80','Graphics & design',0.03],['80','Edit & finishing',0.02],
  ['90','Production insurance',0.02],['90','Contingency',0.03],['90','Production fee',0.02]
];
function finCatName(code){if(code===''||code==null)return 'Uncoded — needs an account';for(var i=0;i<FIN_COA.length;i++)if(FIN_COA[i].code===code)return FIN_COA[i].cat;return code;}

var finCostReport=(typeof finCostReport!=='undefined')?finCostReport:{};
var finCatOpen=(typeof finCatOpen!=='undefined')?finCatOpen:{};
var finView=(typeof finView!=='undefined')?finView:{};

function finEnsureCostReport(key){if(!finCostReport[key]){
    var total=finBudgets[key]||0;var lines=[];var seq=1;var acc=0;var contribIdx=-1;
    FIN_SEED.forEach(function(t,i){var amt=Math.round(t[2]*total);acc+=amt;
      var ln={id:'L'+key+'_'+(seq++),code:t[0]+'-'+String(seq).padStart(2,'0'),cat:t[0],name:t[1],budget:amt,note:''};
      if(t[1]==='Contingency')contribIdx=lines.length;lines.push(ln);});
    // absorb rounding remainder into Contingency so lines sum exactly to the top-line
    if(contribIdx>=0)lines[contribIdx].budget+=(total-acc);
    finCostReport[key]={currency:'USD',lines:lines,etc:{}};}
  var cr=finCostReport[key];if(!cr.etc)cr.etc={};if(!Array.isArray(cr.lines))cr.lines=[];return cr;}
function finRecalcBudget(key){var cr=finEnsureCostReport(key);var t=0;cr.lines.forEach(function(l){t+=(parseFloat(l.budget)||0);});finBudgets[key]=t;return t;}

/* ---- account coding: explicit override -> inherit from ref -> keyword ---- */
function finKeyword(text){for(var i=0;i<FIN_COA.length;i++){if(FIN_COA[i].hint&&FIN_COA[i].hint.test(text||''))return FIN_COA[i].code;}return '';}
function finRecCat(rec,type){if(!rec)return '';if(rec.acct)return rec.acct;
  if(type==='tx')return '40';
  if(type==='inv'&&rec.ref){var ref=finFind('po',rec.ref)||finFind('wo',rec.ref)||finFind('tx',rec.ref);
    if(ref){if(ref.acct)return ref.acct;if(finFind('tx',rec.ref))return '40';return finKeyword((ref.desc||'')+' '+(ref.vendor||'')+' '+(ref.res||''));}}
  if(type==='po'&&rec.wo){var w=finFind('wo',rec.wo);if(w&&w.acct)return w.acct;}
  return finKeyword((rec.desc||'')+' '+(rec.vendor||'')+' '+(rec.res||'')+' '+(rec.scope||''));}
function finSetAcct(type,id,code){var r=finFind(type,id);if(!r)return;r.acct=code||'';saveOps();
  var pk=r.prod;if(pk)renderProjectView(pk);}

/* ---- per-category rollups (no double-count: invoiced items leave committed) ---- */
function finIsActualized(key,recId){return finInvoices.some(function(v){return v.prod===key&&v.ref===recId;});}
function finCatBudget(key,code){var cr=finEnsureCostReport(key);var b=0;cr.lines.forEach(function(l){if(l.cat===code)b+=(parseFloat(l.budget)||0);});return b;}
function finCatCommitted(key,code){var c=0;
  finPOs.forEach(function(po){if(po.prod!==key||po.status==='Draft')return;if(finRecCat(po,'po')!==code)return;if(finIsActualized(key,po.id))return;c+=(po.amount||0);});
  workOrders.forEach(function(w){if(w.prod!==key||w.status==='Draft')return;if(finRecCat(w,'wo')!==code)return;
    if(finPOs.some(function(po){return po.prod===key&&po.wo===w.id&&po.status!=='Draft';}))return; // covered by a PO
    if(finIsActualized(key,w.id))return;c+=(w.cost||0);});
  txBookings.forEach(function(t){if(t.prod!==key||t.status==='Hold')return;if(finRecCat(t,'tx')!==code)return;if(finIsActualized(key,t.id))return;c+=(t.cost||0);});
  return c;}
function finCatActual(key,code){var c=0;finInvoices.forEach(function(v){if(v.prod!==key)return;if(finRecCat(v,'inv')!==code)return;c+=(v.amount||0);});return c;}
function finCatETC(key,code){var cr=finEnsureCostReport(key);var ov=cr.etc?cr.etc[code]:null;
  if(ov!=null&&ov!=='')return Math.max(0,parseFloat(ov)||0);
  return Math.max(0,finCatBudget(key,code)-finCatCommitted(key,code)-finCatActual(key,code));}
function finCatEFC(key,code){return finCatActual(key,code)+finCatCommitted(key,code)+finCatETC(key,code);}

function finActiveCats(key){ // categories that have a budget or any coded spend (plus Uncoded if needed)
  var codes={};FIN_COA.forEach(function(c){codes[c.code]=true;});
  var list=FIN_COA.map(function(c){return c.code;});
  // uncoded bucket
  if(finCatCommitted(key,'')>0||finCatActual(key,'')>0)list.push('');
  return list;}
function finReportTotals(key){finEnsureCostReport(key);var t={budget:0,committed:0,actual:0,etc:0,efc:0};
  finActiveCats(key).forEach(function(code){t.budget+=finCatBudget(key,code);t.committed+=finCatCommitted(key,code);
    t.actual+=finCatActual(key,code);t.etc+=finCatETC(key,code);t.efc+=finCatEFC(key,code);});
  t.variance=t.budget-t.efc;return t;}

/* ============================================================================
   v35 — FINANCE & ACCOUNTING SUITE (enterprise)
   Portfolio-wide accounting for Meta Broadcast: executive cockpit · general ledger +
   chart of accounts · AP & AR aging · budgeting & forecasting · financial reports
   (P&L, Balance Sheet, Cash Flow, Trial Balance). Aggregates the existing per-
   production cost reports / POs / WOs / transmission spend / AP invoices and
   synthesizes a receivables ledger so the statements are internally consistent.
   Rendered at the top level (scope 'all') AND inside each production (scope=key).
   ============================================================================ */
function apExceptionCount(){try{return finOverdueList().length;}catch(e){return 0;}}
function finPct(n){return (n>=0?'+':'')+n.toFixed(1)+'%';}
/* ---- receivables (customer billings) synthesized from contract value -------- */
var FIN_MARGIN=1.18; /* the network is billed cost + ~18% production fee */
var _finAR=null;
function finContract(key){return Math.round((finBudgets[key]||finReportTotals(key).budget||0)*FIN_MARGIN);}
function _finAirISO(key){var p=productions[key]||{};
  if(p.dateStart&&/^\d{4}-\d{2}-\d{2}/.test(p.dateStart))return p.dateStart.slice(0,10);
  var i=Math.max(0,order.indexOf(key));return '2026-'+('0'+((i%12)+1)).slice(-2)+'-15';}
function _finAddDays(iso,n){try{var d=new Date(iso+'T00:00');d.setDate(d.getDate()+n);return d.toISOString().slice(0,10);}catch(e){return iso;}}
function finARModel(){
  if(_finAR)return _finAR;var today=finToday();var out=[];var seq=41000;
  order.forEach(function(k){var contract=finContract(k);if(!contract)return;var p=productions[k];
    var air=_finAirISO(k);var cust=p.customer||'Meta Live Events';
    [['Mobilization / deposit',0.40,-55],['Progress billing',0.35,-5],['Final / reconciliation',0.25,20]].forEach(function(m,mi){
      var amt=Math.round(contract*m[1]);var due=_finAddDays(air,m[2]);var status,paidOn='';
      if(due<_finAddDays(today,-20)){status='Paid';paidOn=_finAddDays(due,mi+2);}
      else if(due<today){status='Overdue';}
      else if(due<_finAddDays(today,25)){status='Sent';}
      else{status='Draft';}
      out.push({id:'AR-'+(seq++),prod:k,customer:cust,desc:m[0],amount:amt,issued:_finAddDays(due,-25),due:due,status:status,paidOn:paidOn});
    });});
  _finAR=out;return out;}
function finARList(scope){var a=finARModel();return (scope&&scope!=='all')?a.filter(function(v){return v.prod===scope;}):a;}
function finARInvoiced(scope){return finARList(scope).filter(function(v){return v.status!=='Draft';}).reduce(function(s,v){return s+v.amount;},0);}
function finARCollected(scope){return finARList(scope).filter(function(v){return v.status==='Paid';}).reduce(function(s,v){return s+v.amount;},0);}
function finAROutstanding(scope){return finARList(scope).filter(function(v){return v.status==='Sent'||v.status==='Overdue';}).reduce(function(s,v){return s+v.amount;},0);}
/* ---- aging buckets ---------------------------------------------------------- */
function _finAge(due){try{return Math.round((new Date(finToday())-new Date(due+'T00:00'))/864e5);}catch(e){return 0;}}
function _finBucket(items,amtOf,dueOf){var b={cur:0,b30:0,b60:0,b90:0,b90p:0,items:items,n:items.length};
  items.forEach(function(it){var age=_finAge(dueOf(it)),amt=amtOf(it);it.__age=age;
    if(age<=0)b.cur+=amt;else if(age<=30)b.b30+=amt;else if(age<=60)b.b60+=amt;else if(age<=90)b.b90+=amt;else b.b90p+=amt;});
  b.total=b.cur+b.b30+b.b60+b.b90+b.b90p;return b;}
function finAPAging(scope){var it=finInvoices.filter(function(v){return v.status!=='Paid'&&(!scope||scope==='all'||v.prod===scope);});
  return _finBucket(it,function(v){return v.amount||0;},function(v){return v.due;});}
function finARAging(scope){var it=finARList(scope).filter(function(v){return v.status==='Sent'||v.status==='Overdue';});
  return _finBucket(it,function(v){return v.amount||0;},function(v){return v.due;});}
/* ---- scope aggregation ------------------------------------------------------ */
function finScopeKeys(scope){return (scope&&scope!=='all')?[scope]:order.slice();}
function finAgg(scope){var t={budget:0,committed:0,actual:0,etc:0,efc:0,invoiced:0,paid:0,openAP:0};
  finScopeKeys(scope).forEach(function(k){var r=finReportTotals(k);t.budget+=r.budget;t.committed+=r.committed;t.actual+=r.actual;t.etc+=r.etc;t.efc+=r.efc;
    var inv=finInvoiced(k),pd=finPaid(k);t.invoiced+=inv;t.paid+=pd;t.openAP+=(inv-pd);});
  t.variance=t.budget-t.efc;t.revenue=finARInvoiced(scope);t.collected=finARCollected(scope);t.ar=finAROutstanding(scope);
  t.sga=Math.round(t.revenue*0.05);t.margin=t.revenue-t.efc;t.opInc=t.margin-t.sga;t.marginPct=t.revenue?t.margin/t.revenue*100:0;return t;}
function finGLRollup(scope){var keys=finScopeKeys(scope);var rows=[];
  FIN_COA.forEach(function(c){var r={code:c.code,cat:c.cat,budget:0,committed:0,actual:0,etc:0,efc:0};
    keys.forEach(function(k){r.budget+=finCatBudget(k,c.code);r.committed+=finCatCommitted(k,c.code);r.actual+=finCatActual(k,c.code);r.etc+=finCatETC(k,c.code);r.efc+=finCatEFC(k,c.code);});
    r.variance=r.budget-r.efc;rows.push(r);});
  return rows;}

/* ---- shared UI atoms -------------------------------------------------------- */
function finCard(cls){return 'bg-white rounded-2xl p-4 sm:p-5 border border-gray-200/60';}
function finKpiTile(label,val,sub,cls){return '<div class="bg-white rounded-2xl p-3.5 border border-gray-200/60" style="box-shadow:0 4px 20px rgba(0,0,0,.03)"><p class="text-[8px] font-bold uppercase tracking-wider text-gray-400">'+label+'</p><p class="text-xl font-bold mono '+(cls||'text-gray-900')+' leading-tight mt-1">'+val+'</p>'+(sub?'<p class="text-[9px] text-gray-500 mt-0.5">'+esc(sub)+'</p>':'')+'</div>';}
function finBarRow(label,val,max,color,rightTxt){var w=max>0?Math.max(1,Math.min(100,Math.abs(val)/max*100)):0;
  return '<div class="flex items-center gap-2 py-1"><span class="text-[10px] text-gray-600 truncate flex-shrink-0" style="width:9rem">'+esc(label)+'</span>'+
    '<div class="flex-1 h-4 bg-gray-100 rounded-md overflow-hidden relative"><div class="h-full rounded-md" style="width:'+w+'%;background:'+color+'"></div></div>'+
    '<span class="text-[10px] mono font-bold text-gray-800 flex-shrink-0 text-right" style="width:6.5rem">'+(rightTxt!=null?rightTxt:$fmt(val))+'</span></div>';}
function finAgingStrip(b,payTerm){var mx=Math.max(1,b.cur,b.b30,b.b60,b.b90,b.b90p);
  var cell=function(l,v,c){return '<div class="flex-1 min-w-[84px] rounded-xl border border-gray-100 bg-gray-50/60 p-2 text-center"><p class="text-[8px] font-bold uppercase tracking-wider text-gray-400">'+l+'</p><p class="text-[13px] font-bold mono '+c+' mt-0.5">'+$fmt(v)+'</p></div>';};
  return '<div class="flex flex-wrap gap-2">'+cell('Current',b.cur,'text-emerald-700')+cell('1–30',b.b30,'text-gray-800')+cell('31–60',b.b60,'text-amber-600')+cell('61–90',b.b90,'text-orange-600')+cell('90+',b.b90p,'text-red-600')+
    '<div class="flex-1 min-w-[100px] rounded-xl border border-gray-200 p-2 text-center" style="background:#0866FF;border-color:transparent"><p class="text-[8px] font-bold uppercase tracking-wider" style="color:rgba(255,255,255,.85)">Total Open</p><p class="text-[13px] font-bold mono text-white mt-0.5">'+$fmt(b.total)+'</p></div></div>';}

/* ---- COCKPIT ---------------------------------------------------------------- */
function finCockpitHTML(scope){var isAll=(scope==='all');var t=finAgg(scope);var apA=finAPAging(scope),arA=finARAging(scope);var gl=finGLRollup(scope);
  var kpis='<div class="grid grid-cols-2 sm:grid-cols-3 xl:grid-cols-6 gap-3">'+
    finKpiTile('Revenue (billed)',$fmt(t.revenue),'contract value')+
    finKpiTile('Est. Final Cost',$fmt(t.efc),$fmt(t.actual)+' actual · '+$fmt(t.committed)+' committed','text-blue-700')+
    finKpiTile('Gross Margin',$fmt(t.margin),finPct(t.marginPct)+' margin',t.margin>=0?'text-emerald-700':'text-red-600')+
    finKpiTile('Budget Variance',(t.variance>=0?'+':'')+$fmt(t.variance),t.variance>=0?'under budget':'over budget',t.variance>=0?'text-emerald-700':'text-red-600')+
    finKpiTile('Open AP',$fmt(t.openAP),apA.n+' invoice(s)','text-amber-600')+
    finKpiTile('Open AR',$fmt(t.ar),arA.n+' invoice(s)','text-purple-700')+'</div>';
  var glmax=gl.reduce(function(m,r){return Math.max(m,r.efc,r.budget);},1);
  var glBars=gl.filter(function(r){return r.budget||r.efc;}).map(function(r){var over=r.variance<0;
    return finBarRow(r.code+' · '+r.cat,r.efc,glmax,over?'linear-gradient(90deg,#E41E3F,#E41E3F)':'linear-gradient(90deg,#0866FF,#0866FF)',$fmt(r.efc));}).join('');
  var spendCard='<div class="'+finCard()+'" style="box-shadow:0 4px 20px rgba(0,0,0,.03)"><h3 class="text-[10px] font-bold uppercase tracking-wider text-gray-600 mb-2">Spend by GL Account — Estimated Final Cost</h3>'+(glBars||'<p class="text-[10px] text-gray-400 py-3">No coded spend yet.</p>')+'</div>';
  var prodCard='';
  if(isAll){var pm=order.reduce(function(m,k){return Math.max(m,finReportTotals(k).efc,finBudgets[k]||0);},1);
    var rows=order.map(function(k){var r=finReportTotals(k);var over=r.variance<0;
      return '<div class="flex items-center gap-2 py-1 cursor-pointer hover:bg-gray-50 rounded-lg px-1 -mx-1" onclick="openProjFinancePopup(\''+k+'\')">'+
        '<span class="w-2 h-2 rounded-full flex-shrink-0" style="background:'+(dotBg[productions[k].tagColor]||'#b0b3b8')+'"></span>'+
        '<span class="text-[10px] font-semibold text-gray-800 truncate flex-shrink-0" style="width:10rem">'+esc(prodName(k))+'</span>'+
        '<div class="flex-1 h-4 bg-gray-100 rounded-md overflow-hidden relative"><div class="h-full absolute top-0 left-0 rounded-md" style="width:'+Math.min(100,(finBudgets[k]||0)/pm*100)+'%;background:#e4e6eb"></div><div class="h-full absolute top-0 left-0 rounded-md" style="width:'+Math.min(100,r.efc/pm*100)+'%;background:'+(over?'linear-gradient(90deg,#E41E3F,#E41E3F)':'linear-gradient(90deg,#31A24C,#31A24C)')+'"></div></div>'+
        '<span class="text-[10px] mono font-bold flex-shrink-0 text-right '+(over?'text-red-600':'text-gray-700')+'" style="width:9.5rem">'+$fmt(r.efc)+' / '+$fmt(finBudgets[k]||0)+'</span></div>';}).join('');
    prodCard='<div class="'+finCard()+'" style="box-shadow:0 4px 20px rgba(0,0,0,.03)"><div class="flex items-center justify-between mb-2"><h3 class="text-[10px] font-bold uppercase tracking-wider text-gray-600">Budget vs Est. Final Cost — by Production</h3><span class="text-[8px] mono text-gray-400">grey = budget · green/red = EFC</span></div>'+rows+'</div>';}
  var agingCard='<div class="grid grid-cols-1 lg:grid-cols-2 gap-4">'+
    '<div class="'+finCard()+'" style="box-shadow:0 4px 20px rgba(0,0,0,.03)"><h3 class="text-[10px] font-bold uppercase tracking-wider text-gray-600 mb-2">Accounts Payable — Aging</h3>'+finAgingStrip(apA)+'</div>'+
    '<div class="'+finCard()+'" style="box-shadow:0 4px 20px rgba(0,0,0,.03)"><h3 class="text-[10px] font-bold uppercase tracking-wider text-gray-600 mb-2">Accounts Receivable — Aging</h3>'+finAgingStrip(arA)+'</div></div>';
  var cash=t.collected-t.paid+2500000; /* opening cash float */
  var cashCard='<div class="grid grid-cols-2 sm:grid-cols-4 gap-3">'+
    finKpiTile('Cash Position',$fmt(cash),'collections − payments','text-emerald-700')+
    finKpiTile('Collected (AR)',$fmt(t.collected),'received from clients')+
    finKpiTile('Paid (AP)',$fmt(t.paid),'settled to vendors')+
    finKpiTile('Working Capital',$fmt(t.ar-t.openAP),'AR − AP',(t.ar-t.openAP)>=0?'text-gray-900':'text-red-600')+'</div>';
  return '<div class="space-y-4">'+kpis+cashCard+(prodCard?prodCard:'')+'<div class="grid grid-cols-1 xl:grid-cols-2 gap-4">'+spendCard+agingCard.replace('grid grid-cols-1 lg:grid-cols-2 gap-4','space-y-4')+'</div></div>';}

/* ---- GENERAL LEDGER --------------------------------------------------------- */
function finGLHTML(scope){var gl=finGLRollup(scope);var tot={budget:0,committed:0,actual:0,etc:0,efc:0,variance:0};
  gl.forEach(function(r){tot.budget+=r.budget;tot.committed+=r.committed;tot.actual+=r.actual;tot.etc+=r.etc;tot.efc+=r.efc;tot.variance+=r.variance;});
  function row(r,bold){var over=r.variance<0;var vp=r.budget?r.variance/r.budget*100:0;
    return '<tr class="'+(bold?'font-bold bg-gray-50':'hover:bg-gray-50')+' border-b border-gray-100">'+
      '<td class="py-2 pl-2 pr-2 mono text-[10px] text-gray-500">'+esc(r.code)+'</td>'+
      '<td class="py-2 pr-2 text-[11px] '+(bold?'text-gray-900':'text-gray-800')+'">'+esc(r.cat)+'</td>'+
      '<td class="py-2 pr-2 text-right mono text-[10px] text-gray-700">'+$fmt(r.budget)+'</td>'+
      '<td class="py-2 pr-2 text-right mono text-[10px] text-blue-700">'+$fmt(r.committed)+'</td>'+
      '<td class="py-2 pr-2 text-right mono text-[10px] text-gray-900">'+$fmt(r.actual)+'</td>'+
      '<td class="py-2 pr-2 text-right mono text-[10px] text-gray-500">'+$fmt(r.etc)+'</td>'+
      '<td class="py-2 pr-2 text-right mono text-[10px] font-bold text-gray-900">'+$fmt(r.efc)+'</td>'+
      '<td class="py-2 pr-2 text-right mono text-[10px] font-bold '+(over?'text-red-600':'text-emerald-700')+'">'+(r.variance>=0?'+':'')+$fmt(r.variance)+'</td>'+
      '<td class="py-2 pr-2 text-right mono text-[9px] '+(over?'text-red-500':'text-emerald-600')+'">'+finPct(vp)+'</td></tr>';}
  var body=gl.map(function(r){return row(r,false);}).join('')+row({code:'',cat:'TOTAL — All Accounts',budget:tot.budget,committed:tot.committed,actual:tot.actual,etc:tot.etc,efc:tot.efc,variance:tot.variance},true);
  var coa='<div class="'+finCard()+'" style="box-shadow:0 4px 20px rgba(0,0,0,.03)"><div class="flex flex-wrap items-center justify-between gap-2 mb-3"><div><h3 class="text-xs font-bold uppercase tracking-wider text-gray-600">General Ledger — Chart of Accounts</h3><p class="text-[9px] text-gray-500 mt-0.5">Budget · Committed (PO/WO/Tx) · Actuals (invoiced) · ETC · Estimate at Completion · Variance to budget</p></div><span class="text-[8px] mono text-gray-400">'+gl.length+' accounts · USD</span></div>'+
    '<div class="overflow-x-auto"><table class="w-full text-left" style="min-width:760px"><thead><tr class="text-[8px] font-bold uppercase tracking-wider text-gray-400 border-b border-gray-200"><th class="py-2 pl-2">Acct</th><th class="py-2">Account</th><th class="py-2 text-right">Budget</th><th class="py-2 text-right">Committed</th><th class="py-2 text-right">Actual</th><th class="py-2 text-right">ETC</th><th class="py-2 text-right">EFC</th><th class="py-2 text-right">Variance</th><th class="py-2 text-right">%</th></tr></thead><tbody>'+body+'</tbody></table></div></div>';
  return '<div class="space-y-4">'+coa+'</div>';}

/* ---- ACCOUNTS PAYABLE / RECEIVABLE ------------------------------------------ */
function _finAgeTag(age){if(age<=0)return '<span class="text-[8px] font-bold text-emerald-700 bg-emerald-50 border border-emerald-200 rounded px-1">current</span>';
  var c=age<=30?'text-gray-600 bg-gray-100 border-gray-200':(age<=60?'text-amber-700 bg-amber-50 border-amber-200':(age<=90?'text-orange-700 bg-orange-50 border-orange-200':'text-red-700 bg-red-50 border-red-200'));
  return '<span class="text-[8px] font-bold '+c+' border rounded px-1">'+age+'d</span>';}
function finAPHTML(scope){var b=finAPAging(scope);var items=b.items.slice().sort(function(a,c){return c.__age-a.__age;});
  var rows=items.map(function(v){return '<tr class="hover:bg-gray-50 border-b border-gray-100 cursor-pointer" onclick="openProjFinance(\''+v.prod+'\')">'+
    '<td class="py-2 pl-2 mono text-[10px] text-gray-500">'+esc(v.id)+'</td>'+
    '<td class="py-2 text-[11px] font-semibold text-gray-900">'+esc(v.vendor)+'</td>'+
    '<td class="py-2 text-[10px] text-gray-600">'+esc(prodName(v.prod))+'</td>'+
    '<td class="py-2 text-[10px] mono text-gray-500">'+esc(v.ref||'—')+'</td>'+
    '<td class="py-2 text-[10px] mono text-gray-600">'+fmtD(v.due)+'</td>'+
    '<td class="py-2 text-center">'+_finAgeTag(v.__age)+'</td>'+
    '<td class="py-2 text-[10px]">'+woStatusPill(v.status)+'</td>'+
    '<td class="py-2 pr-2 text-right mono text-[11px] font-bold text-gray-900">'+$fmt(v.amount)+'</td></tr>';}).join('')||'<tr><td colspan="8" class="py-4 text-center text-[10px] text-gray-400">No open payables — everything is settled.</td></tr>';
  return '<div class="space-y-4"><div class="'+finCard()+'" style="box-shadow:0 4px 20px rgba(0,0,0,.03)"><h3 class="text-xs font-bold uppercase tracking-wider text-gray-600 mb-3">Accounts Payable — Aging</h3>'+finAgingStrip(b)+'</div>'+
    '<div class="'+finCard()+'" style="box-shadow:0 4px 20px rgba(0,0,0,.03)"><div class="flex items-center justify-between mb-2"><h3 class="text-[10px] font-bold uppercase tracking-wider text-gray-600">Open Vendor Invoices</h3><span class="text-[8px] mono text-gray-400">'+b.n+' open · '+$fmt(b.total)+'</span></div>'+
    '<div class="overflow-x-auto"><table class="w-full text-left" style="min-width:720px"><thead><tr class="text-[8px] font-bold uppercase tracking-wider text-gray-400 border-b border-gray-200"><th class="py-2 pl-2">Invoice</th><th class="py-2">Vendor</th><th class="py-2">Production</th><th class="py-2">PO/WO</th><th class="py-2">Due</th><th class="py-2 text-center">Age</th><th class="py-2">Status</th><th class="py-2 text-right">Amount</th></tr></thead><tbody>'+rows+'</tbody></table></div></div></div>';}
function finARHTML(scope){var b=finARAging(scope);var all=finARList(scope).slice().sort(function(a,c){return (a.due<c.due?1:-1);});
  var rows=all.map(function(v){var age=_finAge(v.due);
    return '<tr class="hover:bg-gray-50 border-b border-gray-100 cursor-pointer" onclick="openProjFinance(\''+v.prod+'\')">'+
    '<td class="py-2 pl-2 mono text-[10px] text-gray-500">'+esc(v.id)+'</td>'+
    '<td class="py-2 text-[11px] font-semibold text-gray-900">'+esc(v.customer)+'</td>'+
    '<td class="py-2 text-[10px] text-gray-600">'+esc(prodName(v.prod))+'</td>'+
    '<td class="py-2 text-[10px] text-gray-600">'+esc(v.desc)+'</td>'+
    '<td class="py-2 text-[10px] mono text-gray-600">'+fmtD(v.due)+'</td>'+
    '<td class="py-2 text-center">'+(v.status==='Paid'||v.status==='Draft'?'<span class="text-[8px] text-gray-300">—</span>':_finAgeTag(age))+'</td>'+
    '<td class="py-2 text-[10px]">'+woStatusPill(v.status==='Sent'?'Approved':(v.status==='Overdue'?'Overdue':v.status))+'</td>'+
    '<td class="py-2 pr-2 text-right mono text-[11px] font-bold text-gray-900">'+$fmt(v.amount)+'</td></tr>';}).join('')||'<tr><td colspan="8" class="py-4 text-center text-[10px] text-gray-400">No receivables.</td></tr>';
  return '<div class="space-y-4"><div class="'+finCard()+'" style="box-shadow:0 4px 20px rgba(0,0,0,.03)"><h3 class="text-xs font-bold uppercase tracking-wider text-gray-600 mb-3">Accounts Receivable — Aging</h3>'+finAgingStrip(b)+'</div>'+
    '<div class="'+finCard()+'" style="box-shadow:0 4px 20px rgba(0,0,0,.03)"><div class="flex items-center justify-between mb-2"><h3 class="text-[10px] font-bold uppercase tracking-wider text-gray-600">Customer Billings</h3><span class="text-[8px] mono text-gray-400">'+all.length+' invoice(s) · client fee '+Math.round((FIN_MARGIN-1)*100)+'% over cost</span></div>'+
    '<div class="overflow-x-auto"><table class="w-full text-left" style="min-width:720px"><thead><tr class="text-[8px] font-bold uppercase tracking-wider text-gray-400 border-b border-gray-200"><th class="py-2 pl-2">Invoice</th><th class="py-2">Customer</th><th class="py-2">Production</th><th class="py-2">Milestone</th><th class="py-2">Due</th><th class="py-2 text-center">Age</th><th class="py-2">Status</th><th class="py-2 text-right">Amount</th></tr></thead><tbody>'+rows+'</tbody></table></div></div></div>';}

/* ---- BUDGET & FORECAST ------------------------------------------------------ */
function finBudgetHTML(scope){var isAll=(scope==='all');var gl=finGLRollup(scope);var t=finAgg(scope);
  var mx=gl.reduce(function(m,r){return Math.max(m,r.budget,r.efc);},1);
  var catRows=gl.filter(function(r){return r.budget||r.efc;}).map(function(r){var over=r.variance<0;var bp=r.budget?Math.min(100,r.budget/mx*100):0,ep=r.efc?Math.min(100,r.efc/mx*100):0;
    return '<div class="py-1.5 border-b border-gray-50"><div class="flex items-center justify-between gap-2"><span class="text-[10px] font-semibold text-gray-800">'+esc(r.code+' · '+r.cat)+'</span><span class="text-[10px] mono font-bold '+(over?'text-red-600':'text-emerald-700')+'">'+(r.variance>=0?'+':'')+$fmt(r.variance)+'</span></div>'+
      '<div class="relative h-4 bg-gray-100 rounded-md overflow-hidden mt-1"><div class="h-full absolute top-0 left-0 rounded-md" style="width:'+bp+'%;background:#e4e6eb"></div><div class="h-full absolute top-0 left-0 rounded-md" style="width:'+ep+'%;background:'+(over?'linear-gradient(90deg,#E41E3F,#E41E3F)':'linear-gradient(90deg,#0866FF,#0866FF)')+'"></div></div>'+
      '<div class="flex items-center justify-between mt-0.5 text-[8px] mono text-gray-400"><span>Budget '+$fmt(r.budget)+'</span><span>EFC '+$fmt(r.efc)+'</span></div></div>';}).join('');
  var forecast='<div class="'+finCard()+'" style="box-shadow:0 4px 20px rgba(0,0,0,.03)"><div class="flex flex-wrap items-center justify-between gap-2 mb-3"><div><h3 class="text-xs font-bold uppercase tracking-wider text-gray-600">Budget vs Estimate at Completion</h3><p class="text-[9px] text-gray-500 mt-0.5">grey bar = approved budget · colored bar = current EFC (Actual + Committed + ETC)</p></div>'+
    '<div class="flex items-center gap-2"><span class="text-[8px] font-bold uppercase tracking-wider text-gray-400">Total EFC</span><span class="text-lg font-bold mono '+(t.variance>=0?'text-emerald-700':'text-red-600')+'">'+$fmt(t.efc)+'</span></div></div>'+catRows+'</div>';
  var summary='<div class="grid grid-cols-2 sm:grid-cols-4 gap-3">'+
    finKpiTile('Approved Budget',$fmt(t.budget),'top-line')+
    finKpiTile('Estimate at Completion',$fmt(t.efc),'actual + committed + ETC','text-blue-700')+
    finKpiTile('Variance to Budget',(t.variance>=0?'+':'')+$fmt(t.variance),finPct(t.budget?t.variance/t.budget*100:0),t.variance>=0?'text-emerald-700':'text-red-600')+
    finKpiTile('% Committed',finPct(t.budget?(t.actual+t.committed)/t.budget*100:0).replace('+',''),'of budget spent/locked')+'</div>';
  var prodTable='';
  if(isAll){var rows=order.map(function(k){var r=finReportTotals(k);var over=r.variance<0;
    return '<tr class="hover:bg-gray-50 border-b border-gray-100 cursor-pointer" onclick="openProjFinance(\''+k+'\')"><td class="py-2 pl-2 text-[11px] font-semibold text-gray-900">'+esc(prodName(k))+'</td>'+
      '<td class="py-2 text-right mono text-[10px] text-gray-700">'+$fmt(r.budget)+'</td><td class="py-2 text-right mono text-[10px] text-gray-900">'+$fmt(r.actual)+'</td><td class="py-2 text-right mono text-[10px] text-blue-700">'+$fmt(r.committed)+'</td><td class="py-2 text-right mono text-[10px] font-bold text-gray-900">'+$fmt(r.efc)+'</td>'+
      '<td class="py-2 pr-2 text-right mono text-[10px] font-bold '+(over?'text-red-600':'text-emerald-700')+'">'+(r.variance>=0?'+':'')+$fmt(r.variance)+'</td></tr>';}).join('');
    prodTable='<div class="'+finCard()+'" style="box-shadow:0 4px 20px rgba(0,0,0,.03)"><h3 class="text-[10px] font-bold uppercase tracking-wider text-gray-600 mb-2">Forecast by Production</h3><div class="overflow-x-auto"><table class="w-full text-left" style="min-width:640px"><thead><tr class="text-[8px] font-bold uppercase tracking-wider text-gray-400 border-b border-gray-200"><th class="py-2 pl-2">Production</th><th class="py-2 text-right">Budget</th><th class="py-2 text-right">Actual</th><th class="py-2 text-right">Committed</th><th class="py-2 text-right">EFC</th><th class="py-2 text-right">Variance</th></tr></thead><tbody>'+rows+'</tbody></table></div></div>';}
  return '<div class="space-y-4">'+summary+forecast+prodTable+'</div>';}

/* ---- FINANCIAL REPORTS (P&L / Balance Sheet / Cash Flow / Trial Balance) ----- */
function _finStmtRow(label,val,opts){opts=opts||{};var ind=opts.indent?'padding-left:'+(opts.indent*14+8)+'px':'padding-left:8px';
  return '<tr class="'+(opts.total?'font-bold border-t-2 border-gray-300':(opts.sub?'font-semibold':''))+'"><td class="py-1.5 text-[11px] '+(opts.muted?'text-gray-500':'text-gray-800')+'" style="'+ind+'">'+esc(label)+'</td>'+
    '<td class="py-1.5 pr-3 text-right mono text-[11px] '+(val<0?'text-red-600':(opts.total?'text-gray-900':'text-gray-800'))+'">'+(val==null?'':((val<0?'(':'')+$fmt(Math.abs(val))+(val<0?')':'')))+'</td></tr>';}
function finPL(scope){var t=finAgg(scope);var gl=finGLRollup(scope);
  var rows=_finStmtRow('Production Services Revenue',t.revenue,{sub:true});
  rows+=_finStmtRow('Cost of Production',null,{sub:true});
  gl.filter(function(r){return r.efc;}).forEach(function(r){rows+=_finStmtRow(r.code+' · '+r.cat,-r.efc,{indent:1,muted:true});});
  rows+=_finStmtRow('Total Cost of Production',-t.efc,{sub:true});
  rows+=_finStmtRow('Gross Margin',t.margin,{total:true});
  rows+=_finStmtRow('SG&A / Corporate Allocation',-t.sga,{indent:1,muted:true});
  rows+=_finStmtRow('Operating Income (EBIT)',t.opInc,{total:true});
  return {rows:rows,title:'Income Statement (P&L)',sub:'Revenue less production cost and allocated overhead'};}
function finBS(scope){var t=finAgg(scope);var cash=t.collected-t.paid+2500000;var wip=Math.max(0,t.committed);
  var assets=cash+t.ar+wip;var ap=t.openAP;var deferred=Math.max(0,t.collected-t.efc*(t.revenue?t.collected/t.revenue:0));
  var liab=ap+deferred;var equity=assets-liab;
  var rows=_finStmtRow('ASSETS',null,{sub:true});
  rows+=_finStmtRow('Cash & Cash Equivalents',cash,{indent:1});
  rows+=_finStmtRow('Accounts Receivable',t.ar,{indent:1});
  rows+=_finStmtRow('Unbilled WIP / Committed Costs',wip,{indent:1});
  rows+=_finStmtRow('Total Assets',assets,{total:true});
  rows+=_finStmtRow('LIABILITIES',null,{sub:true});
  rows+=_finStmtRow('Accounts Payable',ap,{indent:1});
  rows+=_finStmtRow('Deferred Revenue',deferred,{indent:1});
  rows+=_finStmtRow('Total Liabilities',liab,{sub:true});
  rows+=_finStmtRow('EQUITY',null,{sub:true});
  rows+=_finStmtRow('Retained Earnings & Net Income',equity,{indent:1});
  rows+=_finStmtRow('Total Liabilities & Equity',liab+equity,{total:true});
  return {rows:rows,title:'Balance Sheet',sub:'Illustrative — equity is the residual (Assets − Liabilities)',data:{cash:cash,ar:t.ar,wip:wip,ap:ap,deferred:deferred,equity:equity,assets:assets}};}
function finCF(scope){var t=finAgg(scope);var netOps=t.collected-t.paid;
  var rows=_finStmtRow('CASH FLOW FROM OPERATIONS',null,{sub:true});
  rows+=_finStmtRow('Collections from Customers',t.collected,{indent:1});
  rows+=_finStmtRow('Payments to Vendors',-t.paid,{indent:1});
  rows+=_finStmtRow('Net Cash from Operations',netOps,{total:true});
  rows+=_finStmtRow('Investing Activities',0,{indent:1,muted:true});
  rows+=_finStmtRow('Financing Activities',0,{indent:1,muted:true});
  rows+=_finStmtRow('Net Change in Cash',netOps,{total:true});
  rows+=_finStmtRow('Opening Cash Float',2500000,{indent:1,muted:true});
  rows+=_finStmtRow('Ending Cash Position',netOps+2500000,{total:true});
  return {rows:rows,title:'Cash Flow Statement',sub:'Indirect method — operating collections vs vendor settlements'};}
function finTB(scope){var bs=finBS(scope).data;var t=finAgg(scope);
  /* retained earnings excludes the current period's net income — that flows through
     the temporary Revenue/Cost/SG&A accounts below, so debits === credits */
  var retained=bs.equity-t.opInc;
  function acc(code,name,amt,side){var dr=0,cr=0;
    if(side==='dr'){if(amt>=0)dr=amt;else cr=-amt;}else{if(amt>=0)cr=amt;else dr=-amt;}return [code,name,dr,cr];}
  var accts=[acc('1000','Cash & Equivalents',bs.cash,'dr'),acc('1100','Accounts Receivable',bs.ar,'dr'),acc('1200','Unbilled WIP',bs.wip,'dr'),
    acc('2000','Accounts Payable',bs.ap,'cr'),acc('2300','Deferred Revenue',bs.deferred,'cr'),acc('3000','Retained Earnings',retained,'cr'),
    acc('4000','Production Revenue',t.revenue,'cr'),acc('5000','Cost of Production',t.efc,'dr'),acc('6000','SG&A / Overhead',t.sga,'dr')];
  var dr=0,cr=0;var rows=accts.map(function(a){dr+=a[2];cr+=a[3];
    return '<tr class="border-b border-gray-100"><td class="py-1.5 pl-2 mono text-[10px] text-gray-500">'+a[0]+'</td><td class="py-1.5 text-[11px] text-gray-800">'+esc(a[1])+'</td>'+
      '<td class="py-1.5 text-right mono text-[10px] text-gray-900">'+(a[2]?$fmt(a[2]):'')+'</td><td class="py-1.5 pr-2 text-right mono text-[10px] text-gray-900">'+(a[3]?$fmt(a[3]):'')+'</td></tr>';}).join('');
  rows+='<tr class="font-bold border-t-2 border-gray-300"><td class="py-2 pl-2"></td><td class="py-2 text-[11px] text-gray-900">TOTAL</td><td class="py-2 text-right mono text-[11px] text-gray-900">'+$fmt(dr)+'</td><td class="py-2 pr-2 text-right mono text-[11px] text-gray-900">'+$fmt(cr)+'</td></tr>';
  return {rows:rows,dr:dr,cr:cr};}
function finReportsHTML(scope){var pl=finPL(scope),bs=finBS(scope),cf=finCF(scope),tb=finTB(scope);
  function stmt(o){return '<div class="'+finCard()+'" style="box-shadow:0 4px 20px rgba(0,0,0,.03)"><div class="mb-2"><h3 class="text-[11px] font-bold uppercase tracking-wider text-gray-700">'+esc(o.title)+'</h3><p class="text-[8px] text-gray-400">'+esc(o.sub||'')+'</p></div><table class="w-full">'+o.rows+'</table></div>';}
  var tbCard='<div class="'+finCard()+'" style="box-shadow:0 4px 20px rgba(0,0,0,.03)"><div class="mb-2"><h3 class="text-[11px] font-bold uppercase tracking-wider text-gray-700">Trial Balance</h3><p class="text-[8px] text-gray-400">Debits = Credits '+(Math.abs(tb.dr-tb.cr)<2?'✓ balanced':'')+'</p></div>'+
    '<table class="w-full"><thead><tr class="text-[8px] font-bold uppercase tracking-wider text-gray-400 border-b border-gray-200"><th class="py-1.5 pl-2 text-left">Acct</th><th class="py-1.5 text-left">Account</th><th class="py-1.5 text-right">Debit</th><th class="py-1.5 pr-2 text-right">Credit</th></tr></thead><tbody>'+tb.rows+'</tbody></table></div>';
  return '<div class="grid grid-cols-1 xl:grid-cols-2 gap-4">'+stmt(pl)+stmt(bs)+stmt(cf)+tbCard+'</div>';}

/* ---- workspace shell -------------------------------------------------------- */
var finWsTab={};
function setFinTab(scope,tab){finWsTab[scope||'all']=tab;
  var y=window.scrollY||window.pageYOffset||0,x=window.scrollX||window.pageXOffset||0;
  if(scope&&scope!=='all'){if(document.getElementById('view-'+scope))renderProjectView(scope);}else renderFinanceView();
  /* Keep scroll when switching Finance sub-tabs inside a production */
  if(scope&&scope!=='all'){try{window.scrollTo(x,y);}catch(e){}}
  else{try{window.scrollTo(0,0);}catch(e2){}}}
function financeWorkspaceHTML(scope){scope=scope||'all';var isAll=(scope==='all');var tab=finWsTab[scope]||'cockpit';
  var tabs=[['cockpit','Executive Cockpit'],['gl','General Ledger'],['ap','Accounts Payable'],['ar','Accounts Receivable'],['budget','Budget & Forecast'],['reports','Financial Reports']];
  if(!isAll)tabs.push(['ops','Ledger & Ops']);
  if(!tabs.some(function(t){return t[0]===tab;}))tab='cockpit';
  var strip=tabs.map(function(t){return '<button onclick="setFinTab(\''+scope+'\',\''+t[0]+'\')" class="px-3.5 py-2 rounded-lg text-[11px] font-bold transition-colors '+(tab===t[0]?'bg-gray-900 text-white shadow-sm':'text-gray-600 hover:bg-gray-100')+'">'+t[1]+'</button>';}).join('');
  var body=tab==='gl'?finGLHTML(scope):(tab==='ap'?finAPHTML(scope):(tab==='ar'?finARHTML(scope):(tab==='budget'?finBudgetHTML(scope):(tab==='reports'?finReportsHTML(scope):(tab==='ops'&&!isAll?financePaneHTML(scope):finCockpitHTML(scope))))));
  var head=isAll?('<div class="flex flex-wrap items-center justify-between gap-3 pb-4 border-b border-gray-300/80">'+
      '<div class="flex items-center gap-3"><div class="w-10 h-10 rounded-xl flex items-center justify-center text-white flex-shrink-0" style="background:linear-gradient(135deg,#1c1e21,#242526)"><svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="#ffffff" stroke-width="2" stroke-linecap="round"><path d="M12 1v22"/><path d="M17 5H9.5a3.5 3.5 0 0 0 0 7h5a3.5 3.5 0 0 1 0 7H6"/></svg></div>'+
      '<div><h1 class="text-2xl font-semibold tracking-tight text-gray-900">Finance &amp; Accounting</h1><p class="text-xs text-gray-500 mt-0.5">Portfolio general ledger, AP/AR, budgeting &amp; reporting across '+order.length+' productions · FY2025–26 · USD</p></div></div>'+
      '<div class="flex items-center gap-2 flex-wrap"><span class="text-[8px] mono font-bold bg-gray-100 text-gray-500 border border-gray-200 px-2 py-1 rounded hidden sm:inline">Meta Finance · FY2025–26 · USD</span>'+
      '<button onclick="finExportCSV(\''+scope+'\')" class="text-[10px] font-bold text-gray-700 border border-gray-300 rounded-lg px-3 py-2 hover:bg-gray-50">⬇ GL CSV</button>'+
      '<button onclick="finPrintPack(\''+scope+'\')" class="text-[10px] font-bold text-white bg-gray-900 rounded-lg px-3 py-2 hover:bg-gray-800">🖨 Statement Pack</button></div></div>'):
    ('<div class="flex flex-wrap items-center justify-between gap-2 mb-1"><div><h3 class="text-xs font-bold uppercase tracking-wider text-gray-600">Finance &amp; Accounting — '+esc(prodName(scope))+'</h3><p class="text-[9px] text-gray-500 mt-0.5">Ledger, receivables, budget &amp; statements for this production · USD</p></div>'+
      '<div class="flex items-center gap-2"><button onclick="finExportCSV(\''+scope+'\')" class="text-[9px] font-bold text-gray-700 border border-gray-300 rounded-lg px-2.5 py-1.5 hover:bg-gray-50">⬇ GL CSV</button><button onclick="finPrintPack(\''+scope+'\')" class="text-[9px] font-bold text-white bg-gray-900 rounded-lg px-2.5 py-1.5 hover:bg-gray-800">🖨 Statements</button></div></div>');
  return '<div class="space-y-4">'+head+'<div class="flex items-center gap-1 bg-gray-100 rounded-xl p-1 flex-wrap">'+strip+'</div>'+body+'</div>';}
function renderFinanceView(){var host=document.getElementById('view-finance');if(!host)return;
  if(typeof permCan==='function'&&!permCan('finance')){host.innerHTML='<div class="bg-white rounded-2xl p-10 border border-gray-200/60 text-center" style="box-shadow:0 4px 20px rgba(0,0,0,.03)"><div class="text-3xl mb-2">🔒</div><h2 class="text-lg font-bold text-gray-900">Finance is restricted</h2><p class="text-sm text-gray-500 mt-1">The accounting suite is available to the Executive &amp; Admin roles. Flip the “Viewing as” switcher in the header to Executive.</p></div>';return;}
  _finAR=null; /* refresh receivables against the latest budgets */
  host.innerHTML=financeWorkspaceHTML('all');}
/* ---- export + printable statement pack -------------------------------------- */
function finExportCSV(scope){var gl=finGLRollup(scope);var lines=['Account Code,Account,Budget,Committed,Actual,ETC,EFC,Variance'];
  gl.forEach(function(r){lines.push([r.code,'"'+r.cat+'"',r.budget,r.committed,r.actual,r.etc,r.efc,r.variance].join(','));});
  var t=finAgg(scope);lines.push(['','TOTAL',t.budget,t.committed,t.actual,t.etc,t.efc,t.variance].join(','));
  var blob=new Blob([lines.join('\n')],{type:'text/csv'});var url=URL.createObjectURL(blob);var a=document.createElement('a');
  a.href=url;a.download='Muse_Live_GL_'+(scope==='all'?'Portfolio':scope)+'.csv';document.body.appendChild(a);a.click();
  setTimeout(function(){document.body.removeChild(a);URL.revokeObjectURL(url);},100);toast('General Ledger exported (CSV)');}
function finPrintPack(scope){var pl=finPL(scope),bs=finBS(scope),cf=finCF(scope),tb=finTB(scope);var gl=finGLRollup(scope);var t=finAgg(scope);
  var name=scope==='all'?'Portfolio — All Productions':prodName(scope);
  function tbl(o){return '<h2>'+esc(o.title)+'</h2><p class="s">'+esc(o.sub||'')+'</p><table class="stmt">'+o.rows.replace(/class="[^"]*"/g,'').replace(/style="[^"]*"/g,'')+'</table>';}
  var glRows=gl.map(function(r){return '<tr><td>'+r.code+'</td><td>'+esc(r.cat)+'</td><td class="n">'+$fmt(r.budget)+'</td><td class="n">'+$fmt(r.committed)+'</td><td class="n">'+$fmt(r.actual)+'</td><td class="n">'+$fmt(r.efc)+'</td><td class="n">'+(r.variance>=0?'+':'')+$fmt(r.variance)+'</td></tr>';}).join('');
  var bar='<div class="bar"><i style="background:linear-gradient(90deg,#0064E0,#0082FB,#00C2FF)"></i></div>';
  var html='<!DOCTYPE html><html><head><meta charset="utf-8"><title>Muse Live — Financial Statement Pack — '+esc(name)+'</title><style>'+
    '@page{size:A4;margin:14mm}*{box-sizing:border-box}body{font-family:-apple-system,Segoe UI,Helvetica,Arial,sans-serif;color:#242526;font-size:11px}'+
    '.bar{display:flex;height:5px}.bar i{flex:1}.hd{background:#1c1e21;color:#ffffff;padding:14px 18px;display:flex;justify-content:space-between;align-items:flex-end}'+
    '.hd h1{font-size:18px;margin:0}.hd .r{text-align:right;font-size:9px;color:#ced0d4;line-height:1.6}'+
    'h2{font-size:12px;text-transform:uppercase;letter-spacing:.5px;color:#1c1e21;margin:16px 0 2px;border-left:3px solid #E41E3F;padding-left:8px}'+
    'p.s{font-size:8px;color:#8A8D91;margin:0 0 4px 11px}table{width:100%;border-collapse:collapse;margin:2px 0 6px}'+
    'table.stmt td{padding:3px 6px;border-bottom:.5px solid #f0f2f5}table.stmt td:last-child{text-align:right;font-family:monospace}'+
    'table.gl th{background:#1c1e21;color:#ffffff;font-size:8px;text-transform:uppercase;padding:5px 6px;text-align:left}table.gl td{border-bottom:.5px solid #e4e6eb;padding:4px 6px;font-size:9px}td.n{text-align:right;font-family:monospace}'+
    '.foot{margin-top:16px;border-top:1px solid #f0f2f5;padding-top:6px;font-size:8px;color:#8A8D91;display:flex;justify-content:space-between}'+
    '.kpi{display:flex;gap:10px;margin:8px 0}.kpi div{flex:1;border:1px solid #e4e6eb;border-radius:6px;padding:6px 8px}.kpi b{display:block;font-size:14px;font-family:monospace}.kpi span{font-size:7px;text-transform:uppercase;letter-spacing:.5px;color:#8A8D91}'+
    '</style></head><body>'+bar+
    '<div class="hd"><div><h1>FINANCIAL STATEMENT PACK</h1><div style="font-size:11px;color:#ced0d4;margin-top:3px">'+esc(name)+'</div></div><div class="r">Meta Broadcast Operations<br>FY2025–26 · USD<br>Prepared '+esc(nowStamp())+'</div></div>'+
    '<div class="kpi"><div><span>Revenue</span><b>'+$fmt(t.revenue)+'</b></div><div><span>Est. Final Cost</span><b>'+$fmt(t.efc)+'</b></div><div><span>Gross Margin</span><b>'+$fmt(t.margin)+'</b></div><div><span>Open AP</span><b>'+$fmt(t.openAP)+'</b></div><div><span>Open AR</span><b>'+$fmt(t.ar)+'</b></div></div>'+
    tbl(pl)+tbl(bs)+tbl(cf)+
    '<h2>Trial Balance</h2><table class="gl"><tr><th>Acct</th><th>Account</th><th>Debit</th><th>Credit</th></tr>'+tb.rows.replace(/class="[^"]*"/g,'').replace(/style="[^"]*"/g,'').replace(/<td /g,'<td class="n" ').replace(/<td class="n" class="n"/g,'<td class="n"')+'</table>'+
    '<h2>General Ledger — Chart of Accounts</h2><table class="gl"><tr><th>Acct</th><th>Account</th><th>Budget</th><th>Committed</th><th>Actual</th><th>EFC</th><th>Variance</th></tr>'+glRows+'</table>'+
    '<div class="foot"><span>Meta Broadcast Telemetry · Confidential · Financial Statement Pack</span><span>Illustrative management accounts · generated from Muse Live</span></div>'+
    '</body></html>';
  var w=window.open('','_blank');if(!w){toast('Allow pop-ups to export the statement pack');return;}
  w.document.open();w.document.write(html);w.document.close();toast('Statement pack ready — choose Save as PDF');
  setTimeout(function(){try{w.focus();w.print();}catch(e){}},650);}

/* ---- mutations ---- */
function finSetLineName(key,id,v){var cr=finEnsureCostReport(key);cr.lines.forEach(function(l){if(l.id===id)l.name=v;});saveOps();}
function finSetLineBudget(key,id,v){var cr=finEnsureCostReport(key);cr.lines.forEach(function(l){if(l.id===id)l.budget=Math.max(0,Math.round(parseFloat(v)||0));});finRecalcBudget(key);saveOps();renderProjectView(key);}
function finAddLine(key,code){var cr=finEnsureCostReport(key);cr.lines.push({id:'L'+key+'_'+Date.now().toString(36),code:code+'-new',cat:code,name:'New line item',budget:0,note:''});finCatOpen[key+code]=true;saveOps();renderProjectView(key);}
function finDelLine(key,id){var cr=finEnsureCostReport(key);cr.lines=cr.lines.filter(function(l){return l.id!==id;});finRecalcBudget(key);saveOps();renderProjectView(key);}
function finSetCatETC(key,code,v){var cr=finEnsureCostReport(key);if(!cr.etc)cr.etc={};
  cr.etc[code]=(v===''||v==null)?'':Math.max(0,Math.round(parseFloat(v)||0));saveOps();renderProjectView(key);}
function finToggleCatRow(key,code){finCatOpen[key+code]=!finCatOpen[key+code];renderProjectView(key);}
function finSetView(key,v){finView[key]=v;renderProjectView(key);}
function finResetReport(key){if(!confirm('Reset the cost report to a fresh topsheet from the current budget total? Line edits and ETC overrides will be lost (coding on POs/invoices is kept).'))return;
  var total=finBudgets[key]||0;delete finCostReport[key];finBudgets[key]=total;finEnsureCostReport(key);saveOps();renderProjectView(key);}

/* ---- view toggle strip ---- */
function finViewStrip(key){var v=finView[key]||'report';
  function b(id,label){return '<button onclick="finSetView(\''+key+'\',\''+id+'\')" class="px-3 py-1.5 rounded-lg text-[10px] font-bold transition-colors '+(v===id?'bg-white text-gray-900 shadow-sm':'text-gray-500 hover:text-gray-700')+'">'+label+'</button>';}
  return '<div class="inline-flex items-center gap-1 bg-gray-100 rounded-xl p-1">'+b('report','Cost Report')+b('labor','Labor')+b('ledger','AP Ledger')+'</div>';}

/* ---- the cost report pane ---- */
function finVarPill(v){if(v>=0)return '<span class="text-[10px] mono font-bold text-emerald-600">'+$fmt(v)+'</span>';
  return '<span class="text-[10px] mono font-bold text-red-600">('+$fmt(Math.abs(v))+')</span>';}
function costReportPaneHTML(key){var p=productions[key];var cr=finEnsureCostReport(key);var T=finReportTotals(key);
  var spent=T.actual+T.committed;var pctEFC=T.budget?Math.min(140,Math.round(T.efc/T.budget*100)):0;
  var over=T.variance<0;
  // summary band — stacked bar (actual / committed / etc) against the budget marker
  var denom=Math.max(T.budget,T.efc,1);
  function seg(val,grad,title){var w=val/denom*100;return w>0.1?'<div style="width:'+w+'%;background:'+grad+'" title="'+title+'"></div>':'';}
  function bigcard(label,val,cls,sub){return '<div class="bg-gray-50 rounded-xl p-3 border border-gray-100"><p class="text-[8px] font-bold uppercase tracking-wider text-gray-500">'+label+'</p><p class="text-base font-bold mono '+(cls||'text-gray-900')+' leading-tight mt-0.5">'+val+'</p>'+(sub?'<p class="text-[8px] mono text-gray-400 mt-0.5">'+sub+'</p>':'')+'</div>';}
  var summary='<div class="bg-white rounded-2xl p-5 border border-gray-200/60" style="box-shadow:0 4px 20px rgba(0,0,0,.03)">'+
    '<div class="flex flex-wrap items-center justify-between gap-2 mb-3"><div><h3 class="text-xs font-bold uppercase tracking-wider text-gray-600">Cost Report — '+esc(p.name)+'</h3>'+
      '<p class="text-[9px] text-gray-500 mt-0.5">Budget → committed → actual → <b>EFC</b>, coded to a broadcast chart of accounts. EFC = actual + open commitments + estimate-to-complete.</p></div>'+
      '<span class="text-[9px] mono '+(over?'text-red-600 font-bold':'text-gray-500')+'">'+(over?'⛔ OVER BY '+$fmt(Math.abs(T.variance)):'✓ '+$fmt(T.variance)+' under')+' · '+cr.currency+'</span></div>'+
    '<div class="grid grid-cols-2 sm:grid-cols-3 xl:grid-cols-6 gap-2 mb-3">'+
      bigcard('Budget',$fmt(T.budget))+
      bigcard('Committed',$fmt(T.committed),'text-blue-700','open, not yet invoiced')+
      bigcard('Actual',$fmt(T.actual),'text-gray-900','invoiced to date')+
      bigcard('Est. to Complete',$fmt(T.etc),'text-gray-500')+
      bigcard('EFC',$fmt(T.efc),over?'text-red-600':'text-gray-900',pctEFC+'% of budget')+
      bigcard('Variance',(over?'('+$fmt(Math.abs(T.variance))+')':$fmt(T.variance)),over?'text-red-600':'text-emerald-700',over?'projected overage':'projected under')+
    '</div>'+
    '<div class="relative h-3 rounded-full bg-gray-100 overflow-hidden flex">'+
      seg(T.actual,'linear-gradient(90deg,#31A24C,#31A24C)','Actual')+
      seg(T.committed,'linear-gradient(90deg,#0866FF,#0866FF)','Committed')+
      seg(T.etc,'repeating-linear-gradient(45deg,#e4e6eb,#e4e6eb 4px,#f0f2f5 4px,#f0f2f5 8px)','Estimate to complete')+
      (T.budget<denom?'<div class="absolute top-0 bottom-0" style="left:'+(T.budget/denom*100)+'%;width:2px;background:#1C1E21" title="Budget"></div>':'')+
    '</div>'+
    '<div class="flex items-center gap-3 mt-1.5 text-[8px] mono text-gray-500"><span class="flex items-center gap-1"><span class="w-2 h-2 rounded-sm" style="background:#1E7B34"></span>actual</span><span class="flex items-center gap-1"><span class="w-2 h-2 rounded-sm" style="background:#0866ff"></span>committed</span><span class="flex items-center gap-1"><span class="w-2 h-2 rounded-sm" style="background:#e4e6eb"></span>to complete</span><span class="flex items-center gap-1"><span class="w-2 h-3" style="background:#1C1E21"></span>budget</span></div></div>';

  // topsheet rows — sortable + filterable (v28 WI7)
  var catCodes=finActiveCats(key);
  var _cq=finWsQ[key+'.cost']||'';
  if(_cq)catCodes=catCodes.filter(function(code){
    if((finCatName(code)+' '+code).toLowerCase().indexOf(_cq)>-1)return true;
    return cr.lines.some(function(l){return l.cat===code&&(l.name||'').toLowerCase().indexOf(_cq)>-1;});});
  var _cs=finWsSort[key+'.cost'];
  if(_cs&&_cs.col){var _cg={account:function(c){return finCatName(c).toLowerCase();},budget:function(c){return finCatBudget(key,c);},
      committed:function(c){return finCatCommitted(key,c);},actual:function(c){return finCatActual(key,c);},
      efc:function(c){return finCatEFC(key,c);},variance:function(c){return finCatBudget(key,c)-finCatEFC(key,c);}}[_cs.col];
    if(_cg)catCodes=catCodes.slice().sort(function(a,b){var x=_cg(a),y=_cg(b);if(x<y)return _cs.dir==='asc'?-1:1;if(x>y)return _cs.dir==='asc'?1:-1;return 0;});}
  var rows=catCodes.map(function(code){var b=finCatBudget(key,code),com=finCatCommitted(key,code),act=finCatActual(key,code),etc=finCatETC(key,code),efc=finCatEFC(key,code);
    var vr=b-efc;if(b===0&&com===0&&act===0&&etc===0)return '';
    var open=!!finCatOpen[key+code];var ov=cr.etc&&cr.etc[code]!=null&&cr.etc[code]!=='';
    var pct=b?Math.min(100,Math.round(efc/b*100)):(efc>0?100:0);
    var barCol=vr<0?'bg-red-500':(efc>b*0.9?'bg-amber-500':'bg-emerald-500');
    var head='<tr class="border-t border-gray-100 '+(code===''?'bg-red-50/40':'hover:bg-gray-50')+' cursor-pointer" onclick="finToggleCatRow(\''+key+'\',\''+code+'\')">'+
      '<td class="p-1.5"><span class="inline-block w-3 text-gray-400">'+(open?'▾':'▸')+'</span><span class="text-[9px] mono text-gray-400 mr-1">'+(code||'—')+'</span><span class="text-[10px] font-bold text-gray-800">'+esc(finCatName(code))+'</span></td>'+
      '<td class="p-1.5 text-right mono text-[10px] text-gray-700">'+$fmt(b)+'</td>'+
      '<td class="p-1.5 text-right mono text-[10px] text-blue-700">'+$fmt(com)+'</td>'+
      '<td class="p-1.5 text-right mono text-[10px] text-gray-800">'+$fmt(act)+'</td>'+
      '<td class="p-1.5 text-right" onclick="event.stopPropagation()"><input type="number" value="'+Math.round(etc)+'" onchange="finSetCatETC(\''+key+'\',\''+code+'\',this.value)" title="'+(ov?'manual override':'auto: budget − committed − actual')+'" class="w-16 text-[10px] mono text-right border rounded px-1 py-0.5 '+(ov?'border-blue-300 bg-blue-50':'border-gray-200 text-gray-500')+'" style="outline:none"></td>'+
      '<td class="p-1.5 text-right mono text-[10px] font-bold '+(vr<0?'text-red-600':'text-gray-900')+'">'+$fmt(efc)+'</td>'+
      '<td class="p-1.5 text-right">'+finVarPill(vr)+'</td>'+
      '<td class="p-1.5" style="width:84px"><div class="h-1.5 rounded-full bg-gray-100 overflow-hidden"><div class="'+barCol+' h-full" style="width:'+pct+'%"></div></div></td>'+
    '</tr>';
    if(!open)return head;
    // expanded: budget lines + coded spend records
    var lines=cr.lines.filter(function(l){return l.cat===code;});
    var lineRows=lines.map(function(l){return '<div class="flex items-center gap-1.5 py-0.5">'+
      '<span class="text-[8px] mono text-gray-300 w-12">'+esc(l.code||'')+'</span>'+
      '<input value="'+esc(l.name).replace(/"/g,'&quot;')+'" onchange="finSetLineName(\''+key+'\',\''+l.id+'\',this.value)" class="flex-1 text-[10px] border border-transparent hover:border-gray-200 rounded px-1.5 py-0.5" style="outline:none">'+
      '<input type="number" value="'+Math.round(l.budget||0)+'" onchange="finSetLineBudget(\''+key+'\',\''+l.id+'\',this.value)" class="w-24 text-[10px] mono text-right border border-gray-200 rounded px-1.5 py-0.5" style="outline:none">'+
      '<button onclick="finDelLine(\''+key+'\',\''+l.id+'\')" class="text-gray-300 hover:text-red-500 text-[10px] w-4">✕</button></div>';}).join('');
    // spend records coded here
    var recs=[];
    finPOs.forEach(function(r){if(r.prod===key&&finRecCat(r,'po')===code)recs.push({t:'po',id:r.id,who:r.vendor,desc:r.desc,amt:r.amount,locked:!!r.acct,actual:finIsActualized(key,r.id)});});
    workOrders.forEach(function(r){if(r.prod===key&&finRecCat(r,'wo')===code&&!finPOs.some(function(po){return po.prod===key&&po.wo===r.id;}))recs.push({t:'wo',id:r.id,who:r.res||'WO',desc:r.desc,amt:r.cost,locked:!!r.acct,actual:finIsActualized(key,r.id)});});
    txBookings.forEach(function(r){if(r.prod===key&&finRecCat(r,'tx')===code)recs.push({t:'tx',id:r.id,who:r.res,desc:'Transmission',amt:r.cost,locked:true,actual:finIsActualized(key,r.id)});});
    finInvoices.forEach(function(r){if(r.prod===key&&finRecCat(r,'inv')===code)recs.push({t:'inv',id:r.id,who:r.vendor,desc:'Invoice'+(r.ref?' · '+r.ref:''),amt:r.amount,locked:!!r.acct,actual:true});});
    var catOpts=function(cur){return '<option value="">Uncoded</option>'+FIN_COA.map(function(c){return '<option value="'+c.code+'"'+(cur===c.code?' selected':'')+'>'+c.code+' '+esc(c.cat)+'</option>';}).join('');};
    var recHTML=recs.length?recs.map(function(r){return '<div class="flex items-center gap-1.5 py-0.5 text-[9px]">'+
      '<span class="mono font-bold '+(r.actual?'text-gray-800':'text-blue-700')+' w-12">'+r.id+'</span>'+
      '<span class="px-1 rounded text-[7px] font-bold '+(r.actual?'bg-gray-200 text-gray-600':'bg-blue-100 text-blue-700')+'">'+(r.actual?'ACTUAL':'COMMIT')+'</span>'+
      '<span class="flex-1 truncate text-gray-600">'+esc(r.who||'')+' · '+esc(r.desc||'')+'</span>'+
      '<span class="mono text-gray-800">'+$fmt(r.amt)+'</span>'+
      (r.t==='tx'?'<span class="text-[7px] text-gray-300 w-28 text-center">fixed: transmission</span>':'<select onchange="finSetAcct(\''+r.t+'\',\''+r.id+'\',this.value)" class="text-[8px] border rounded px-1 py-0.5 '+(r.locked?'border-gray-200':'border-amber-300 bg-amber-50')+'" style="outline:none;max-width:7rem" title="'+(r.locked?'coded':'auto-guessed — confirm')+'">'+catOpts(code)+'</select>')+
    '</div>';}).join(''):'<p class="text-[8px] text-gray-400 py-1">No committed or actual spend coded here yet.</p>';
    var detail='<tr><td colspan="8" class="px-3 pb-3 pt-1 bg-gray-50/60">'+
      '<div class="grid grid-cols-1 lg:grid-cols-2 gap-3">'+
        '<div><div class="flex items-center justify-between mb-1"><span class="text-[8px] font-bold uppercase tracking-wider text-gray-400">Budget lines</span>'+
          '<button onclick="finAddLine(\''+key+'\',\''+code+'\')" class="text-[8px] font-bold text-blue-700 hover:underline">+ line</button></div>'+(lineRows||'<p class="text-[8px] text-gray-400">No budget lines.</p>')+'</div>'+
        '<div><span class="text-[8px] font-bold uppercase tracking-wider text-gray-400">Coded spend ('+recs.length+')</span><div class="mt-1">'+recHTML+'</div></div>'+
      '</div></td></tr>';
    return head+detail;
  }).join('');

  var th=function(t,a){return '<th class="p-1.5 text-[8px] font-bold uppercase tracking-wider text-gray-400 '+(a||'text-left')+'">'+t+'</th>';};
  var topsheet='<div class="bg-white rounded-2xl p-4 sm:p-5 border border-gray-200/60" style="box-shadow:0 4px 20px rgba(0,0,0,.03)">'+
    '<div class="flex flex-wrap items-center justify-between gap-2 mb-2"><h3 class="text-[10px] font-bold uppercase tracking-wider text-gray-600">Topsheet — by account · sortable</h3>'+
      '<div class="flex items-center gap-2"><input value="'+esc(_cq).replace(/"/g,'&quot;')+'" onchange="finWsQSet(\''+key+'\',\'cost\',this.value)" placeholder="Filter accounts &amp; lines…" class="text-[10px] border border-gray-200 rounded-lg px-2 py-1" style="outline:none;width:160px">'+
      '<button onclick="finResetReport(\''+key+'\')" class="text-[8px] font-bold text-gray-400 hover:text-gray-700">↺ reset to template</button></div></div>'+
    '<div class="overflow-x-auto"><table class="w-full" style="min-width:680px"><thead><tr>'+
      finThSort(key,'cost','account','Account')+finThSort(key,'cost','budget','Budget','text-right')+finThSort(key,'cost','committed','Committed','text-right')+finThSort(key,'cost','actual','Actual','text-right')+th('ETC','text-right')+finThSort(key,'cost','efc','EFC','text-right')+finThSort(key,'cost','variance','Variance','text-right')+th('')+
    '</tr></thead><tbody>'+rows+
    '<tr class="border-t-2 border-gray-300 font-bold bg-gray-50/60"><td class="p-1.5 text-[10px] text-gray-800">TOTAL · '+catCodes.filter(function(c){return finCatBudget(key,c)||finCatCommitted(key,c)||finCatActual(key,c);}).length+' accounts</td>'+
      '<td class="p-1.5 text-right mono text-[10px]">'+$fmt(T.budget)+'</td><td class="p-1.5 text-right mono text-[10px] text-blue-700">'+$fmt(T.committed)+'</td>'+
      '<td class="p-1.5 text-right mono text-[10px]">'+$fmt(T.actual)+'</td><td class="p-1.5 text-right mono text-[10px] text-gray-500">'+$fmt(T.etc)+'</td>'+
      '<td class="p-1.5 text-right mono text-[10px] '+(over?'text-red-600':'')+'">'+$fmt(T.efc)+'</td><td class="p-1.5 text-right">'+finVarPill(T.variance)+'</td><td></td></tr>'+
    '</tbody></table></div>'+
    '<p class="text-[8px] text-gray-400 mt-2">Tip: click an account to break out its budget lines and re-code the POs, work orders and invoices that landed in it. ETC defaults to remaining budget; type a number to project a different landing.</p>'+
  '</div>';
  return summary+topsheet;
}


/* ===== Finance: labor & union-rate engine ===== */
/* ============================================================================
   FINANCE — LABOR & UNION-RATE ENGINE
   The dominant, most volatile cost on a live show. Builds crew labor from a
   broadcast rate card (NABET-CWA / IATSE / DGA), with overtime tiers (1.5x then
   2x), meal and turnaround penalties, fringes (pension/H&W + payroll burden) and
   kit fees — then rolls up against the cost report's Production Labor accounts.
   Rates are EDITABLE starting estimates, not published union scale.
   Pulls real positions & people from each production's crew.
   ========================================================================== */

// keyword -> default rate assumptions (hourly base is a ballpark, fully editable)
var LABOR_RATE_RULES=[
 [/director of eng|engineering manager|network architect|networking engineer/i,{baseHr:105,union:'NABET-CWA',fringePct:0.30,kit:0}],
 [/show director|assistant director|^director\b/i,{baseHr:130,union:'DGA',fringePct:0.32,kit:0}],
 [/technical director|\bTD\b/i,{baseHr:95,union:'NABET-CWA',fringePct:0.30,kit:0}],
 [/executive producer|senior producer|line producer|^producer|\bVP\b/i,{baseHr:135,union:'Staff',fringePct:0.28,kit:0}],
 [/EIC|tech manager|video shader|shader/i,{baseHr:100,union:'NABET-CWA',fringePct:0.30,kit:0}],
 [/steadicam/i,{baseHr:110,union:'IATSE 600',fringePct:0.32,kit:750}],
 [/\bjib\b/i,{baseHr:90,union:'IATSE 600',fringePct:0.32,kit:500}],
 [/hard cam|handheld|camera|\bcam op\b/i,{baseHr:78,union:'IATSE 600',fringePct:0.32,kit:150}],
 [/\bA1\b|audio engineer/i,{baseHr:90,union:'NABET-CWA',fringePct:0.30,kit:200}],
 [/\bA2\b|RF tech/i,{baseHr:72,union:'NABET-CWA',fringePct:0.30,kit:0}],
 [/EVS|replay/i,{baseHr:88,union:'NABET-CWA',fringePct:0.30,kit:0}],
 [/chyron|graphics/i,{baseHr:82,union:'NABET-CWA',fringePct:0.30,kit:0}],
 [/lighting director|\bLD\b/i,{baseHr:92,union:'IATSE',fringePct:0.32,kit:0}],
 [/lead utility/i,{baseHr:65,union:'NABET-CWA',fringePct:0.30,kit:0}],
 [/utility/i,{baseHr:55,union:'NABET-CWA',fringePct:0.30,kit:0}],
 [/floor|stage manager/i,{baseHr:72,union:'NABET-CWA',fringePct:0.30,kit:0}],
 [/teleprompter/i,{baseHr:60,union:'NABET-CWA',fringePct:0.30,kit:0}],
 [/transmission|sat operator|driver/i,{baseHr:75,union:'NABET-CWA',fringePct:0.30,kit:0}],
 [/IT client|IT network|engineer/i,{baseHr:95,union:'Staff',fringePct:0.28,kit:0}],
 [/production manager/i,{baseHr:95,union:'Staff',fringePct:0.28,kit:0}]
];
var LABOR_UNIONS=['NABET-CWA','IATSE','IATSE 600','IATSE 695','DGA','Staff','Local Hire','Daily Hire'];
var laborRatesOpen=(typeof laborRatesOpen!=='undefined')?laborRatesOpen:{};

function laborDefaultRate(pos){var base={baseHr:70,union:'NABET-CWA',fringePct:0.30,kit:0};
  for(var i=0;i<LABOR_RATE_RULES.length;i++){if(LABOR_RATE_RULES[i][0].test(pos||'')){base=LABOR_RATE_RULES[i][1];break;}}
  return {baseHr:base.baseHr,union:base.union,fringePct:base.fringePct,kit:base.kit,dayHrs:10,ot1after:10,ot2after:12,ot1x:1.5,ot2x:2};}

function ensureLabor(key){var p=productions[key];if(!p.labor)p.labor={rates:{},lines:{},defDays:3,defHours:12};
  var L=p.labor;if(!L.rates)L.rates={};if(!L.lines)L.lines={};if(L.defDays==null)L.defDays=3;if(L.defHours==null)L.defHours=12;
  var crew=(typeof getProjectCrew==='function')?getProjectCrew(key):[];
  crew.forEach(function(s){if(!L.rates[s.pos])L.rates[s.pos]=laborDefaultRate(s.pos);
    if(!L.lines[s.id])L.lines[s.id]={days:L.defDays,hoursPerDay:L.defHours,meals:0,turn:0,kit:(laborDefaultRate(s.pos).kit>0),perdiem:0};});
  if(!L.importLines)L.importLines=[]; /* rows that matched no crew slot */
  return L;}

/* ---- per-slot computation (OT tiers, penalties, fringes, kit) ---- */
function laborSlotCost(key,slot){var L=ensureLabor(key);var r=L.rates[slot.pos]||laborDefaultRate(slot.pos);
  var ln=L.lines[slot.id]||{days:L.defDays,hoursPerDay:L.defHours,meals:0,turn:0,kit:false};
  var H=Math.max(0,parseFloat(ln.hoursPerDay)||0),days=Math.max(0,parseFloat(ln.days)||0);
  var dh=r.dayHrs||10,o2=r.ot2after||12;
  var stH=Math.min(H,dh),ot1H=Math.max(0,Math.min(H,o2)-dh),ot2H=Math.max(0,H-o2);
  var base=stH*r.baseHr,ot1=ot1H*r.baseHr*(r.ot1x||1.5),ot2=ot2H*r.baseHr*(r.ot2x||2);
  var meal=(parseFloat(ln.meals)||0)*r.baseHr;                 // each meal penalty ≈ 1 base hour
  var perDay=base+ot1+ot2+meal;
  var turn=(parseFloat(ln.turn)||0)*r.baseHr*2;                // each turnaround invasion ≈ 2 base hours
  var gross=perDay*days+turn;
  var fringe=gross*(r.fringePct||0);
  var kit=(ln.kit?(r.kit||0):0)*days;                          // kit/box rental — not fringeable
  var pd=(parseFloat(ln.perdiem)||0)*days;                     // v28 WI7: per diem — daily, not fringeable
  return {base:base*days,ot1:ot1*days,ot2:ot2*days,ot:(ot1+ot2)*days,meal:meal*days,turn:turn,
    gross:gross,fringe:fringe,kit:kit,perdiem:pd,total:gross+fringe+kit+pd,
    hours:H*days,stHours:stH*days,otHours:(ot1H+ot2H)*days,days:days};}
/* cost of an imported labor row (no crew slot) — same OT/fringe math */
function laborImportCost(row){
  var H=Math.max(0,parseFloat(row.hoursPerDay)||0),days=Math.max(0,parseFloat(row.days)||0);
  var baseHr=parseFloat(row.baseHr)||0,dh=10,o2=12;
  var stH=Math.min(H,dh),ot1H=Math.max(0,Math.min(H,o2)-dh),ot2H=Math.max(0,H-o2);
  var perDay=stH*baseHr+ot1H*baseHr*1.5+ot2H*baseHr*2;
  var gross=perDay*days;var fringe=gross*0.30;
  var kit=(parseFloat(row.kit)||0)*days;var pd=(parseFloat(row.perdiem)||0)*days;
  return {base:stH*baseHr*days,ot:(ot1H*1.5+ot2H*2)*baseHr*days,gross:gross,fringe:fringe,kit:kit,perdiem:pd,
    total:gross+fringe+kit+pd,hours:H*days,otHours:(ot1H+ot2H)*days,days:days};}

function laborTotals(key){var L=ensureLabor(key);var crew=(typeof getProjectCrew==='function')?getProjectCrew(key):[];
  var t={base:0,ot:0,pen:0,kit:0,pd:0,fringe:0,total:0,hours:0,otHours:0,heads:0,mandays:0,positions:crew.length};
  var names={};crew.forEach(function(s){var c=laborSlotCost(key,s);t.base+=c.base;t.ot+=c.ot;t.pen+=c.meal+c.turn;
    t.kit+=c.kit;t.pd+=(c.perdiem||0);t.fringe+=c.fringe;t.total+=c.total;t.hours+=c.hours;t.otHours+=c.otHours;t.mandays+=c.days;
    if((s.name||'').trim())names[s.name]=1;});
  (L.importLines||[]).forEach(function(row){var c=laborImportCost(row);t.base+=c.base;t.ot+=c.ot;
    t.kit+=c.kit;t.pd+=c.perdiem;t.fringe+=c.fringe;t.total+=c.total;t.hours+=c.hours;t.otHours+=c.otHours;t.mandays+=c.days;
    if((row.name||'').trim())names[row.name]=1;});
  t.heads=Object.keys(names).length;t.otPct=t.base>0?(t.ot/t.base*100):0;return t;}

/* ---- mutations ---- */
function laborSetRate(key,pos,field,val){var L=ensureLabor(key);if(!L.rates[pos])L.rates[pos]=laborDefaultRate(pos);
  var num=(field==='union');L.rates[pos][field]=num?val:Math.max(0,parseFloat(val)||0);stampEdit(key);renderProjectView(key);}
function laborSetLine(key,slotId,field,val){var L=ensureLabor(key);if(!L.lines[slotId])L.lines[slotId]={days:L.defDays,hoursPerDay:L.defHours,meals:0,turn:0,kit:false};
  if(field==='kit')L.lines[slotId].kit=!L.lines[slotId].kit;else L.lines[slotId][field]=Math.max(0,parseFloat(val)||0);
  stampEdit(key);renderProjectView(key);}
function laborSetDefaults(key,field,val){var L=ensureLabor(key);L[field]=Math.max(0,parseFloat(val)||0);
  var crew=(typeof getProjectCrew==='function')?getProjectCrew(key):[];
  crew.forEach(function(s){if(L.lines[s.id]){if(field==='defDays')L.lines[s.id].days=L.defDays;if(field==='defHours')L.lines[s.id].hoursPerDay=L.defHours;}});
  stampEdit(key);renderProjectView(key);}
function laborToggleRates(key){laborRatesOpen[key]=!laborRatesOpen[key];renderProjectView(key);}
function laborDelImport(key,i){var L=ensureLabor(key);(L.importLines||[]).splice(i,1);stampEdit(key);renderProjectView(key);}

/* ---- push the labor estimate into the cost report's Production Labor (acct 20) ---- */
function finApplyLaborToBudget(key){var est=laborTotals(key).total;var cr=finEnsureCostReport(key);
  var lines=cr.lines.filter(function(l){return l.cat==='20';});
  if(!lines.length){cr.lines.push({id:'L'+key+'_lab'+Date.now().toString(36),code:'20-lab',cat:'20',name:'Crew labor (from labor engine)',budget:Math.round(est),note:''});}
  else{var sum=lines.reduce(function(s,l){return s+(parseFloat(l.budget)||0);},0);
    if(sum>0){lines.forEach(function(l){l.budget=Math.round((parseFloat(l.budget)||0)*est/sum);});}
    else{lines[0].budget=Math.round(est);}}
  finRecalcBudget(key);saveOps();stampEdit(key);renderProjectView(key);
  toast&&toast('Labor estimate '+$fmt(est)+' pushed to budget (acct 20)');}

/* ---- pane ---- */
function laborPaneHTML(key){var p=productions[key];var L=ensureLabor(key);var crew=(typeof getProjectCrew==='function')?getProjectCrew(key):[];
  var T=laborTotals(key);var labBudget=(typeof finCatBudget==='function')?finCatBudget(key,'20'):0;
  var bvar=labBudget-T.total;
  function card(label,val,cls,sub){return '<div class="bg-gray-50 rounded-xl p-3 border border-gray-100"><p class="text-[8px] font-bold uppercase tracking-wider text-gray-500">'+label+'</p><p class="text-base font-bold mono '+(cls||'text-gray-900')+' leading-tight mt-0.5">'+val+'</p>'+(sub?'<p class="text-[8px] mono text-gray-400 mt-0.5">'+sub+'</p>':'')+'</div>';}
  var otCls=T.otPct>40?'text-red-600':(T.otPct>20?'text-amber-600':'text-emerald-600');
  var summary='<div class="bg-white rounded-2xl p-5 border border-gray-200/60" style="box-shadow:0 4px 20px rgba(0,0,0,.03)">'+
    '<div class="flex flex-wrap items-center justify-between gap-2 mb-3"><div><h3 class="text-xs font-bold uppercase tracking-wider text-gray-600">Crew Labor — '+esc(p.name)+'</h3>'+
      '<p class="text-[9px] text-gray-500 mt-0.5">Rate card × hours with OT tiers, penalties &amp; fringes. Pulls this production\'s crew positions.</p></div>'+
      '<button onclick="finApplyLaborToBudget(\''+key+'\')" class="text-[9px] font-bold text-white bg-gray-900 rounded-lg px-3 py-2 hover:bg-gray-800">↳ Push estimate to budget (acct 20)</button></div>'+
    '<div class="grid grid-cols-2 sm:grid-cols-3 xl:grid-cols-6 gap-2 mb-3">'+
      card('Straight time',$fmt(T.base))+
      card('Overtime',$fmt(T.ot),'text-amber-600',T.otHours.toFixed(0)+' OT hrs')+
      card('Penalties',$fmt(T.pen),T.pen>0?'text-red-600':'text-gray-900','meal + turnaround')+
      card('Kit / fringes',$fmt(T.kit+T.fringe),'text-gray-700',$fmt(T.fringe)+' fringe')+
      card('Total labor',$fmt(T.total),'text-gray-900',T.heads+' crew · '+T.mandays.toFixed(0)+' man-days')+
      card('OT % of straight',T.otPct.toFixed(0)+'%',otCls,T.otPct>40?'scheduling risk':(T.otPct>20?'watch':'healthy'))+
    '</div>'+
    '<div class="flex items-center justify-between rounded-xl px-3 py-2 '+(bvar<0?'bg-red-50 border border-red-200':'bg-emerald-50 border border-emerald-200')+'">'+
      '<span class="text-[10px] font-semibold '+(bvar<0?'text-red-800':'text-emerald-800')+'">Labor budget (acct 20): '+$fmt(labBudget)+' · estimate '+$fmt(T.total)+'</span>'+
      '<span class="text-[10px] mono font-bold '+(bvar<0?'text-red-600':'text-emerald-700')+'">'+(bvar<0?'over by '+$fmt(Math.abs(bvar)):$fmt(bvar)+' headroom')+'</span></div>'+
    '<p class="text-[8px] text-amber-600 mt-2">⚠ Rates are editable starting estimates — not published union scale. Set your negotiated rate per local/agreement.</p></div>';

  // rate card (collapsible)
  var open=!!laborRatesOpen[key];
  var posList=Object.keys(L.rates).sort();
  var rateRows=posList.map(function(pos){var r=L.rates[pos];
    function n(field,w){return '<input type="number" value="'+(r[field]||0)+'" onchange="laborSetRate(\''+key+'\',\''+esc(pos).replace(/'/g,"\\'")+'\',\''+field+'\',this.value)" class="text-[10px] mono text-right border border-gray-200 rounded px-1 py-0.5" style="outline:none;width:'+w+'">';}
    var uni='<select onchange="laborSetRate(\''+key+'\',\''+esc(pos).replace(/'/g,"\\'")+'\',\'union\',this.value)" class="text-[9px] border border-gray-200 rounded px-1 py-0.5 bg-white" style="outline:none">'+LABOR_UNIONS.map(function(u){return '<option'+(r.union===u?' selected':'')+'>'+u+'</option>';}).join('')+'</select>';
    return '<tr class="border-t border-gray-100"><td class="p-1 text-[10px] font-semibold text-gray-700">'+esc(pos)+'</td>'+
      '<td class="p-1">'+uni+'</td>'+
      '<td class="p-1 text-right">'+n('baseHr','56px')+'</td>'+
      '<td class="p-1 text-right">'+n('dayHrs','42px')+'</td>'+
      '<td class="p-1 text-right">'+n('ot2after','42px')+'</td>'+
      '<td class="p-1 text-right">'+n('fringePct','46px')+'</td>'+
      '<td class="p-1 text-right">'+n('kit','56px')+'</td></tr>';}).join('');
  var th=function(t,a){return '<th class="p-1 text-[8px] font-bold uppercase tracking-wider text-gray-400 '+(a||'text-left')+'">'+t+'</th>';};
  var rateCard='<div class="bg-white rounded-2xl p-4 sm:p-5 border border-gray-200/60" style="box-shadow:0 4px 20px rgba(0,0,0,.03)">'+
    '<div class="flex items-center justify-between '+(open?'mb-2':'')+'"><button onclick="laborToggleRates(\''+key+'\')" class="text-[10px] font-bold uppercase tracking-wider text-gray-600 flex items-center gap-1"><span class="text-gray-400">'+(open?'▾':'▸')+'</span>Rate Card <span class="text-gray-400 font-normal normal-case">'+posList.length+' positions · $/hr, std day, 2× after, fringe %, kit/day</span></button></div>'+
    (open?'<div class="overflow-x-auto"><table class="w-full" style="min-width:560px"><thead><tr>'+th('Position')+th('Union')+th('Base $/hr','text-right')+th('Std hrs','text-right')+th('2× after','text-right')+th('Fringe %','text-right')+th('Kit/day','text-right')+'</tr></thead><tbody>'+rateRows+'</tbody></table></div><p class="text-[8px] text-gray-400 mt-1.5">OT is 1.5× after the standard day and 2× after the "2× after" hour. Fringe % covers pension, health &amp; welfare and payroll burden.</p>':'')+'</div>';

  // crew estimate, grouped by crew group
  var groups=(typeof CREW_GROUPS!=='undefined')?CREW_GROUPS:[];var grpHTML=groups.map(function(g){
    var slots=crew.filter(function(s){return s.group===g;});if(!slots.length)return '';
    var rows=slots.map(function(s){var r=L.rates[s.pos]||laborDefaultRate(s.pos);var ln=L.lines[s.id]||{days:L.defDays,hoursPerDay:L.defHours,meals:0,turn:0,kit:false};var c=laborSlotCost(key,s);
      function n(field,val,w){return '<input type="number" value="'+val+'" onchange="laborSetLine(\''+key+'\',\''+s.id+'\',\''+field+'\',this.value)" class="text-[10px] mono text-right border border-gray-200 rounded px-1 py-0.5" style="outline:none;width:'+w+'">';}
      return '<tr class="border-t border-gray-100 hover:bg-gray-50">'+
        '<td class="p-1"><span class="text-[10px] font-semibold text-gray-800">'+esc(s.pos)+'</span>'+(s.name?'<span class="text-[9px] text-gray-500"> · '+esc(s.name)+'</span>':'<span class="text-[8px] text-amber-500"> · open</span>')+'</td>'+
        '<td class="p-1 text-[8px] mono text-gray-400">'+esc(r.union||'')+'</td>'+
        '<td class="p-1 text-right text-[9px] mono text-gray-500">$'+r.baseHr+'</td>'+
        '<td class="p-1 text-right">'+n('days',ln.days,'40px')+'</td>'+
        '<td class="p-1 text-right">'+n('hoursPerDay',ln.hoursPerDay,'44px')+'</td>'+
        '<td class="p-1 text-right">'+n('meals',ln.meals||0,'36px')+'</td>'+
        '<td class="p-1 text-right">'+n('turn',ln.turn||0,'36px')+'</td>'+
        '<td class="p-1 text-center"><input type="checkbox" '+(ln.kit?'checked':'')+' onchange="laborSetLine(\''+key+'\',\''+s.id+'\',\'kit\',0)" '+(r.kit>0?'':'disabled title="no kit on this rate"')+'></td>'+
        '<td class="p-1 text-right">'+n('perdiem',ln.perdiem||0,'46px')+'</td>'+
        '<td class="p-1 text-right text-[8px] mono text-gray-400">'+(c.otHours>0?c.otHours.toFixed(0)+'h OT':'—')+'</td>'+
        '<td class="p-1 text-right text-[10px] mono font-bold text-gray-800">'+$fmt(c.total)+'</td></tr>';}).join('');
    var gsub=slots.reduce(function(s,sl){return s+laborSlotCost(key,sl).total;},0);
    return '<div class="mb-3"><div class="flex items-center justify-between mb-1"><h4 class="text-[9px] font-bold uppercase tracking-wider" style="color:'+((typeof CREW_GROUP_COLOR!=='undefined'&&CREW_GROUP_COLOR[g])||'#65676B')+'">'+esc(g)+'</h4><span class="text-[9px] mono text-gray-500">'+$fmt(gsub)+'</span></div>'+
      '<div class="overflow-x-auto"><table class="w-full" style="min-width:680px"><thead><tr>'+th('Position / person')+th('Union')+th('$/hr','text-right')+th('Days','text-right')+th('Hrs/day','text-right')+th('Meal','text-right')+th('Turn','text-right')+th('Kit','text-center')+th('Per diem $','text-right')+th('OT','text-right')+th('Cost','text-right')+'</tr></thead><tbody>'+rows+'</tbody></table></div></div>';
  }).join('');
  /* rows that matched no crew slot */
  if(L.importLines&&L.importLines.length){
    var impRows=L.importLines.map(function(row,ri){var c=laborImportCost(row);
      return '<tr class="border-t border-gray-100 hover:bg-gray-50"><td class="p-1"><span class="text-[10px] font-semibold text-gray-800">'+esc(row.pos||'')+'</span><span class="text-[9px] text-gray-500"> · '+esc(row.name||'')+'</span></td>'+
        '<td class="p-1 text-[8px] mono text-gray-400">'+esc(row.union||'')+'</td>'+
        '<td class="p-1 text-right text-[9px] mono text-gray-500">$'+(row.baseHr||0)+'</td>'+
        '<td class="p-1 text-right text-[9px] mono text-gray-600">'+(row.days||0)+'</td>'+
        '<td class="p-1 text-right text-[9px] mono text-gray-600">'+(row.hoursPerDay||0)+'</td>'+
        '<td class="p-1 text-right text-[9px] mono text-gray-400">—</td><td class="p-1 text-right text-[9px] mono text-gray-400">—</td>'+
        '<td class="p-1 text-center text-[9px] mono text-gray-500">$'+(row.kit||0)+'</td>'+
        '<td class="p-1 text-right text-[9px] mono text-gray-600">$'+(row.perdiem||0)+'</td>'+
        '<td class="p-1 text-right text-[8px] mono text-gray-400">'+(c.otHours>0?c.otHours.toFixed(0)+'h OT':'—')+'</td>'+
        '<td class="p-1 text-right text-[10px] mono font-bold text-gray-800">'+$fmt(c.total)+
          ' <button onclick="laborDelImport(\''+key+'\','+ri+')" class="text-gray-300 hover:text-red-500 text-[9px]" title="Remove imported row">✕</button></td></tr>';}).join('');
    var impSub=L.importLines.reduce(function(s2,row){return s2+laborImportCost(row).total;},0);
    grpHTML+='<div class="mb-3"><div class="flex items-center justify-between mb-1"><h4 class="text-[9px] font-bold uppercase tracking-wider text-violet-600">Imported from Excel — not yet crewed</h4><span class="text-[9px] mono text-gray-500">'+$fmt(impSub)+'</span></div>'+
      '<div class="overflow-x-auto"><table class="w-full" style="min-width:680px"><thead><tr>'+th('Position / person')+th('Union')+th('$/hr','text-right')+th('Days','text-right')+th('Hrs/day','text-right')+th('Meal','text-right')+th('Turn','text-right')+th('Kit','text-center')+th('Per diem $','text-right')+th('OT','text-right')+th('Cost','text-right')+'</tr></thead><tbody>'+impRows+'</tbody></table></div></div>';}
  var estimate='<div class="bg-white rounded-2xl p-4 sm:p-5 border border-gray-200/60" style="box-shadow:0 4px 20px rgba(0,0,0,.03)">'+
    '<div class="flex flex-wrap items-center justify-between gap-2 mb-3"><h3 class="text-[10px] font-bold uppercase tracking-wider text-gray-600">Crew Estimate <span class="text-gray-400 font-normal normal-case">— one line per position; edit days &amp; hours</span></h3>'+
      '<div class="flex items-center gap-2 text-[9px]"><label class="text-gray-500">Default days <input type="number" value="'+L.defDays+'" onchange="laborSetDefaults(\''+key+'\',\'defDays\',this.value)" class="w-12 text-[10px] mono border border-gray-200 rounded px-1 py-0.5 text-right" style="outline:none"></label>'+
      '<label class="text-gray-500">hrs/day <input type="number" value="'+L.defHours+'" onchange="laborSetDefaults(\''+key+'\',\'defHours\',this.value)" class="w-12 text-[10px] mono border border-gray-200 rounded px-1 py-0.5 text-right" style="outline:none"></label></div></div>'+
    (grpHTML||'<p class="text-[11px] text-gray-400 text-center py-4">No crew positions defined yet — add positions in the Crew tab and they\'ll appear here.</p>')+
  '</div>';
  return summary+rateCard+estimate;
}




/* ===== Production schedule (robust) ===== */
/* ============================================================================
   PRODUCTION SCHEDULE  (robust)
   Four coordinated views on one show's timeline:
     • Timeline   — phase arc (Prep→Mobilize→Build→Rehearse→Show→Strike) + countdown
     • Milestones — dated tracker with owner, category, status, overdue flags
     • Run of Show— minute-by-minute show-day call sheet (crew calls, eng checks,
                    rehearsal, meals, AIR window, strike) + meal-penalty warning
     • List       — the existing categorized schedule (preserved)
   Seeds from the production's own schedule rows, air date and crew.
   ========================================================================== */

/* ---- date helpers ---- */
function schedParse(s){if(!s)return null;s=(''+s).trim();if(!s||/^tbd$/i.test(s))return null;
  var iso=s.match(/^(\d{4})-(\d{2})-(\d{2})/);if(iso)return new Date(+iso[1],+iso[2]-1,+iso[3]);
  // strip a trailing "· 18:30 ET" style suffix
  var clean=s.split('·')[0].trim();var d=new Date(clean);if(!isNaN(d))return new Date(d.getFullYear(),d.getMonth(),d.getDate());
  return null;}
function schedFmtShort(d){return d?d.toLocaleDateString('en-US',{month:'short',day:'numeric'}):'TBD';}
function schedFmtFull(d){return d?d.toLocaleDateString('en-US',{month:'short',day:'numeric',year:'numeric'}):'TBD';}
function schedNow(){var n=new Date();return new Date(n.getFullYear(),n.getMonth(),n.getDate());}
function schedDayDiff(a,b){return Math.round((a-b)/86400000);}
function schedAddDays(d,n){var x=new Date(d);x.setDate(x.getDate()+n);return x;}

/* ---- clock helpers (run of show) ---- */
function schedParseClock(s){if(!s)return null;var m=(''+s).match(/(\d{1,2}):(\d{2})\s*(am|pm)?/i);if(!m)return null;
  var h=+m[1],min=+m[2];if(m[3]){if(/pm/i.test(m[3])&&h<12)h+=12;if(/am/i.test(m[3])&&h===12)h=0;}return h*60+min;}
function schedFmtClock(mins){mins=((mins%1440)+1440)%1440;var h=Math.floor(mins/60),m=mins%60;var ap=h<12?'AM':'PM';var h12=h%12;if(h12===0)h12=12;
  return h12+':'+(m<10?'0':'')+m+' '+ap;}

/* ---- chart of milestones (offset = days from air; re matches schedule rows) ---- */
var SCHED_MS=[
 {key:'survey',name:'Site Survey & Tech Recce',cat:'Survey',off:-60,re:/survey|recce|site visit|walk.?through/i},
 {key:'plan',name:'Technical Plan Locked',cat:'Engineering',off:-45,re:/tech plan|technical plan|facilit|kick.?off|engineering|design lock/i},
 {key:'equip',name:'Equipment & Trucks Ordered',cat:'Logistics',off:-40,re:/truck|mobile unit|equipment|gear order|flypack/i},
 {key:'tx',name:'Transmission Paths Ordered',cat:'Transmission',off:-21,re:/fiber|satellite|\bsat\b|transmission|uplink|signal path|\btx\b/i},
 {key:'power',name:'Power & Facilities Confirmed',cat:'Site',off:-30,re:/power|generator|genny|distro|facilit/i},
 {key:'crew',name:'Crew Booked & Confirmed',cat:'Crew',off:-25,re:/crew book|staffing|crew confirm|hire/i},
 {key:'travel',name:'Crew Travel Booked',cat:'Logistics',off:-14,re:/travel|flight|hotel|wheels up|lodging/i},
 {key:'loadin',name:'Load-In / Compound Build',cat:'Build',off:-5,re:/load.?in|compound|rigging|build|setup|mount/i},
 {key:'cable',name:'Cabling & Camera Complete',cat:'Build',off:-3,re:/cabl|camera build|cam build|cam map|fiber pull/i},
 {key:'techreh',name:'Technical Rehearsal',cat:'Rehearsal',off:-2,re:/tech.*rehears|technical rehears/i},
 {key:'dress',name:'Dress Rehearsal',cat:'Rehearsal',off:-1,re:/dress|full rehears|final rehears/i},
 {key:'air',name:'ON AIR',cat:'Broadcast',off:0,re:/live|broadcast|on air|ceremony|kick.?off|\bmatch\b|takeover|summit|opening|final/i},
 {key:'strike',name:'Strike Complete',cat:'Strike',off:2,re:/strike|load.?out|wrap|tear.?down|de.?rig/i}
];
var SCHED_CAT_COLOR={Survey:'#0866ff',Engineering:'#0866ff',Logistics:'#f5832a',Site:'#1E7B34',Transmission:'#0866ff',Crew:'#0a58ca',Build:'#f5832a',Rehearsal:'#f7b928',Broadcast:'#e41e3f',Strike:'#65676b'};
var SCHED_PHASES=[
 {name:'Prep',keys:['survey','plan','equip','tx','power','crew'],color:'#0866ff'},
 {name:'Mobilize',keys:['travel','loadin'],color:'#f5832a'},
 {name:'Build',keys:['loadin','cable'],color:'#f5832a'},
 {name:'Rehearse',keys:['techreh','dress'],color:'#f7b928'},
 {name:'Show',keys:['air'],color:'#e41e3f'},
 {name:'Strike',keys:['strike'],color:'#65676b'}];
var ROS_SEED=[
 {off:-360,dur:30,title:'Crew Call — Technical & Engineering',type:'call',dept:'Engineering'},
 {off:-330,dur:30,title:'Power Up & Generator Check',type:'check',dept:'Site / Power'},
 {off:-300,dur:30,title:'Camera Call & RF Coordination',type:'check',dept:'Camera'},
 {off:-270,dur:30,title:'Transmission Path Check — sat / fiber to network',type:'check',dept:'Transmission'},
 {off:-240,dur:30,title:"Intercom & Comms Check (RTS ADAM / RVON)",type:'check',dept:'Engineering'},
 {off:-210,dur:30,title:'Talent Call & Mic Check',type:'talent',dept:'Production'},
 {off:-180,dur:30,title:'Meal — Crew',type:'meal',dept:'All'},
 {off:-150,dur:60,title:'Camera Blocking & Facilities Check',type:'rehearsal',dept:'Camera'},
 {off:-90,dur:60,title:'Technical Rehearsal',type:'rehearsal',dept:'All'},
 {off:-30,dur:30,title:'Standby — 30 to Air / Final Reset',type:'check',dept:'All'},
 {off:0,dur:210,title:'ON AIR',type:'air',dept:'All'},
 {off:210,dur:15,title:'Off Air / Show Ends',type:'air',dept:'All'},
 {off:225,dur:105,title:'Strike Begins',type:'strike',dept:'Technical'},
 {off:330,dur:30,title:'Compound Secure',type:'strike',dept:'Engineering'}];
var ROS_TYPE_COLOR={call:'#0866ff',check:'#0866ff',talent:'#e41e3f',rehearsal:'#f7b928',meal:'#1E7B34',air:'#e41e3f',strike:'#65676b'};
var ROS_TYPE_LABEL={call:'Call',check:'Check',talent:'Talent',rehearsal:'Rehearsal',meal:'Meal',air:'On Air',strike:'Strike'};
var schedView=(typeof schedView!=='undefined')?schedView:{};
var schedRosDay=(typeof schedRosDay!=='undefined')?schedRosDay:{};

/* ---- find the broadcast row + air clock ---- */
function schedBcRow(p){var rows=p.schedule||[];
  for(var j=0;j<rows.length;j++){if((rows[j][4]||'').trim()&&rows[j][4]!=='—')return rows[j];}  // row with a real on-air time = the show
  for(var i=0;i<rows.length;i++){var r=rows[i];if(/\blive\b|broadcast|on air|ceremony|\bmatch\b|takeover|summit|opening ceremon|grand final/i.test(r[2]||''))return r;}
  return rows[rows.length-1]||null;}
function schedAirDate(p){var r=schedBcRow(p);var d=r?schedParse(r[0]||r[4]):null;return d||schedParse(p.date);}

/* ---- seed ---- */
function ensureSched(key){var p=productions[key];if(p.sched&&p.sched.milestones)return p.sched;
  var rows=p.schedule||[];var air=schedAirDate(p);var now=schedNow();var risk=/risk/i.test(p.status||'');var crew=getProjectCrew(key);
  function rowDate(re){for(var i=0;i<rows.length;i++){if(re.test((rows[i][2]||'')))return schedParse(rows[i][0]);}return null;}
  var ms=SCHED_MS.map(function(m){var d=(m.key==='air')?air:(rowDate(m.re)||(air?schedAddDays(air,m.off):null));
    var st;if(!d)st='pending';else{var dd=schedDayDiff(d,now);st=(m.key==='power'&&risk)?'at-risk':(dd<-1?'done':(dd<=5?'in-progress':'pending'));}
    return {id:'MS_'+key+'_'+m.key,key:m.key,name:m.name,cat:m.cat,date:d?d.toISOString().slice(0,10):'',owner:schedOwnerFor(m.cat,crew),status:st,note:''};});
  // run of show for the broadcast day
  var bc=schedBcRow(p);var airClk=(bc&&schedParseClock(bc[1]))||(bc&&schedParseClock(bc[4]))||900; // default 15:00
  var callClk=(bc&&schedParseClock(bc[3]))||null;var offClk=null;
  if(bc&&bc[4]){var m2=(''+bc[4]).match(/(\d{1,2}):(\d{2})\s*(am|pm)?\s*[A-Z]{0,3}\s*$/i);if(m2)offClk=schedParseClock(m2[0]);}
  var evs=ROS_SEED.map(function(e,i){var t=airClk+e.off;if(e.off===-360&&callClk!=null)t=callClk;var dur=e.dur;
    if(e.type==='air'&&e.off===0&&offClk!=null&&offClk>airClk)dur=offClk-airClk;
    return {id:'RE_'+key+'_'+i,time:((t%1440)+1440)%1440,dur:dur,title:e.title,type:e.type,dept:e.dept};});
  var dayDate=air?air.toISOString().slice(0,10):(rows[0]?(schedParse(rows[0][0])||now).toISOString().slice(0,10):now.toISOString().slice(0,10));
  p.sched={milestones:ms,days:[{id:'D_'+key+'_show',date:dayDate,label:'Show Day',events:evs}]};
  return p.sched;}

/* ---- milestone mutations ---- */
var SCHED_STATUS_ORDER=['pending','in-progress','at-risk','done'];
function schedCycleStatus(key,id){var s=ensureSched(key);s.milestones.forEach(function(m){if(m.id===id){var i=SCHED_STATUS_ORDER.indexOf(m.status);m.status=SCHED_STATUS_ORDER[(i+1)%SCHED_STATUS_ORDER.length];}});stampEdit(key);renderProjectView(key);}
function schedSetMs(key,id,field,val){var s=ensureSched(key);s.milestones.forEach(function(m){if(m.id===id)m[field]=val;});stampEdit(key);if(field==='date')renderProjectView(key);else saveState&&saveState();}
function schedAddMs(key){var s=ensureSched(key);s.milestones.push({id:'MS_'+key+'_'+Date.now().toString(36),key:'custom',name:'New milestone',cat:'Engineering',date:'',owner:'',status:'pending',note:''});stampEdit(key);renderProjectView(key);}
function schedDelMs(key,id){var s=ensureSched(key);s.milestones=s.milestones.filter(function(m){return m.id!==id;});stampEdit(key);renderProjectView(key);}

/* ---- run-of-show mutations ---- */
function schedDay(key){var s=ensureSched(key);var idx=schedRosDay[key]||0;return s.days[idx]||s.days[0];}
function schedSetEv(key,id,field,val){var d=schedDay(key);d.events.forEach(function(e){if(e.id===id){e[field]=(field==='time')?(schedParseClock(val)!=null?schedParseClock(val):e.time):(field==='dur'?Math.max(0,parseInt(val)||0):val);}});stampEdit(key);renderProjectView(key);}
function schedAddEv(key){var d=schedDay(key);var last=d.events[d.events.length-1];d.events.push({id:'RE_'+key+'_'+Date.now().toString(36),time:last?last.time+30:540,dur:30,title:'New event',type:'check',dept:'All'});stampEdit(key);renderProjectView(key);}
function schedDelEv(key,id){var d=schedDay(key);d.events=d.events.filter(function(e){return e.id!==id;});stampEdit(key);renderProjectView(key);}
function schedSortEv(key){var d=schedDay(key);d.events.sort(function(a,b){return a.time-b.time;});stampEdit(key);renderProjectView(key);}

/* ---- meal-penalty gap analysis (ties to the labor engine's meal rules) ---- */
function schedMealGaps(key){var d=schedDay(key);var evs=d.events.slice().sort(function(a,b){return a.time-b.time;});
  var call=evs.length?evs[0].time:null;var air=null;evs.forEach(function(e){if(e.type==='air'&&air==null)air=e.time;});
  var anchors=[];if(call!=null)anchors.push(call);evs.forEach(function(e){if(e.type==='meal')anchors.push(e.time+e.dur);});if(air!=null)anchors.push(air);
  anchors.sort(function(a,b){return a-b;});var maxGap=0,gapStart=null;
  for(var i=1;i<anchors.length;i++){var g=anchors[i]-anchors[i-1];if(g>maxGap){maxGap=g;gapStart=anchors[i-1];}}
  return {maxGap:maxGap,gapStart:gapStart,risk:maxGap>360,meals:evs.filter(function(e){return e.type==='meal';}).length};}

/* ---- view toggle ---- */
function schedSetView(key,v){schedView[key]=v;renderProjectView(key);}
function schedViewStrip(key){var v=schedView[key]||'timeline';
  function b(id,label){return '<button onclick="schedSetView(\''+key+'\',\''+id+'\')" class="px-3 py-1.5 rounded-lg text-[10px] font-bold transition-colors '+(v===id?'bg-white text-gray-900 shadow-sm':'text-gray-500 hover:text-gray-700')+'">'+label+'</button>';}
  return '<div class="inline-flex items-center gap-1 bg-gray-100 rounded-xl p-1 flex-wrap">'+b('timeline','Timeline')+b('milestones','Milestones')+b('runofshow','Run of Show')+b('list','List')+'</div>';}

/* ============================ VIEW: TIMELINE ============================ */
function schedTimelineHTML(key){var p=productions[key];var s=ensureSched(key);var now=schedNow();var air=schedAirDate(p);
  // countdown
  var cd,cdSub,cdCls;
  if(!air){cd='Air date TBD';cdSub='set a broadcast date in the schedule';cdCls='text-gray-400';}
  else{var dd=schedDayDiff(air,now);
    if(dd>1){cd=dd+' days';cdSub='until air · '+schedFmtFull(air);cdCls='text-gray-900';}
    else if(dd===1){cd='Tomorrow';cdSub='air day · '+schedFmtFull(air);cdCls='text-amber-600';}
    else if(dd===0){cd='ON AIR TODAY';cdSub=schedFmtFull(air);cdCls='text-red-600';}
    else{cd='Wrapped';cdSub='aired '+Math.abs(dd)+' day'+(Math.abs(dd)===1?'':'s')+' ago · '+schedFmtFull(air);cdCls='text-gray-400';}}
  var done=s.milestones.filter(function(m){return m.status==='done';}).length;
  var atRisk=s.milestones.filter(function(m){return m.status==='at-risk';}).length;
  var hero='<div class="bg-white rounded-2xl p-5 border border-gray-200/60" style="box-shadow:0 4px 20px rgba(0,0,0,.03)">'+
    '<div class="flex flex-wrap items-end justify-between gap-3">'+
      '<div><p class="text-[9px] font-bold uppercase tracking-wider text-gray-500">Countdown</p><p class="text-3xl font-bold mono '+cdCls+' leading-none mt-1">'+cd+'</p><p class="text-[10px] text-gray-500 mt-1">'+cdSub+'</p></div>'+
      '<div class="flex gap-2">'+
        '<div class="bg-gray-50 rounded-xl px-3 py-2 border border-gray-100 text-center"><p class="text-[8px] font-bold uppercase tracking-wider text-gray-500">Milestones</p><p class="text-base font-bold mono text-gray-900">'+done+'/'+s.milestones.length+'</p></div>'+
        '<div class="bg-gray-50 rounded-xl px-3 py-2 border border-gray-100 text-center"><p class="text-[8px] font-bold uppercase tracking-wider text-gray-500">At Risk</p><p class="text-base font-bold mono '+(atRisk?'text-red-600':'text-gray-900')+'">'+atRisk+'</p></div>'+
        '<div class="bg-gray-50 rounded-xl px-3 py-2 border border-gray-100 text-center"><p class="text-[8px] font-bold uppercase tracking-wider text-gray-500">Venue</p><p class="text-[10px] font-semibold text-gray-700 max-w-[160px] truncate">'+esc((p.venue||'TBD').split('·')[0])+'</p></div>'+
      '</div></div></div>';

  // gantt
  var msD=s.milestones.map(function(m){return {m:m,d:schedParse(m.date)};}).filter(function(x){return x.d;});
  var gantt;
  if(msD.length<2){gantt='<div class="bg-white rounded-2xl p-5 border border-gray-200/60 text-[11px] text-gray-400 text-center" style="box-shadow:0 4px 20px rgba(0,0,0,.03)">Add dates to the milestones to draw the production timeline.</div>';}
  else{
    var min=msD[0].d,max=msD[0].d;msD.forEach(function(x){if(x.d<min)min=x.d;if(x.d>max)max=x.d;});
    min=schedAddDays(min,-3);max=schedAddDays(max,3);var span=Math.max(1,schedDayDiff(max,min));
    var W=1000,L=84,R=992,top=18,rowH=24;var x=function(d){return L+(schedDayDiff(d,min)/span)*(R-L);};
    var rows=SCHED_PHASES.map(function(ph,i){var ds=ph.keys.map(function(k){var mm=s.milestones.filter(function(z){return z.key===k;})[0];return mm?schedParse(mm.date):null;}).filter(Boolean);
      if(!ds.length)return '';var a=ds[0],b=ds[0];ds.forEach(function(z){if(z<a)a=z;if(z>b)b=z;});
      var x1=x(a),x2=x(b);if(x2-x1<6)x2=x1+6;var y=top+i*rowH;
      return '<text x="6" y="'+(y+11)+'" font-size="9" font-weight="700" fill="#65676B">'+ph.name+'</text>'+
        '<rect x="'+x1.toFixed(1)+'" y="'+y+'" width="'+(x2-x1).toFixed(1)+'" height="14" rx="7" fill="'+ph.color+'" opacity="0.85"></rect>';}).join('');
    var lane=top+SCHED_PHASES.length*rowH+8;
    var marks=msD.map(function(z){var cx=x(z.d);var col=SCHED_CAT_COLOR[z.m.cat]||'#65676B';var done=z.m.status==='done';var rk=z.m.status==='at-risk';
      return '<circle cx="'+cx.toFixed(1)+'" cy="'+lane+'" r="4" fill="'+(rk?'#e41e3f':(done?col:'#ffffff'))+'" stroke="'+col+'" stroke-width="2"><title>'+esc(z.m.name)+' · '+schedFmtFull(z.d)+' · '+z.m.status+'</title></circle>';}).join('');
    // month gridlines
    var ticks='';var cur=new Date(min.getFullYear(),min.getMonth(),1);if(cur<min)cur=schedAddDays(cur,0);
    var guard=0;cur=new Date(min.getFullYear(),min.getMonth(),1);
    while(cur<=max&&guard<48){if(cur>=min){var tx=x(cur);ticks+='<line x1="'+tx.toFixed(1)+'" y1="'+top+'" x2="'+tx.toFixed(1)+'" y2="'+(lane+8)+'" stroke="#f0f2f5" stroke-width="1"></line>'+
      '<text x="'+tx.toFixed(1)+'" y="'+(lane+20)+'" font-size="8" fill="#b0b3b8">'+cur.toLocaleDateString('en-US',{month:'short'})+(cur.getMonth()===0?" '"+(''+cur.getFullYear()).slice(2):'')+'</text>';}
      cur=new Date(cur.getFullYear(),cur.getMonth()+1,1);guard++;}
    var todayLine='';if(now>=min&&now<=max){var tx2=x(now);todayLine='<line x1="'+tx2.toFixed(1)+'" y1="'+(top-6)+'" x2="'+tx2.toFixed(1)+'" y2="'+(lane+8)+'" stroke="#e41e3f" stroke-width="1.5" stroke-dasharray="3 2"></line><text x="'+tx2.toFixed(1)+'" y="'+(top-9)+'" font-size="8" font-weight="700" fill="#e41e3f" text-anchor="middle">TODAY</text>';}
    var H=lane+26;
    gantt='<div class="bg-white rounded-2xl p-4 sm:p-5 border border-gray-200/60" style="box-shadow:0 4px 20px rgba(0,0,0,.03)">'+
      '<h3 class="text-[10px] font-bold uppercase tracking-wider text-gray-600 mb-2">Production Timeline</h3>'+
      '<div class="overflow-x-auto"><svg viewBox="0 0 '+W+' '+H+'" width="100%" style="min-width:680px;display:block">'+ticks+todayLine+rows+marks+'</svg></div>'+
      '<div class="flex flex-wrap items-center gap-3 mt-2 pt-2 border-t border-gray-100">'+SCHED_PHASES.map(function(ph){return '<span class="flex items-center gap-1.5 text-[8px] text-gray-500"><span class="w-2.5 h-2.5 rounded-full" style="background:'+ph.color+'"></span>'+ph.name+'</span>';}).join('')+'</div></div>';}
  return hero+gantt;
}

/* ============================ VIEW: MILESTONES ============================ */
function schedMilestonesHTML(key){var p=productions[key];var s=ensureSched(key);var now=schedNow();var msCrew=getProjectCrew(key).filter(function(c){return (c.name||'').trim();});var dlId='mscrew_'+key;var msDL='<datalist id="'+dlId+'">'+msCrew.map(function(c){return '<option value="'+esc(c.name).replace(/"/g,'&quot;')+'">'+esc(c.pos||'')+'</option>';}).join('')+'</datalist>';
  var sc={done:{c:'#1E7B34',l:'Done',bg:'bg-emerald-50 text-emerald-700'},'in-progress':{c:'#0866ff',l:'In progress',bg:'bg-blue-50 text-blue-700'},'at-risk':{c:'#e41e3f',l:'At risk',bg:'bg-red-50 text-red-700'},pending:{c:'#b0b3b8',l:'Pending',bg:'bg-gray-100 text-gray-500'}};
  var ordered=s.milestones.slice().sort(function(a,b){var da=schedParse(a.date),db=schedParse(b.date);if(!da)return 1;if(!db)return -1;return da-db;});
  var rows=ordered.map(function(m){var d=schedParse(m.date);var dd=d?schedDayDiff(d,now):null;var overdue=d&&dd<0&&m.status!=='done';
    var st=sc[m.status]||sc.pending;var col=SCHED_CAT_COLOR[m.cat]||'#65676B';
    var rel=dd==null?'':(dd===0?'today':(dd>0?'in '+dd+'d':Math.abs(dd)+'d ago'));
    return '<div class="flex items-center gap-2 py-2 border-t border-gray-100 '+(overdue?'bg-red-50/40':'')+'">'+
      '<button onclick="schedCycleStatus(\''+key+'\',\''+m.id+'\')" title="click to change status" class="flex-shrink-0 w-4 h-4 rounded-full" style="background:'+(m.status==='done'?st.c:'#ffffff')+';border:2px solid '+st.c+'"></button>'+
      '<span class="w-1.5 h-6 rounded-full flex-shrink-0" style="background:'+col+'"></span>'+
      '<div class="min-w-0 flex-1"><input value="'+esc(m.name).replace(/"/g,'&quot;')+'" onchange="schedSetMs(\''+key+'\',\''+m.id+'\',\'name\',this.value)" class="text-[11px] font-semibold text-gray-800 w-full border border-transparent hover:border-gray-200 rounded px-1 py-0.5" style="outline:none">'+
        '<div class="flex items-center gap-1.5 px-1"><span class="text-[8px] font-bold uppercase tracking-wider px-1.5 py-0.5 rounded" style="background:'+col+'22;color:'+col+'">'+esc(m.cat)+'</span>'+
        '<input list="'+dlId+'" value="'+esc(m.owner||'').replace(/"/g,'&quot;')+'" placeholder="assign owner…" title="pick from crew or type a name" onchange="schedSetMs(\''+key+'\',\''+m.id+'\',\'owner\',this.value)" class="text-[9px] text-gray-600 border border-transparent hover:border-gray-200 rounded px-1" style="outline:none;width:124px"></div></div>'+
      '<div class="text-right flex-shrink-0"><input type="date" value="'+esc(m.date||'')+'" onchange="schedSetMs(\''+key+'\',\''+m.id+'\',\'date\',this.value)" class="text-[9px] mono text-gray-600 border border-gray-200 rounded px-1 py-0.5" style="outline:none">'+
        '<p class="text-[8px] mono '+(overdue?'text-red-600 font-bold':'text-gray-400')+' mt-0.5">'+(overdue?'OVERDUE · ':'')+rel+'</p></div>'+
      '<span class="text-[8px] font-bold px-1.5 py-0.5 rounded flex-shrink-0 '+st.bg+'">'+st.l+'</span>'+
      '<button onclick="schedDelMs(\''+key+'\',\''+m.id+'\')" class="text-gray-300 hover:text-red-500 text-[11px] flex-shrink-0 w-4">✕</button></div>';}).join('');
  var done=s.milestones.filter(function(m){return m.status==='done';}).length;
  var next=ordered.filter(function(m){var d=schedParse(m.date);return d&&schedDayDiff(d,now)>=0&&m.status!=='done';})[0];
  var pct=s.milestones.length?Math.round(done/s.milestones.length*100):0;
  return '<div class="bg-white rounded-2xl p-5 border border-gray-200/60" style="box-shadow:0 4px 20px rgba(0,0,0,.03)">'+
    '<div class="flex flex-wrap items-center justify-between gap-2 mb-2"><div><h3 class="text-[10px] font-bold uppercase tracking-wider text-gray-600">Milestones</h3>'+
      '<p class="text-[9px] text-gray-500 mt-0.5">'+done+' of '+s.milestones.length+' complete'+(next?' · next: '+esc(next.name)+' ('+schedFmtShort(schedParse(next.date))+')':'')+'</p></div>'+
      '<button onclick="schedAddMs(\''+key+'\')" class="text-[9px] font-bold text-white bg-gray-900 rounded-lg px-2.5 py-1.5 hover:bg-gray-800">+ Milestone</button></div>'+
    '<div class="h-1.5 rounded-full bg-gray-100 overflow-hidden mb-1"><div class="h-full bg-emerald-500" style="width:'+pct+'%"></div></div>'+
    rows+
    '<p class="text-[8px] text-gray-400 mt-2">Click the circle to advance status (pending → in progress → at risk → done). Dates drive the Timeline.</p>'+msDL+'</div>';
}

/* ============================ VIEW: RUN OF SHOW ============================ */
function schedRunOfShowHTML(key){var p=productions[key];var s=ensureSched(key);var d=schedDay(key);
  var evs=d.events.slice().sort(function(a,b){return a.time-b.time;});
  var gap=schedMealGaps(key);
  var dayDate=schedParse(d.date);
  // vertical timeline
  var rows=evs.map(function(e){var col=ROS_TYPE_COLOR[e.type]||'#65676B';var isAir=e.type==='air'&&/on air/i.test(e.title);
    var endT=e.time+e.dur;
    return '<div class="flex items-stretch gap-2 '+(isAir?'bg-red-50/60 -mx-2 px-2 rounded-lg':'')+'">'+
      '<div class="flex-shrink-0 w-20 text-right pt-1.5"><p class="text-[10px] mono font-bold '+(isAir?'text-red-600':'text-gray-700')+'">'+schedFmtClock(e.time)+'</p><p class="text-[8px] mono text-gray-300">'+e.dur+'m</p></div>'+
      '<div class="flex-shrink-0 flex flex-col items-center"><span class="w-2.5 h-2.5 rounded-full mt-2" style="background:'+col+'"></span><span class="w-0.5 flex-1" style="background:#e4e6eb"></span></div>'+
      '<div class="flex-1 min-w-0 pb-3 pt-0.5"><div class="flex items-center gap-1.5"><input value="'+esc(e.title).replace(/"/g,'&quot;')+'" onchange="schedSetEv(\''+key+'\',\''+e.id+'\',\'title\',this.value)" class="text-[11px] font-semibold '+(isAir?'text-red-700':'text-gray-800')+' flex-1 border border-transparent hover:border-gray-200 rounded px-1 py-0.5" style="outline:none">'+
        '<span class="text-[7px] font-bold uppercase px-1.5 py-0.5 rounded flex-shrink-0" style="background:'+col+'22;color:'+col+'">'+(ROS_TYPE_LABEL[e.type]||e.type)+'</span>'+
        '<button onclick="schedDelEv(\''+key+'\',\''+e.id+'\')" class="text-gray-300 hover:text-red-500 text-[10px] flex-shrink-0 w-4">✕</button></div>'+
        '<div class="flex items-center gap-2 px-1 mt-0.5"><input value="'+schedFmtClock(e.time)+'" onchange="schedSetEv(\''+key+'\',\''+e.id+'\',\'time\',this.value)" title="start time" class="text-[9px] mono text-gray-500 border border-transparent hover:border-gray-200 rounded px-1" style="outline:none;width:74px">'+
        '<input type="number" value="'+e.dur+'" onchange="schedSetEv(\''+key+'\',\''+e.id+'\',\'dur\',this.value)" title="minutes" class="text-[9px] mono text-gray-500 border border-transparent hover:border-gray-200 rounded px-1" style="outline:none;width:44px"><span class="text-[8px] text-gray-300">min · ends '+schedFmtClock(endT)+'</span>'+
        '<select onchange="schedSetEv(\''+key+'\',\''+e.id+'\',\'dept\',this.value)" class="text-[8px] text-gray-500 border border-transparent hover:border-gray-200 rounded px-1 bg-transparent" style="outline:none">'+['Engineering','Camera','Audio','Transmission','Site / Power','Production','Technical','All'].map(function(dp){return '<option'+(e.dept===dp?' selected':'')+'>'+dp+'</option>';}).join('')+'</select></div></div></div>';}).join('');
  var warn=gap.risk?'<div class="flex items-start gap-2 rounded-lg px-3 py-2 mb-3 bg-amber-50 border border-amber-200"><span class="text-xs leading-none mt-0.5">⚠</span><span class="text-[10px] font-semibold text-amber-800">Meal-penalty risk: '+(gap.maxGap/60).toFixed(1)+' hours without a meal break'+(gap.gapStart!=null?' starting '+schedFmtClock(gap.gapStart):'')+'. Most agreements (NABET-CWA / IATSE) trigger penalties past 6 hours — add a meal or the labor engine will accrue penalty pay.</span></div>':
    '<div class="flex items-center gap-2 rounded-lg px-3 py-2 mb-3 bg-emerald-50 border border-emerald-200"><span class="w-1.5 h-1.5 rounded-full bg-emerald-500"></span><span class="text-[10px] font-semibold text-emerald-800">Meal timing healthy — longest stretch is '+(gap.maxGap/60).toFixed(1)+'h ('+gap.meals+' meal break'+(gap.meals===1?'':'s')+' scheduled).</span></div>';
  return '<div class="bg-white rounded-2xl p-5 border border-gray-200/60" style="box-shadow:0 4px 20px rgba(0,0,0,.03)">'+
    '<div class="flex flex-wrap items-center justify-between gap-2 mb-3"><div><h3 class="text-[10px] font-bold uppercase tracking-wider text-gray-600">Run of Show — '+esc(d.label)+(dayDate?' · '+schedFmtFull(dayDate):'')+'</h3>'+
      '<p class="text-[9px] text-gray-500 mt-0.5">Minute-by-minute call sheet for the broadcast day. Times feed the meal-penalty check.</p></div>'+
      '<div class="flex items-center gap-1.5"><button onclick="schedSortEv(\''+key+'\')" class="text-[9px] font-bold text-gray-500 hover:text-gray-800 px-2 py-1.5">↕ sort</button><button onclick="schedAddEv(\''+key+'\')" class="text-[9px] font-bold text-white bg-gray-900 rounded-lg px-2.5 py-1.5 hover:bg-gray-800">+ Event</button></div></div>'+
    warn+
    '<div>'+rows+'</div></div>';
}

/* ---- milestone owner + call-sheet add-ons ---- */
/* ---- milestone owner ↔ live crew wiring ---- */
var SCHED_OWNER_MATCH={
 Survey:/survey|scout|location|site|tech manager|eic|engineer in charge/i,
 Engineering:/tech manager|engineer|eic|engineering|network/i,
 Logistics:/production manager|coordinator|logistic|travel|transport|production/i,
 Site:/power|site|facilit|rigging|utility|tech manager/i,
 Transmission:/transmission|\bsat\b|network|uplink|fiber|\brf\b|\bit\b|client services/i,
 Crew:/production manager|coordinator|staffing|crew|production/i,
 Build:/tech manager|engineer|rigging|utility|cabl|a2/i,
 Rehearsal:/director|technical director|\btd\b|producer|stage manager/i,
 Broadcast:/eic|engineer in charge|technical director|\btd\b|director/i,
 Strike:/tech manager|utility|rigging|engineer/i
};
function schedOwnerFor(cat,crew){var re=SCHED_OWNER_MATCH[cat];if(!re||!crew)return '';for(var i=0;i<crew.length;i++){if((crew[i].name||'').trim()&&re.test(crew[i].pos||''))return crew[i].name;}return '';}

/* ---- printable Run-of-Show call sheet (Save as PDF) ---- */
function printRunOfShow(key){var p=productions[key];var s=ensureSched(key);var d=schedDay(key);
  var evs=d.events.slice().sort(function(a,b){return a.time-b.time;});
  var dayDate=schedParse(d.date);var gap=schedMealGaps(key);
  var airEv=evs.filter(function(e){return e.type==='air'&&/on air/i.test(e.title);})[0];
  var call=evs[0];
  var crew=getProjectCrew(key).filter(function(c){return (c.name||'').trim();});
  function roleName(re){var m=crew.filter(function(c){return re.test(c.pos||'');})[0];return m?m.name:'—';}
  var tm=roleName(/tech manager/i),eic=roleName(/eic|engineer in charge/i),pm=roleName(/production manager/i);
  var mealChip=gap.risk?'<span class="chip r">Meal risk · '+(gap.maxGap/60).toFixed(1)+'h gap</span>':'<span class="chip g">Meals OK · '+(gap.maxGap/60).toFixed(1)+'h max</span>';
  var body=evs.map(function(e){var isAir=e.type==='air'&&/on air/i.test(e.title);var col=ROS_TYPE_COLOR[e.type]||'#65676B';
    return '<tr class="'+(isAir?'air':(e.type==='meal'?'meal':''))+'"><td class="t">'+schedFmtClock(e.time)+'</td><td class="c">'+e.dur+'m</td>'+
      '<td><span class="dot" style="background:'+col+'"></span>'+esc(e.title)+'</td><td>'+esc(ROS_TYPE_LABEL[e.type]||e.type)+'</td><td>'+esc(e.dept)+'</td><td class="t">'+schedFmtClock(e.time+e.dur)+'</td></tr>';}).join('');
  var bar='<div class="bar"><i style="background:linear-gradient(90deg,#0064E0,#0082FB,#00C2FF)"></i></div>';
  var html='<!DOCTYPE html><html><head><meta charset="utf-8"><title>Run of Show — '+esc(p.name)+'</title><style>'+
    '@page{size:A4;margin:12mm}*{box-sizing:border-box;-webkit-print-color-adjust:exact;print-color-adjust:exact}'+
    'html,body{margin:0;padding:0}body{font-family:-apple-system,Segoe UI,Helvetica,Arial,sans-serif;color:#242526}'+
    '.bar{display:flex;height:5px}.bar i{flex:1}'+
    '.hd{background:#18191A;color:#ffffff;padding:14px 18px;display:flex;justify-content:space-between;align-items:flex-end}'+
    '.hd h1{font-size:19px;margin:0;letter-spacing:.5px}.hd .s{font-size:11px;color:#b0b3b8;margin-top:3px}.hd .r{text-align:right;font-size:9px;color:#b0b3b8;line-height:1.6}'+
    '.stats{display:flex;border-bottom:1px solid #f0f2f5}.stat{flex:1;padding:10px 14px;border-right:1px solid #f0f2f5}.stat:last-child{border-right:none}.stat .l{font-size:8px;text-transform:uppercase;letter-spacing:1px;color:#8A8D91}.stat .n{font-size:15px;font-weight:700;margin-top:2px;font-family:monospace}.stat .n.a{color:#e41e3f}'+
    '.chip{display:inline-block;font-size:9px;font-weight:700;padding:2px 8px;border-radius:20px}.chip.r{background:#fef6e0;color:#b24a00}.chip.g{background:#e6f4ea;color:#1E7B34}'+
    'table{width:100%;border-collapse:collapse;margin-top:0;font-size:10px}th{background:#18191A;color:#ffffff;text-align:left;padding:6px 8px;font-size:9px}td{border-bottom:0.5px solid #e4e6eb;padding:6px 8px;vertical-align:top}td.t{font-family:monospace;white-space:nowrap}td.c{font-family:monospace;color:#8A8D91;text-align:center}.dot{display:inline-block;width:8px;height:8px;border-radius:50%;margin-right:6px;vertical-align:middle}tr.air td{background:#fde7ea;font-weight:700}tr.meal td{background:#e6f4ea}'+
    '.foot{margin-top:14px;display:flex;justify-content:space-between;font-size:8px;color:#8a8d91;border-top:1px solid #f0f2f5;padding-top:6px}'+
    '</style></head><body>'+bar+
    '<div class="hd"><div><h1>RUN OF SHOW · CALL SHEET</h1><div class="s">'+esc(p.name)+' — '+esc(d.label)+(dayDate?' · '+schedFmtFull(dayDate):'')+'</div></div>'+
      '<div class="r">Tech Manager: '+esc(tm)+'<br>EIC: '+esc(eic)+'<br>Production Mgr: '+esc(pm)+'</div></div>'+
    '<div class="stats">'+
      '<div class="stat"><div class="l">Crew Call</div><div class="n">'+(call?schedFmtClock(call.time):'—')+'</div></div>'+
      '<div class="stat"><div class="l">On Air</div><div class="n a">'+(airEv?schedFmtClock(airEv.time):'—')+'</div></div>'+
      '<div class="stat"><div class="l">Off Air</div><div class="n">'+(airEv?schedFmtClock(airEv.time+airEv.dur):'—')+'</div></div>'+
      '<div class="stat"><div class="l">Events</div><div class="n">'+evs.length+'</div></div>'+
      '<div class="stat"><div class="l">Meal Timing</div><div style="margin-top:4px">'+mealChip+'</div></div>'+
    '</div>'+
    '<table><thead><tr><th style="width:64px">Time</th><th style="width:40px">Dur</th><th>Event</th><th style="width:70px">Type</th><th style="width:120px">Dept</th><th style="width:64px">Ends</th></tr></thead><tbody>'+body+'</tbody></table>'+
    '<div class="foot"><span>Meta Broadcast Telemetry · Confidential · Run of Show</span><span>'+esc(p.name)+' · '+evs.length+' events · generated from Muse Live</span></div>'+
    '</body></html>';
  var w=window.open('','_blank');if(!w){toast('Allow pop-ups to export the call sheet');return;}
  w.document.open();w.document.write(html);w.document.close();
  toast('Call sheet ready — choose Save as PDF');
  setTimeout(function(){try{w.focus();w.print();}catch(e){}},650);
}

