/* ---- STUB: post an operational alert into a Teams channel via Microsoft Graph ---
   Real endpoint:  POST {graphEndpoint}/teams/{teamId}/channels/{channelId}/messages
   channelId : Teams channel identifier (string)
   message   : plain-text body of the notification                                */
/* Microsoft Graph — Excel workbook API client (STUB · v28 WI7).
   Bearer-auth request shape, DISABLED by default; honest simulation when invoked.
   Flip M365ExcelAPI.enabled=true and configure M365Config to activate later. */
var M365ExcelAPI={
  enabled:false,
  baseUrl:'https://graph.microsoft.com/v1.0',
  request:function(method,path,payload){
    if(!this.enabled){
      console.info('%c[M365·Excel] stub DISABLED — call ignored','color:#0a58ca;font-weight:bold',method,path);
      return Promise.resolve({status:501,simulated:true,disabled:true,message:'M365ExcelAPI is disabled by default. Set M365ExcelAPI.enabled=true and configure M365Config to activate.'});}
    var self=this;
    return m365AcquireToken('Files.ReadWrite').then(function(token){
      console.groupCollapsed('%c[M365·Excel] '+method+' '+path+' (SIMULATED)','color:#0a58ca;font-weight:bold');
      console.log('Request :',method+' '+self.baseUrl+path);
      console.log('Headers :',{Authorization:'Bearer '+token,'Content-Type':'application/json'});
      if(payload)console.log('Payload :',payload);
      console.log('Status  :','200 OK (mock) — no real Graph call was made');
      console.groupEnd();
      return {status:200,simulated:true,data:null};});},
  getUsedRange:function(item,sheet){return this.request('GET','/me/drive/items/'+(item||'{item-id}')+'/workbook/worksheets/'+(sheet||'Sheet1')+'/usedRange');},
  patchRange:function(item,sheet,addr,values){return this.request('PATCH','/me/drive/items/'+(item||'{item-id}')+'/workbook/worksheets/'+(sheet||'Sheet1')+"/range(address='"+(addr||'A1')+"')",{values:values||[]});},
  createSession:function(item){return this.request('POST','/me/drive/items/'+(item||'{item-id}')+'/workbook/createSession',{persistChanges:true});}
};

