  validateRow:function(v){var errs=[];
    if(v.project&&!productions[v.project])errs.push('“Project Key” must be a production key ('+order.join(', ')+') or empty — got “'+v.project+'”');
    return errs;},
  rows:function(){loadInvOnce();return inventory.map(function(it){return [it.barcode,it.name,it.category,it.serial||'',it.status,it.location||'',it.project||'',it.assignedTo||'',it.value||0,it.condition||'',museRichPlain(it.notes)];});},
