xlsxRegister({key:'personnel',label:'Personnel',sheet:'Personnel',
  can:function(){return (typeof permIsAdmin!=='function')||permIsAdmin();},
  cols:[{k:'name',label:'Name',req:true,type:'text'},
        {k:'pos',label:'Position',req:true,type:'text'},
        {k:'group',label:'Group',req:false,type:'text',enum:['Field & Technical','IT / Network & Engineering','PCR / Control Room','Production & Executive']},
        {k:'email',label:'Email',req:false,type:'text'},
        {k:'phone',label:'Phone',req:false,type:'text'},
        {k:'prov',label:'Provider',req:false,type:'text'},
        {k:'passport',label:'Passport / ID',req:false,type:'text'},
        {k:'homeBase',label:'Home Base (IATA)',req:false,type:'text'},
        {k:'category',label:'Category',req:false,type:'text',enum:['Employee','Freelancer','Vendor','Talent / On-Air']},
        {k:'subGroup',label:'Sub-Group',req:false,type:'text'},
        {k:'ktn',label:'Known Traveler #',req:false,type:'text'},
        {k:'ffp',label:'FF Programs (AA:123; DL:456)',req:false,type:'text'},
        {k:'costCenter',label:'Cost Center',req:false,type:'text'},
        {k:'assignedWBS',label:'Assigned WBS',req:false,type:'text'},
        {k:'seat',label:'Seat Pref',req:false,type:'text',enum:['aisle','window','middle']},
        {k:'meal',label:'Meal Pref',req:false,type:'text'},
        {k:'hotels',label:'Hotel Loyalty (comma-sep)',req:false,type:'text'}],
  /* NOTE: portalAccessKey and exportExempt are intentionally NOT columns — the key is a
     secret (never serialized) and the exemption is settable only at account creation. */
  example:['Jordan Lee',"Replay Operator",'PCR / Control Room','jordan.lee@meta.com','(212) 556-0177','Demo Network Ops','P-00000000','MIA','Freelancer','Technical Crew','KTN000000000','AA:AA00000','CC-DEMO-A1','PRJ-DEMO-01','aisle','','Demo Hotel Loyalty 00000'],
  validateRow:function(v){var errs=[];
    if(v.homeBase&&!/^[A-Za-z]{3}$/.test(v.homeBase))errs.push('“Home Base (IATA)” should be a 3-letter airport code — got “'+v.homeBase+'”');
    if(v.email&&!/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(v.email))errs.push('“Email” doesn’t look like an email address — got “'+v.email+'”');
    if(v.ffp&&v.ffp.split(';').some(function(p){return p.trim()&&p.indexOf(':')<0;}))errs.push('“FF Programs” should look like “AA:AA90123; DL:12345” — got “'+v.ffp+'”');
    return errs;},
  rows:function(){return (typeof personnelRoster==='function'?personnelRoster():[]).map(function(m){var tp=m.travelPreferences||{};
    return [m.name,m.pos||'',m.group||'',m.email||'',m.phone||'',m.prov||'',m.passport||'',m.homeBase||'',
      m.category||'',m.subGroup||'',m.knownTravelerNumber||'',
      (m.frequentFlyerPrograms||[]).map(function(f){return f.airline+':'+f.number;}).join('; '),
      m.costCenter||'',m.assignedWBS||'',tp.seat||'',tp.mealPreference||'',(tp.loyaltyHotels||[]).join(', ')];});},
  apply:function(rows){var upd=0,added=0;loadPerDataOnce();loadCustomPersOnce();
    var roster={};(typeof personnelRoster==='function'?personnelRoster():[]).forEach(function(m){roster[m.name.toLowerCase()]=m;});
    function extApply(od,v){
      if(v.category)od.category=v.category;if(v.subGroup)od.subGroup=v.subGroup;if(v.ktn)od.knownTravelerNumber=v.ktn;
      if(v.ffp)od.frequentFlyerPrograms=v.ffp.split(';').map(function(p){var m2=p.split(':');return {airline:(m2[0]||'').trim().toUpperCase(),number:(m2[1]||'').trim()};}).filter(function(f){return f.airline||f.number;});
      if(v.costCenter)od.costCenter=v.costCenter;if(v.assignedWBS)od.assignedWBS=v.assignedWBS;
      if(v.seat||v.meal||v.hotels){var tp=od.travelPreferences||{};
        if(v.seat)tp.seat=v.seat;if(v.meal)tp.mealPreference=v.meal;
        if(v.hotels)tp.loyaltyHotels=v.hotels.split(',').map(function(s){return s.trim();}).filter(function(s){return s;});
        tp.homeAirport=tp.homeAirport||(v.homeBase||'').toUpperCase();od.travelPreferences=tp;}}
    rows.forEach(function(v){var known=roster[v.name.toLowerCase()];
      if(known){if(!personnelData[known.name])personnelData[known.name]={};var od=personnelData[known.name];
        if(v.pos)od.pos=v.pos;if(v.group)od.group=v.group;if(v.email)od.email=v.email;if(v.phone)od.phone=v.phone;
        if(v.passport)od.passport=v.passport;if(v.homeBase)od.homeBase=v.homeBase.toUpperCase();extApply(od,v);upd++;}
      else{customPersonnel.push({name:v.name,pos:v.pos,group:v.group||'Field & Technical',email:v.email||'',phone:v.phone||'',prov:v.prov||'',passport:v.passport||'',homeBase:(v.homeBase||'').toUpperCase()});
        if(!personnelData[v.name])personnelData[v.name]={};extApply(personnelData[v.name],v);added++;}});
    savePersonnelData();saveCustomPers();try{renderPersonnelDir();}catch(e){}
    if(typeof museBus!=='undefined')museBus.emit('personnel.updated',{source:'xlsx'});
    return 'Personnel: '+upd+' updated, '+added+' added';}});
xlsxRegister({key:'talent',label:'On-Air Talent',sheet:'Talent',
  can:function(){return (typeof permIsAdmin!=='function')||permIsAdmin();},
  cols:[{k:'name',label:'Name',req:true,type:'text'},
        {k:'show',label:'Known For / Show',req:false,type:'text'},
        {k:'notes',label:'Notes',req:false,type:'text'}],
  example:['Dana Whitfield','Buen Día','Bilingual host — CDMX based'],
  rows:function(){return IFB_HOST_TALENT.map(function(n){return [n,'',''];}).concat(customTalent.map(function(t){return [t.name,t.show||'',t.notes||''];}));},
  apply:function(rows){var added=0,skipped=0;
    rows.forEach(function(v){var exists=IFB_HOST_TALENT.indexOf(v.name)>-1||customTalent.some(function(t){return t.name.toLowerCase()===v.name.toLowerCase();});
      if(exists){skipped++;return;}
      customTalent.push({name:v.name,show:v.show||'',notes:v.notes||''});added++;});
    saveTalent();
    return 'Talent: '+added+' added'+(skipped?', '+skipped+' already on the list':'')+' — available in every REM talent dropdown';}});
xlsxRegister({key:'locations',label:'Production Locations',sheet:'Locations',needsProd:true,
  can:function(){return (typeof permIsAdmin!=='function')||permIsAdmin();},
  cols:[{k:'name',label:'Name',req:true,type:'text'},
        {k:'venue',label:'Venue',req:false,type:'text'},
        {k:'city',label:'City',req:false,type:'text'},
        {k:'cc',label:'Country Code',req:false,type:'text'},
        {k:'lat',label:'Latitude',req:true,type:'num'},
        {k:'lng',label:'Longitude',req:true,type:'num'},
        {k:'tz',label:'Time Zone (IANA)',req:true,type:'text'},
        {k:'role',label:'Role',req:false,type:'text'}],
  example:['Gillette Stadium','Gillette Stadium','Foxborough, MA','US','42.0909','-71.2643','America/New_York','Group stage venue'],
  validateRow:function(v){var errs=[];
    if(v.tz){try{new Intl.DateTimeFormat('en-US',{timeZone:v.tz});}catch(e){errs.push('“Time Zone (IANA)” isn’t a valid zone — got “'+v.tz+'” (try America/New_York)');}}
    if(v.cc&&!/^[A-Za-z]{2}$/.test(v.cc))errs.push('“Country Code” should be 2 letters — got “'+v.cc+'”');
    return errs;},
  rows:function(key){return (typeof locsOf==='function'?locsOf(key):[]).map(function(L){return [L.name,L.venue||'',L.city||'',L.cc||'',L.lat,L.lng,L.tz||'',L.role||''];});},
  apply:function(rows,key){var p=productions[key];if(!p)throw new Error('no production');
    if(!p.locations)p.locations=[];var added=0,upd=0;
    function flagOf(cc){if(!/^[A-Za-z]{2}$/.test(cc||''))return '📍';cc=cc.toUpperCase();
      return String.fromCodePoint(0x1F1E6+cc.charCodeAt(0)-65,0x1F1E6+cc.charCodeAt(1)-65);}
    rows.forEach(function(v,i){var hit=null;p.locations.forEach(function(L){if(L.name.toLowerCase()===v.name.toLowerCase())hit=L;});
      var lat=parseFloat(v.lat),lng=parseFloat(v.lng);
      if(hit){hit.venue=v.venue||hit.venue;hit.city=v.city||hit.city;hit.cc=v.cc||hit.cc;hit.lat=lat;hit.lng=lng;hit.tz=v.tz;hit.role=v.role||hit.role;hit.flag=flagOf(v.cc||hit.cc);upd++;}
      else{p.locations.push({id:'loc_x'+Date.now().toString(36)+i,name:v.name,venue:v.venue||v.name,city:v.city||'',cc:(v.cc||'').toUpperCase(),
        lat:lat,lng:lng,tz:v.tz,tzl:'',flag:flagOf(v.cc),role:v.role||''});added++;}});
    stampEdit(key);try{locDeptBind(key);}catch(e){}try{renderProjectView(key);}catch(e){}
    return prodName(key)+' locations: '+upd+' updated, '+added+' added';}});
xlsxRegister({key:'gearcat',label:'ENG Gear Catalog',sheet:'Gear Catalog',
  can:function(){return (typeof permIsAdmin!=='function')||permIsAdmin();},
  cols:[{k:'cat',label:'Category',req:true,type:'text',enum:Object.keys(ENG_GEAR_CATALOG)},
        {k:'item',label:'Item',req:true,type:'text'}],
  example:['Grip & Support','Rolling road case (large)'],
  rows:function(){var out=[];Object.keys(ENG_GEAR_CATALOG).forEach(function(cat){ENG_GEAR_CATALOG[cat].forEach(function(it){out.push([cat,it]);});});return out;},
  apply:function(rows){var added=0,skipped=0;
    rows.forEach(function(v){if(ENG_GEAR_CATALOG[v.cat].indexOf(v.item)>-1){skipped++;return;}
      ENG_GEAR_CATALOG[v.cat].push(v.item);
      if(!customGearCat[v.cat])customGearCat[v.cat]=[];
      if(customGearCat[v.cat].indexOf(v.item)<0)customGearCat[v.cat].push(v.item);added++;});
    saveGearCat();
    return 'Gear catalog: '+added+' item(s) added'+(skipped?', '+skipped+' already listed':'')+' — live in the ENG gear picker';}});

/* v30 Module 1: department-tile equipment — CSV/XLSX import routed into the correct tile.
   IMPORT SCHEMA (column order is the contract; a plain CSV with these headers works too):
   Department | Make | Model | Serial | Scan ID / Barcode | Qty | Status | Location / Assignment | Notes
   - Department must be one of the canonical tile names (validated against DEPT_NAMES).
   - Scan ID empty → a unique MUSE-<DEPT>-###### id is generated on import.
   - Rows with a Scan ID matching an existing line in that tile UPDATE it (merge); others append. */
xlsxRegister({key:'tile_equipment',label:'Department Status — Production Areas',sheet:'Equipment',needsProd:true,
  can:function(){return (typeof permScope!=='function')||permScope('equipment')==='all';},
  cols:[{k:'dept',label:'Department',req:true,type:'text',enum:DEPT_NAMES},
        {k:'make',label:'Make',req:false,type:'text'},
        {k:'model',label:'Model',req:false,type:'text'},
        {k:'serial',label:'Serial',req:false,type:'text'},
        {k:'scanid',label:'Scan ID / Barcode',req:false,type:'text'},
        {k:'qty',label:'Qty',req:false,type:'num'},
        {k:'status',label:'Status',req:false,type:'text',enum:EQUIP_LINE_STATUSES},
        {k:'loc',label:'Location / Assignment',req:false,type:'text'},
        {k:'notes',label:'Notes',req:false,type:'text'}],
  example:['Audio',"Sennheiser",'Axient AD4Q','AX4Q-77812','MUSE-AUD-104501','2','Confirmed','FOH rack — stage left','Handheld RF package'],
  validateRow:function(v){var errs=[];if(!(v.make||v.model))errs.push('Provide at least a Make or a Model');return errs;},
  rows:function(ctxKey){var p=productions[ctxKey];var out=[];if(!p||!p.tbEquip)return out;
    var deps=DEPT_NAMES.slice();Object.keys(p.tbEquip).forEach(function(d){if(deps.indexOf(d)<0)deps.push(d);});
    deps.forEach(function(dep){(p.tbEquip[dep]||[]).forEach(function(ln){if(!ln)return;
      out.push([dep,'',ln.item||ln.model||'',ln.serial||'',ln.scanid||'',ln.qty||1,ln.status||'',ln.loc||'',ln.notes||'']);});});
    return out;},
  apply:function(rows,ctxKey){var p=productions[ctxKey];if(!p)return 'No production selected';
    var added=0,updated=0,stN=0,flN=0,depts={};
    var eq=[],st=[],fl=[];
    rows.forEach(function(v){
      if(v._kind==='departments')st.push(v);
      else if(v._kind==='fields')fl.push(v);
      else eq.push(v);
    });
    st.forEach(function(v){
      var dept=xlsxMatchDept(v.dept);if(!dept)return;
      var di=-1,i;for(i=0;i<(p.dept||[]).length;i++){if(p.dept[i][0]===dept){di=i;break;}}
      if(di<0){p.dept=p.dept||[];p.dept.push([dept,'pending','—']);di=p.dept.length-1;}
      var ns=xlsxMatchStatus(v.status);if(ns)p.dept[di][1]=ns;
      if(v.notes){p.dept[di][2]=v.notes;p.dept[di].__customNote=true;}
      stN++;depts[dept]=1;
    });
    var buckets={};
    fl.forEach(function(v){
      var dept=xlsxMatchDept(v.dept);if(!dept)return;
      var def=xlsxMatchField(dept,v.field||v.label);if(!def)return;
      var fk=def[0];var ftype=def[3]||(typeof def[2]==='string'?def[2]:'');
      var key=dept+'\0'+fk;
      if(!buckets[key])buckets[key]={dept:dept,fk:fk,ftype:ftype,items:[]};
      buckets[key].items.push(v);
    });
    Object.keys(buckets).forEach(function(key){
      var b=buckets[key];if(!p.tbFields)p.tbFields={};if(!p.tbFields[b.dept])p.tbFields[b.dept]={};
      var def=xlsxMatchField(b.dept,b.fk);
      var ftype=b.ftype||(def&&(def[3]||(typeof def[2]==='string'?def[2]:'')))||'';
      if(ftype==='rvon'){
        var arr=b.items.map(function(v,idx){
          var extra=''+(v.extra||'');
          var parts=extra.split('|').map(function(s){return s.trim();});
          var t='',person='',ch=idx+1;
          parts.forEach(function(x){
            var m=/^ch\s*(\d+)/i.exec(x);
            if(m)ch=parseInt(m[1],10);
            else if(/^(IFB|PL)$/i.test(x))t=x.toUpperCase();
            else if(x)person=x;
          });
          return {a:(v.value||'').toUpperCase(),t:t,p:person,_ch:ch};
        }).sort(function(a,c){return a._ch-c._ch;});
        p.tbFields[b.dept].rvon=arr.map(function(e){return {a:e.a,t:e.t,p:e.p};});
        flN+=arr.length;depts[b.dept]=1;return;
      }
      var asList=ftype==='addable'||(def&&Array.isArray(def[2])&&ftype!=='num'&&ftype!=='ip'&&ftype!=='text'&&ftype!=='header');
      if(asList){
        p.tbFields[b.dept][b.fk]=b.items.map(function(v){return v.value;}).filter(Boolean);
        flN+=b.items.length;depts[b.dept]=1;return;
      }
      p.tbFields[b.dept][b.fk]=b.items.length?b.items[b.items.length-1].value:'';
      flN+=1;depts[b.dept]=1;
    });
    eq.forEach(function(v){var dept=v.dept;var name=((v.make||'')+' '+(v.model||'')).trim();
      var lines=getEquip(p,dept);var hit=null;
      if(v.scanid){for(var i=0;i<lines.length;i++){if((lines[i].scanid||'').toLowerCase()===(''+v.scanid).toLowerCase()){hit=lines[i];break;}}}
      if(hit){updated++;}else{hit={};lines.push(hit);added++;}
      if(dept==='Cameras / Video'||dept==='Lighting')hit.model=name;
      else if(dept==='Talent / Production')hit.name=name;
      else hit.item=name;
      if((''+(v.qty==null?'':v.qty)).replace(/\s/g,'')!=='')hit.qty=Math.max(1,Math.round(parseFloat(v.qty)||1));
      else if(!hit.qty)hit.qty=1;
      hit.serial=v.serial||hit.serial||'';hit.scanid=v.scanid||hit.scanid||genEquipScanId(dept);
      hit.status=v.status||hit.status||'';hit.loc=v.loc||hit.loc||'';if(v.notes)hit.notes=v.notes;
      depts[dept]=1;});
    stampEdit(ctxKey);try{renderAll();}catch(e){}try{renderProjectView(ctxKey);}catch(e){}
    var bits=[];
    if(stN)bits.push(stN+' department status row(s)');
    if(added||updated)bits.push(added+' equipment added, '+updated+' updated');
    if(flN)bits.push(flN+' field value(s)');
    if(!bits.length)bits.push('no changes');
    return 'Department Status: '+bits.join(' · ')+' across '+Object.keys(depts).length+' department(s)';}});

/* compact Excel control cluster used by dynamic section headers (WI8) */
function xlsxBtns(tk,ctx){var c=ctx?("'"+ctx+"'"):'null';
  var lab=tk==='tile_equipment'?'All departments':'Excel';
  var tip=tk==='tile_equipment'?'One workbook for every production-area department — import scans the whole file':'Download a pre-formatted template';
  return '<span class="inline-flex items-center gap-1 flex-wrap"><span class="text-[8px] font-bold uppercase tracking-wider text-gray-400">'+lab+'</span>'+
    '<button onclick="xlsxTemplate(\''+tk+'\','+c+')" class="text-[9px] font-bold text-gray-600 border border-gray-200 bg-white rounded-lg px-2 py-1 hover:bg-gray-50" title="'+tip+'">Template</button>'+
    '<button onclick="xlsxImportOpen(\''+tk+'\','+c+')" class="text-[9px] font-bold text-white bg-gray-900 border border-gray-900 rounded-lg px-2 py-1 hover:bg-gray-800">Import</button>'+
    '<button onclick="xlsxExport(\''+tk+'\','+c+')" class="text-[9px] font-bold text-gray-600 border border-gray-200 bg-white rounded-lg px-2 py-1 hover:bg-gray-50">Export</button></span>';}

/* combined finance workbook + finance PDFs (NEW exports — existing PDFs untouched) */
function xlsxExportFinanceAll(key){
  if(typeof permCan==='function'&&!permCan('finance')){toast('🔒 Not available for your role');return;}
  loadSheetJS().then(function(){
    var wb=XLSX.utils.book_new();
    ['finance_cost','finance_labor','finance_ap'].forEach(function(tk){var sp=XLSX_TYPES[tk];
      XLSX.utils.book_append_sheet(wb,_xlsxSheetFor(sp,sp.rows(key)),sp.sheet.slice(0,31));});
    XLSX.writeFile(wb,'Muse_Live_Finance_'+key+'.xlsx');
    toast('Combined finance workbook exported (3 sheets)');
  }).catch(function(e){toast(''+(e.message||e));});}
function finWsPDF(key,section){
  if(typeof permCan==='function'&&!permCan('finance')){toast('🔒 Not available for your role');return;}
  var p=productions[key];if(!p)return;
  var secs=section==='all'?['cost','labor','ap']:[section];
  var TITLES={cost:'Cost Report — Budget vs Actual vs Variance',labor:'Labor — Rates, Hours, OT, Allowances & Per Diems',ap:'AP Ledger — Invoices & Aging'};
  function tableFor(sec){
    if(sec==='cost'){var head=['Code','Category','Budget','Committed','Actual','ETC','EFC','Variance'];
      var body=finActiveCats(key).map(function(c){var b=finCatBudget(key,c),cm=finCatCommitted(key,c),a=finCatActual(key,c),e=finCatETC(key,c),f=finCatEFC(key,c);
        if(!b&&!cm&&!a&&!e)return null;return [c||'—',finCatName(c),$fmt(b),$fmt(cm),$fmt(a),$fmt(e),$fmt(f),$fmt(b-f)];}).filter(Boolean);
      var T=finReportTotals(key);body.push(['','TOTAL',$fmt(T.budget),$fmt(T.committed),$fmt(T.actual),$fmt(T.etc),$fmt(T.efc),$fmt(T.variance)]);
      return {head:head,body:body};}
    if(sec==='labor'){var head2=['Name','Position','Union','$/hr','Days','Hrs/day','ST $','OT $','Kit','Per Diem','Fringe','Total'];
      var L=ensureLabor(key);var crew=(typeof getProjectCrew==='function')?getProjectCrew(key):[];
      var body2=crew.map(function(s){var r=L.rates[s.pos]||laborDefaultRate(s.pos);var c=laborSlotCost(key,s);
        return [s.name||'(open)',s.pos,r.union||'',''+r.baseHr,''+c.days,''+((L.lines[s.id]||{}).hoursPerDay||0),$fmt(c.base),$fmt(c.ot),$fmt(c.kit),$fmt(c.perdiem||0),$fmt(c.fringe),$fmt(c.total)];});
      (L.importLines||[]).forEach(function(row){var c=laborImportCost(row);
        body2.push([(row.name||'')+' *',row.pos||'',row.union||'',''+row.baseHr,''+row.days,''+row.hoursPerDay,$fmt(c.base),$fmt(c.ot),$fmt(c.kit),$fmt(c.perdiem),$fmt(c.fringe),$fmt(c.total)]);});
      var T2=laborTotals(key);body2.push(['','TOTAL','','','','',$fmt(T2.base),$fmt(T2.ot),$fmt(T2.kit),$fmt(T2.pd||0),$fmt(T2.fringe),$fmt(T2.total)]);
      return {head:head2,body:body2};}
    var head3=['Invoice #','Vendor','Linked PO','Amount','Received','Due','Status','Days Out'];
    var body3=finInvoices.filter(function(v){return v.prod===key;}).map(function(v){
      return [v.id,v.vendor,v.ref||'—',$fmt(v.amount),v.recd||'—',v.due||'—',apStatusLabel(v),''+apAgingDays(v)];});
    return {head:head3,body:body3};}
  if(window.jspdf&&window.jspdf.jsPDF&&window.jspdf.jsPDF.API&&typeof window.jspdf.jsPDF.API.autoTable==='function'){
    try{var J=window.jspdf.jsPDF,doc=new J({unit:'pt',format:'letter',orientation:'landscape'});
      var PW=doc.internal.pageSize.getWidth(),PH=doc.internal.pageSize.getHeight();
      var SPECTRUM=['#0064E0','#0066E2','#0068E3','#006AE5','#006CE7','#006EE9','#0070EA','#0072EC','#0073EE','#0075F0','#0077F1','#0079F3','#007BF5','#007DF7','#007FF8','#0081FA','#0084FB','#0088FB','#008CFC','#0090FC','#0095FC','#0099FC','#009DFD','#00A1FD','#00A5FD','#00A9FD','#00ADFE','#00B1FE','#00B6FE','#00BAFE','#00BEFF','#00C2FF'];
      secs.forEach(function(sec,si){if(si>0)doc.addPage();
        SPECTRUM.forEach(function(c2,i){doc.setFillColor(c2);doc.rect(i*(PW/6),0,PW/6,4,'F');});
        doc.setFont('helvetica','bold');doc.setFontSize(13);doc.setTextColor(24,25,26);doc.text('MUSE LIVE — FINANCE WORKSPACE',40,36);
        doc.setFont('helvetica','normal');doc.setFontSize(8);doc.setTextColor(101,103,107);
        doc.text(p.name+'  ·  '+TITLES[sec]+'  ·  generated '+new Date().toLocaleDateString(),40,48);
        var t=tableFor(sec);
        doc.autoTable({head:[t.head],body:t.body,startY:58,margin:{left:40,right:40},
          styles:{fontSize:7,cellPadding:3},headStyles:{fillColor:[231,243,255],textColor:[5,5,5],fontSize:6.5},
          didParseCell:function(d){if(d.section==='body'&&d.row.index===t.body.length-1&&(sec==='cost'||sec==='labor'))d.cell.styles.fontStyle='bold';}});
        SPECTRUM.forEach(function(c2,i){doc.setFillColor(c2);doc.rect(i*(PW/6),PH-4,PW/6,4,'F');});});
      doc.save('Muse_Live_Finance_'+key+'_'+(section||'all')+'.pdf');toast('Finance PDF exported');return;
    }catch(e){console.error(e);}}
  /* fallback: print window */
  var w=window.open('','_blank');if(!w){toast('Allow pop-ups to export');return;}
  var html=secs.map(function(sec){var t=tableFor(sec);
    return '<h2>'+esc(p.name)+' — '+esc(TITLES[sec])+'</h2><table border="1" cellspacing="0" cellpadding="4" style="border-collapse:collapse;font:9px monospace"><tr>'+t.head.map(function(hh){return '<th>'+esc(hh)+'</th>';}).join('')+'</tr>'+
      t.body.map(function(rw){return '<tr>'+rw.map(function(cc){return '<td>'+esc(''+cc)+'</td>';}).join('')+'</tr>';}).join('')+'</table>';}).join('<div style="page-break-after:always"></div>');
  w.document.write('<!DOCTYPE html><html><head><meta charset="utf-8"><title>Finance</title></head><body style="font-family:Helvetica,Arial,sans-serif">'+html+'<script>setTimeout(function(){window.print();},400);<\/script></body></html>');
  w.document.close();}

/* ================================================================================
   15. ROLES & PERMISSIONS + ACCOUNT PROVISIONING  (v28 · Work Item 1)
       Per-module permission flags. Two demo roles ship (Executive · Camera Operator/
       Field); provisioned accounts become additional switchable roles with their own
       per-module grants. Everything persists (muselive_role_v1 / muselive_accounts_v1).
       Scope values: true/false (module on/off) · 'all' · 'own' (equipment, travel) ·
       'team' (comms: exec-level threads invisible).
   ================================================================================ */
var MUSE_ROLES={
 executive:{id:'executive',label:'Executive',persona:'Lila Hart',title:'VP, Technical Production · Admin',admin:true,
   perms:{finance:true,scheduling:true,vendors:true,equipment:'all',travel:'all',comms:'all'}},
 camop:{id:'camop',label:'Camera Operator / Field',persona:'Avery Nolan',title:'Hard Cam Op · Field Crew',admin:false,
   perms:{finance:false,scheduling:false,vendors:false,equipment:'own',travel:'own',comms:'team'}}
};
var museRoleId='executive';
var museAccounts={};
var _permLoaded=false;
function permLoad(){if(_permLoaded)return;_permLoaded=true;
  try{var r=localStorage.getItem('muselive_role_v1');if(r&&(MUSE_ROLES[r]||r.indexOf('acct:')===0))museRoleId=r;}catch(e){}
  try{var a=localStorage.getItem('muselive_accounts_v1');if(a){var o=JSON.parse(a);if(o&&typeof o==='object')museAccounts=o;}}catch(e){}}
function permSave(){try{localStorage.setItem('muselive_role_v1',museRoleId);}catch(e){}
  try{localStorage.setItem('muselive_accounts_v1',JSON.stringify(museAccounts));}catch(e){}}
function permRoleDef(){permLoad();
  if(museRoleId&&museRoleId.indexOf('acct:')===0){var a=museAccounts[museRoleId.slice(5)];
    if(a&&a.status==='active')return {id:museRoleId,label:a.person,persona:a.person,title:(a.title||'Provisioned Account'),admin:!!a.admin,perms:a.perms||{}};
    museRoleId='executive';}
  return MUSE_ROLES[museRoleId]||MUSE_ROLES.executive;}
function permCan(mod){var v=permRoleDef().perms[mod];return v===undefined?true:v!==false;}
function permScope(mod){var v=permRoleDef().perms[mod];if(v==='own'||v==='team'||v==='all')return v;return v===false?false:'all';}
function permUser(){return permRoleDef().persona;}
function permRoleTitle(){return permRoleDef().title;}
function permIsAdmin(){return !!permRoleDef().admin;}
function permViewAllowed(view){if(view==='vendors')return permCan('vendors');return true;}
function permInventory(){try{loadInvOnce();}catch(e){}var inv=(typeof inventory!=='undefined')?inventory:[];
  if(permScope('equipment')!=='own')return inv;
  var me=permUser();return inv.filter(function(it){return (it.assignedTo||'')===me;});}

/* ---- comms audience model: which threads are executive/high-level ---- */
var COMMS_EXEC_THREADS={'T-30377':1,'T-88161':1,'T-88134':1,'T-88160':1,'T-npc501':1,'T-milano':1};
function commsAudience(m){if(m.audience)return m.audience;
  if(COMMS_EXEC_THREADS[m.thread||m.id])return 'exec';
  if(m.linkType==='po'||m.linkType==='wo'||m.linkType==='inv'||m.linkType==='account')return 'exec';
  return 'ops';}
function permComms(){var all=(typeof comms!=='undefined')?comms:[];
  if(permScope('comms')==='all')return all;
  return all.filter(function(m){return commsAudience(m)!=='exec';});}

/* ---- executive-circle chat (Omni drawer · visible only with full comms access) ---- */
var OMNI_EXEC_CHAT=[
 {from:'Elena Vasquez · CFO Office',body:'FY26 broadcast capex review moved to Thursday. Need the Muse AI World Tour EFC and the Orion Reveal draft budget on the deck.',ts:'08:05',dir:'in'},
 {from:'Legal · Rights Desk',body:'Three music sync clearances for Muse AI World Tour are in final review — outside counsel expects sign-off Friday.',ts:'08:22',dir:'in'},
 {from:'You',body:'Holding the vendor POs over $250k until the capex review clears. Flag anything that risks the load-in dates.',ts:'08:31',dir:'out'},
 {from:'Elena Vasquez · CFO Office',body:'Understood. Aggreko and NEP are inside the approved envelope — no schedule risk from finance.',ts:'08:44',dir:'in'}];

/* ---- role switcher (header) ---- */
function renderRoleSwitch(){var m=document.getElementById('roleSwitchMount');if(!m)return;permLoad();
  var opts='<optgroup label="Demo Roles">'+['executive','camop'].map(function(id){var r=MUSE_ROLES[id];
    return '<option value="'+id+'"'+(museRoleId===id?' selected':'')+'>'+r.label+'</option>';}).join('')+'</optgroup>';
  var act=Object.keys(museAccounts).filter(function(n){return museAccounts[n].status==='active';});
  if(act.length)opts+='<optgroup label="Provisioned Accounts">'+act.map(function(n){var v='acct:'+n;
    return '<option value="'+v+'"'+(museRoleId===v?' selected':'')+'>'+esc(n)+'</option>';}).join('')+'</optgroup>';
  m.innerHTML='<div class="role-switch" title="Demo: flip the whole interface between roles"><span class="role-switch-label">Viewing<br>as</span><select onchange="applyRole(this.value)" aria-label="Role switcher">'+opts+'</select></div>';}
function permHeaderChip(){var d=permRoleDef();
  var n=document.getElementById('userChipName');if(n)n.textContent=d.persona;
  var t=document.getElementById('userChipTitle');if(t)t.textContent=d.title;
  var av=document.getElementById('userChipAvatar');if(av)av.textContent=d.persona.split(' ').map(function(x){return x[0];}).slice(0,2).join('').toUpperCase();}
function applyRole(id,quiet){permLoad();museRoleId=id;permSave();
  var d=permRoleDef();permHeaderChip();renderRoleSwitch();
  try{_searchIdx=null;_searchFuse=null;}catch(e){}
  var act=(document.querySelector('.view-pane.active')||{}).id||'';act=act.replace('view-','');
  try{renderAll();}catch(e){}
  try{renderOps();}catch(e){}
  if(act&&typeof permViewAllowed==='function'&&!permViewAllowed(act)){switchView('dashboard');}
  else if(act&&productions[act]){try{renderProjectView(act);}catch(e){}}
  else if(act==='equipment'){try{renderEquipView();}catch(e){}}
  else if(act==='comms'){try{renderComms();}catch(e){}}
  else if(act==='schedule'){try{renderSchedule();}catch(e){}}
  else if(act==='personnel'){try{renderPersonnelDir();}catch(e){}}
  else if(act==='engrequests'){try{renderEng();}catch(e){}}
  try{if(typeof omniDrawerOpen!=='undefined'&&omniDrawerOpen)renderOmniDrawer();}catch(e){}
  try{omniFabBadge();}catch(e){}
  try{commsNavBadge();}catch(e){}
  if(!quiet)toast(d.admin?'Viewing as '+d.label+' — unrestricted':'Viewing as '+d.label+' — restricted access');}
function permInit(){permLoad();permHeaderChip();renderRoleSwitch();}

/* ---- guard rail: navigation to a forbidden view bounces home ---- */
(function(){var _sv=switchView;switchView=function(view){
  if(typeof permViewAllowed==='function'&&!permViewAllowed(view)){toast('🔒 Not available for your role');view='dashboard';}
  _sv(view);};})();

/* ================= ACCOUNT PROVISIONING ================= */
function accountFor(name){permLoad();return museAccounts[name]||null;}
function accountPersonInfo(name){var r=(typeof personnelRoster==='function')?personnelRoster():[];
  for(var i=0;i<r.length;i++){if(r[i].name===name)return r[i];}return {name:name,pos:'',email:'',phone:''};}
function genAccountFor(name){permLoad();
  if(!permIsAdmin()){toast('🔒 Only admins can provision accounts');return;}
  var a=museAccounts[name];
  if(!a){var info=accountPersonInfo(name);
    var tok=('PLS'+Date.now().toString(36)+Math.random().toString(36).slice(2,8)).toUpperCase();
    a={person:name,title:info.pos||'Provisioned Account',email:info.email||'',phone:info.phone||'',
       token:tok,status:'invited',invitedOn:nowStamp(),activatedOn:'',admin:false,
       perms:{finance:false,scheduling:false,vendors:false,equipment:'own',travel:'own',comms:'team'},
       cred:{user:(info.email||name.toLowerCase().replace(/[^a-z]+/g,'.')).split('@')[0],set:false}};
    museAccounts[name]=a;permSave();
    /* SIMULATED invite email through the established comms stub — logged, never actually sent */
    try{var nmax=9006;comms.forEach(function(m){var n=parseInt((m.id||'').replace('MSG-',''),10);if(n>nmax)nmax=n;});
      comms.unshift({id:'MSG-'+(nmax+1),channel:'email',dir:'out',priority:'normal',from:'Meta Provisioning',
        to:name+(a.email?' <'+a.email+'>':''),subject:'[SIMULATED] You’re invited to Muse Live',
        body:'Hi '+name.split(' ')[0]+' — an Muse Live account has been created for you. Open your invite to set up access: '+inviteLink(a)+' (Simulated provisioning email — demo only, nothing was sent externally.)',
        ts:nowStamp(),linkType:'account',linkId:name,prod:'',read:true,thread:'T-acct-'+a.token});
      saveComms();}catch(e){}
    try{if(typeof commsNavBadge==='function')commsNavBadge();}catch(e){}
    /* v31: portal access key is issued at account creation (a secret — museRedact strips it
       from every export). exportExempt is offered on the invite tab until activation. */
    try{if(!personnelInfo(name).portalAccessKey){
      var pin=name.split(/\s+/).map(function(w){return (w[0]||'').toUpperCase();}).join('').slice(0,3);
      setPersonnelInfo(name,'portalAccessKey','PORTAL-'+pin+'-'+Math.floor(1000+Math.random()*9000));}}catch(e){}
    try{museAudit('account.created',{person:name});museBus.emit('account.created',{person:name});}catch(e){}
    toast('Invite created · simulated email logged to Omni');}
  openAccountModal(name,'invite');}
/* v31 PHASE 6: techbook-export exemption — settable ONLY here (account creation flow),
   ONLY by an admin, and locked once the account activates. Default is always included. */
function acctSetExportExempt(name,val){
  if(typeof permIsAdmin==='function'&&!permIsAdmin()){toast('🔒 Only admins can set export exemption');return;}
  var a=accountFor(name);
  if(a&&a.status==='active'){toast('Locked — exemption can only be set at account creation, before activation');openAccountModal(name,'invite');return;}
  setPersonnelInfo(name,'exportExempt',!!val);
  museAudit('personnel.exportExempt.set',{person:name,exempt:!!val});
  toast(name+(val?' will be OMITTED from techbook exports':' will be included in techbook exports (default)'));}
function inviteLink(a){return location.origin+'/invite/'+a.token;}
function copyInviteLink(name){var a=accountFor(name);if(!a)return;var s=inviteLink(a);
  function fallback(){try{var ta=document.createElement('textarea');ta.value=s;ta.style.position='fixed';ta.style.opacity='0';
    document.body.appendChild(ta);ta.select();document.execCommand('copy');ta.remove();toast('Invite link copied');}catch(e){toast(s);}}
  try{if(navigator.clipboard&&navigator.clipboard.writeText){navigator.clipboard.writeText(s).then(function(){toast('Invite link copied');},fallback);}else fallback();}catch(e){fallback();}}
function closeAccountModal(){var ov=document.getElementById('accountOverlay');if(ov)ov.style.display='none';}
function openAccountModal(name,mode){permLoad();var a=museAccounts[name];if(!a){toast('No account for '+name);return;}
  var ov=document.getElementById('accountOverlay');var bx=document.getElementById('accountBox');if(!ov||!bx)return;
  var nm=name.replace(/'/g,"\\'");
  var statusChip=a.status==='active'?
    '<span class="text-[9px] font-bold uppercase tracking-wider px-2 py-0.5 rounded-full bg-emerald-50 border border-emerald-200 text-emerald-700">● Active</span>':
    '<span class="text-[9px] font-bold uppercase tracking-wider px-2 py-0.5 rounded-full bg-amber-50 border border-amber-200 text-amber-700">● Invited · awaiting activation</span>';
  var tabs=['invite','form','perms'].map(function(t){var lab={invite:'Invite',form:'Invite Form (their view)',perms:'Permissions'}[t];
    return '<button onclick="openAccountModal(\''+nm+'\',\''+t+'\')" class="text-[10px] font-bold px-3 py-1.5 rounded-lg '+(mode===t?'bg-gray-900 text-white':'text-gray-600 hover:bg-gray-100')+'">'+lab+'</button>';}).join('');
  var head='<div class="flex items-start justify-between mb-1"><div><h3 class="text-sm font-bold text-gray-900 leading-none">Meta Account — '+esc(name)+'</h3>'+
    '<p class="text-[10px] text-gray-500 mt-1">'+esc(a.title||'')+'</p></div><button onclick="closeAccountModal()" class="text-gray-400 hover:text-gray-700 text-lg leading-none">✕</button></div>'+
    '<div class="flex items-center gap-2 mb-3">'+statusChip+'<span class="text-[9px] mono text-gray-400">invited '+esc(a.invitedOn||'')+(a.activatedOn?' · activated '+esc(a.activatedOn):'')+'</span></div>'+
    '<div class="inline-flex items-center gap-1 bg-gray-100 rounded-xl p-1 mb-4">'+tabs+'</div>';
  var body='';
  if(mode==='invite'){
    body='<p class="text-[10px] font-bold uppercase tracking-wider text-gray-500 mb-1.5">Shareable invite link</p>'+
    '<div class="invite-link-box mb-3"><span class="mono text-[10px] text-sky-800 flex-1 min-w-0" style="word-break:break-all">'+esc(inviteLink(a))+'</span>'+
      '<button onclick="copyInviteLink(\''+nm+'\')" class="text-[10px] font-bold text-white bg-sky-600 hover:bg-sky-700 rounded-lg px-2.5 py-1.5 flex-shrink-0">Copy</button></div>'+
    '<div class="sim-note mb-3"><span>⚠</span><span><b>Simulated send:</b> the invite email was logged to the Omni inbox through the comms stub — no real email left this demo. The link opens the in-app invite form below.</span></div>'+
    /* v31: export policy — set at creation, admin-only, locks on activation */
    '<label class="flex items-start gap-2 text-[10px] text-gray-700 bg-amber-50/60 border border-amber-200 rounded-lg px-3 py-2 mb-3 cursor-pointer">'+
      '<input type="checkbox" class="rounded mt-0.5"'+((typeof personnelInfo==='function'&&personnelInfo(name).exportExempt)?' checked':'')+(a.status==='active'?' disabled':'')+' onchange="acctSetExportExempt(\''+nm+'\',this.checked)">'+
      '<span><b>Exempt from full techbook export.</b> Default: every person is included regardless of position. This is the only exemption path — admin-set, here at account creation'+(a.status==='active'?' <b>(locked — account is active)</b>':', locks on activation')+'. Secrets (portal key, API keys) are stripped from every export independently of this setting.</span></label>'+
    (personnelInfo(name).portalAccessKey?'<p class="text-[9px] text-gray-500 mb-3">🔑 Portal access key on file: <span class="mono font-bold">'+esc(personnelInfo(name).portalAccessKey)+'</span> — share privately; grants the traveler portal; never included in any export.</p>':'')+
    '<div class="flex items-center gap-2">'+
      '<button onclick="openAccountModal(\''+nm+'\',\'form\')" class="flex-1 text-[11px] font-bold text-white bg-gray-900 hover:bg-gray-800 rounded-lg px-3 py-2.5">Open invite form →</button>'+
      '<button onclick="openAccountModal(\''+nm+'\',\'perms\')" class="flex-1 text-[11px] font-bold text-gray-700 border border-gray-300 hover:bg-gray-50 rounded-lg px-3 py-2.5">Assign permissions</button></div>';}
  else if(mode==='form'){
    var dis=a.status==='active';
    body='<div class="sim-note mb-3"><span>👁</span><span>This is the <b>invitee’s own view</b> — what '+esc(name.split(' ')[0])+' sees after opening the invite link.</span></div>'+
    '<div class="space-y-2.5">'+
    '<div><label class="text-[10px] font-bold uppercase tracking-wider text-gray-600 block mb-1">Full Name</label><input id="acct_name" value="'+esc(a.person).replace(/"/g,'&quot;')+'" class="w-full text-sm border border-gray-300 rounded-lg px-3 py-2" style="outline:none"'+(dis?' disabled':'')+'></div>'+
    '<div class="grid grid-cols-2 gap-2.5"><div><label class="text-[10px] font-bold uppercase tracking-wider text-gray-600 block mb-1">Email</label><input id="acct_email" value="'+esc(a.email).replace(/"/g,'&quot;')+'" class="w-full text-sm border border-gray-300 rounded-lg px-3 py-2" style="outline:none"'+(dis?' disabled':'')+'></div>'+
    '<div><label class="text-[10px] font-bold uppercase tracking-wider text-gray-600 block mb-1">Mobile</label><input id="acct_phone" value="'+esc(a.phone).replace(/"/g,'&quot;')+'" class="w-full text-sm border border-gray-300 rounded-lg px-3 py-2" style="outline:none"'+(dis?' disabled':'')+'></div></div>'+
    '<div class="grid grid-cols-2 gap-2.5"><div><label class="text-[10px] font-bold uppercase tracking-wider text-gray-600 block mb-1">Username</label><input id="acct_user" value="'+esc(a.cred.user||'').replace(/"/g,'&quot;')+'" class="w-full text-sm mono border border-gray-300 rounded-lg px-3 py-2" style="outline:none"'+(dis?' disabled':'')+'></div>'+
    '<div><label class="text-[10px] font-bold uppercase tracking-wider text-gray-600 block mb-1">Password <span class="normal-case text-gray-400">(credential mock)</span></label><input id="acct_pass" type="password" placeholder="••••••••" class="w-full text-sm border border-gray-300 rounded-lg px-3 py-2" style="outline:none"'+(dis?' disabled':'')+'></div></div>'+
    '</div>'+
    (dis?'<p class="text-[10px] text-emerald-700 font-bold mt-3">✓ Account activated '+esc(a.activatedOn)+' — available in the role switcher.</p>':
      '<button onclick="activateAccount(\''+nm+'\')" class="w-full text-[11px] font-bold text-white bg-emerald-600 hover:bg-emerald-700 rounded-lg px-3 py-2.5 mt-3.5">Activate account</button>')+
    '<p class="text-[9px] text-gray-400 mt-2">Demo credential mock — nothing is stored beyond this browser’s localStorage.</p>';}
  else{ // perms
    function togRow(mod,lab,desc){var on=a.perms[mod]!==false;
      return '<div class="perm-row"><div class="min-w-0"><p class="text-[11px] font-bold text-gray-900">'+lab+'</p><p class="text-[9px] text-gray-500">'+desc+'</p></div>'+
        '<button class="perm-toggle'+(on?' on':'')+'" onclick="permSet(\''+nm+'\',\''+mod+'\','+(on?'false':'true')+')" aria-label="Toggle '+lab+'" role="switch" aria-checked="'+(on?'true':'false')+'"></button></div>';}
    function scopeRow(mod,lab,desc,opts){var cur=a.perms[mod];
      return '<div class="perm-row"><div class="min-w-0"><p class="text-[11px] font-bold text-gray-900">'+lab+'</p><p class="text-[9px] text-gray-500">'+desc+'</p></div>'+
        '<span class="perm-scope">'+opts.map(function(o){return '<button class="'+(cur===o[0]?'on':'')+'" onclick="permSet(\''+nm+'\',\''+mod+'\',\''+o[0]+'\')">'+o[1]+'</button>';}).join('')+'</span></div>';}
    body='<p class="text-[10px] text-gray-500 mb-2.5">Per-module access for this account. Changes apply instantly and persist — the account is switchable from the header once activated.</p>'+
      togRow('finance','Finance','Cost report, labor, AP ledger, budgets')+
      togRow('scheduling','Scheduling','Muse Schedule bookings, timecards & crew labor')+
      togRow('vendors','Vendors','Vendor directory & rental documents')+
      scopeRow('equipment','Equipment','Which tracked gear is visible',[['all','All gear'],['own','Own gear']])+
      scopeRow('travel','Travel','Which itineraries are visible',[['all','All crew'],['own','Own only']])+
      scopeRow('comms','Omni-Channel','Exec-level threads & chat groups',[['all','All groups'],['team','Team only']])+
      '<div class="perm-row" style="border-color:#e7f3ff;background:#e7f3ff"><div class="min-w-0"><p class="text-[11px] font-bold text-purple-900">Administrator</p><p class="text-[9px] text-purple-500">Full control · can provision accounts</p></div>'+
        '<button class="perm-toggle'+(a.admin?' on':'')+'" onclick="permSet(\''+nm+'\',\'admin\','+(a.admin?'false':'true')+')" aria-label="Toggle Administrator" role="switch" aria-checked="'+(a.admin?'true':'false')+'"></button></div>';}
  bx.innerHTML=head+body;ov.style.display='flex';}
function activateAccount(name){var a=accountFor(name);if(!a)return;
  var g=function(id){var el=document.getElementById(id);return el?el.value:'';};
  if(g('acct_name'))a.person=g('acct_name');if(g('acct_email'))a.email=g('acct_email');
  if(g('acct_phone'))a.phone=g('acct_phone');if(g('acct_user'))a.cred.user=g('acct_user');
  a.cred.set=!!g('acct_pass');a.status='active';a.activatedOn=nowStamp();
  if(a.person!==name){museAccounts[a.person]=a;delete museAccounts[name];name=a.person;}
  permSave();renderRoleSwitch();toast(name+' activated — now in the role switcher');
  openAccountModal(name,'perms');}
function permSet(name,mod,val){var a=accountFor(name);if(!a)return;
  if(!permIsAdmin()){toast('🔒 Only admins can change permissions');return;}
  if(val==='true')val=true;if(val==='false')val=false;
  if(mod==='admin')a.admin=!!val;else a.perms[mod]=val;
  permSave();openAccountModal(name,'perms');
  if(museRoleId==='acct:'+name)applyRole(museRoleId,true);}

/* first badge paint once the app is up */
try{setTimeout(omniFabBadge,400);}catch(e){}

/* Wave B bootstrap — run after app-a + app-b are both evaluated */
(function museBoot(){
  function go(){try{if(typeof initApp==='function')initApp();}catch(e){console.error('Muse Live initApp failed',e);}}
  if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',go);
  else go();
})();

